// Auto-discovery of OS trust anchors for the Cline CLI.
//
// Bun does not read the OS trust store, so the 3.x CLI cannot see corporate
// MITM / self-signed CAs out of the box. This runs in the Node `bin/cline`
// wrapper (not Bun), reads the full OS store via tls.getCACertificates("system")
// (Node >= 22, no --use-system-ca flag), and hands the certs to the Bun child
// via NODE_EXTRA_CA_CERTS, which both runtimes honor. Mirrors the JetBrains
// plugin's configureCertificates(), sourcing from the OS instead of the IDE.
//
// Dependency-free CommonJS with injectable modules so it is unit-testable and
// ships verbatim in the published wrapper package.

const PEM_MARKER = "-----BEGIN CERTIFICATE-----";
const CERT_BLOCK =
	/-----BEGIN CERTIFICATE-----[\s\S]*?-----END CERTIFICATE-----/g;

/**
 * Returns only the complete certificate blocks from PEM text, or null when
 * there are none. User files may also hold private keys (combined cert+key
 * PEMs) or other sections, which must never be copied into the managed
 * bundle. Files that contain nothing but certificates pass through verbatim
 * so unchanged bundles keep hash-skipping the rewrite.
 */
function sanitizePem(text) {
	const blocks = text.match(CERT_BLOCK) ?? [];
	if (blocks.length === 0) {
		return null;
	}
	const rest = text.replace(CERT_BLOCK, "");
	if (/^\s*$/.test(rest)) {
		return text;
	}
	return `${blocks.join("\n")}\n`;
}

/**
 * Returns OS-trusted certificates as PEM strings, or [] when unavailable.
 * tls.getCACertificates("system") requires Node >= 22.
 */
function harvestSystemCerts(tlsModule) {
	try {
		const tls = tlsModule || require("node:tls");
		if (typeof tls.getCACertificates !== "function") {
			return [];
		}
		const certs = tls.getCACertificates("system");
		if (!Array.isArray(certs)) {
			return [];
		}
		return certs.filter(
			(cert) => typeof cert === "string" && cert.includes(PEM_MARKER),
		);
	} catch {
		return [];
	}
}

/**
 * Returns the file's certificate blocks as PEM text, or null when missing,
 * unreadable, or holding no complete certificate block.
 */
function readUserBundle(fsModule, userPath) {
	if (!userPath) {
		return null;
	}
	try {
		const fs = fsModule || require("node:fs");
		const stat = fs.statSync(userPath, { throwIfNoEntry: false });
		if (!stat || !stat.isFile()) {
			return null;
		}
		// Binary DER would not have loaded in the runtime either; require PEM.
		return sanitizePem(fs.readFileSync(userPath, "utf8"));
	} catch {
		return null;
	}
}

/**
 * Reads the user's NODE_EXTRA_CA_CERTS value into PEM strings. Node treats the
 * value as a single file, but some users set an OS-path-delimited list; the
 * whole value is tried as one file first, then split.
 * The managed bundle is excluded so reading it back never re-appends its certs.
 */
function readUserCerts(fsModule, pathModule, value, managedPath) {
	if (!value) {
		return [];
	}
	const fs = fsModule || require("node:fs");
	const path = pathModule || require("node:path");
	const candidates = [];
	const whole = readUserBundle(fs, value);
	if (whole) {
		candidates.push({ filePath: value, pem: whole });
	} else if (value.includes(path.delimiter)) {
		for (const segment of value.split(path.delimiter)) {
			const trimmed = segment.trim();
			if (!trimmed) {
				continue;
			}
			const pem = readUserBundle(fs, trimmed);
			if (pem) {
				candidates.push({ filePath: trimmed, pem });
			}
		}
	}
	const pems = [];
	for (const candidate of candidates) {
		const isManaged =
			managedPath &&
			path.resolve(candidate.filePath) === path.resolve(managedPath);
		if (!isManaged) {
			pems.push(candidate.pem);
		}
	}
	return pems;
}

/**
 * Concatenates the user PEMs (if any) and the system certificates into one
 * bundle. A separating newline is inserted between parts so adjacent END/BEGIN
 * markers cannot fuse into one invalid line.
 */
function buildBundle({ systemCerts, userPems }) {
	const parts = [...(userPems ?? []), ...systemCerts];
	return parts
		.map((part) => (part.endsWith("\n") ? part : `${part}\n`))
		.join("");
}

/** Counts individual PEM certificates across the given bundle strings. */
function countCerts(pems) {
	let count = 0;
	for (const pem of pems) {
		count += pem.split(PEM_MARKER).length - 1;
	}
	return count;
}

function readFileIfExists(fs, filePath) {
	try {
		return fs.readFileSync(filePath, "utf8");
	} catch {
		return null;
	}
}

function resolveClineDir(env, os, path) {
	return env.CLINE_DIR?.trim() || path.join(os.homedir(), ".cline");
}

/**
 * True when the api-unavailable warning should print. Stamped per Node version
 * in the cline dir so the nudge shows once rather than on every command; a
 * version change (upgrade that still falls short, or downgrade) re-arms it.
 * When the stamp cannot be read or written, warn — bookkeeping failures must
 * never suppress a real diagnostic.
 */
function shouldWarnApiUnavailable(env, deps = {}) {
	const fs = deps.fs || require("node:fs");
	const os = deps.os || require("node:os");
	const path = deps.path || require("node:path");
	const version = deps.nodeVersion || process.versions.node;
	const dir = resolveClineDir(env, os, path);
	const stamp = path.join(dir, `.ca-api-warned-${version}`);
	try {
		if (fs.existsSync(stamp)) {
			return false;
		}
		fs.mkdirSync(dir, { recursive: true });
		fs.writeFileSync(stamp, "", { mode: 0o600 });
		return true;
	} catch {
		return true;
	}
}

/** Atomically writes [content] to [target]; returns true on success. */
function writeBundle(fs, dir, target, content) {
	const tmp = `${target}.${process.pid}.${Date.now()}.tmp`;
	try {
		fs.mkdirSync(dir, { recursive: true });
		// Owner read/write: the bundle holds public CA material, not secrets,
		// but there is no reason to make it world-writable.
		fs.writeFileSync(tmp, content, { mode: 0o600 });
		try {
			fs.renameSync(tmp, target);
		} catch {
			// Windows can reject rename over a file a concurrent child holds open.
			fs.rmSync(target, { force: true });
			fs.renameSync(tmp, target);
		}
		return true;
	} catch {
		// Never leave a partial temp file behind (e.g. ENOSPC mid-write).
		try {
			fs.rmSync(tmp, { force: true });
		} catch {
			// Ignore: best-effort cleanup.
		}
		return false;
	}
}

/**
 * Harvests OS trust anchors, merges them with any user NODE_EXTRA_CA_CERTS, and
 * points env.NODE_EXTRA_CA_CERTS at a single managed PEM bundle. Mutates `env`
 * in place. Returns an outcome the caller can log; `action` is one of
 * "unchanged" | "written" | "write-failed-reused" | "write-failed" |
 * "no-system-certs" | "api-unavailable".
 */
function configureNodeExtraCaCerts(env, deps = {}) {
	const fs = deps.fs || require("node:fs");
	const os = deps.os || require("node:os");
	const path = deps.path || require("node:path");
	const tls = deps.tls || require("node:tls");

	// tls.getCACertificates("system") needs Node >= 22.15; on older Nodes the
	// harvest cannot run at all, which the caller should surface to the user.
	if (typeof tls.getCACertificates !== "function") {
		return {
			action: "api-unavailable",
			path: null,
			systemCertCount: 0,
			userCertCount: 0,
		};
	}

	const systemCerts = harvestSystemCerts(tls);
	if (systemCerts.length === 0) {
		// Nothing to add: leave any user-provided NODE_EXTRA_CA_CERTS untouched
		// and let the runtime fall back to its bundled CAs.
		return {
			action: "no-system-certs",
			path: null,
			systemCertCount: 0,
			userCertCount: 0,
		};
	}

	const managedDir = resolveClineDir(env, os, path);
	const managedPath = path.join(managedDir, "cli-node-extra-ca-certs.pem");
	const userValue = (env.NODE_EXTRA_CA_CERTS || "").trim() || null;
	const userPems = readUserCerts(fs, path, userValue, managedPath);
	const bundle = buildBundle({ systemCerts, userPems });
	const base = {
		path: managedPath,
		systemCertCount: systemCerts.length,
		userCertCount: countCerts(userPems),
	};

	// Skip the rewrite when the bundle is already current. Avoids per-launch I/O
	// and the concurrent-rename race in the steady state.
	if (readFileIfExists(fs, managedPath) === bundle) {
		env.NODE_EXTRA_CA_CERTS = managedPath;
		return { ...base, action: "unchanged" };
	}

	if (writeBundle(fs, managedDir, managedPath, bundle)) {
		env.NODE_EXTRA_CA_CERTS = managedPath;
		return { ...base, action: "written" };
	}

	// Write failed: fall back to a previously-written bundle if one exists.
	if (readFileIfExists(fs, managedPath)) {
		env.NODE_EXTRA_CA_CERTS = managedPath;
		return { ...base, action: "write-failed-reused" };
	}
	return { ...base, path: null, action: "write-failed" };
}

module.exports = {
	harvestSystemCerts,
	sanitizePem,
	readUserBundle,
	readUserCerts,
	buildBundle,
	countCerts,
	configureNodeExtraCaCerts,
	shouldWarnApiUnavailable,
};

#!/usr/bin/env node

// Binary resolver for Cline CLI.
//
// This script runs with Node.js (available everywhere npm is) and finds the
// correct platform-specific compiled binary to execute. The compiled binary
// has Bun embedded, so users don't need Bun installed.
//
// Resolution order:
// 1. CLINE_BIN_PATH env var override
// 2. Cached binary at bin/.cline (created by postinstall)
// 3. Walk up node_modules to find the platform-specific package

const childProcess = require("child_process");
const fs = require("fs");
const path = require("path");
const os = require("os");

const scriptPath = fs.realpathSync(__filename);
const scriptDir = path.dirname(scriptPath);
const childEnv = {
	...process.env,
	CLINE_WRAPPER_PATH: scriptPath,
};

// Auto-discover OS trust anchors and pass them to the Bun child via
// NODE_EXTRA_CA_CERTS. The Bun runtime does not read the OS store on its own,
// so corporate/self-signed CAs would otherwise fail. This wrapper runs on
// Node, which can read the full store here.
try {
	const caCerts = require("./ca-certs.cjs");
	const outcome = caCerts.configureNodeExtraCaCerts(childEnv);
	const debug =
		process.env.CLINE_DEBUG === "1" || process.env.CLINE_DEBUG === "true";
	// Not debug-gated: on old Nodes the harvest silently doing nothing is
	// indistinguishable from a broken corporate proxy. Stamped per Node
	// version so the nudge shows once, not on every command.
	if (
		outcome &&
		outcome.action === "api-unavailable" &&
		!childEnv.NODE_EXTRA_CA_CERTS &&
		caCerts.shouldWarnApiUnavailable(childEnv)
	) {
		console.warn(
			`[cline] Node ${process.versions.node} cannot read the OS trust store (needs >= 22.15); ` +
				"corporate or self-signed CAs may fail TLS. Upgrade Node or set NODE_EXTRA_CA_CERTS.",
		);
	}
	if (debug && outcome) {
		if (outcome.action === "no-system-certs") {
			console.warn(
				"[cline] No OS trust anchors found; relying on the runtime's bundled CAs.",
			);
		} else if (outcome.action === "write-failed") {
			console.warn(
				"[cline] Could not write the managed CA bundle; relying on the runtime's bundled CAs.",
			);
		} else {
			console.warn(
				`[cline] Trust: ${outcome.systemCertCount} OS + ${outcome.userCertCount} user CAs (${outcome.action}) -> ${outcome.path}`,
			);
		}
	}
} catch {
	// Best effort: fall back to the runtime's default trust on any failure.
}

function run(target) {
	const result = childProcess.spawnSync(target, process.argv.slice(2), {
		stdio: "inherit",
		env: childEnv,
	});
	if (result.error) {
		console.error(result.error.message);
		process.exit(1);
	}
	if (typeof result.status === "number") {
		process.exit(result.status);
	}
	if (result.signal) {
		process.kill(process.pid, result.signal);
		process.exit(128);
	}
	process.exit(1);
}

// 1. Check env var override
const envPath = process.env.CLINE_BIN_PATH;
if (envPath) {
	run(envPath);
}

// 2. Check cached binary
const cached = path.join(scriptDir, ".cline");
if (fs.existsSync(cached)) {
	run(cached);
}

// 3. Detect platform and architecture
const platformMap = {
	darwin: "darwin",
	linux: "linux",
	win32: "windows",
};
const archMap = {
	x64: "x64",
	arm64: "arm64",
};

let platform = platformMap[os.platform()];
if (!platform) {
	platform = os.platform();
}
let arch = archMap[os.arch()];
if (!arch) {
	arch = os.arch();
}

const base = "@cline/cli-" + platform + "-" + arch;
const binary = platform === "windows" ? "cline.exe" : "cline";

// Build fallback chain of package names to try
const names = [base];

function findBinary(startDir) {
	let current = startDir;
	for (;;) {
		const modules = path.join(current, "node_modules");
		if (fs.existsSync(modules)) {
			for (const name of names) {
				// Scoped package: @cline/cli-darwin-arm64 lives at
				// node_modules/@cline/cli-darwin-arm64
				const candidate = path.join(modules, name, "bin", binary);
				if (fs.existsSync(candidate)) return candidate;
			}
		}
		const parent = path.dirname(current);
		if (parent === current) {
			return undefined;
		}
		current = parent;
	}
}

const resolved = findBinary(scriptDir);
if (!resolved) {
	console.error(
		"Could not find the Cline CLI binary for your platform.\n" +
			"Your platform: " +
			os.platform() +
			" " +
			os.arch() +
			"\n" +
			"Looked for: " +
			names.map(function (n) {
				return '"' + n + '"';
			}).join(" or ") +
			"\n\n" +
			"Try reinstalling: npm install -g cline",
	);
	process.exit(1);
}

run(resolved);

import {
	copyFileSync,
	cpSync,
	existsSync,
	mkdirSync,
	readdirSync,
	statSync,
} from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { $ } from "bun";

function defineProcessEnv(name: string): string {
	return JSON.stringify(process.env[name] ?? "");
}

const sourcemap = Bun.env.CLINE_SOURCEMAPS === "1" ? "linked" : "none";
const rootDir = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(rootDir, "../../");
const hubWebviewSourcePath = join(repoRoot, "apps/cline-hub/src/webview");
const hubWebviewDistPath = join(repoRoot, "apps/cline-hub/dist/webview");
const hubWebviewIndexPath = join(hubWebviewDistPath, "index.html");
const cliHubWebviewDistPath = join(rootDir, "dist/cline-hub/webview");

function newestFileMtimeMs(dir: string): number {
	let newest = 0;
	for (const entry of readdirSync(dir, { withFileTypes: true })) {
		if (
			entry.name === "node_modules" ||
			entry.name === "dist" ||
			entry.name === ".turbo"
		) {
			continue;
		}
		const path = join(dir, entry.name);
		if (entry.isDirectory()) {
			newest = Math.max(newest, newestFileMtimeMs(path));
		} else if (entry.isFile()) {
			newest = Math.max(newest, statSync(path).mtimeMs);
		}
	}
	return newest;
}

function shouldBuildHubWebview(): boolean {
	if (!existsSync(hubWebviewIndexPath)) {
		return true;
	}
	try {
		return (
			newestFileMtimeMs(hubWebviewSourcePath) >
			statSync(hubWebviewIndexPath).mtimeMs
		);
	} catch {
		return true;
	}
}

if (shouldBuildHubWebview()) {
	console.log("Building Cline Hub webview...");
	await $`bun -F @cline/cline-hub build:webview`.cwd(repoRoot);
}

const result = await Bun.build({
	entrypoints: ["./src/index.ts"],
	outdir: "./dist",
	target: "node",
	format: "esm",
	sourcemap,
	packages: "bundle", // Keep private workspace packages bundled so npm consumers do not need @cline/* at runtime.
	external: [
		// OpenTUI resolves a platform-specific native package at runtime.
		// Bundling through that resolution path rewrites the import in a way that
		// breaks Linux e2e runs from dist/. Keep React external too so OpenTUI and
		// the CLI share one React runtime instead of ending up with duplicate hook
		// dispatchers in the bundle.
		"@opentui/core",
		"@opentui/react",
		"@opentui-ui/dialog",
		"opentui-spinner",
		"react",
		"react/jsx-runtime",
		"react/jsx-dev-runtime",
		"react-devtools-core",
	],
	define: {
		"process.env.NODE_ENV": '"production"',
		...(process.env.TELEMETRY_SERVICE_API_KEY
			? {
					"process.env.TELEMETRY_SERVICE_API_KEY": defineProcessEnv(
						"TELEMETRY_SERVICE_API_KEY",
					),
				}
			: {}),
		...(process.env.ERROR_SERVICE_API_KEY
			? {
					"process.env.ERROR_SERVICE_API_KEY": defineProcessEnv(
						"ERROR_SERVICE_API_KEY",
					),
				}
			: {}),
		"process.env.OTEL_TELEMETRY_ENABLED": defineProcessEnv(
			"OTEL_TELEMETRY_ENABLED",
		),
		"process.env.OTEL_EXPORTER_OTLP_ENDPOINT": defineProcessEnv(
			"OTEL_EXPORTER_OTLP_ENDPOINT",
		),
		"process.env.OTEL_METRICS_EXPORTER": defineProcessEnv(
			"OTEL_METRICS_EXPORTER",
		),
		"process.env.OTEL_LOGS_EXPORTER": defineProcessEnv("OTEL_LOGS_EXPORTER"),
		"process.env.OTEL_EXPORTER_OTLP_PROTOCOL": defineProcessEnv(
			"OTEL_EXPORTER_OTLP_PROTOCOL",
		),
		"process.env.OTEL_METRIC_EXPORT_INTERVAL": defineProcessEnv(
			"OTEL_METRIC_EXPORT_INTERVAL",
		),
		"process.env.OTEL_EXPORTER_OTLP_HEADERS": defineProcessEnv(
			"OTEL_EXPORTER_OTLP_HEADERS",
		),
	},
	env: "OTEL_*",
	banner:
		'import { createRequire as __clineCreateRequire } from "node:module"; const require = __clineCreateRequire(import.meta.url);',
});

if (result.logs.length > 0) {
	for (const log of result.logs) {
		console.warn(log);
	}
}

const coreBootstrapPath = join(
	rootDir,
	"../../sdk/packages/core/dist/extensions/plugin-sandbox-bootstrap.js",
);
const cliBootstrapPath = join(
	rootDir,
	"./dist/extensions/plugin-sandbox-bootstrap.js",
);
mkdirSync(dirname(cliBootstrapPath), { recursive: true });
copyFileSync(coreBootstrapPath, cliBootstrapPath);

if (existsSync(hubWebviewDistPath)) {
	mkdirSync(dirname(cliHubWebviewDistPath), { recursive: true });
	cpSync(hubWebviewDistPath, cliHubWebviewDistPath, { recursive: true });
}

export interface BuildOptions {
	single: boolean;
	skipInstall: boolean;
	skipSdkBuild: boolean;
	installNativeVariants: boolean;
}

export function parseBuildOptions(args: readonly string[]): BuildOptions {
	return {
		single: args.includes("--single"),
		skipInstall: args.includes("--skip-install"),
		skipSdkBuild: args.includes("--skip-sdk-build"),
		installNativeVariants: args.includes("--install-native-variants"),
	};
}

export function shouldInstallNativeVariants(input: {
	options: BuildOptions;
	opentuiVersion: string | undefined;
}): boolean {
	return Boolean(
		input.opentuiVersion &&
			input.options.installNativeVariants &&
			!input.options.skipInstall,
	);
}

export function validateBuildOptions(input: {
	options: BuildOptions;
	opentuiVersion: string | undefined;
	targetCount: number;
}): string | undefined {
	if (input.targetCount === 0) {
		return "No matching targets for this platform.";
	}
	if (
		input.opentuiVersion &&
		!input.options.single &&
		!input.options.skipInstall &&
		!input.options.installNativeVariants
	) {
		return [
			"Cross-platform OpenTUI builds require native package variants.",
			"Pass --install-native-variants to allow the build script to run bun install for all OpenTUI native packages.",
			"Pass --skip-install only when those packages are already installed.",
		].join("\n");
	}
	return undefined;
}

#!/usr/bin/env bun

import {
	cpSync,
	existsSync,
	mkdirSync,
	readdirSync,
	readFileSync,
	realpathSync,
	statSync,
} from "node:fs";
import { join, relative, resolve } from "node:path";
import { $ } from "bun";
import {
	parseBuildOptions,
	shouldInstallNativeVariants,
	validateBuildOptions,
} from "./build-options";

const cliDir = resolve(import.meta.dir, "..");
const rootDir = resolve(cliDir, "../..");
process.chdir(cliDir);

// Telemetry / OTEL environment variables that should be baked into the
// compiled binary at build time. Mirrors the list of secrets injected by the
// `cli-publish` GitHub Actions workflow. These are inlined via Bun's `define`
// so the CLI ships with the production telemetry configuration without
// requiring the end user to set any env vars.
const BUILD_TIME_INLINED_ENV_VARS = [
	"TELEMETRY_SERVICE_API_KEY",
	"ERROR_SERVICE_API_KEY",
	"OTEL_TELEMETRY_ENABLED",
	"OTEL_LOGS_EXPORTER",
	"OTEL_METRICS_EXPORTER",
	"OTEL_EXPORTER_OTLP_PROTOCOL",
	"OTEL_EXPORTER_OTLP_ENDPOINT",
	"OTEL_EXPORTER_OTLP_HEADERS",
] as const;

function buildInlinedEnvDefines(): Record<string, string> {
	const defines: Record<string, string> = {};
	for (const name of BUILD_TIME_INLINED_ENV_VARS) {
		defines[`process.env.${name}`] = JSON.stringify(process.env[name] ?? "");
	}
	return defines;
}

const pkg = JSON.parse(readFileSync(join(cliDir, "package.json"), "utf-8"));
const version: string = pkg.version;
const repository: unknown = pkg.repository;

console.log(`Building @cline/cli v${version}`);

const buildOptions = parseBuildOptions(process.argv.slice(2));

const allTargets: {
	os: string;
	arch: "arm64" | "x64";
}[] = [
	{ os: "linux", arch: "arm64" },
	{ os: "linux", arch: "x64" },
	{ os: "darwin", arch: "arm64" },
	{ os: "darwin", arch: "x64" },
	{ os: "win32", arch: "x64" },
	{ os: "win32", arch: "arm64" },
];

const targets = buildOptions.single
	? allTargets.filter(
			(item) => item.os === process.platform && item.arch === process.arch,
		)
	: allTargets;

const opentuiVersion = pkg.dependencies["@opentui/core"];
const optionsError = validateBuildOptions({
	options: buildOptions,
	opentuiVersion,
	targetCount: targets.length,
});
if (optionsError) {
	console.error(optionsError);
	process.exit(1);
}

await $`rm -rf dist`;

// Pre-install all platform variants of native packages so cross-compilation
// can resolve them. Without this, Bun only has the host platform's native
// binary and cross-compiled builds fail to resolve @opentui/core's FFI layer.
if (shouldInstallNativeVariants({ options: buildOptions, opentuiVersion })) {
	console.log(
		`Installing all platform variants of @opentui/core@${opentuiVersion}...`,
	);
	await $`bun install --os="*" --cpu="*" @opentui/core@${opentuiVersion}`;
}

// Build the SDK first (the CLI bundles workspace packages)
if (!buildOptions.skipSdkBuild) {
	console.log("Building SDK packages...");
	await $`bun run build:sdk`.cwd(rootDir);

	console.log("Building CLI bundle...");
	await $`bun -F @cline/cli build`.cwd(rootDir);
}

const hubWebviewSource = join(cliDir, "../cline-hub/src/webview");
const hubWebviewDist = join(cliDir, "../cline-hub/dist/webview");
const hubWebviewIndex = join(hubWebviewDist, "index.html");

function newestFileMtimeMs(dir: string): number {
	let newest = 0;
	for (const entry of readdirSync(dir, { withFileTypes: true })) {
		if (
			entry.name === "node_modules" ||
			entry.name === "dist" ||
			entry.name === ".turbo"
		) {
			continue;
		}
		const path = join(dir, entry.name);
		if (entry.isDirectory()) {
			newest = Math.max(newest, newestFileMtimeMs(path));
		} else if (entry.isFile()) {
			newest = Math.max(newest, statSync(path).mtimeMs);
		}
	}
	return newest;
}

function shouldBuildHubWebview(): boolean {
	if (!existsSync(hubWebviewIndex)) {
		return true;
	}
	try {
		return (
			newestFileMtimeMs(hubWebviewSource) > statSync(hubWebviewIndex).mtimeMs
		);
	} catch {
		return true;
	}
}

if (shouldBuildHubWebview()) {
	console.log("Building Cline Hub webview...");
	await $`bun -F @cline/cline-hub build:webview`.cwd(rootDir);
}

const binaries: Record<string, string> = {};

function findOpenTuiParserWorker(): string {
	const localPath = resolve(
		cliDir,
		"node_modules/@opentui/core/parser.worker.js",
	);
	const rootPath = resolve(
		rootDir,
		"node_modules/@opentui/core/parser.worker.js",
	);
	const parserWorkerPath = existsSync(localPath) ? localPath : rootPath;
	return realpathSync(parserWorkerPath);
}

function getBunTarget(
	item: (typeof allTargets)[number],
): Bun.Build.CompileTarget {
	const targetOs = item.os === "win32" ? "windows" : item.os;
	return `bun-${targetOs}-${item.arch}` as Bun.Build.CompileTarget;
}

async function buildCompiledBinary(input: {
	bunTarget: Bun.Build.CompileTarget;
	dirName: string;
	outfile: string;
}): Promise<void> {
	const parserWorker = findOpenTuiParserWorker();
	const targetOs = input.bunTarget.includes("windows") ? "windows" : "posix";
	const bunfsRoot = targetOs === "windows" ? "B:/~BUN/root/" : "/$bunfs/root/";
	const parserWorkerPath = relative(rootDir, parserWorker).replaceAll(
		"\\",
		"/",
	);

	// Build to /tmp first so Bun's temp-file rename stays on one filesystem
	// layer in containerized environments (virtiofs, overlayfs).
	const entrypoint = join(cliDir, "src/index.ts");
	const tmpDir = join("/tmp", `cline-build-${input.dirName}`);
	const tmpOutfile = join(
		tmpDir,
		input.outfile.endsWith(".exe") ? "cline.exe" : "cline",
	);
	mkdirSync(tmpDir, { recursive: true });

	process.chdir("/tmp");
	const result = await Bun.build({
		entrypoints: [entrypoint, parserWorker],
		splitting: true,
		compile: {
			target: input.bunTarget,
			outfile: tmpOutfile,
		},
		minify: true,
		external: ["@anthropic-ai/vertex-sdk"],
		define: {
			OTUI_TREE_SITTER_WORKER_PATH: bunfsRoot + parserWorkerPath,
			// Inline telemetry/OTEL env vars at build time so the compiled
			// binary ships with production telemetry configuration baked in.
			...buildInlinedEnvDefines(),
		},
		throw: false,
	});
	process.chdir(cliDir);

	if (!result.success) {
		console.error(`Build failed for ${input.dirName}:`);
		for (const log of result.logs) {
			console.error(log);
		}
		process.exit(1);
	}

	await $`cp ${tmpOutfile} ${input.outfile} && chmod 755 ${input.outfile}`;
	await $`rm -rf ${tmpDir}`;
}

for (const item of targets) {
	// npm treats "win32" specially in os field, but for package naming use "windows"
	const displayOs = item.os === "win32" ? "windows" : item.os;
	const name = `@cline/cli-${displayOs}-${item.arch}`;
	const dirName = `cli-${displayOs}-${item.arch}`;
	const binaryName = item.os === "win32" ? "cline.exe" : "cline";
	const bunTarget = getBunTarget(item);

	console.log(`\nBuilding ${name} (target: ${bunTarget})...`);
	const outDir = join(cliDir, `dist/${dirName}/bin`);
	mkdirSync(outDir, { recursive: true });

	const outfile = join(outDir, binaryName);

	await buildCompiledBinary({ bunTarget, dirName, outfile });

	// Smoke test: only run on current platform
	if (item.os === process.platform && item.arch === process.arch) {
		console.log(`  Smoke test: ${outfile} --version`);
		try {
			const output = await $`${outfile} --version`.text();
			const actualVersion = output.trim();
			if (actualVersion !== version) {
				throw new Error(
					`Expected --version to print ${version}, got ${actualVersion}`,
				);
			}
			console.log(`  Passed: ${actualVersion}`);
		} catch (e) {
			console.error(`  Smoke test FAILED for ${name}:`, e);
			process.exit(1);
		}
	}

	// Copy plugin sandbox bootstrap if it exists
	const bootstrapSrc = join(
		rootDir,
		"sdk/packages/core/dist/extensions/plugin-sandbox-bootstrap.js",
	);
	if (existsSync(bootstrapSrc)) {
		const bootstrapDir = join(cliDir, `dist/${dirName}/extensions`);
		mkdirSync(bootstrapDir, { recursive: true });
		const content = readFileSync(bootstrapSrc);
		await Bun.write(join(bootstrapDir, "plugin-sandbox-bootstrap.js"), content);
	}

	if (existsSync(hubWebviewDist)) {
		const hubWebviewDest = join(cliDir, `dist/${dirName}/cline-hub/webview`);
		mkdirSync(join(cliDir, `dist/${dirName}/cline-hub`), {
			recursive: true,
		});
		cpSync(hubWebviewDist, hubWebviewDest, { recursive: true });
	}

	// Generate platform package.json
	await Bun.write(
		join(cliDir, `dist/${dirName}/package.json`),
		`${JSON.stringify(
			{
				name,
				version,
				description: `Cline CLI binary for ${displayOs} ${item.arch}`,
				os: [item.os],
				cpu: [item.arch],
				...(repository ? { repository } : {}),
				bin: {
					cline: `bin/${binaryName}`,
				},
			},
			null,
			2,
		)}\n`,
	);

	binaries[name] = version;
	console.log(`  Built ${name}`);
}

console.log(`\nBuild complete. ${Object.keys(binaries).length} targets built.`);
console.log("Packages:");
for (const [name, ver] of Object.entries(binaries)) {
	console.log(`  ${name}@${ver}`);
}

export { binaries, version };

