import {
	installPlugin,
	type PluginInstallOptions,
	type PluginInstallResult,
	type PluginMcpOAuthCandidate,
	type PluginUninstallOptions,
	uninstallPlugin,
} from "@cline/core";

export type {
	PluginInstallOptions,
	PluginInstallResult,
	PluginMcpOAuthCandidate,
} from "@cline/core";
export {
	collectPluginMcpOAuthCandidates,
	installPlugin,
	isOfficialPluginSlug,
	parsePluginSource,
} from "@cline/core";

export interface PluginInstallMcpOAuthOptions {
	interactive?: boolean;
	selectCandidates?: (
		candidates: PluginMcpOAuthCandidate[],
	) => Promise<PluginMcpOAuthCandidate[]>;
	authorize?: (candidate: PluginMcpOAuthCandidate) => Promise<void>;
}

export interface PluginInstallIo {
	writeln: (text?: string) => void;
	writeErr: (text: string) => void;
}

type PluginInstallCommandOptions = PluginInstallOptions & {
	json?: boolean;
	io?: PluginInstallIo;
	mcpOAuth?: PluginInstallMcpOAuthOptions;
};

function serializePluginInstallResult(
	result: PluginInstallResult,
): Omit<PluginInstallResult, "mcpOAuthCandidates"> {
	return {
		source: result.source,
		installPath: result.installPath,
		entryPaths: result.entryPaths,
		mcpSyncFailures: result.mcpSyncFailures,
	};
}

function isInteractivePluginInstall(
	options: PluginInstallCommandOptions,
): boolean {
	return (
		options.mcpOAuth?.interactive ??
		(process.stdin.isTTY && process.stdout.isTTY)
	);
}

async function selectMcpOAuthCandidatesWithClack(
	candidates: PluginMcpOAuthCandidate[],
): Promise<PluginMcpOAuthCandidate[]> {
	const p = await import("@clack/prompts");
	const action = await p.select({
		message: "Authorize plugin MCP servers now?",
		options: [
			{
				value: "all",
				label: "Authorize all",
				hint: "open browser authorization for each server",
			},
			{
				value: "choose",
				label: "Choose servers",
				hint: "select which servers to authorize",
			},
			{
				value: "skip",
				label: "Skip",
			},
		],
	});
	if (p.isCancel(action) || action === "skip") {
		return [];
	}
	if (action === "all") {
		return candidates;
	}

	const selectedNames = await p.multiselect({
		message: "Select MCP servers to authorize",
		options: candidates.map((candidate) => ({
			value: candidate.name,
			label: candidate.name,
			hint: `${candidate.transportType} [${candidate.pluginName}]`,
		})),
		required: false,
	});
	if (p.isCancel(selectedNames) || !Array.isArray(selectedNames)) {
		return [];
	}
	const selected = new Set(selectedNames);
	return candidates.filter((candidate) => selected.has(candidate.name));
}

async function authorizeMcpOAuthCandidate(
	candidate: PluginMcpOAuthCandidate,
): Promise<void> {
	const { authorizeMcpServerOAuthWithBrowser } = await import(
		"../wizards/mcp/oauth"
	);
	await authorizeMcpServerOAuthWithBrowser(candidate.name, {
		throwOnError: true,
	});
}

async function runPluginMcpOAuthFollowup(
	candidates: PluginMcpOAuthCandidate[],
	options: PluginInstallCommandOptions,
): Promise<void> {
	if (candidates.length === 0) {
		return;
	}

	if (!isInteractivePluginInstall(options)) {
		options.io?.writeln("Plugin MCP servers may require OAuth authorization:");
		for (const candidate of candidates) {
			options.io?.writeln(
				`  ${candidate.name} (${candidate.transportType}, plugin: ${candidate.pluginName})`,
			);
		}
		options.io?.writeln(
			'Run "cline mcp" and choose "Authorize OAuth" to authorize them.',
		);
		return;
	}

	const selected =
		options.mcpOAuth?.selectCandidates !== undefined
			? await options.mcpOAuth.selectCandidates(candidates)
			: await selectMcpOAuthCandidatesWithClack(candidates);
	const authorize = options.mcpOAuth?.authorize ?? authorizeMcpOAuthCandidate;
	for (const candidate of selected) {
		try {
			await authorize(candidate);
		} catch (error) {
			const message = error instanceof Error ? error.message : String(error);
			options.io?.writeErr(
				`Warning: failed to authorize MCP server ${candidate.name}: ${message}. Run "cline mcp" and choose "Authorize OAuth" to retry.`,
			);
		}
	}
}

export async function runPluginInstallCommand(
	options: PluginInstallCommandOptions,
): Promise<number> {
	try {
		const result = await installPlugin(options);
		if (options.json) {
			process.stdout.write(
				JSON.stringify(serializePluginInstallResult(result)),
			);
			return 0;
		}
		options.io?.writeln(`Installed plugin from ${result.source}`);
		options.io?.writeln(`  Path: ${result.installPath}`);
		for (const failure of result.mcpSyncFailures) {
			options.io?.writeErr(
				`Warning: failed to sync plugin MCP servers for ${failure.pluginName ?? failure.pluginPath}: ${failure.message}`,
			);
		}
		await runPluginMcpOAuthFollowup(result.mcpOAuthCandidates, options);
		return 0;
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		options.io?.writeErr(message);
		return 1;
	}
}

export async function runPluginUninstallCommand(
	options: PluginUninstallOptions & { json?: boolean; io?: PluginInstallIo },
): Promise<number> {
	try {
		const result = await uninstallPlugin(options);
		if (options.json) {
			process.stdout.write(JSON.stringify(result));
			return 0;
		}
		options.io?.writeln(`Uninstalled plugin ${result.name}`);
		options.io?.writeln(`  Removed: ${result.installPath}`);
		return 0;
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		options.io?.writeErr(message);
		return 1;
	}
}

import { Command, CommanderError, Option } from "commander";
import { version } from "../../package.json";
import {
	CLI_COMPACTION_MODE_OPTION_DESCRIPTION,
	parseCliCompactionMode,
} from "../utils/compaction-mode";
import type { ParsedArgs } from "../utils/types";

export { CommanderError };

function normalizeAutoApproveValue(
	value: string | boolean | undefined,
): string {
	if (value === undefined || value === true) {
		return "true";
	}
	return String(value);
}

/**
 * Add the shared root-level options to any command.
 */
export function addRootOptions(cmd: Command): Command {
	return (
		cmd
			.option("-p, --plan", "Run in plan mode")
			.option("--json", "Output messages as JSON instead of styled text")
			.option(
				"--auto-approve <boolean>",
				"Set tool auto-approval for all tools (default: true)",
				normalizeAutoApproveValue,
			)
			.option("-c, --cwd <path>", "Working directory")
			.option(
				"--thinking <level>",
				"Set reasoning effort: none|low|medium|high|xhigh. Bare --thinking uses medium; omitted leaves provider default.",
			)
			.option("--compaction <mode>", CLI_COMPACTION_MODE_OPTION_DESCRIPTION)
			.option(
				"-i, --tui",
				"Open the terminal user interface (TUI) for interactive sessions",
			)
			.option("--id <session-id>", "Resume an existing session by ID")
			.option("-P, --provider <id>", "Provider id (default: cline)")
			.option("-k, --key <api-key>", "API key override for this run")
			.option(
				"-m, --model <model-id>",
				"Model to use for the session with the selected provider",
			)
			.option(
				"-s, --system <system-prompt>",
				"Override the default system prompt",
			)
			.option("-z, --zen", "Start a session that runs in the background hub")
			.option(
				"--retries [value]",
				"Number of maximum consecutive mistakes (retries) before exiting (default: 6)",
			)
			.option(
				"-t, --timeout <seconds>",
				"Optional timeout in seconds (default: 0 for no timeout)",
			)
			.option(
				"--acp",
				"Run in Agent Client Protocol (ACP) mode for editor integration",
			)
			.option(
				"--config <path>",
				"Configuration directory (default: ~/.cline/data/settings)",
			)
			.option(
				"--data-dir <path>",
				"Use isolated local state at this directory path (default: ~/.cline)",
			)
			.option(
				"--hooks-dir <path>",
				"Directory path to additional hooks for runtime hook injection (default: ~/.cline/hooks)",
			)
			.option(
				"--worktree",
				"Auto-create a detached git worktree under ~/.cline/worktrees/ and run the task there",
			)
			.option("--update", "Check for updates and install if available")
			.option("--kanban", "Run the kanban app")
			.option("-v, --verbose", "Show verbose output")
			// HIDDEN/LEGACY OPTIONS BELOW
			.addOption(
				// Act mode is the default. Keep the legacy flags accepted for users who
				// still pass them, but do not advertise them in help output.
				new Option("-a, --act", "Run in act mode").hideHelp(),
			)
			.addOption(
				// `-y, --yolo` is still accepted (and behaves the same as before) but
				// hidden from `--help` output.
				new Option(
					"-y, --yolo",
					"Enable yolo mode where agents can use tools without approval with only a small set of tools available.",
				).hideHelp(),
			)
			.addOption(
				// TODO: Refactor teams to resume session without team name
				new Option(
					"--team-name <name>",
					"Override the runtime team state name",
				).hideHelp(),
			)
	);
}

export function createProgram(): Command {
	const program = new Command("cline")
		.description("Cline CLI - AI coding assistant in your terminal")
		.version(version, "-V, --version", "Output the version number")
		.exitOverride() // don't call process.exit
		.configureOutput({
			writeOut: () => {}, // suppress by default; main.ts re-enables for routing
			writeErr: () => {},
		})
		.allowExcessArguments()
		.enablePositionalOptions()
		.argument(
			"[prompt]",
			"Your prompt. Default to start in act mode with auto-approve enabled.",
		);

	addRootOptions(program);

	return program;
}

export function commanderToParsedArgs(program: Command): ParsedArgs {
	const opts = program.opts();

	const result: ParsedArgs = {
		verbose: !!opts.verbose,
		interactive: !!opts.tui,
		outputMode: opts.json ? "json" : "text",
		mode: opts.plan ? "plan" : opts.yolo ? "yolo" : opts.zen ? "zen" : "act",
		sandbox: !!opts.dataDir,
		acpMode: !!opts.acp,
		thinking: false,
		reasoningEffort: undefined,
		defaultToolAutoApprove: true,
		id: opts.id,
	};

	// Approval: last-wins semantics
	if (opts.autoApprove !== undefined) {
		const raw = String(opts.autoApprove).trim().toLowerCase();
		if (raw === "true") {
			result.defaultToolAutoApprove = true;
			result.autoApproveOverride = true;
		} else if (raw === "false") {
			result.defaultToolAutoApprove = false;
			result.autoApproveOverride = false;
		} else if (raw) {
			result.invalidAutoApprove = raw;
		}
	}
	if (opts.yolo) {
		result.defaultToolAutoApprove = true;
		result.autoApproveOverride = true;
	}

	// Timeout validation
	if (opts.timeout !== undefined) {
		const raw = opts.timeout.trim();
		const parsed = Number.parseInt(raw, 10);
		if (raw && Number.isInteger(parsed) && parsed >= 1) {
			result.timeoutSeconds = parsed;
		} else if (raw) {
			result.invalidTimeoutSeconds = raw;
		}
	}

	if (opts.thinking !== undefined) {
		const effort = String(opts.thinking).trim().toLowerCase();
		if (
			effort === "none" ||
			effort === "low" ||
			effort === "medium" ||
			effort === "high" ||
			effort === "xhigh"
		) {
			result.thinkingExplicitlySet = true;
			if (effort === "none") {
				result.thinking = false;
				result.reasoningEffort = undefined;
			} else {
				result.thinking = true;
				result.reasoningEffort = effort;
			}
		} else if (effort) {
			result.invalidThinkingLevel = effort;
		}
	}

	if (opts.compaction !== undefined) {
		const mode = String(opts.compaction).trim().toLowerCase();
		const compactionMode = parseCliCompactionMode(mode);
		if (compactionMode) {
			result.compactionMode = compactionMode;
		} else if (mode) {
			result.invalidCompactionMode = mode;
		}
	}

	// Retries (max consecutive mistakes) validation
	if (opts.retries !== undefined) {
		const raw = opts.retries.trim();
		const parsed = Number.parseInt(raw, 10);
		if (raw && Number.isInteger(parsed) && parsed >= 1) {
			result.retries = parsed;
		} else if (raw) {
			result.invalidRetries = raw;
		}
	}

	// Simple string/number options
	if (opts.dataDir !== undefined) result.dataDir = opts.dataDir;
	if (opts.config !== undefined) result.configDir = opts.config;
	if (opts.hooksDir !== undefined) result.hooksDir = opts.hooksDir;
	if (opts.worktree !== undefined) result.worktree = !!opts.worktree;
	if (opts.cwd !== undefined) result.cwd = opts.cwd;
	if (opts.teamName !== undefined) result.teamName = opts.teamName;
	if (opts.system !== undefined) result.systemPrompt = opts.system;
	if (opts.model !== undefined) result.model = opts.model;
	if (opts.provider !== undefined) result.provider = opts.provider;
	if (opts.key !== undefined) result.key = opts.key;
	else if (opts.apiKey !== undefined) result.key = opts.apiKey;
	if (opts.id !== undefined) result.id = opts.id;

	// Positional args → prompt
	const positional = program.args;
	if (positional.length > 0) {
		result.prompt = positional.join(" ");
	}

	return result;
}

