				return;
			}
			const client = ensured.client;
			try {
				const result = await client.pauseSchedule(scheduleId);
				if (!result) {
					io.writeErr(`schedule not found: ${scheduleId}`);
					fail();
					return;
				}
				emitJsonOrText(!!opts.json, io, result);
			} finally {
				client.close();
			}
