	const resumeCmd = schedule
		.command("resume")
		.description("Resume a schedule")
		.argument("<schedule-id>", "Schedule ID");
	addSharedOptions(resumeCmd);
	resumeCmd.action(
		action(async (scheduleId: string) => {
