			}
		}),
	);

	const triggerCmd = schedule
		.command("trigger")
		.description("Trigger a schedule immediately")
		.argument("<schedule-id>", "Schedule ID");
	addSharedOptions(triggerCmd);
	triggerCmd.action(
		action(async (scheduleId: string) => {
