export const __test__ = {
	findBindingForThread: (
		bindings: ConnectorBindingStore<GoogleChatThreadState>,
		thread: Pick<Thread<GoogleChatThreadState>, "id" | "channelId" | "isDM"> & {
			participantKey?: string;
		},
