function createRuntimeClient(
	responseText: string,
	messages: unknown[] = [
		{
			role: "assistant",
			content: [{ type: "text", text: responseText }],
		},
	],
) {
	const startRuntimeSession = vi.fn(async () => ({ sessionId: "session-1" }));
	const updateSession = vi.fn(async () => undefined);
	const getSession = vi.fn(
		async (sessionId: string): Promise<{ sessionId: string } | undefined> => ({
			sessionId,
		}),
	);
	const abortRuntimeSession = vi.fn(async () => undefined);
	const deleteSession = vi.fn(async () => undefined);
	const sendRuntimeSession = vi.fn(async () => ({
		result: {
			text: responseText,
			finishReason: "stop",
			iterations: 1,
		},
	}));
	const readMessages = vi.fn(async () => messages);
	return {
		client: {
			startRuntimeSession,
			updateSession,
			getSession,
			abortRuntimeSession,
			stopRuntimeSession: abortRuntimeSession,
			deleteSession,
			sendRuntimeSession,
			readMessages,
			streamEvents: vi.fn(() => () => undefined),
		},
		startRuntimeSession,
		updateSession,
		getSession,
		sendRuntimeSession,
		readMessages,
	};
}

function messageText(message: unknown): string {
	if (typeof message === "string") {
		return message;
	}
	if (message && typeof message === "object" && "raw" in message) {
		const raw = (message as { raw: unknown }).raw;
		return typeof raw === "string" ? raw : String(raw);
	}
	return String(message);
}

