import {
	closeSync,
	existsSync,
	mkdirSync,
	openSync,
	statSync,
	truncateSync,
} from "node:fs";
import { dirname, join } from "node:path";
import type { BasicLogger, RuntimeLoggerConfig } from "@cline/core";
import { resolveClineDataDir } from "@cline/core";
import { registerDisposable } from "@cline/shared";
import pino, {
	type DestinationStream,
	type LevelWithSilent,
	type Logger as PinoLogger,
} from "pino";
import { getCliBuildInfo } from "../utils/common";

const loggerCache = new Map<
	string,
	{ logger: PinoLogger; destination?: DestinationStream }
>();
const cleanupTimersByDestination = new Map<string, NodeJS.Timeout>();
const LOG_CLEANUP_INTERVAL_MS = 2 * 24 * 60 * 60 * 1000;

export interface CliLoggerAdapter {
	readonly pino: PinoLogger;
	readonly core: BasicLogger;
	readonly runtimeConfig: RuntimeLoggerConfig;
	child(bindings: Record<string, unknown>): CliLoggerAdapter;
}

interface CreateCliLoggerAdapterInput {
	runtime: "cli" | "rpc-runtime";
	component?: string;
	runtimeConfig?: RuntimeLoggerConfig;
}

const LOG_LEVELS: ReadonlySet<LevelWithSilent> = new Set([
	"trace",
	"debug",
	"info",
	"warn",
	"error",
	"fatal",
	"silent",
]);

function normalizeLogLevel(value: string | undefined): LevelWithSilent {
	const candidate = value?.trim().toLowerCase() as LevelWithSilent | undefined;
	if (!candidate || !LOG_LEVELS.has(candidate)) {
		return "info";
	}
	return candidate;
}

function normalizeRuntimeConfig(input: {
	runtime: "cli" | "rpc-runtime";
	runtimeConfig?: RuntimeLoggerConfig;
}): Required<RuntimeLoggerConfig> {
	const base = input.runtimeConfig;
	const defaultDestination = join(
		resolveClineDataDir(),
		"logs",
		`${getCliBuildInfo().name}.log`,
	);
	const enabledEnv = process.env.CLINE_LOG_ENABLED?.trim();
	const enabled =
		base?.enabled ??
		!(enabledEnv === "0" || enabledEnv?.toLowerCase() === "false");
	const level = normalizeLogLevel(base?.level ?? process.env.CLINE_LOG_LEVEL);
	const destination =
		base?.destination?.trim() ||
		process.env.CLINE_LOG_PATH?.trim() ||
		defaultDestination;
	const name =
		base?.name?.trim() ||
		process.env.CLINE_LOG_NAME?.trim() ||
		`${getCliBuildInfo().name}.${input.runtime}`;
	const bindings = base?.bindings ?? {};

	return {
		enabled,
		level,
		destination,
		name,
		bindings,
	};
}

function getOrCreatePinoLogger(
	config: Required<RuntimeLoggerConfig>,
	runtime: "cli" | "rpc-runtime",
): PinoLogger {
	if (!config.enabled) {
		return pino({
			name: config.name,
			level: "silent",
			enabled: false,
			timestamp: pino.stdTimeFunctions.isoTime,
		});
	}
	const key = `${runtime}|${config.enabled}|${config.level}|${config.destination}|${config.name}`;
	const cached = loggerCache.get(key);
	if (cached) {
		return cached.logger;
	}

	if (loggerCache.size === 0) {
		registerDisposable(shutdownCliLoggerAdapters);
	}

	const destination = createWritableDestination(config.destination, runtime);
	if (destination) {
		cleanupStaleLogFile(config.destination);
		startLogCleanupTimer(config.destination);
	}
	const created = pino(
		{
			name: config.name,
			level: config.level,
			timestamp: pino.stdTimeFunctions.isoTime,
			enabled: config.enabled,
		},
		destination ?? createFallbackDestination(runtime),
	);
	loggerCache.set(key, { logger: created, destination });
	return created;
}

function createWritableDestination(
	destinationPath: string,
	_runtime: "cli" | "rpc-runtime",
): DestinationStream | undefined {
	try {
		mkdirSync(dirname(destinationPath), { recursive: true });
		const fd = openSync(destinationPath, "a");
		closeSync(fd);
		const dest = pino.destination({
			dest: destinationPath,
			mkdir: true,
			sync: true,
		});
		// SonicBoom registers its own process 'exit' handler that calls
		// flushSync().  When the process exits before the async stream is
		// ready (e.g. --help, --version) that handler throws
		// "sonic boom is not ready yet".  Wrap flushSync so it silently
		// no-ops instead of throwing.
		const origFlushSync = dest.flushSync.bind(dest);
		dest.flushSync = () => {
			try {
				origFlushSync();
			} catch {
				// Best-effort: stream not ready or already closed.
			}
		};
		return dest;
	} catch {
		return undefined;
	}
}

function createFallbackDestination(
	runtime: "cli" | "rpc-runtime",
): DestinationStream {
	if (runtime === "cli") {
		return {
			write: (msg) => {
				process.stderr.write(msg);
			},
		};
	}
	return pino.destination({ dest: 2, sync: false });
}

function cleanupStaleLogFile(destination: string): void {
	if (!existsSync(destination)) {
		return;
	}
	try {
		const stats = statSync(destination);
		const ageMs = Date.now() - stats.mtimeMs;
		if (ageMs >= LOG_CLEANUP_INTERVAL_MS) {
			truncateSync(destination, 0);
		}
	} catch {
		// no-op: cleanup is best-effort.
	}
}

function startLogCleanupTimer(destination: string): void {
	if (cleanupTimersByDestination.has(destination)) {
		return;
	}
	const timer = setInterval(() => {
		try {
			truncateSync(destination, 0);
		} catch {
			// no-op: cleanup is best-effort.
		}
	}, LOG_CLEANUP_INTERVAL_MS);
	timer.unref();
	cleanupTimersByDestination.set(destination, timer);
}

function stopLogCleanupTimers(): void {
	for (const timer of cleanupTimersByDestination.values()) {
		clearInterval(timer);
	}
	cleanupTimersByDestination.clear();
}

function toPinoFields(
	metadata?: Record<string, unknown>,
): Record<string, unknown> | undefined {
	if (!metadata) {
		return undefined;
	}
	const { error, ...rest } = metadata;
	if (error === undefined) {
		return Object.keys(rest).length > 0 ? rest : undefined;
	}
	const fields: Record<string, unknown> = { ...rest, err: error };
	return fields;
}

function createCoreLogger(logger: PinoLogger): BasicLogger {
	return {
		debug: (message, metadata) => {
			const fields = toPinoFields(metadata);
			if (fields) {
				logger.debug(fields, message);
				return;
			}
			logger.debug(message);
		},
		log: (message, metadata) => {
			const severity = metadata?.severity;
			const rest =
				metadata === undefined
					? undefined
					: (() => {
							const { severity: _ignored, ...r } = metadata;
							return Object.keys(r).length > 0 ? r : undefined;
						})();
			const fields = toPinoFields(rest);
			const levelFn =
				severity === "warn"
					? logger.warn
					: severity === "error"
						? logger.error
						: logger.info;
			if (fields) {
				levelFn.call(logger, fields, message);
				return;
			}
			levelFn.call(logger, message);
		},
		error: (message, metadata) => {
			const fields = toPinoFields(metadata);
			if (fields) {
				logger.error(fields, message);
				return;
			}
			logger.error(message);
		},
	};
}

function createAdapterFromPino(
	logger: PinoLogger,
	runtimeConfig: Required<RuntimeLoggerConfig>,
): CliLoggerAdapter {
	return {
		pino: logger,
		core: createCoreLogger(logger),
		runtimeConfig,
		child: (bindings) =>
			createAdapterFromPino(logger.child(bindings), runtimeConfig),
	};
}

export function createCliLoggerAdapter(
	input: CreateCliLoggerAdapterInput,
): CliLoggerAdapter {
	const runtimeConfig = normalizeRuntimeConfig({
		runtime: input.runtime,
		runtimeConfig: input.runtimeConfig,
	});
	const baseLogger = getOrCreatePinoLogger(runtimeConfig, input.runtime);
	const logger = baseLogger.child({
		...runtimeConfig.bindings,
		...(input.component ? { component: input.component } : {}),
	});
	return createAdapterFromPino(logger, runtimeConfig);
}

function isIgnorableLoggerShutdownError(error: unknown): boolean {
	const message = error instanceof Error ? error.message : String(error);
	return (
		message.includes("sonic boom is not ready yet") ||
		message.includes("SonicBoom destroyed")
	);
}

function flushLoggerEntry(entry: {
	logger: PinoLogger;
	destination?: DestinationStream;
}): void {
	try {
		const syncFlusher = entry.destination as DestinationStream & {
			flushSync?: () => void;
		};
		if (syncFlusher && typeof syncFlusher.flushSync === "function") {
			syncFlusher.flushSync();
			return;
		}
		if (typeof entry.logger.flush === "function") {
			entry.logger.flush();
		}
	} catch (error) {
		if (!isIgnorableLoggerShutdownError(error)) {
			throw error;
		}
	}
}

export function flushCliLoggerAdapters(): void {
	for (const entry of loggerCache.values()) {
		try {
			flushLoggerEntry(entry);
		} catch {
			// no-op: shutdown flush is best-effort.
		}
	}
}

export function shutdownCliLoggerAdapters(): void {
	for (const entry of loggerCache.values()) {
		try {
			flushLoggerEntry(entry);
		} catch {
			// no-op: shutdown flush is best-effort.
		}
		try {
			const closableDestination = entry.destination as DestinationStream & {
				end?: () => void;
			};
			closableDestination.end?.();
		} catch (error) {
			if (!isIgnorableLoggerShutdownError(error)) {
				// no-op: shutdown close is best-effort.
			}
		}
	}
	loggerCache.clear();
	stopLogCleanupTimers();
}

import type { BasicLogger } from "@cline/core";
import { createCliLoggerAdapter, flushCliLoggerAdapters } from "./adapter";

export function logCliError(
	logger: BasicLogger | undefined,
	message: string,
	metadata: Record<string, unknown> & { error?: unknown } = {},
): void {
	if (logger?.error) {
		logger.error(message, metadata);
		return;
	}
	logger?.log(message, {
		...metadata,
		severity: "error",
	});
}

export function logCliProcessError(kind: string, error: unknown): void {
	try {
		const logger = createCliLoggerAdapter({
			runtime: "cli",
			component: "process",
		});
		logCliError(logger.core, "CLI process error", { kind, error });
		flushCliLoggerAdapters();
	} catch {
		// Process-level logging is best-effort; stderr still gets the error.
	}
}

import { createCliLoggerAdapter } from "./adapter";

interface LogSpawnedProcessInput {
	component: string;
	command: string[];
	childPid?: number;
	cwd?: string;
	detached?: boolean;
	metadata?: Record<string, unknown>;
}

export function logSpawnedProcess(input: LogSpawnedProcessInput): void {
	try {
		const logger = createCliLoggerAdapter({
			runtime: "cli",
			component: input.component,
		});
		logger.core.log("Process spawned", {
			command: input.command.join(" "),
			commandArgs: input.command.slice(1),
			executable: input.command[0],
			childPid: input.childPid,
			cwd: input.cwd,
			detached: input.detached,
			...input.metadata,
		});
	} catch {
		// Best-effort logging only.
	}
}

