import {
	formatDisplayUserInput,
	type Message,
	normalizeUserInput,
} from "@cline/shared";

const FORK_TITLE_SUFFIX = " (fork)";
const MAX_FORK_TITLE_LENGTH = 120;

function normalizeForkTitleText(value: string | undefined): string | undefined {
	const normalized = normalizeUserInput(formatDisplayUserInput(value))
		.replace(/\s+/g, " ")
		.trim();
	return normalized || undefined;
}

function truncateForForkSuffix(base: string): string {
	const maxBaseLength = MAX_FORK_TITLE_LENGTH - FORK_TITLE_SUFFIX.length;
	if (base.length <= maxBaseLength) {
		return base;
	}
	return base.slice(0, maxBaseLength).trimEnd();
}

function extractMessageText(message: Message): string | undefined {
	if (typeof message.content === "string") {
		return message.content;
	}
	const parts: string[] = [];
	for (const block of message.content) {
		if (block.type === "text") {
			parts.push(block.text);
		}
	}
	return parts.join("\n").trim() || undefined;
}

function inferForkTitleFromMessages(messages: Message[]): string | undefined {
	for (const role of ["user", "assistant"] as const) {
		for (const message of messages) {
			if (message.role !== role) {
				continue;
			}
			const text = extractMessageText(message);
			const normalized = normalizeForkTitleText(text);
			if (normalized) {
				return normalized;
			}
		}
	}
	return undefined;
}

export function deriveForkSessionTitle(input: {
	sourceTitle?: string | null;
	sourcePrompt?: string | null;
	messages: Message[];
}): string {
	const base =
		normalizeForkTitleText(input.sourceTitle ?? undefined) ??
		normalizeForkTitleText(input.sourcePrompt ?? undefined) ??
		inferForkTitleFromMessages(input.messages) ??
		"Untitled";
	return `${truncateForForkSuffix(base)}${FORK_TITLE_SUFFIX}`;
}

import { describe, expect, it } from "vitest";
import { createMistakeLimitDecisionResolver } from "./mistakes";

describe("createMistakeLimitDecisionResolver", () => {
	it("stops immediately when auto-approve is enabled", async () => {
		const decide = createMistakeLimitDecisionResolver({
			autoApproveAllRef: { current: true },
			askQuestionRef: { current: null },
		});

		await expect(
			decide({
				iteration: 1,
				consecutiveMistakes: 3,
				maxConsecutiveMistakes: 3,
				reason: "api_error",
			}),
		).resolves.toMatchObject({
			action: "stop",
		});
	});

	it("continues with retry guidance for the default answer", async () => {
		const decide = createMistakeLimitDecisionResolver({
			autoApproveAllRef: { current: false },
			askQuestionRef: { current: null },
		});

		await expect(
			decide({
				iteration: 4,
				consecutiveMistakes: 2,
				maxConsecutiveMistakes: 3,
				reason: "tool_execution_failed",
				details: "bad args",
			}),
		).resolves.toMatchObject({
			action: "continue",
			guidance: expect.stringContaining("retry with a different approach"),
		});
	});

	it("honors an explicit stop answer", async () => {
		const decide = createMistakeLimitDecisionResolver({
			autoApproveAllRef: { current: false },
			askQuestionRef: { current: async () => "Stop this run" },
		});

		await expect(
			decide({
				iteration: 4,
				consecutiveMistakes: 2,
				maxConsecutiveMistakes: 3,
				reason: "invalid_tool_call",
			}),
		).resolves.toMatchObject({
			action: "stop",
		});
	});
});

export interface MistakeLimitContext {
	iteration: number;
	consecutiveMistakes: number;
	maxConsecutiveMistakes: number;
	reason: "api_error" | "invalid_tool_call" | "tool_execution_failed";
	details?: string;
}

export function createMistakeLimitDecisionResolver(input: {
	autoApproveAllRef: { current: boolean };
	askQuestionRef: {
		current: ((question: string, options: string[]) => Promise<string>) | null;
	};
}) {
	return async (context: MistakeLimitContext) => {
		if (input.autoApproveAllRef.current) {
			return {
				action: "stop" as const,
				reason: `max consecutive mistakes reached (${context.maxConsecutiveMistakes}) in yolo mode`,
			};
		}
		const detail = context.details?.trim();
		const summary = detail
			? `${context.reason}: ${detail}`
			: `${context.reason} at iteration ${context.iteration}`;
		const questionText = `mistake_limit_reached (${context.consecutiveMistakes}/${context.maxConsecutiveMistakes})\nLatest: ${summary}\nHow should Cline continue?`;
		const questionOptions = ["Try a different approach", "Stop this run"];
		const answer = input.askQuestionRef.current
			? await input.askQuestionRef.current(questionText, questionOptions)
			: (questionOptions[0] ?? "");
		const normalized = answer.trim().toLowerCase();
		if (
			normalized === "2" ||
			normalized === "stop this run" ||
			normalized === "stop" ||
			normalized === "n" ||
			normalized === "no"
		) {
			return {
				action: "stop" as const,
				reason: "stopped after mistake_limit_reached prompt",
			};
		}
		if (
			normalized === "1" ||
			normalized === "try a different approach" ||
			normalized.length === 0
		) {
			return {
				action: "continue" as const,
				guidance:
					"mistake_limit_reached: retry with a different approach, validate tool parameters before calls, and avoid repeating failed steps.",
			};
		}
		return {
			action: "continue" as const,
			guidance: `mistake_limit_reached: ${answer.trim()}`,
		};
	};
}

