import type { UserInstructionConfigService } from "@cline/core";
import { HubSessionClient } from "@cline/core";
import type { ChatStartSessionRequest } from "@cline/shared";
import { resolveCliSessionMetadata } from "../utils/enterprise";
import { ensureCliHubServer } from "../utils/hub-runtime";
import { c, emitJsonLine, writeErr, writeln } from "../utils/output";
import type { Config } from "../utils/types";
import { buildUserInputMessage } from "./prompt";

const ZEN_DISPATCH_ACK_TIMEOUT_MS = 5_000;

/**
 * Zen mode: fire-and-forget dispatch of a task to the background hub.
 *
 * Unlike a normal CLI run, zen mode does not stay connected to watch the
 * session stream. It submits the turn to the hub and exits immediately. The
 * hub continues to execute the agent loop in the background and, on
 * completion, already publishes a `ui.notify` event which the menubar app
 * (if installed) surfaces as a system notification. If the menubar app is not
 * running, users can still find the result later via `cline history`.
 *
 * Because no human is available to approve tool calls once the CLI exits,
 * zen mode forces full tool auto-approval (same semantics as yolo) and only
 * works with a hub-backed session. Sandbox mode (enabled via --data-dir) is
 * incompatible with zen because sandbox requires a local backend that
 * terminates with the CLI.
 */
export async function runZen(
	prompt: string,
	config: Config,
	userInstructionService?: UserInstructionConfigService,
): Promise<void> {
	if (config.sandbox) {
		writeErr(
			"--zen cannot be combined with --data-dir (sandbox requires a local backend).",
		);
		process.exitCode = 1;
		return;
	}
	if (
		process.env.CLINE_SESSION_BACKEND_MODE?.trim().toLowerCase() === "local"
	) {
		writeErr(
			"--zen requires the hub backend but CLINE_SESSION_BACKEND_MODE=local is set.",
		);
		process.exitCode = 1;
		return;
	}

	const workspaceRoot = config.workspaceRoot ?? config.cwd;
	let hubUrl: string;
	let hubAuthToken: string;
	try {
		const hub = await ensureCliHubServer(workspaceRoot);
		hubUrl = hub.url;
		hubAuthToken = hub.authToken;
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		writeErr(`failed to start background hub: ${message}`);
		process.exitCode = 1;
		return;
	}

	const sessionClient = new HubSessionClient({
		address: hubUrl,
		authToken: hubAuthToken,
		clientType: "cli-zen",
		displayName: "Cline CLI (zen)",
		workspaceRoot,
		cwd: config.cwd,
	});

	let sessionId: string | undefined;
	try {
		await sessionClient.connect();

		const {
			prompt: userInput,
			userImages,
			userFiles,
		} = await buildUserInputMessage(prompt, userInstructionService);

		const startRequest: ChatStartSessionRequest = {
			workspaceRoot,
			cwd: config.cwd,
			provider: config.providerId,
			model: config.modelId,
			apiKey: config.apiKey || undefined,
			systemPrompt: config.systemPrompt,
			// Zen runs unattended: use yolo-style tool behavior so tool calls are
			// auto-approved without a human in the loop.
			mode: "yolo",
			rules: undefined,
			enableTools: true,
			enableSpawn: false,
			enableTeams: false,
			autoApproveTools: true,
			toolExecutors: ["submit"],
			source: "cline-cli-zen",
			interactive: false,
			logger: config.loggerConfig,
		};

		const started = await sessionClient.startRuntimeSession(startRequest);
		sessionId = started.sessionId;
		const remoteConfigMetadata = await resolveCliSessionMetadata(
			sessionId,
		).catch(() => undefined);
		if (remoteConfigMetadata && sessionClient.updateSession) {
			await sessionClient
				.updateSession({
					sessionId,
					metadata: remoteConfigMetadata,
				})
				.catch(() => undefined);
		}

		// Wait for the hub to acknowledge `session.send_input` before closing the
		// socket. That confirms the prompt frame reached the hub and was accepted
		// for execution, avoiding silent drops on slow or loaded systems.
		await Promise.race([
			sessionClient.sendRuntimeSession(started.sessionId, {
				config: startRequest,
				prompt: userInput,
				attachments:
					userImages.length > 0 || userFiles.length > 0
						? {
								userImages: userImages.length > 0 ? userImages : undefined,
								userFiles:
									userFiles.length > 0
										? userFiles.map((content, index) => ({
												name: `attachment-${index + 1}`,
												content,
											}))
										: undefined,
							}
						: undefined,
			}),
			new Promise<never>((_, reject) => {
				setTimeout(() => {
					reject(
						new Error(
							`timed out waiting for hub to acknowledge zen dispatch after ${ZEN_DISPATCH_ACK_TIMEOUT_MS} ms`,
						),
					);
				}, ZEN_DISPATCH_ACK_TIMEOUT_MS);
			}),
		]);

		if (config.outputMode === "json") {
			emitJsonLine("stdout", {
				type: "zen_dispatched",
				sessionId,
				hubUrl,
				workspaceRoot,
			});
		} else {
			writeln(
				`${c.dim}[zen]${c.reset} the CLI is exiting; the session ${sessionId} will continue running in the background.`,
			);
			writeln(
				`${c.dim}[zen]${c.reset} check ${c.dim} history${c.reset} later to see the result.`,
			);
		}
		process.exitCode = 0;
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		if (config.outputMode === "json") {
			emitJsonLine("stderr", {
				type: "zen_error",
				sessionId,
				message,
			});
		} else {
			writeErr(`zen dispatch failed: ${message}`);
		}
		process.exitCode = 1;
	} finally {
		sessionClient.close();
	}
}

import type { AgentEvent } from "@cline/core";
import { describe, expect, it, vi } from "vitest";
import { subscribeToAgentEvents } from "./session-events";

type AgentDoneEvent = Extract<AgentEvent, { type: "done" }>;

describe("subscribeToAgentEvents", () => {
	const done = ({
		iterations,
		text = "ok",
		usage,
	}: {
		iterations: number;
		text?: string;
		usage?: AgentDoneEvent["usage"];
	}): AgentDoneEvent => ({
		type: "done",
		reason: "completed",
		iterations,
		text,
		...(usage ? { usage } : {}),
	});

	it("suppresses duplicate structured done events", () => {
		const sessionManager = {
			subscribe: vi.fn((listener: (event: unknown) => void) => {
				listener({
					type: "agent_event",
					payload: {
						event: done({ iterations: 5 }),
					},
				});
				listener({
					type: "agent_event",
					payload: {
						event: done({ iterations: 0, text: "" }),
					},
				});
				return () => {};
			}),
		};
		const onAgentEvent = vi.fn();

		subscribeToAgentEvents(sessionManager, onAgentEvent);

		expect(onAgentEvent).toHaveBeenCalledTimes(1);
		expect(onAgentEvent).toHaveBeenCalledWith(
			expect.objectContaining({ iterations: 5 }),
		);
	});

	it("suppresses duplicate chunk-parsed done events", () => {
		const sessionManager = {
			subscribe: vi.fn((listener: (event: unknown) => void) => {
				listener({
					type: "chunk",
					payload: {
						stream: "agent",
						chunk: JSON.stringify(done({ iterations: 5 })),
					},
				});
				listener({
					type: "chunk",
					payload: {
						stream: "agent",
						chunk: JSON.stringify(done({ iterations: 0 })),
					},
				});
				return () => {};
			}),
		};
		const onAgentEvent = vi.fn();

		subscribeToAgentEvents(sessionManager, onAgentEvent);

		expect(onAgentEvent).toHaveBeenCalledTimes(1);
		expect(onAgentEvent).toHaveBeenCalledWith(
			expect.objectContaining({ iterations: 5 }),
		);
	});

	it("emits a later richer structured done event", () => {
		const richUsage: AgentDoneEvent["usage"] = {
			inputTokens: 10,
			outputTokens: 20,
		};
		const sessionManager = {
			subscribe: vi.fn((listener: (event: unknown) => void) => {
				listener({
					type: "agent_event",
					payload: {
						event: done({ iterations: 0, text: "" }),
					},
				});
				listener({
					type: "agent_event",
					payload: {
						event: done({
							iterations: 5,
							text: "final answer",
							usage: richUsage,
						}),
					},
				});
				return () => {};
			}),
		};
		const onAgentEvent = vi.fn();

		subscribeToAgentEvents(sessionManager, onAgentEvent);

		expect(onAgentEvent).toHaveBeenCalledTimes(2);
		expect(onAgentEvent).toHaveBeenLastCalledWith(
			expect.objectContaining({
				iterations: 5,
				text: "final answer",
				usage: richUsage,
			}),
		);
	});

	it("emits a richer structured done after a chunk fallback done", () => {
		const sessionManager = {
			subscribe: vi.fn((listener: (event: unknown) => void) => {
				listener({
					type: "chunk",
					payload: {
						stream: "agent",
						chunk: JSON.stringify(done({ iterations: 0, text: "" })),
					},
				});
				listener({
					type: "agent_event",
					payload: {
						event: done({ iterations: 5, text: "final answer" }),
					},
				});
				return () => {};
			}),
		};
		const onAgentEvent = vi.fn();

		subscribeToAgentEvents(sessionManager, onAgentEvent);

		expect(onAgentEvent).toHaveBeenCalledTimes(2);
		expect(onAgentEvent).toHaveBeenLastCalledWith(
			expect.objectContaining({ iterations: 5, text: "final answer" }),
		);
	});

	it("emits done events for separate turns", () => {
		const sessionManager = {
			subscribe: vi.fn((listener: (event: unknown) => void) => {
				listener({
					type: "agent_event",
					payload: {
						event: done({ iterations: 5 }),
					},
				});
				listener({
					type: "agent_event",
					payload: {
						event: { type: "iteration_start", iteration: 1 },
					},
				});
				listener({
					type: "agent_event",
					payload: {
						event: done({ iterations: 1 }),
					},
				});
				return () => {};
			}),
		};
		const onAgentEvent = vi.fn();

		subscribeToAgentEvents(sessionManager, onAgentEvent);

		expect(onAgentEvent).toHaveBeenCalledTimes(3);
		expect(onAgentEvent).toHaveBeenLastCalledWith(
			expect.objectContaining({ type: "done", iterations: 1 }),
		);
	});

	it("keeps teammate usage while suppressing teammate output", () => {
		const teammateText: AgentEvent = {
			type: "content_start",
			contentType: "text",
			text: "hidden teammate output",
		};
		const teammateUsage: AgentEvent = {
			type: "usage",
			inputTokens: 7,
			outputTokens: 5,
			cost: 0.12,
			totalInputTokens: 7,
			totalOutputTokens: 5,
			totalCost: 0.12,
		};
		const leadText: AgentEvent = {
			type: "content_start",
			contentType: "text",
			text: "lead output",
		};
		const sessionManager = {
			subscribe: vi.fn((listener: (event: unknown) => void) => {
				listener({
					type: "agent_event",
					payload: {
						teamRole: "teammate",
						event: teammateText,
					},
				});
				listener({
					type: "agent_event",
					payload: {
						teamRole: "teammate",
						event: teammateUsage,
					},
				});
				listener({
					type: "agent_event",
					payload: {
						teamRole: "lead",
						event: leadText,
					},
				});
				return () => {};
			}),
		};
		const onAgentEvent = vi.fn();

		subscribeToAgentEvents(sessionManager, onAgentEvent);

		expect(onAgentEvent).toHaveBeenCalledTimes(2);
		expect(onAgentEvent).toHaveBeenNthCalledWith(1, teammateUsage);
		expect(onAgentEvent).toHaveBeenNthCalledWith(2, leadText);
	});
});

import { EventEmitter } from "node:events";
import type {
	AgentEvent,
	CoreSessionEvent,
	RuntimeHostSubscribeOptions,
	TeamEvent,
} from "@cline/core";

export const getUIEventEmitter = () =>
	new EventEmitter() as InteractiveEventBridge;

export interface PendingPromptSnapshot {
	sessionId: string;
	prompts: Array<{
		id: string;
		prompt: string;
		delivery: "queue" | "steer";
		attachmentCount: number;
	}>;
}

export interface PendingPromptSubmittedEvent {
	sessionId: string;
	id: string;
	prompt: string;
	delivery: "queue" | "steer";
	attachmentCount: number;
}

interface InteractiveEventBridge {
	on(event: "agent", listener: (event: AgentEvent) => void): this;
	on(event: "team", listener: (event: TeamEvent) => void): this;
	on(
		event: "pending-prompts",
		listener: (event: PendingPromptSnapshot) => void,
	): this;
	on(
		event: "pending-prompt-submitted",
		listener: (event: PendingPromptSubmittedEvent) => void,
	): this;
	off(event: "agent", listener: (event: AgentEvent) => void): this;
	off(event: "team", listener: (event: TeamEvent) => void): this;
	off(
		event: "pending-prompts",
		listener: (event: PendingPromptSnapshot) => void,
	): this;
	off(
		event: "pending-prompt-submitted",
		listener: (event: PendingPromptSubmittedEvent) => void,
	): this;
	emit(event: "agent", payload: AgentEvent): boolean;
	emit(event: "team", payload: TeamEvent): boolean;
	emit(event: "pending-prompts", payload: PendingPromptSnapshot): boolean;
	emit(
		event: "pending-prompt-submitted",
		payload: PendingPromptSubmittedEvent,
	): boolean;
}

type SessionManagerSubscriber = {
	subscribe(
		listener: (event: unknown) => void,
		options?: RuntimeHostSubscribeOptions,
	): () => void;
};

type AgentDoneEvent = Extract<AgentEvent, { type: "done" }>;

function doneEventCompletenessScore(event: AgentDoneEvent): number {
	let score = 0;
	if (typeof event.text === "string" && event.text.trim().length > 0) {
		score += 2;
	}
	if (typeof event.iterations === "number" && event.iterations > 0) {
		score += 2;
	}
	if (event.usage) {
		score += 3;
	}
	if (event.reason !== "completed") {
		score += 1;
	}
	return score;
}

export function subscribeToAgentEvents(
	sessionManager: SessionManagerSubscriber,
	onAgentEvent: (event: AgentEvent) => void,
	options?: RuntimeHostSubscribeOptions,
): () => void {
	let hasSeenStructuredAgentEvent = false;
	let lastDoneEvent: AgentDoneEvent | undefined;
	const emitAgentEvent = (event: AgentEvent): void => {
		if (event.type === "iteration_start") {
			lastDoneEvent = undefined;
		}
		if (event.type === "done") {
			if (
				lastDoneEvent &&
				doneEventCompletenessScore(event) <=
					doneEventCompletenessScore(lastDoneEvent)
			) {
				return;
			}
			lastDoneEvent = event;
		}
		onAgentEvent(event);
	};
	return sessionManager.subscribe((event: unknown) => {
		const typedEvent = event as
			| { type: "agent_event"; payload: { event: AgentEvent } }
			| { type: "chunk"; payload: { stream: string; chunk: string } }
			| { type: string; payload?: unknown };
		if (typedEvent.type === "agent_event") {
			hasSeenStructuredAgentEvent = true;
			const payload = typedEvent.payload as
				| { event?: AgentEvent; teamRole?: string }
				| undefined;
			// Skip teammate output because it would interleave with lead output on
			// shared stdout, but keep usage events so session totals update live.
			if (
				payload?.event &&
				(payload.teamRole !== "teammate" || payload.event.type === "usage")
			) {
				emitAgentEvent(payload.event);
			}
			return;
		}

		const chunkEvent = event as
			| { type: "chunk"; payload: { stream: string; chunk: string } }
			| { type: string; payload?: unknown };
		if (
			chunkEvent.type !== "chunk" ||
			!chunkEvent.payload ||
			typeof chunkEvent.payload !== "object"
		) {
			return;
		}
		if (hasSeenStructuredAgentEvent) {
			return;
		}
		const payload = chunkEvent.payload as { stream?: string; chunk?: string };
		if (payload.stream !== "agent" || typeof payload.chunk !== "string") {
			return;
		}
		try {
			emitAgentEvent(JSON.parse(payload.chunk) as AgentEvent);
		} catch {
			// Best-effort event parsing path.
		}
	}, options);
}

export function subscribeToPendingPromptEvents(
	sessionManager: SessionManagerSubscriber,
	handlers: {
		onPendingPrompts: (event: PendingPromptSnapshot) => void;
		onPendingPromptSubmitted: (event: PendingPromptSubmittedEvent) => void;
	},
): () => void {
	return sessionManager.subscribe((event: unknown) => {
		const typedEvent = event as CoreSessionEvent;
		if (typedEvent.type === "pending_prompts") {
			handlers.onPendingPrompts(typedEvent.payload);
			return;
		}
		if (typedEvent.type === "pending_prompt_submitted") {
			handlers.onPendingPromptSubmitted(typedEvent.payload);
		}
	});
}

import { describe, expect, it } from "vitest";
import {
	applyInteractiveAutoApproveOverride,
	cloneToolPolicies,
	resolveInteractiveAutoApprovePolicy,
} from "./tool-policies";

describe("tool policy helpers", () => {
	it("keeps safe tools auto-approved when toggled off", () => {
		const baseline = {
			"*": { autoApprove: true },
			run_commands: { autoApprove: true, enabled: true },
			read_files: { enabled: true },
		};
		const target = cloneToolPolicies(baseline);

		applyInteractiveAutoApproveOverride({
			targetPolicies: target,
			baselinePolicies: baseline,
			enabled: false,
		});

		expect(target).toEqual({
			"*": { autoApprove: false },
			ask_followup_question: { autoApprove: true },
			ask_question: { autoApprove: true },
			fetch_web_content: { autoApprove: true },
			run_commands: { autoApprove: false, enabled: true },
			read_files: { autoApprove: true, enabled: true },
			search_codebase: { autoApprove: true },
			skills: { autoApprove: true },
			submit_and_exit: { autoApprove: true },
		});
	});

	it("keeps explicit per-tool approval requirements when toggled off", () => {
		const baseline = {
			"*": { autoApprove: true },
			ask_question: { autoApprove: false, enabled: true },
			editor: { autoApprove: true, enabled: true },
		};
		const target = cloneToolPolicies(baseline);

		applyInteractiveAutoApproveOverride({
			targetPolicies: target,
			baselinePolicies: baseline,
			enabled: false,
		});

		expect(target).toMatchObject({
			"*": { autoApprove: false },
			ask_question: { autoApprove: false, enabled: true },
			editor: { autoApprove: false, enabled: true },
		});
	});

	it("forces all baseline policies to auto-approve when toggled back on", () => {
		const baseline = {
			"*": { autoApprove: false },
			run_commands: { autoApprove: true, enabled: true },
			editor: { autoApprove: false, enabled: true },
		};
		const target = cloneToolPolicies(baseline);

		applyInteractiveAutoApproveOverride({
			targetPolicies: target,
			baselinePolicies: baseline,
			enabled: false,
		});
		applyInteractiveAutoApproveOverride({
			targetPolicies: target,
			baselinePolicies: baseline,
			enabled: true,
		});

		expect(target).toEqual({
			"*": { autoApprove: true },
			run_commands: { autoApprove: true, enabled: true },
			editor: { autoApprove: true, enabled: true },
		});
	});

	it("resolves live per-tool policies from the interactive auto-approve state", () => {
		const baseline = {
			"*": { autoApprove: false },
			read_files: { enabled: true },
			editor: { autoApprove: false, enabled: true },
		};

		expect(
			resolveInteractiveAutoApprovePolicy({
				toolName: "editor",
				baselinePolicies: baseline,
				enabled: true,
			}),
		).toEqual({ autoApprove: true, enabled: true });
		expect(
			resolveInteractiveAutoApprovePolicy({
				toolName: "run_commands",
				baselinePolicies: baseline,
				enabled: false,
			}),
		).toEqual({ autoApprove: false });
		expect(
			resolveInteractiveAutoApprovePolicy({
				toolName: "read_files",
				baselinePolicies: baseline,
				enabled: false,
			}),
		).toEqual({ autoApprove: true, enabled: true });
	});
});

import type { ToolPolicy } from "@cline/core";

const SAFE_AUTO_APPROVE_TOOL_NAMES = [
	"ask_followup_question",
	"ask_question",
	"fetch_web_content",
	"read_files",
	"search_codebase",
	"skills",
	"submit_and_exit",
];

const SAFE_AUTO_APPROVE_TOOLS = new Set<string>(SAFE_AUTO_APPROVE_TOOL_NAMES);

function clonePolicy(policy: ToolPolicy | undefined): ToolPolicy {
	return policy ? { ...policy } : {};
}

export function cloneToolPolicies(
	policies: Record<string, ToolPolicy>,
): Record<string, ToolPolicy> {
	return Object.fromEntries(
		Object.entries(policies).map(([name, policy]) => [
			name,
			clonePolicy(policy),
		]),
	);
}

export function resolveInteractiveAutoApprovePolicy(input: {
	toolName: string;
	baselinePolicies: Record<string, ToolPolicy>;
	enabled: boolean;
}): ToolPolicy {
	const toolPolicy = input.baselinePolicies[input.toolName] ?? {};
	const baselinePolicy = {
		...(input.baselinePolicies["*"] ?? {}),
		...toolPolicy,
	};
	return {
		...baselinePolicy,
		autoApprove: input.enabled
			? true
			: SAFE_AUTO_APPROVE_TOOLS.has(input.toolName)
				? (toolPolicy.autoApprove ?? true)
				: false,
	};
}

export function applyInteractiveAutoApproveOverride(input: {
	targetPolicies: Record<string, ToolPolicy>;
	baselinePolicies: Record<string, ToolPolicy>;
	enabled: boolean;
}): void {
	const nextPolicies: Record<string, ToolPolicy> = input.enabled
		? Object.fromEntries(
				Object.entries(input.baselinePolicies).map(([name, policy]) => [
					name,
					{
						...policy,
						autoApprove: true,
					},
				]),
			)
		: Object.fromEntries(
				Object.entries(input.baselinePolicies).map(([name, policy]) => [
					name,
					{
						...policy,
						autoApprove: resolveInteractiveAutoApprovePolicy({
							toolName: name,
							baselinePolicies: input.baselinePolicies,
							enabled: false,
						}).autoApprove,
					},
				]),
			);

	if (!input.enabled) {
		for (const name of SAFE_AUTO_APPROVE_TOOL_NAMES) {
			nextPolicies[name] ??= { autoApprove: true };
		}
	}

	const globalPolicy = clonePolicy(nextPolicies["*"]);
	globalPolicy.autoApprove = input.enabled;
	nextPolicies["*"] = globalPolicy;

	for (const key of Object.keys(input.targetPolicies)) {
		delete input.targetPolicies[key];
	}
	for (const [name, policy] of Object.entries(nextPolicies)) {
		input.targetPolicies[name] = policy;
	}
}

import {
	type BuiltinToolAvailabilityContext,
	getCoreBuiltinToolCatalog,
	resolveDisabledToolNames,
	type ToolCatalogEntry,
} from "@cline/core";

export type { ToolCatalogEntry } from "@cline/core";

export function getToolCatalog(
	availabilityContext?: BuiltinToolAvailabilityContext,
): ToolCatalogEntry[] {
	return getCoreBuiltinToolCatalog({
		disabledToolIds: resolveDisabledToolNames(),
		...availabilityContext,
	});
}

