import type { Terminal } from "@microsoft/tui-test/lib/terminal/term";
import { expectVisible } from "../terminal.js";

const TAB_ORDER = [
	"API",
	"Auto-approve",
	"Features",
	"Account",
	"Other",
] as const;

export type SettingsTab = (typeof TAB_ORDER)[number];

/**
 * Navigate to a specific settings tab by pressing Right from the API tab (index 0).
 * Waits for each tab's content to appear before pressing the next key, making
 * navigation deterministic regardless of machine speed.
 */
export async function goToSettingsTab(
	terminal: Terminal,
	tab: SettingsTab,
): Promise<void> {
	const targetIndex = TAB_ORDER.indexOf(tab);
	for (let i = 0; i < targetIndex; i++) {
		terminal.keyRight();
		// Wait for the next tab's content to appear before pressing again
		await assertTabContent(terminal, TAB_ORDER[i + 1]);
	}
}

/** Assert the API tab content is visible */
export async function assertApiTab(terminal: Terminal): Promise<void> {
	await expectVisible(terminal, ["Provider:", "Model ID:"]);
}

/** Assert the Auto-approve tab content is visible */
export async function assertAutoApproveTab(terminal: Terminal): Promise<void> {
	await expectVisible(terminal, [
		"Read project files",
		"Execute safe commands",
		"Edit project files",
	]);
}

/** Assert the Features tab content is visible */
export async function assertFeaturesTab(terminal: Terminal): Promise<void> {
	await expectVisible(terminal, [
		"Subagents",
		"Web tools",
		"Double-check completion",
	]);
}

/** Assert the Account tab content is visible */
export async function assertAccountTab(terminal: Terminal): Promise<void> {
	// The account tab shows sign-in options when not authenticated to Cline
	await expectVisible(terminal, /sign in|sign out/i);
}

/** Assert the Other tab content is visible */
export async function assertOtherTab(terminal: Terminal): Promise<void> {
	await expectVisible(terminal, ["Preferred language:", "Cline v"]);
}

/**
 * Assert the content for a given tab is visible.
 * Used internally by goToSettingsTab to confirm navigation landed correctly.
 */
export async function assertTabContent(
	terminal: Terminal,
	tab: SettingsTab,
): Promise<void> {
	switch (tab) {
		case "API":
			return assertApiTab(terminal);
		case "Auto-approve":
			return assertAutoApproveTab(terminal);
		case "Features":
			return assertFeaturesTab(terminal);
		case "Account":
			return assertAccountTab(terminal);
		case "Other":
			return assertOtherTab(terminal);
	}
}

// ---------------------------------------------------------------------------
// Process-level helpers for headless / contract-style CLI tests.
//
// These helpers spawn cline as a child process and return stdout, stderr,
// and exit code - without going through the TUI harness. Use these for:
//   - Exit code assertions
//   - Pure stdout/stderr contract tests
//   - Piped stdin tests (echo "..." | cline -y ...)
//   - JSON output validation
//   - Timeout behavior
// ---------------------------------------------------------------------------

import { type SpawnSyncOptions, spawnSync } from "node:child_process";
import { CLINE_BIN } from "./constants.js";
import { clineEnv } from "./env.js";

export interface RunResult {
	stdout: string;
	stderr: string;
	exitCode: number | null;
	combined: string;
}

export interface RunOptions {
	/** Named config dir under `configs/`, or absolute path */
	config?: string;
	/** Additional env vars */
	env?: NodeJS.ProcessEnv;
	/** Stdin to pipe into the process */
	stdin?: string;
	/** Timeout in ms (default: 30_000) */
	timeout?: number;
	/** Working directory for the spawned process */
	cwd?: string;
}

/**
 * Run `cline [args]` synchronously and return stdout/stderr/exitCode.
 *
 * Suitable for deterministic, fast-exiting commands like:
 *   cline --help, cline --version, cline auth -p ... -k ..., etc.
 */
export function runCline(args: string[], opts: RunOptions = {}): RunResult {
	const {
		config = "default",
		env: extraEnv = {},
		stdin,
		timeout = 30_000,
		cwd = process.cwd(),
	} = opts;

	const spawnOpts: SpawnSyncOptions = {
		encoding: "utf8",
		timeout,
		cwd,
		env: { ...clineEnv(config), ...extraEnv },
		input: stdin,
	};

	const result = spawnSync(CLINE_BIN, args, spawnOpts);

	const stdout = (result.stdout as string) ?? "";
	const stderr = (result.stderr as string) ?? "";

	return {
		stdout,
		stderr,
		exitCode: result.status,
		combined: stdout + stderr,
	};
}

/**
 * Assert that a runCline result exited with the expected code.
 * Throws a descriptive error if the code doesn't match.
 */
export function assertExitCode(
	result: RunResult,
	expected: number,
	label = "",
): void {
	if (result.exitCode !== expected) {
		const prefix = label ? `[${label}] ` : "";
		throw new Error(
			`${prefix}Expected exit code ${expected}, got ${result.exitCode}.\n` +
				`stdout: ${result.stdout}\n` +
				`stderr: ${result.stderr}`,
		);
	}
}

/**
 * Assert that stdout/stderr contains a given string or matches a regex.
 */
export function assertOutput(
	result: RunResult,
	pattern: string | RegExp,
	stream: "stdout" | "stderr" | "combined" = "combined",
	label = "",
): void {
	const text = result[stream];
	const matches =
		typeof pattern === "string" ? text.includes(pattern) : pattern.test(text);

	if (!matches) {
		const prefix = label ? `[${label}] ` : "";
		throw new Error(
			`${prefix}Expected ${stream} to match ${pattern}.\n` +
				`stdout: ${result.stdout}\n` +
				`stderr: ${result.stderr}`,
		);
	}
}

// ---------------------------------------------------------------------------
// Terminal interaction helpers for TUI tests.
//
// These wrap common tui-test patterns to keep test bodies readable.
// ---------------------------------------------------------------------------

import { expect } from "@microsoft/tui-test";
import type { Terminal } from "@microsoft/tui-test/lib/terminal/term";
import { EXIT_CODE_TIMEOUT } from "./constants.js";

// ---------------------------------------------------------------------------
// Core wait / assertion helpers
// ---------------------------------------------------------------------------

const maxTimeoutMs = 10_000;

/**
 * Internal helper – asserts visibility (or not) for one or more patterns.
 */
async function expectTextVisibility(
	terminal: Terminal,
	text: string | RegExp | (string | RegExp)[],
	visible: boolean,
	options: { timeout?: number } = { timeout: maxTimeoutMs },
): Promise<void> {
	const items = Array.isArray(text) ? text : [text];
	const timeoutOpt =
		options.timeout !== undefined ? { timeout: options.timeout } : undefined;
	await Promise.all(
		items.map((t) => {
			// tui-test uses String.prototype.matchAll internally, which requires
			// the global flag on RegExp arguments. Ensure it is set.
			if (t instanceof RegExp && !t.flags.includes("g")) {
				t = new RegExp(t.source, `${t.flags}g`);
			}
			const locator = terminal.getByText(t, {
				full: true,
				strict: false,
			});
			return visible
				? expect(locator).toBeVisible(timeoutOpt)
				: expect(locator).not.toBeVisible(timeoutOpt);
		}),
	);
}

/**
 * Wait for one or more text strings/regexes to appear on screen.
 *
 * @example
 *   await expectVisible(terminal, "What can I do for you?");
 *   await expectVisible(terminal, ["/help", "/settings"], { timeout: 5000 });
 */
export async function expectVisible(
	terminal: Terminal,
	text: string | RegExp | (string | RegExp)[],
	options: { timeout?: number } = { timeout: maxTimeoutMs },
): Promise<void> {
	return expectTextVisibility(terminal, text, true, options);
}

export async function expectExitCode(
	terminal: Terminal,
	exitCode: number,
): Promise<void> {
	const xCode = await waitForTerminalExit(terminal);
	expect(xCode).toBe(exitCode);
}

/**
 * Assert that one or more text strings/regexes are **not** visible on screen.
 *
 * @example
 *   await expectNotVisible(terminal, "Loading…");
 *   await expectNotVisible(terminal, ["/secret", /error/i], { timeout: 5000 });
 */
export async function expectNotVisible(
	terminal: Terminal,
	text: string | RegExp | (string | RegExp)[],
	options: { timeout?: number } = { timeout: maxTimeoutMs },
): Promise<void> {
	return expectTextVisibility(terminal, text, false, options);
}

/**
 * Type text into the terminal and press Enter.
 * Waits `delay` ms between writing and submitting to let the UI settle.
 */
export async function typeAndSubmit(
	terminal: Terminal,
	text: string,
	delay = 500,
): Promise<void> {
	terminal.write(text);
	await new Promise((resolve) => setTimeout(resolve, delay));
	terminal.submit();
}

/**
 * Gracefully shut down the CLI process by sending Ctrl+C (SIGINT) and
 * waiting for the process to actually exit.
 *
 * This is necessary for VCR recording tests because tui-test normally
 * terminates processes with SIGKILL (signal 9), which cannot be caught
 * and prevents `process.on('exit')` handlers from flushing recorded
 * HTTP interactions to disk. Sending SIGINT first triggers the CLI's
 * graceful shutdown path which flushes VCR cassettes before exiting.
 *
 * @param timeout Maximum ms to wait for exit before giving up (default 5000)
 */
export async function gracefulShutdown(terminal: Terminal): Promise<number> {
	terminal.keyCtrlC();
	return await waitForTerminalExit(terminal);
}

export async function waitForTerminalExit(
	terminal: Terminal,
	timeout = 31000,
): Promise<number> {
	return await new Promise<number>((resolve) => {
		let resolved = false;
		const done = (code: number) => {
			if (resolved) return;
			resolved = true;
			clearTimeout(timer);
			clearInterval(poller);
			resolve(code);
		};

		const timer = setTimeout(() => done(EXIT_CODE_TIMEOUT), timeout); // exit code 124 is timeout

		// Register listener for future exit events
		terminal.onExit((exitResult) => done(exitResult.exitCode));

		// Poll terminal.exitResult as a fallback for the race condition where
		// the process exits before onExit listener is registered (the event
		// fires once and is not replayed for late subscribers).
		const poller = setInterval(() => {
			if (terminal.exitResult) {
				done(terminal.exitResult.exitCode);
			}
		}, 1000);
	});
}

