	it("exposes plugins as a local settings shortcut", () => {
		const registry = buildSlashCommandRegistry({});
		const commandNames = getVisibleSystemSlashCommands(registry).map(
			(command) => command.name,
		);

		expect(resolveSlashCommand(registry, "plugins")).toMatchObject({
			source: "tui",
			execution: "local",
			description: "Manage plugins",
			visible: true,
			selectable: true,
		});
		expect(commandNames).toContain("plugins");
		expect(commandNames.indexOf("plugins")).toBeGreaterThan(
			commandNames.indexOf("mcp"),
		);
		expect(commandNames.indexOf("plugins")).toBeLessThan(
			commandNames.indexOf("skills"),
		);
	});

	it("keeps config as a hidden alias for settings", () => {
		const registry = buildSlashCommandRegistry({ canFork: true });

		expect(resolveSlashCommand(registry, "config")).toMatchObject({
			source: "tui",
			execution: "local",
			description: "Modify agent configuration",
			visible: false,
			selectable: false,
		});
		expect(
			getVisibleSystemSlashCommands(registry).map((command) => command.name),
		).not.toContain("config");
		expect(
			getVisibleSystemSlashCommands(registry).map((command) => command.name),
		).toContain("settings");
	});

	it("always exposes the account command", () => {
		const registry = buildSlashCommandRegistry({});

		expect(resolveSlashCommand(registry, "account")).toMatchObject({
			source: "tui",
			execution: "local",
			visible: true,
		});
		expect(
			getVisibleSystemSlashCommands(registry).map((command) => command.name),
		).toContain("account");
	});
});

import { formatUserCommandBlock } from "@cline/shared";
import type { InteractiveSlashCommand } from "../interactive-welcome";

export type SlashCommandSource =
	| "tui"
	| "runtime"
	| "plugin"
	| "skill"
	| "workflow";

export type SlashCommandExecution = "local" | "runtime" | "user-command";

export type LocalSlashCommandName =
	| "settings"
	| "config"
	| "mcp"
	| "plugins"
	| "account"
	| "model"
	| "compact"
	| "skills"
	| "fork"
	| "undo"
	| "clear"
	| "history"
	| "quit"
	| "help";

export interface SlashCommandRegistryEntry {
	name: string;
	description: string;
	instructions: string;
	source: SlashCommandSource;
	kind?: InteractiveSlashCommand["kind"];
	execution: SlashCommandExecution;
	visible: boolean;
	selectable: boolean;
	preserveInput?: boolean;
}

export interface SlashCommandRegistry {
	entries: SlashCommandRegistryEntry[];
	byName: Map<string, SlashCommandRegistryEntry>;
}

const TUI_LOCAL_COMMANDS: Array<{
	name: LocalSlashCommandName;
	description: string;
	visible?: boolean;
	preserveInput?: boolean;
}> = [
	{
		name: "settings",
		description: "Modify agent configuration",
	},
	{
		name: "config",
		description: "Modify agent configuration",
		visible: false,
	},
	{
		name: "model",
		description: "Switch model or provider",
	},
	{
		name: "account",
		description: "View Cline account",
	},
	{
		name: "mcp",
		description: "Manage MCP servers",
	},
	{
		name: "plugins",
		description: "Manage plugins",
	},
	{
		name: "compact",
		description: "Compact context",
	},
	{
		name: "skills",
		description: "Browse skills and workflows",
		preserveInput: true,
	},
	{
		name: "fork",
		description: "Create a named fork of the current session",
	},
	{
		name: "undo",
		description: "Restore to a previous checkpoint",
	},
	{
		name: "clear",
		description: "Start a new session",
	},
	{
		name: "history",
		description: "View session history",
	},
	{
		name: "help",
		description: "Show help",
	},
	{
		name: "quit",
		description: "Exit Cline",
	},
];

const SYSTEM_COMMAND_ORDER = [
	"settings",
	"model",
	"account",
	"mcp",
	"plugins",
	"compact",
	"skills",
	"fork",
	"undo",
	"clear",
	"team",
	"history",
	"help",
	"quit",
] satisfies ReadonlyArray<LocalSlashCommandName | "team">;

const SYSTEM_COMMAND_PRIORITY = new Map<string, number>(
	SYSTEM_COMMAND_ORDER.map((name, index) => [name, index]),
);

function normalizeCommandName(name: string): string {
	return name.trim().replace(/^\/+/, "").toLowerCase();
}

function normalizeCommandDescription(description: string | undefined): string {
	return description?.replace(/\s+/g, " ").trim() ?? "";
}

function addEntry(
	byName: Map<string, SlashCommandRegistryEntry>,
	entry: SlashCommandRegistryEntry,
): void {
	const normalized = normalizeCommandName(entry.name);
	if (!normalized || byName.has(normalized)) {
		return;
	}
	byName.set(normalized, {
		...entry,
		name: normalized,
		description: normalizeCommandDescription(entry.description),
	});
}

function entryFromRuntimeCommand(
	command: InteractiveSlashCommand,
	source: "runtime" | "plugin" | "skill" | "workflow",
): SlashCommandRegistryEntry | undefined {
	const name = normalizeCommandName(command.name);
	if (!name) {
		return undefined;
	}
	const execution: SlashCommandExecution =
		command.kind === "skill" || command.kind === "workflow"
			? "user-command"
			: "runtime";
	return {
		name,
		description: command.description ?? "",
		instructions: command.instructions,
		source,
		kind: command.kind,
		execution,
		visible: true,
		selectable: true,
	};
}

export function buildSlashCommandRegistry(input: {
	workflowSlashCommands?: InteractiveSlashCommand[];
	additionalSlashCommands?: InteractiveSlashCommand[];
	canFork?: boolean;
}): SlashCommandRegistry {
	const byName = new Map<string, SlashCommandRegistryEntry>();

	for (const command of TUI_LOCAL_COMMANDS) {
		const isFork = command.name === "fork";
		const visible =
			(command.visible ?? true) && (!isFork || input.canFork === true);
		addEntry(byName, {
			name: command.name,
			description: command.description,
			instructions: "",
			source: "tui",
			execution: "local",
			visible,
			selectable: visible,
			preserveInput: command.preserveInput,
		});
	}

	for (const command of input.workflowSlashCommands ?? []) {
		const source =
			command.kind === "skill" || command.kind === "workflow"
				? command.kind
				: "runtime";
		const entry = entryFromRuntimeCommand(command, source);
		if (entry) {
			addEntry(byName, entry);
		}
	}

	for (const command of input.additionalSlashCommands ?? []) {
		const entry = entryFromRuntimeCommand(command, "plugin");
		if (entry) {
			addEntry(byName, entry);
		}
	}

	return {
		entries: [...byName.values()],
		byName,
	};
}

export function resolveSlashCommand(
	registry: SlashCommandRegistry,
	commandName: string,
): SlashCommandRegistryEntry | undefined {
	return registry.byName.get(normalizeCommandName(commandName));
}

const USER_COMMAND_SLASH_PATTERN = /(^|\s)\/([a-zA-Z0-9_.-]+)(?=\s|$)/g;

export function formatSlashCommandAutocompleteValue(
	entry: SlashCommandRegistryEntry,
): string {
	return `/${entry.name} `;
}

export function expandUserCommandPrompt(
	input: string,
	registry: SlashCommandRegistry,
): string {
	if (input.includes("<user_command")) {
		return input;
	}

	const expandedSlashCommands = input.replace(
		USER_COMMAND_SLASH_PATTERN,
		(match, prefix: string, name: string) => {
			const command = resolveSlashCommand(registry, name);
			if (command?.execution !== "user-command") {
				return match;
			}
			return `${prefix}${formatUserCommandBlock(command.instructions, command.name)}`;
		},
	);
	if (expandedSlashCommands !== input) {
		return expandedSlashCommands;
	}

	const match = /^\/([a-zA-Z0-9_.-]+)(\s+[\s\S]*)?$/.exec(input.trim());
	if (!match) {
		return input;
	}
	const command = resolveSlashCommand(registry, match[1] ?? "");
	if (!command || command.execution !== "user-command") {
		return input;
	}
	const rest = (match[2] ?? "").trim();
	const block = formatUserCommandBlock(command.instructions, command.name);
	return rest ? `${block} ${rest}` : block;
}

export function getVisibleSystemSlashCommands(
	registry: SlashCommandRegistry,
): SlashCommandRegistryEntry[] {
	const visible = registry.entries.filter(
		(entry) => entry.visible && entry.execution !== "user-command",
	);
	const priorityOf = (name: string) =>
		SYSTEM_COMMAND_PRIORITY.get(name) ?? SYSTEM_COMMAND_ORDER.length;
	return visible
		.map((entry, index) => ({ entry, index }))
		.sort((a, b) => {
			const pa = priorityOf(a.entry.name);
			const pb = priorityOf(b.entry.name);
			if (pa !== pb) return pa - pb;
			return a.index - b.index;
		})
		.map(({ entry }) => entry);
}

export function getVisibleUserSlashCommands(
	registry: SlashCommandRegistry,
): SlashCommandRegistryEntry[] {
	return registry.entries.filter(
		(entry) => entry.visible && entry.execution === "user-command",
	);
}

export function getInvokableUserSlashCommands(
	registry: SlashCommandRegistry,
): SlashCommandRegistryEntry[] {
	return registry.entries.filter((entry) => entry.execution === "user-command");
}

import { useTerminalDimensions } from "@opentui/react";
import type {
	AutocompleteMode,
	AutocompleteOption,
} from "../hooks/use-autocomplete";
import { useTerminalBackground } from "../hooks/use-terminal-background";
import { getDefaultForeground, palette } from "../palette";

const MAX_ROWS = 7;
export const DROPDOWN_MAX_HEIGHT = MAX_ROWS + 2;

export interface AutocompleteDropdownProps {
	mode: AutocompleteMode;
	options: AutocompleteOption[];
	selected: number;
	onSelect: (option: AutocompleteOption) => void;
	accent?: string;
	containerWidth?: number;
}

export function AutocompleteDropdown(props: AutocompleteDropdownProps) {
	const { mode, options, selected, onSelect, accent = palette.act } = props;
	const { width: termWidth } = useTerminalDimensions();

	if (!mode || options.length === 0) return null;

	const effectiveWidth = props.containerWidth ?? termWidth;
	const rowBudget = Math.max(10, effectiveWidth - 4);
	const safeSelected = Math.max(0, Math.min(selected, options.length - 1));

	if (options.length <= MAX_ROWS) {
		return (
			<box
				flexDirection="column"
				border
				borderStyle="rounded"
				borderColor="gray"
			>
				{options.map((opt, i) => (
					<OptionRow
						key={opt.display}
						opt={opt}
						isSelected={i === safeSelected}
						rowBudget={rowBudget}
						mode={mode}
						accent={accent}
						onSelect={onSelect}
					/>
				))}
			</box>
		);
	}

	const halfWindow = Math.floor(MAX_ROWS / 2);
	let start = Math.max(0, safeSelected - halfWindow);
	if (start + MAX_ROWS > options.length) {
		start = options.length - MAX_ROWS;
	}

	const moreAbove = start;
	const moreBelow = options.length - (start + MAX_ROWS);
	const showAboveIndicator = moreAbove > 0;
	const showBelowIndicator = moreBelow > 0;

	const itemSlots =
		MAX_ROWS - (showAboveIndicator ? 1 : 0) - (showBelowIndicator ? 1 : 0);
	const itemStart = showAboveIndicator ? start + 1 : start;
	const visibleItems = options.slice(itemStart, itemStart + itemSlots);

	const aboveCount = itemStart;
	const belowCount = options.length - (itemStart + itemSlots);

	return (
		<box flexDirection="column" border borderStyle="rounded" borderColor="gray">
			{showAboveIndicator && (
				<box paddingX={1} justifyContent="center">
					<text fg="gray">
						{"\u25b2"} {aboveCount} more
					</text>
				</box>
			)}
			{visibleItems.map((opt, i) => {
				const absoluteIdx = itemStart + i;
				return (
					<OptionRow
						key={opt.display}
						opt={opt}
						isSelected={absoluteIdx === safeSelected}
						rowBudget={rowBudget}
						mode={mode}
						accent={accent}
						onSelect={onSelect}
					/>
				);
			})}
			{showBelowIndicator && (
				<box paddingX={1} justifyContent="center">
					<text fg="gray">
						{"\u25bc"} {belowCount} more
					</text>
				</box>
			)}
		</box>
	);
}

function truncateEnd(str: string, max: number): string {
	if (str.length <= max) return str;
	return `${str.slice(0, max - 1)}\u2026`;
}

function truncateStart(str: string, max: number): string {
	if (str.length <= max) return str;
	return `\u2026${str.slice(-(max - 1))}`;
}

function OptionRow(props: {
	opt: AutocompleteOption;
	isSelected: boolean;
	rowBudget: number;
	mode: AutocompleteMode;
	accent: string;
	onSelect: (option: AutocompleteOption) => void;
}) {
	const terminalBg = useTerminalBackground();
	const defaultFg = getDefaultForeground(terminalBg);
	const { opt, isSelected, rowBudget, mode, accent, onSelect } = props;

	if (opt.isHeader) {
		return (
			<box paddingX={1}>
				<text fg="gray">{opt.display}</text>
			</box>
		);
	}

	const prefix = isSelected ? "\u276f " : "  ";
	const budgetAfterPrefix = rowBudget - prefix.length;

	let displayName: string;
	let descText = "";

	if (mode === "@") {
		displayName = truncateStart(opt.display, budgetAfterPrefix);
	} else {
		if (opt.description) {
			const descColumnBudget = Math.max(
				0,
				Math.floor(budgetAfterPrefix * 0.62),
			);
			const displayBudget = Math.max(
				1,
				budgetAfterPrefix - descColumnBudget - 1,
			);
			displayName = truncateEnd(opt.display, displayBudget);
			if (descColumnBudget > 3) {
				descText = truncateEnd(opt.description, descColumnBudget);
			}
		} else {
			displayName = truncateEnd(opt.display, budgetAfterPrefix);
		}
	}

	const descGap = descText
		? Math.max(1, budgetAfterPrefix - displayName.length - descText.length)
		: 0;

	return (
		<box
			paddingX={1}
			backgroundColor={isSelected ? accent : undefined}
			onMouseDown={() => onSelect(opt)}
		>
			<text wrapMode="none">
				<span fg={isSelected ? palette.textOnSelection : "gray"}>{prefix}</span>
				<span fg={isSelected ? palette.textOnSelection : defaultFg}>
					{displayName}
				</span>
				{descText ? (
					<span fg={isSelected ? palette.textOnSelection : "gray"}>
						{" ".repeat(descGap)}
						{descText}
					</span>
				) : null}
			</text>
		</box>
	);
}

