export function ChatEntryView(props: {
	entry: ChatEntry;
	accent?: string;
	/** Mode the entry was produced in (resolved with the current-mode fallback). */
	mode?: SyntaxAccentMode;
	loadIndividualSubscriptionPlans?: () => Promise<ClineSubscriptionPlan[]>;
	terminalTheme: TerminalTheme;
}) {
	const { entry, accent = palette.act, mode = "act", terminalTheme } = props;
	const terminalBg = useTerminalBackground();
	const defaultFg = getDefaultForeground(terminalBg);
	const userMsgBg = getUserMessageBackground(terminalBg);

	switch (entry.kind) {
		case "user":
			return (
				<box
					flexDirection="row"
					backgroundColor={userMsgBg}
					marginX={-1}
					paddingLeft={1}
					paddingRight={2}
				>
					<box width={2}>
						<text fg={accent}>{"❯"}</text>
					</box>
					<text fg={defaultFg} selectable>
						{entry.text}
					</text>
				</box>
			);

		case "user_submitted":
			return (
				<box
					flexDirection="row"
					backgroundColor={userMsgBg}
					marginX={-1}
					paddingLeft={1}
					paddingRight={2}
				>
					<box width={2}>
						<text fg={accent}>{"❯"}</text>
					</box>
					{entry.delivery === "steer" && <text fg="yellow">[steer] </text>}
					{entry.delivery === "queue" && <text fg="gray">[queued] </text>}
					<text fg={defaultFg} selectable>
						{entry.text}
					</text>
				</box>
			);

		case "assistant_text": {
			const content = trimLeading(entry.text);
			if (!content.trim()) return null;
			return (
				<box flexDirection="row">
					<box width={2}>
						{entry.streaming ? (
							<spinner name="dots" color={accent} />
						) : (
							<text fg={accent}>*</text>
						)}
					</box>
					<box flexGrow={1}>
						<markdown
							content={content}
							syntaxStyle={getSyntaxStyle(terminalTheme, mode)}
							streaming={entry.streaming}
							fg={defaultFg}
						/>
					</box>
				</box>
			);
		}

		case "reasoning":
			return <ReasoningBlock text={entry.text} streaming={entry.streaming} />;

		case "tool_call":
			return (
				<ToolCallView
					toolName={entry.toolName}
					inputSummary={entry.inputSummary}
					rawInput={entry.rawInput}
					streaming={entry.streaming}
					result={entry.result}
					accent={accent}
					defaultFg={defaultFg}
				/>
			);

		case "error":
			if (isClineAccountCreditsErrorMessage(entry.text)) {
				return <ClineCreditsErrorView defaultFg={defaultFg} />;
			}
			if (isClineOrgIndividualInferenceSubscriptionErrorMessage(entry.text)) {
				return (
					<ClineOrgIndividualInferenceSubscriptionErrorView
						defaultFg={defaultFg}
						terminalTheme={terminalTheme}
					/>
				);
			}
			if (isClinePassSubscriptionError(entry.text)) {
				return (
					<ClinePassSubscriptionErrorView
						defaultFg={defaultFg}
						loadIndividualSubscriptionPlans={
							props.loadIndividualSubscriptionPlans
						}
						terminalTheme={terminalTheme}
					/>
				);
			}
			if (isClinePassLimitErrorMessage(entry.text)) {
				return (
					<ClinePassLimitErrorView
						message={entry.text}
						defaultFg={defaultFg}
						terminalTheme={terminalTheme}
					/>
				);
			}
			return (
				<box flexDirection="row">
					<text fg="red" content="* " />
					<text fg="red" selectable content={`Error: ${entry.text}`} />
				</box>
			);

		case "status":
			return (
				<box flexDirection="row">
					<text fg="gray" content="* " />
					<text fg="gray" selectable content={entry.text} />
				</box>
			);

		case "team":
			return (
				<box flexDirection="row">
					<text fg="gray" content="* " />
					<text fg="gray" selectable content={entry.text} />
				</box>
			);

		case "compaction":
			return <CompactionDividerRow entry={entry} />;

		case "done": {
			const parts: string[] = [];
			if (entry.elapsed) parts.push(`${entry.elapsed}s`);
			if (entry.tokens > 0)
				parts.push(`${entry.tokens.toLocaleString()} tokens`);
			if (entry.cost > 0) parts.push(`$${entry.cost.toFixed(2)}`);
			if (entry.iterations > 0)
				parts.push(
					`${entry.iterations} iteration${entry.iterations !== 1 ? "s" : ""}`,
				);
			if (parts.length === 0) return null;
			return <text fg="gray" content={parts.join(" | ")} />;
		}
	}
}

import "opentui-spinner/react";
import type { AgentMode, ClineSubscriptionPlan } from "@cline/core";
import type { ScrollBoxRenderable } from "@opentui/core";
import {
	forwardRef,
	useCallback,
	useEffect,
	useImperativeHandle,
	useRef,
} from "react";
import type { TranscriptCommand } from "../hooks/transcript-keybinds";
import { useTerminalTheme } from "../hooks/use-terminal-background";
import { getModeAccent } from "../palette";
import type { ChatEntry } from "../types";
import { ChatEntryView } from "./chat-entry";

export interface TranscriptScrollHandle {
	runTranscriptCommand: (command: TranscriptCommand) => void;
}

interface ChatMessageListProps {
	entries: ChatEntry[];
	isStreaming?: boolean;
	loadIndividualSubscriptionPlans?: () => Promise<ClineSubscriptionPlan[]>;
	uiMode?: AgentMode;
}

export const ChatMessageList = forwardRef<
	TranscriptScrollHandle,
	ChatMessageListProps
>(function ChatMessageList(props, ref) {
	const scrollboxRef = useRef<ScrollBoxRenderable | null>(null);
	const lastEntry = props.entries.at(-1);
	const terminalTheme = useTerminalTheme();
	const accent = getModeAccent(props.uiMode ?? "act", terminalTheme);
	const userSubmissionScrollKey =
		lastEntry?.kind === "user_submitted" ? props.entries.length : 0;

	const runTranscriptCommand = useCallback((command: TranscriptCommand) => {
		const scrollbox = scrollboxRef.current;
		if (!scrollbox) return;

		switch (command) {
			case "messages_page_up":
				scrollbox.scrollBy(-scrollbox.height / 2);
				return;
			case "messages_page_down":
				scrollbox.scrollBy(scrollbox.height / 2);
				return;
			case "messages_half_page_up":
				scrollbox.scrollBy(-scrollbox.height / 4);
				return;
			case "messages_half_page_down":
				scrollbox.scrollBy(scrollbox.height / 4);
				return;
			case "messages_first":
				scrollbox.scrollTo(0);
				return;
			case "messages_last":
				scrollbox.scrollTo(scrollbox.scrollHeight);
				return;
		}
	}, []);

	useImperativeHandle(
		ref,
		() => ({
			runTranscriptCommand,
		}),
		[runTranscriptCommand],
	);

	useEffect(() => {
		if (!userSubmissionScrollKey) return;

		const scrollToBottom = () => {
			const scrollbox = scrollboxRef.current;
			if (!scrollbox) return;

			scrollbox.scrollTo(scrollbox.scrollHeight);
		};

		scrollToBottom();
		queueMicrotask(scrollToBottom);
		const timeout = setTimeout(scrollToBottom, 0);
		return () => clearTimeout(timeout);
	}, [userSubmissionScrollKey]);

	return (
		<scrollbox
			ref={scrollboxRef}
			flexGrow={1}
			stickyScroll
			stickyStart="bottom"
		>
			<box flexDirection="column" paddingX={1} paddingY={1} gap={1}>
				{props.entries.map((entry, i) => {
					const key = `${i}:${entry.kind}`;
					// Single source of truth for the entry's mode: the glyph accent
					// and the markdown accent must never diverge.
					const entryMode = entry.mode ?? props.uiMode ?? "act";
					return (
						<ChatEntryView
							key={key}
							entry={entry}
							accent={getModeAccent(entryMode, terminalTheme)}
							mode={entryMode === "plan" ? "plan" : "act"}
							loadIndividualSubscriptionPlans={
								props.loadIndividualSubscriptionPlans
							}
							terminalTheme={terminalTheme}
						/>
					);
				})}
				{props.isStreaming && (
					<box flexDirection="row" gap={1}>
						<spinner name="dots" color={accent} />
						<text fg="gray">Thinking... (esc to cancel)</text>
					</box>
				)}
			</box>
		</scrollbox>
	);
});

// @jsxImportSource @opentui/react
import type { ClineAccountOrganization } from "@cline/core";
import type { ChoiceContext } from "@opentui-ui/dialog";
import { useDialogKeyboard } from "@opentui-ui/dialog/react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
	type ClineAccountSnapshot,
	formatClineCredits,
	isClineAccountAuthErrorMessage,
} from "../../cline-account";
import { palette } from "../../palette";

export type AccountDialogAction =
	| "change-model"
	| "change-provider"
	| "learn-more"
	| "login";

type AccountView = "overview" | "organizations";

type AccountState =
	| { status: "loading"; message: string }
	| { status: "loaded"; snapshot: ClineAccountSnapshot }
	| { status: "unauthenticated"; message: string }
	| { status: "error"; message: string };

interface OrganizationRowData {
	id: string;
	organizationId: string | null;
	label: string;
	description: string;
	active: boolean;
}

interface AccountAction {
	id:
		| "change-model"
		| "change-account"
		| "change-provider"
		| "learn-more"
		| "login";
	label: string;
	description: string;
	enabled: boolean;
}

const LOADED_ACTIONS: AccountAction[] = [
	{
		id: "change-model",
		label: "Change model",
		description: "Open the Cline model selector",
		enabled: true,
	},
	{
		id: "change-account",
		label: "Change account",
		description: "Switch personal account or organization",
		enabled: true,
	},
	{
		id: "change-provider",
		label: "Change provider",
		description: "Open provider picker",
		enabled: true,
	},
];

const UNAUTHENTICATED_ACTIONS: AccountAction[] = [
	{
		id: "login",
		label: "Sign in or create account",
		description: "Use Cline OAuth",
		enabled: true,
	},
	{
		id: "learn-more",
		label: "Learn more",
		description: "Open cline.bot",
		enabled: true,
	},
];

function clampIndex(index: number, total: number): number {
	if (total <= 0) return 0;
	if (index < 0) return total - 1;
	if (index >= total) return 0;
	return index;
}

function formatDate(dateStr: string): string {
	const date = new Date(dateStr);
	if (Number.isNaN(date.getTime())) {
		return dateStr;
	}
	return date.toLocaleDateString("en-US", {
		month: "short",
		day: "numeric",
		year: "numeric",
	});
}

function userInitial(snapshot: ClineAccountSnapshot): string {
	const candidate =
		snapshot.user.displayName?.trim() || snapshot.user.email?.trim() || "?";
	return candidate.charAt(0).toUpperCase();
}

function AccountField(props: { label: string; value: string }) {
