				<input
					value={query}
					onInput={(value: string) => {
						setQuery(value);
						setSelected(0);
					}}
					placeholder="Search actions..."
					flexGrow={1}
					focused
				/>
			</box>

			<box flexDirection="column">
				{visible.length === 0 ? (
					<text fg="gray">No matching commands found.</text>
				) : (
					visible.map((item, localIndex) => {
						const absoluteIndex = start + localIndex;
						const isSelected = absoluteIndex === safeSelected;
						return (
							<box key={item.id} flexDirection="column">
								<box
									flexDirection="column"
									paddingLeft={itemPaddingLeft}
									paddingRight={itemPaddingRight}
									width={contentWidth}
									overflow="hidden"
									backgroundColor={isSelected ? palette.selection : undefined}
									onMouseDown={() => resolve(item.result)}
								>
									<box flexDirection="row" height={1} width={itemContentWidth}>
										<text
											fg={isSelected ? palette.textOnSelection : "white"}
											width={labelWidth}
											flexShrink={0}
										>
											{truncate(item.label, labelWidth)}
										</text>
										<text width={shortcutGap} flexShrink={0}>
											{" "}
										</text>
										<text
											fg={isSelected ? palette.textOnSelection : palette.act}
											width={shortcutWidth}
											flexShrink={0}
										>
											{item.shortcut}
										</text>
									</box>
									<text
										fg={isSelected ? palette.textOnSelection : "gray"}
										width={descriptionWidth}
									>
										{item.description}
									</text>
								</box>
								{localIndex < visible.length - 1 ? (
									<box
										border={["top"]}
										borderStyle="rounded"
										borderColor="gray"
										width={contentWidth}
										height={1}
									/>
								) : null}
							</box>
						);
					})
				)}
			</box>

			<text fg="gray">
				Type to search, arrow keys navigate, Enter to run, Esc to close
			</text>
		</box>
	);
}

import type { InteractiveConfigItem } from "../../interactive-config";
import { isToggleableInteractiveConfigItem } from "../../interactive-config";

export type ExtDetailRow =
	| { kind: "header"; name: string; source: string }
	| { kind: "field"; label: "Path" | "Description" | "Error"; value: string[] }
	| { kind: "status"; enabled: boolean };

const TOGGLE_FOOTER = "Space toggle status, Tab/Enter/Esc to go back";
const DETAIL_FOOTER = "Tab/Enter/Esc to go back";

const MAX_DESCRIPTION_LINES = 12;
const MAX_DESCRIPTION_COLUMNS = 78;

function wrapDetailLine(line: string): string[] {
	if (line.length <= MAX_DESCRIPTION_COLUMNS) {
		return [line];
	}
	const wrapped: string[] = [];
	let remaining = line;
	while (remaining.length > MAX_DESCRIPTION_COLUMNS) {
		let splitAt = remaining.lastIndexOf(" ", MAX_DESCRIPTION_COLUMNS);
		if (splitAt <= 0) {
			splitAt = MAX_DESCRIPTION_COLUMNS;
		}
		wrapped.push(remaining.slice(0, splitAt));
		remaining = remaining.slice(splitAt).trimStart();
	}
	wrapped.push(remaining);
	return wrapped;
}

function truncateDescription(description: string): string[] {
	const lines = description.split("\n").flatMap(wrapDetailLine);
	if (lines.length <= MAX_DESCRIPTION_LINES) {
		return lines;
	}
	return [
		...lines.slice(0, MAX_DESCRIPTION_LINES),
		`… truncated ${lines.length - MAX_DESCRIPTION_LINES} lines`,
	];
}

export function shouldCloseExtDetailForKey(keyName: string): boolean {
	return keyName === "escape" || keyName === "return" || keyName === "tab";
}

export function shouldToggleExtDetailForKey(
	keyName: string,
	item: Pick<InteractiveConfigItem, "kind" | "source" | "enabled">,
): boolean {
	return (
		keyName === "space" &&
		typeof item.enabled === "boolean" &&
		isToggleableInteractiveConfigItem(item)
	);
}

export function getExtDetailFooterText(
	item: Pick<InteractiveConfigItem, "kind" | "source" | "enabled">,
): string {
	return typeof item.enabled === "boolean" &&
		isToggleableInteractiveConfigItem(item)
		? TOGGLE_FOOTER
		: DETAIL_FOOTER;
}

export function getExtDetailRows(item: InteractiveConfigItem): ExtDetailRow[] {
	const rows: ExtDetailRow[] = [
		{ kind: "header", name: item.name, source: item.source },
		{ kind: "field", label: "Path", value: [item.path] },
	];
	if (item.description) {
		rows.push({
			kind: "field",
			label: "Description",
			value: truncateDescription(item.description),
		});
	}
	if (item.loadError) {
		rows.push({
			kind: "field",
			label: "Error",
			value: truncateDescription(item.loadError),
		});
	}
	if (
		typeof item.enabled === "boolean" &&
		isToggleableInteractiveConfigItem(item)
	) {
		rows.push({ kind: "status", enabled: item.enabled });
	}
	return rows;
}

import { describe, expect, it } from "vitest";
import type { InteractiveConfigItem } from "../../interactive-config";
import {
	getExtDetailFooterText,
	getExtDetailRows,
	shouldCloseExtDetailForKey,
	shouldToggleExtDetailForKey,
} from "./config-dialogs-helpers";

function createItem(
	overrides: Partial<InteractiveConfigItem> &
		Pick<InteractiveConfigItem, "kind">,
): InteractiveConfigItem {
	return {
		id: "item-id",
		name: "item-name",
		path: "/tmp/item",
		enabled: true,
		source: "workspace",
		...overrides,
	};
}

describe("config detail dialog helpers", () => {
	it("closes details for Enter, Escape, and Tab", () => {
		expect(shouldCloseExtDetailForKey("return")).toBe(true);
		expect(shouldCloseExtDetailForKey("escape")).toBe(true);
		expect(shouldCloseExtDetailForKey("tab")).toBe(true);
		expect(shouldCloseExtDetailForKey("space")).toBe(false);
	});

	it("toggles detail status on Space only for toggleable rows", () => {
		const skill = createItem({ kind: "skill" });
		const mcp = createItem({ kind: "mcp" });
		const workflow = createItem({ kind: "workflow" });

		expect(shouldToggleExtDetailForKey("space", skill)).toBe(true);
		expect(shouldToggleExtDetailForKey("space", mcp)).toBe(true);
		expect(shouldToggleExtDetailForKey("return", skill)).toBe(false);
		expect(shouldToggleExtDetailForKey("space", workflow)).toBe(false);
	});

	it("builds useful detail rows with status for toggleable items", () => {
		expect(
			getExtDetailRows(
				createItem({
					kind: "skill",
					name: "add-model",
					source: "global",
					path: "/tmp/add-model/SKILL.md",
					description: "Add a model safely",
					enabled: false,
				}),
			),
		).toEqual([
			{ kind: "header", name: "add-model", source: "global" },
			{ kind: "field", label: "Path", value: ["/tmp/add-model/SKILL.md"] },
			{ kind: "field", label: "Description", value: ["Add a model safely"] },
			{ kind: "status", enabled: false },
		]);
	});

	it("omits status and toggle hint for non-toggleable items", () => {
		const workflow = createItem({
			kind: "workflow",
			name: "release",
			description: "Run release workflow",
		});

		expect(getExtDetailRows(workflow)).toEqual([
			{ kind: "header", name: "release", source: "workspace" },
			{ kind: "field", label: "Path", value: ["/tmp/item"] },
			{ kind: "field", label: "Description", value: ["Run release workflow"] },
		]);
		expect(getExtDetailFooterText(workflow)).toBe("Tab/Enter/Esc to go back");
	});

	it("shows toggle hint for toggleable items", () => {
		expect(getExtDetailFooterText(createItem({ kind: "skill" }))).toBe(
			"Space toggle status, Tab/Enter/Esc to go back",
		);
	});

	it("bounds long descriptions so path and status remain visible", () => {
		const rows = getExtDetailRows(
			createItem({
				kind: "skill",
				name: "karpathy-rules",
				source: "global",
				path: "/tmp/karpathy-rules.md",
				description: Array.from(
					{ length: 30 },
					(_, index) => `Long rule line ${index + 1}`,
				).join("\n"),
				enabled: true,
			}),
		);

		expect(rows[1]).toEqual({
			kind: "field",
			label: "Path",
			value: ["/tmp/karpathy-rules.md"],
		});
		expect(rows[2]?.kind).toBe("field");
		if (rows[2]?.kind === "field") {
			expect(rows[2].label).toBe("Description");
			expect(rows[2].value).toHaveLength(13);
			expect(rows[2].value.at(-1)).toContain("… truncated");
		}
		expect(rows[3]).toEqual({ kind: "status", enabled: true });
	});

	it("wraps long description lines before truncating", () => {
		const rows = getExtDetailRows(
			createItem({
				kind: "rule",
				description: "a ".repeat(120).trim(),
			}),
		);

		expect(rows[2]?.kind).toBe("field");
		if (rows[2]?.kind === "field") {
			expect(rows[2].value.length).toBeGreaterThan(1);
			expect(rows[2].value.every((line) => line.length <= 78)).toBe(true);
		}
	});
});

import type { ChoiceContext } from "@opentui-ui/dialog";
import { useDialogKeyboard } from "@opentui-ui/dialog/react";
import { useState } from "react";
import type {
	InteractiveConfigData,
	InteractiveConfigItem,
	LoadInteractiveConfigDataOptions,
} from "../../interactive-config";
import { palette } from "../../palette";
import {
	getExtDetailFooterText,
	getExtDetailRows,
	shouldCloseExtDetailForKey,
	shouldToggleExtDetailForKey,
} from "./config-dialogs-helpers";

export function ExtDetailContent(
	props: ChoiceContext<void> & {
		item: InteractiveConfigItem;
		onToggleConfigItem?: (
			item: InteractiveConfigItem,
			options?: LoadInteractiveConfigDataOptions,
		) => Promise<InteractiveConfigData | undefined>;
	},
) {
	const [item, setItem] = useState(props.item);
	const [toggleError, setToggleError] = useState<string | undefined>();

	const toggleStatus = async () => {
		if (
			!props.onToggleConfigItem ||
			!shouldToggleExtDetailForKey("space", item)
		) {
			return;
		}
		const previousItem = item;
		setToggleError(undefined);
		if (typeof item.enabled === "boolean") {
			setItem({ ...item, enabled: !item.enabled });
		}
		try {
			const nextData = await props.onToggleConfigItem(item, {
				includePluginTools: false,
			});
			if (nextData) {
				const nextItem = [
					...nextData.workflows,
					...nextData.rules,
					...nextData.skills,
					...nextData.hooks,
					...nextData.agents,
					...nextData.plugins,
					...nextData.mcp,
					...nextData.tools,
				].find(
					(candidate) =>
						candidate.id === item.id && candidate.path === item.path,
				);
				if (nextItem) {
					setItem(nextItem);
				}
			}
		} catch (error) {
			setItem(previousItem);
			const message = error instanceof Error ? error.message : String(error);
			setToggleError(`Failed to update ${item.name}: ${message}`);
		}
	};

	useDialogKeyboard((key) => {
		if (shouldToggleExtDetailForKey(key.name, item)) {
			void toggleStatus();
			return;
		}
		if (shouldCloseExtDetailForKey(key.name)) {
			props.dismiss();
		}
	}, props.dialogId);
	const rows = getExtDetailRows(item);
	const footerText = getExtDetailFooterText(item);

	return (
		<box flexDirection="column" paddingX={1}>
			{rows.map((row) => {
				switch (row.kind) {
					case "header":
						return (
							<box
								key="header"
								flexDirection="row"
								justifyContent="space-between"
							>
								<text fg={palette.act}>
									<strong>{row.name}</strong>
								</text>
								<text
									fg={row.source === "workspace" ? palette.success : "gray"}
								>
									{row.source}
								</text>
							</box>
						);
					case "field":
						return (
							<box key={row.label} flexDirection="column" marginTop={1}>
								<text fg="gray">{row.label}</text>
								{row.value.map((line) => (
									<text key={`${row.label}-${line}`}>{line || " "}</text>
								))}
							</box>
						);
					case "status":
						return (
							<box
								key="status"
								flexDirection="row"
								marginTop={1}
								justifyContent="space-between"
							>
								<text fg="gray">Status</text>
								<text fg={row.enabled ? palette.success : "red"}>
									{row.enabled ? "Enabled" : "Disabled"}
								</text>
							</box>
						);
				}
				return null;
			})}
			<text fg="gray" marginTop={1}>
				<em>{footerText}</em>
			</text>
			{toggleError && (
				<text fg="red" marginTop={1}>
					{toggleError}
				</text>
			)}
		</box>
	);
}

export function DeleteConfigItemConfirmContent(
	props: ChoiceContext<boolean> & {
		item: InteractiveConfigItem;
	},
) {
	useDialogKeyboard((key) => {
		if (key.name === "return" || key.name === "y") {
			props.resolve(true);
		} else if (key.name === "escape" || key.name === "n") {
			props.dismiss();
		}
	}, props.dialogId);

	return (
		<box flexDirection="column" paddingX={1}>
			<text>Delete plugin {props.item.name}?</text>
			<text fg="gray" marginTop={1}>
				This removes the installed plugin files from {props.item.path}.
			</text>
			<text fg="gray" marginTop={1}>
				<em>Y/Enter to confirm, N/Esc to cancel</em>
			</text>
		</box>
	);
}

export function ConfigErrorContent(
	props: ChoiceContext<void> & {
		title: string;
		message: string;
	},
) {
	useDialogKeyboard((key) => {
		if (key.name === "return" || key.name === "escape") {
			props.dismiss();
		}
	}, props.dialogId);

	return (
		<box flexDirection="column" paddingX={1}>
			<text fg="red">{props.title}</text>
			<text fg="gray" marginTop={1}>
				{props.message}
			</text>
			<text fg="gray" marginTop={1}>
				<em>Enter/Esc to close</em>
			</text>
		</box>
	);
}

