import { useState } from "react";
import { palette } from "../../palette";

export interface McpEntry {
	name: string;
	path: string;
	enabled?: boolean;
	description?: string;
	lastError?: string;
	pluginName?: string;
}

export type McpServerToggleResult =
	| { ok: true; server: McpEntry }
	| { ok: false; message: string };

function stringifyError(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

export function getMcpManagerFooterText(hasServers: boolean): string {
	return hasServers
		? "Space toggle selected, Esc to go back"
		: "Esc to go back";
}

export function getMcpManagerEntryStatus(
	server: Pick<McpEntry, "description" | "lastError">,
): string {
	return server.lastError ? "oauth error" : (server.description ?? "");
}

export function toggleMcpServer(server: McpEntry): McpServerToggleResult {
	if (server.pluginName) {
		return {
			ok: false,
			message: `MCP server "${server.name}" is managed by plugin "${server.pluginName}". Disable the plugin to disable this server.`,
		};
	}
	try {
		const currentlyEnabled = server.enabled !== false;
		setMcpServerDisabled({
			filePath: server.path,
			name: server.name,
			disabled: currentlyEnabled,
		});
		return {
			ok: true,
			server: {
				...server,
				enabled: !currentlyEnabled,
			},
		};
	} catch (error) {
		return {
			ok: false,
			message: `Unable to toggle MCP server "${server.name}": ${stringifyError(error)}`,
		};
	}
}

export function McpManagerContent(
	props: ChoiceContext<boolean> & {
		servers: McpEntry[];
	},
) {
	const [selected, setSelected] = useState(0);
	const [servers, setServers] = useState(props.servers);
	const [changed, setChanged] = useState(false);
	const [error, setError] = useState<string | null>(null);

	const settingsPath = servers[0]?.path ?? resolveDefaultMcpSettingsPath();
	const itemCount = servers.length;
	const selectedServer = servers[selected];
	const hasPluginOwnedServers = servers.some((server) => server.pluginName);

	useDialogKeyboard((key) => {
		if (key.name === "escape") {
			if (changed) {
				props.resolve(true);
			} else {
				props.dismiss();
			}
			return;
		}
		if (itemCount > 0) {
			if (key.name === "up") {
				setError(null);
				setSelected((s) => (s > 0 ? s - 1 : itemCount - 1));
				return;
			}
			if (key.name === "down") {
				setError(null);
				setSelected((s) => (s < itemCount - 1 ? s + 1 : 0));
				return;
			}
			if (key.name === "space") {
				const target = servers[selected];
				const result = target ? toggleMcpServer(target) : undefined;
				if (result?.ok) {
					setServers((current) =>
						current.map((server, index) =>
							index === selected ? result.server : server,
						),
					);
					setChanged(true);
					setError(null);
				} else if (result) {
					setError(result.message);
				}
				return;
			}
		}
	}, props.dialogId);

	return (
		<box flexDirection="column" paddingX={1}>
			<text fg={palette.act}>MCP Servers</text>

			<text fg="gray" marginTop={1}>
				Settings file:
			</text>
			<text selectable>{settingsPath}</text>

			<text fg="gray" marginTop={1}>
				Run cline mcp to add, edit, or remove servers.
			</text>

			{servers.length > 0 && (
				<box flexDirection="column" marginTop={1}>
					{servers.map((srv, i) => {
						const isSel = i === selected;
						const enabled =
							typeof srv.enabled === "boolean" ? srv.enabled : true;
						const enabledIcon =
							typeof srv.enabled === "boolean" ? (enabled ? "● " : "○ ") : "";
						const status = getMcpManagerEntryStatus(srv);
						let rowColor = isSel ? palette.act : "gray";
						if (enabled && typeof srv.enabled === "boolean") {
							rowColor = palette.success;
						}
						if (srv.lastError) {
							rowColor = palette.error;
						}
						return (
							<box
								key={srv.name}
								flexDirection="row"
								justifyContent="space-between"
							>
								<text fg={rowColor}>
									{isSel ? "\u25b8 " : "  "}
									{enabledIcon}
									{srv.name}
									{srv.pluginName ? " *" : ""}
								</text>
								{status && (
									<text fg={srv.lastError ? palette.error : "gray"}>
										{status}
									</text>
								)}
							</box>
						);
					})}
				</box>
			)}

			{servers.length === 0 && (
				<text fg="gray" marginTop={1}>
					No servers configured.
				</text>
			)}

			{error && (
				<text fg={palette.error} marginTop={1}>
					{error}
				</text>
			)}

			{selectedServer?.lastError && (
				<box flexDirection="column" marginTop={1}>
					<text fg={palette.error}>OAuth error</text>
					<text fg={palette.error}>{selectedServer.lastError}</text>
					<text fg="gray">
						Run cline mcp and choose Authorize OAuth to retry.
					</text>
				</box>
			)}

			{hasPluginOwnedServers && (
				<text fg="gray" marginTop={1}>
					* managed by plugin; disable the plugin to disable the server.
				</text>
			)}

			<text fg="gray" marginTop={1}>
				<em>{getMcpManagerFooterText(servers.length > 0)}</em>
			</text>
		</box>
	);
}

import {
	getProviderAuthStorageId,
	type ProviderSettingsManager,
	saveLocalProviderSettings,
} from "@cline/core";
import { CLI_PROMO_CODE } from "../../../utils/cline-pass-errors";

const CLINE_PASS_SUBSCRIPTION_PATH = "/dashboard/subscription";
const DEFAULT_APP_BASE_URL = "https://app.cline.bot";

/**
 * Persist a manually entered API key for an OAuth-capable provider — the
 * escape hatch for when OAuth login isn't working. Any stored OAuth tokens
 * are cleared: the auth handler prefers auth.accessToken over apiKey, so a
 * stale token would otherwise keep winning over the manual key.
 *
 * The key is written both to the provider's auth storage entry (cline-pass
 * stores credentials under "cline") and to the provider's own entry: settings
 * resolution lets a direct entry shadow the storage entry, and provider
 * switching copies merged settings (including auth) into direct entries, so
 * both must be updated for the manual key to reliably take effect.
 */
export function saveManualProviderApiKey(
	manager: ProviderSettingsManager,
	providerId: string,
	apiKey: string,
): void {
	// Empty strings delete these keys from the stored auth object.
	const clearedAuth = { accessToken: "", refreshToken: "", apiKey: "" };
	const storageProviderId = getProviderAuthStorageId(providerId) ?? providerId;
	saveLocalProviderSettings(manager, {
		providerId: storageProviderId,
		apiKey,
		auth: clearedAuth,
	});
	if (
		providerId !== storageProviderId &&
		manager.read().providers[providerId]
	) {
		saveLocalProviderSettings(manager, {
			providerId,
			apiKey,
			auth: clearedAuth,
		});
	}
}

export function buildClinePassSubscriptionPageUrl(
	appBaseUrl: string | undefined,
): string {
	const url = new URL(
		CLINE_PASS_SUBSCRIPTION_PATH,
		appBaseUrl || DEFAULT_APP_BASE_URL,
	);
	url.searchParams.set("personal", "true");
	url.searchParams.set("code", CLI_PROMO_CODE);
	return url.toString();
}

