const DEFAULT_FIELD_LABELS: Partial<Record<ProviderConfigFieldKey, string>> = {
	apiKey: "API key",
	baseUrl: "Base URL",
	azureApiVersion: "Azure API Version",
	awsRegion: "AWS Region",
	awsProfile: "AWS Profile Name",
	gcpProjectId: "Google Cloud Project ID",
	gcpRegion: "Google Cloud Region",
	sapClientId: "Client ID",
	sapClientSecret: "Client Secret",
	sapTokenUrl: "Token URL",
	sapResourceGroup: "Resource Group",
	sapDeploymentId: "Deployment ID",
};

const DEFAULT_FIELD_PLACEHOLDERS: Partial<
	Record<ProviderConfigFieldKey, string>
> = {
	apiKey: "sk-...",
	baseUrl: "",
	azureApiVersion: "2025-01-01-preview",
	awsRegion: "us-east-1",
	awsProfile: "default",
	gcpProjectId: "my-gcp-project",
	gcpRegion: "us-central1",
	sapClientId: "sb-...|xsuaa_std!b...",
	sapClientSecret: "SAP AI Core client secret",
	sapTokenUrl: "https://<subdomain>.authentication.sap.hana.ondemand.com",
	sapResourceGroup: "default",
	sapDeploymentId: "",
};

/** Render order for cycling focus with Tab. */
const FIELD_ORDER: ProviderConfigFieldKey[] = [
	"awsRegion",
	"gcpProjectId",
	"gcpRegion",
	"baseUrl",
	"azureApiVersion",
	"apiKey",
	"awsProfile",
	"sapClientId",
	"sapClientSecret",
	"sapTokenUrl",
	"sapResourceGroup",
	"sapDeploymentId",
];

export type ProviderConfigInputFields = Partial<
	Record<ProviderConfigFieldKey, ProviderConfigFieldRequirement>
>;

/**
 * Single-purpose configure dialog: collects API key and (when applicable)
 * base URL. Model selection happens separately in the standard model picker
 * after this dialog resolves. No fields are required. The dialog accepts
 * blanks. If credentials are missing or wrong, the API call surfaces the
 * provider's own error to the user.
 */
export function ProviderConfigInputContent(
	props: ChoiceContext<boolean> & {
		providerId: string;
		providerName: string;
		fields: ProviderConfigInputFields;
		providerSettingsManager: ProviderSettingsManager;
	},
) {
	const {
		resolve,
		dismiss,
		dialogId,
		providerId,
		providerName,
		providerSettingsManager,
	} = props;

	const config = useMemo(
		() => getProviderConfigFields(providerId),
		[providerId],
	);
	const fieldKeys = useMemo<ProviderConfigFieldKey[]>(
		() => FIELD_ORDER.filter((key) => config.fields[key] !== undefined),
		[config],
	);

	const existingSettings =
		providerSettingsManager.getProviderSettings(providerId);
	const [values, setValues] = useState<ProviderConfigValues>(() => {
		const initial: ProviderConfigValues = {};
		if (config.fields.baseUrl) {
			initial.baseUrl =
				existingSettings?.baseUrl?.trim() ??
				config.fields.baseUrl?.defaultValue ??
				"";
		}
		if (config.fields.azureApiVersion) {
			initial.azureApiVersion =
				existingSettings?.azure?.apiVersion?.trim() ?? "";
		}
		if (config.fields.awsRegion) {
			const ep = existingSettings?.aws?.profile?.trim() ?? "";
			initial.awsRegion =
				existingSettings?.aws?.region?.trim() || getDefaultAwsRegion(ep);
		}
		if (config.fields.gcpProjectId)
			initial.gcpProjectId = existingSettings?.gcp?.projectId?.trim() ?? "";
		if (config.fields.gcpRegion)
			initial.gcpRegion =
				existingSettings?.gcp?.region?.trim() ??
				config.fields.gcpRegion.defaultValue ??
				"us-central1";
		if (config.fields.apiKey)
			initial.apiKey = existingSettings?.apiKey?.trim() ?? "";
		if (config.fields.awsProfile)
			initial.awsProfile = existingSettings?.aws?.profile?.trim() ?? "";
		if (config.fields.sapClientId)
			initial.sapClientId = existingSettings?.sap?.clientId?.trim() ?? "";
		if (config.fields.sapClientSecret)
			initial.sapClientSecret =
				existingSettings?.sap?.clientSecret?.trim() ?? "";
		if (config.fields.sapTokenUrl)
			initial.sapTokenUrl = existingSettings?.sap?.tokenUrl?.trim() ?? "";
		if (config.fields.sapResourceGroup)
			initial.sapResourceGroup =
				existingSettings?.sap?.resourceGroup?.trim() ?? "default";
		if (config.fields.sapDeploymentId)
			initial.sapDeploymentId =
				existingSettings?.sap?.deploymentId?.trim() ?? "";
		return initial;
	});

	const [focusedField, setFocusedField] = useState<ProviderConfigFieldKey>(
		() => fieldKeys[0] ?? "apiKey",
	);

	const submit = () => {
		const apiKey = values.apiKey?.trim();
		const awsProfile = values.awsProfile?.trim();
		const hasAzureFields = config.fields.azureApiVersion;
		const hasAwsFields = config.fields.awsRegion || config.fields.awsProfile;
		const hasGcpFields = config.fields.gcpProjectId || config.fields.gcpRegion;
		const hasSapFields =
			config.fields.sapClientId ||
			config.fields.sapClientSecret ||
			config.fields.sapTokenUrl ||
			config.fields.sapResourceGroup ||
			config.fields.sapDeploymentId;
		saveLocalProviderSettings(providerSettingsManager, {
			providerId,
			apiKey: config.fields.apiKey ? apiKey : undefined,
			baseUrl: config.fields.baseUrl ? values.baseUrl?.trim() : undefined,
			azure: hasAzureFields ? resolveProviderConfigAzure(values) : undefined,
			aws: hasAwsFields
				? {
						region: resolveProviderConfigAwsRegion(values),
						authentication: apiKey ? "api-key" : "profile",
						profile: apiKey ? undefined : awsProfile || undefined,
					}
				: undefined,
			gcp: hasGcpFields ? resolveProviderConfigGcp(values) : undefined,
			sap: hasSapFields ? resolveProviderConfigSap(values) : undefined,
		});
		resolve(true);
	};

	useDialogKeyboard((key) => {
		if (key.name === "escape") {
			dismiss();
			return;
		}
		if (key.name === "return") {
			submit();
			return;
		}
		if (key.name === "tab" && fieldKeys.length > 1) {
			const idx = fieldKeys.indexOf(focusedField);
			const nextIdx = key.shift
				? (idx - 1 + fieldKeys.length) % fieldKeys.length
				: (idx + 1) % fieldKeys.length;
			const next = fieldKeys[nextIdx];
			if (next) setFocusedField(next);
		}
	}, dialogId);

	return (
		<box flexDirection="column" paddingX={1} gap={1}>
			<text fg={palette.act}>
				<strong>{providerName}</strong>
			</text>

			{config.description && <text fg="gray">{config.description}</text>}

			{fieldKeys.map((key) => {
				const requirement = config.fields[key];
				if (!requirement) return null;
				const label = requirement.label ?? DEFAULT_FIELD_LABELS[key] ?? key;
				const placeholder =
					requirement.placeholder ??
					(key === "baseUrl" && requirement.defaultValue
						? requirement.defaultValue
						: (DEFAULT_FIELD_PLACEHOLDERS[key] ?? ""));
				return (
					<box key={key} flexDirection="column">
						<text fg="gray">{label}</text>
						{requirement.note && <text fg="gray">{requirement.note}</text>}
						<box
							border
							borderStyle="rounded"
							borderColor={focusedField === key ? palette.act : "gray"}
							paddingX={1}
						>
							<input
								value={values[key] ?? ""}
								onInput={(v: string) =>
									setValues((prev) => updateProviderConfigValue(prev, key, v))
								}
								placeholder={placeholder}
								flexGrow={1}
								focused={focusedField === key}
							/>
						</box>
					</box>
				);
			})}

			<text fg="gray">
				<em>
					{fieldKeys.length > 1
						? "Tab to switch fields, Enter to save, Esc to go back"
						: "Enter to save, Esc to go back"}
				</em>
			</text>
		</box>
	);
}

export function CodexCliStatusContent(
	props: ChoiceContext<boolean> & {
		providerName: string;
	},
) {
	const { resolve, dismiss, dialogId, providerName } = props;
	const [status, setStatus] = useState<CodexCliStatus | undefined>();
	const [checking, setChecking] = useState(false);

	const refresh = useCallback(() => {
		setStatus(undefined);
		setChecking(true);
		checkCodexCliInstalled()
			.then(setStatus)
			.catch((error: unknown) => {
				setStatus({
					installed: false,
					reason: error instanceof Error ? error.message : String(error),
				});
			})
			.finally(() => setChecking(false));
	}, []);

	useEffect(() => {
		refresh();
	}, [refresh]);

	useDialogKeyboard((key) => {
		if (key.name === "escape") {
			dismiss();
			return;
		}
		if (key.name === "r") {
			refresh();
			return;
		}
		if (key.name === "return" && status?.installed) {
			resolve(true);
		}
	}, dialogId);

	return (
		<box flexDirection="column" paddingX={1} gap={1}>
			<text fg={palette.act}>
				<strong>{providerName}</strong>
			</text>

			{checking && <text fg="gray">Checking for Codex CLI...</text>}

			{status?.installed && (
				<box flexDirection="column" gap={1}>
					<text fg={palette.success}>{"\u25cf"} Codex CLI installed</text>
					<text fg="gray">{status.version}</text>
				</box>
			)}

			{status && !status.installed && (
				<box flexDirection="column" gap={1}>
					<text fg="yellow">Codex CLI was not found</text>
					<text fg="gray">{status.reason}</text>
					<text fg="gray">Install Codex CLI from:</text>
					<text fg={palette.act} selectable>
						{CODEX_CLI_INSTALL_URL}
					</text>
				</box>
			)}

			<text fg="gray">
				<em>
					{status?.installed
						? "Enter to continue, R to recheck, Esc to go back"
						: "R to recheck, Esc to go back"}
				</em>
			</text>
		</box>
	);
}

/**
 * Resolves `true` on successful login, `"use_api_key"` when the user opts
 * into manual API key entry (only offered with `allowApiKeyFallback`).
 */
export type OAuthLoginResult = boolean | "use_api_key";

export function OAuthLoginContent(
	props: ChoiceContext<OAuthLoginResult> & {
		providerId: string;
		providerName: string;
		allowApiKeyFallback?: boolean;
	},
) {
	const {
		resolve,
		dismiss,
		dialogId,
		providerId,
		providerName,
		allowApiKeyFallback,
	} = props;
	const [mode, setMode] = useState<"browser" | "device">(
		providerId === "cline" ? "device" : "browser",
	);
	const [status, setStatus] = useState("Opening browser...");
	const [authUrl, setAuthUrl] = useState("");
	const [error, setError] = useState("");
	const [deviceUserCode, setDeviceUserCode] = useState("");
	const [deviceVerifyUrl, setDeviceVerifyUrl] = useState("");
	const [deviceError, setDeviceError] = useState("");
	const activeAuthAttemptRef = useRef<AuthAttempt | undefined>(undefined);

	const startAuthAttempt = useCallback(() => {
		const attempt: AuthAttempt = { cancelled: false };
		activeAuthAttemptRef.current = attempt;
		return attempt;
	}, []);

	const cancelAuthAttempt = useCallback(() => {
		const attempt = activeAuthAttemptRef.current;
		if (attempt) {
			attempt.cancelled = true;
		}
		activeAuthAttemptRef.current = undefined;
	}, []);

	const isActiveAuthAttempt = useCallback((attempt: AuthAttempt) => {
		return activeAuthAttemptRef.current === attempt && !attempt.cancelled;
	}, []);

	const startDeviceAuthCodeFlow = useCallback(() => {
		cancelAuthAttempt();
		const attempt = startAuthAttempt();
		setMode("device");
		setError("");
		setDeviceUserCode("");
		setDeviceVerifyUrl("");
		setDeviceError("");

		const manager = new ProviderSettingsManager();
		const existing = manager.getProviderSettings(providerId);
		const apiBaseUrl =
			existing?.baseUrl?.trim() || getClineEnvironmentConfig().apiBaseUrl;

		startClineDeviceAuth()
			.then((result) => {
				if (!isActiveAuthAttempt(attempt)) return;
				setDeviceUserCode(result.userCode);
				setDeviceVerifyUrl(
					result.verificationUriComplete || result.verificationUri,
				);

				completeClineDeviceAuth({
					deviceCode: result.deviceCode,
					expiresInSeconds: result.expiresInSeconds,
					pollIntervalSeconds: result.pollIntervalSeconds,
					apiBaseUrl,
					provider: providerId,
				})
					.then((credentials) => {
						if (!isActiveAuthAttempt(attempt)) return;
						saveLocalProviderOAuthCredentials(
							manager,
							providerId,
							existing,
							credentials,
						);
						resolve(true);
					})
					.catch((err: unknown) => {
						if (!isActiveAuthAttempt(attempt)) return;
						setDeviceError(err instanceof Error ? err.message : String(err));
					});
			})
			.catch((err: unknown) => {
				if (!isActiveAuthAttempt(attempt)) return;
				setDeviceError(err instanceof Error ? err.message : String(err));
			});
	}, [
		providerId,
		resolve,
		startAuthAttempt,
		isActiveAuthAttempt,
		cancelAuthAttempt,
	]);

	// biome-ignore lint/correctness/useExhaustiveDependencies: run once on mount
	useEffect(() => {
		if (providerId === "cline") {
			startDeviceAuthCodeFlow();
			return cancelAuthAttempt;
		}

		const attempt = startAuthAttempt();
		const manager = new ProviderSettingsManager();
		const existing = manager.getProviderSettings(providerId);

		loginLocalProvider(providerId, existing, (url: string) => {
			setAuthUrl(url);
			setStatus("Waiting for authentication in browser...");
			try {
				void open(url, { wait: false }).catch(() => {
					setStatus(
						"Could not open browser automatically. Open the URL below.",
					);
				});
			} catch {
				setStatus("Could not open browser automatically. Open the URL below.");
			}
		})
			.then((credentials) => {
				if (!isActiveAuthAttempt(attempt)) return;
				saveLocalProviderOAuthCredentials(
					manager,
					providerId,
					existing,
					credentials,
				);
				resolve(true);
			})
			.catch((err: unknown) => {
				if (!isActiveAuthAttempt(attempt)) return;
				const msg = err instanceof Error ? err.message : String(err);
				setError(msg);
				setStatus("Authentication failed");
			});
		return cancelAuthAttempt;
	}, []);

	useDialogKeyboard((key) => {
		if (key.name === "escape") {
			cancelAuthAttempt();
			dismiss();
			return;
		}
		if (key.name === "k" && allowApiKeyFallback) {
			cancelAuthAttempt();
			resolve("use_api_key");
		}
	}, dialogId);

	const escapeHint = allowApiKeyFallback
		? "K to enter an API key instead, Esc to cancel"
		: "Esc to cancel";
	const escapeHintColor = allowApiKeyFallback ? "white" : "gray";

	if (mode === "device") {
		return (
			<box flexDirection="column" paddingX={1} gap={1}>
				<text fg={palette.act}>
					<strong>{providerName}</strong>
				</text>

				{!deviceUserCode && !deviceError && (
					<text fg="gray">Requesting device code...</text>
				)}

				{deviceUserCode && !deviceError && (
					<box flexDirection="column" gap={1}>
						<text fg="gray">Your code:</text>
						<text fg="white" selectable>
							<strong>{deviceUserCode}</strong>
						</text>
						<text fg="gray">Visit this URL and enter the code above:</text>
						<text fg={palette.act} selectable>
							<a href={deviceVerifyUrl}>{deviceVerifyUrl}</a>
						</text>
					</box>
				)}

				{deviceError && <text fg="red">{deviceError}</text>}

				<text fg={escapeHintColor}>
					<em>{escapeHint}</em>
				</text>
			</box>
		);
	}

	return (
		<box flexDirection="column" paddingX={1} gap={1}>
			<text fg={palette.act}>
				<strong>{providerName}</strong>
			</text>

			<text>{status}</text>

			{authUrl && (
				<text fg="gray" selectable>
					<a href={authUrl}>{authUrl}</a>
				</text>
			)}

			{error && <text fg="red">{error}</text>}

			<text fg={escapeHintColor}>
				<em>{escapeHint}</em>
			</text>
		</box>
	);
}

/**
 * Manual API key entry for OAuth-capable providers — the escape hatch for
 * when OAuth login isn't working. Saving clears any stored OAuth tokens so
 * the manual key takes effect (see saveManualProviderApiKey).
 */
export function OAuthApiKeyInputContent(
	props: ChoiceContext<boolean> & {
		providerId: string;
		providerName: string;
		providerSettingsManager: ProviderSettingsManager;
	},
) {
	const {
		resolve,
		dismiss,
		dialogId,
		providerId,
		providerName,
		providerSettingsManager,
	} = props;
	const [value, setValue] = useState("");

	const submit = () => {
		const apiKey = value.trim();
		if (!apiKey) return;
		saveManualProviderApiKey(providerSettingsManager, providerId, apiKey);
		resolve(true);
	};

	useDialogKeyboard((key) => {
		if (key.name === "escape") {
			dismiss();
			return;
		}
		if (key.name === "return") {
			submit();
		}
	}, dialogId);

	return (
		<box flexDirection="column" paddingX={1} gap={1}>
			<text fg={palette.act}>
				<strong>{providerName}</strong>
			</text>

			<text fg="gray">
				Use an API key from your Cline dashboard instead of OAuth login. This
				replaces any saved login tokens.
			</text>

			<box flexDirection="column">
				<text fg="gray">API key</text>
				<box
					border
					borderStyle="rounded"
					borderColor={palette.act}
					paddingX={1}
				>
					<input
						value={value}
						onInput={setValue}
						placeholder="Paste your API key"
						flexGrow={1}
						focused
					/>
				</box>
			</box>

			<text fg="gray">
				<em>Enter to save, Esc to go back</em>
			</text>
		</box>
	);
}

import { useTerminalDimensions } from "@opentui/react";
import type { ChoiceContext } from "@opentui-ui/dialog";
import { useDialogKeyboard } from "@opentui-ui/dialog/react";
import { useMemo, useRef, useState } from "react";
import type { SlashCommandRegistryEntry } from "../../commands/slash-command-registry";
import { palette } from "../../palette";

export const SKILLS_MARKETPLACE_ACTION = "__skills_marketplace__";
export const SKILLS_MARKETPLACE_URL = "https://skills.sh/";

interface SkillsPickerContentProps extends ChoiceContext<string> {
	commands: SlashCommandRegistryEntry[];
}

function matchesFilter(
	command: SlashCommandRegistryEntry,
	filter: string,
): boolean {
	const query = filter.trim().toLowerCase();
	if (!query) return true;
	return (
		command.name.toLowerCase().includes(query) ||
		command.description.toLowerCase().includes(query)
	);
}

export function SkillsPickerContent(props: SkillsPickerContentProps) {
	const { resolve, dismiss, dialogId, commands } = props;
	const { height, width } = useTerminalDimensions();
	const [filter, setFilter] = useState("");
	const [selected, setSelected] = useState(0);

	const filtered = useMemo(
		() => commands.filter((command) => matchesFilter(command, filter)),
		[commands, filter],
	);
	const hasFilter = filter.trim().length > 0;
	const showMarketplace = !hasFilter;
	const totalItems = filtered.length + (showMarketplace ? 1 : 0);
	const marketplaceIndex = filtered.length;
	const safeSelected = Math.min(selected, Math.max(0, totalItems - 1));
	const filteredRef = useRef(filtered);
	filteredRef.current = filtered;
	const selectedRef = useRef(safeSelected);
	selectedRef.current = safeSelected;
	const totalItemsRef = useRef(totalItems);
	totalItemsRef.current = totalItems;
	const marketplaceIndexRef = useRef(marketplaceIndex);
	marketplaceIndexRef.current = marketplaceIndex;
	const showMarketplaceRef = useRef(showMarketplace);
	showMarketplaceRef.current = showMarketplace;

	useDialogKeyboard((key) => {
		if (key.name === "escape") {
			dismiss();
			return;
		}
		if (key.name === "return" || key.name === "enter" || key.name === "tab") {
			if (
				showMarketplaceRef.current &&
				selectedRef.current === marketplaceIndexRef.current
			) {
				resolve(SKILLS_MARKETPLACE_ACTION);
				return;
			}
			const command = filteredRef.current[selectedRef.current];
			if (command) resolve(command.name);
			return;
		}
		if (key.name === "up") {
			setSelected((index) => {
				const len = totalItemsRef.current;
				return len === 0 || index <= 0 ? Math.max(0, len - 1) : index - 1;
			});
			return;
		}
		if (key.name === "down") {
			setSelected((index) => {
				const len = totalItemsRef.current;
				return len === 0 || index >= len - 1 ? 0 : index + 1;
			});
		}
	}, dialogId);

	const maxVisible = Math.max(3, height - 12);
	const start = Math.max(
		0,
		Math.min(
			safeSelected - Math.floor(maxVisible / 2),
			Math.max(0, totalItems - maxVisible),
		),
	);
	const visibleItems = Array.from(
		{ length: Math.min(maxVisible, Math.max(0, totalItems - start)) },
		(_, index) => start + index,
	);
	const commandWidth = Math.min(36, Math.max(18, Math.floor(width * 0.32)));
	const enterAction =
		totalItems === 0
			? undefined
			: safeSelected === marketplaceIndex && showMarketplace
				? "open"
				: "insert";

	return (
		<box flexDirection="column" gap={1}>
			<box flexDirection="row" justifyContent="space-between">
				<text fg="white">
					<strong>Skills</strong>
				</text>
				<text fg="gray">esc</text>
			</box>

			<box border borderStyle="rounded" borderColor="gray" paddingX={1}>
				<input
					onInput={(value: string) => {
						setFilter(value);
						setSelected(0);
					}}
					placeholder="Search skills..."
					flexGrow={1}
					focused
				/>
			</box>

			<box flexDirection="column">
				<text fg="magenta">Skills</text>

				{totalItems === 0 ? (
					<box flexDirection="column">
						<text fg="gray">No matching skills found.</text>
					</box>
				) : (
					visibleItems.map((absoluteIndex) => {
						const isSelected = absoluteIndex === safeSelected;
						if (showMarketplace && absoluteIndex === marketplaceIndex) {
							return (
								<box
									key="skills-marketplace"
									flexDirection="row"
									backgroundColor={isSelected ? palette.selection : undefined}
									onMouseDown={() => resolve(SKILLS_MARKETPLACE_ACTION)}
									height={1}
								>
									<text fg={isSelected ? palette.textOnSelection : palette.act}>
										{isSelected ? "❯ " : "  "}
										Browse more skills at {SKILLS_MARKETPLACE_URL}
									</text>
								</box>
							);
						}

						const command = filtered[absoluteIndex];
						if (!command) return null;
						return (
							<box
								key={command.name}
								flexDirection="row"
								backgroundColor={isSelected ? palette.selection : undefined}
								onMouseDown={() => resolve(command.name)}
								height={1}
							>
								<text
									fg={isSelected ? palette.textOnSelection : "white"}
									width={commandWidth}
									flexShrink={0}
								>
									{command.name}
								</text>
								<text fg={isSelected ? palette.textOnSelection : "gray"}>
									{command.description}
								</text>
							</box>
						);
					})
				)}
			</box>

			{commands.length === 0 && !hasFilter && (
				<text fg="gray">
					Install skills with: <strong>npx skills add owner/repo</strong>
				</text>
			)}

			<text fg="gray">
				<em>
					Type to filter, ↑/↓ navigate
					{enterAction ? `, Enter to ${enterAction}` : ""}, Esc to close
				</em>
			</text>
		</box>
	);
}

import type { ToolApprovalRequest } from "@cline/shared";
import type { ChoiceContext } from "@opentui-ui/dialog";
import { useDialogKeyboard } from "@opentui-ui/dialog/react";
import type React from "react";
import { palette } from "../../palette";
import {
	parseApplyPatchInput,
	parseEditorInput,
	parseReadFilesInput,
	parseRunCommandsInput,
	parseSearchInput,
	parseSpawnAgentInput,
	parseWebFetchInput,
	shortenPath,
} from "../../utils/tool-parsing";

export function formatApprovalParams(
	toolName: string,
	rawInput: unknown,
): React.ReactNode {
	switch (toolName) {
		case "read_files": {
			const info = parseReadFilesInput(rawInput);
			if (!info?.files.length) break;
			return info.files.map((f, i) => {
				const range =
					f.startLine != null
						? ` lines ${f.startLine}-${f.endLine ?? "end"}`
						: "";
				return (
					<text key={f.path} fg="gray" selectable>
						{"  "}
						{shortenPath(f.path, 60)}
						{range && <span fg="gray">{range}</span>}
						{i < info.files.length - 1 ? "\n" : ""}
					</text>
				);
			});
		}
		case "run_commands": {
			const info = parseRunCommandsInput(rawInput);
			if (!info?.commands.length) break;
			return info.commands.map((cmd, i) => (
				<text key={`cmd-${i.toString()}`} fg="gray" selectable>
					{"  "}$ {cmd}
				</text>
			));
		}
		case "editor":
		case "edit":
		case "write": {
			const info = parseEditorInput(rawInput);
			if (!info) break;
			return (
				<text fg="gray" selectable>
					{"  "}
					{shortenPath(info.path, 60)}
				</text>
			);
		}
		case "apply_patch": {
			const patchInfo = parseApplyPatchInput(rawInput);
			if (!patchInfo?.files.length) break;
			return (
				<text fg="gray" selectable>
					{"  "}
					{patchInfo.files.map((f) => shortenPath(f, 60)).join(", ")}
				</text>
			);
		}
		case "search_codebase": {
			const info = parseSearchInput(rawInput);
			if (!info?.queries.length) break;
			return (
				<text fg="gray" selectable>
					{"  "}
					{info.queries.join(", ")}
				</text>
			);
		}
		case "fetch_web_content": {
			const info = parseWebFetchInput(rawInput);
			if (!info?.urls.length) break;
			return info.urls.map((url, i) => (
				<text key={`url-${i.toString()}`} fg="gray" selectable>
					{"  "}
					{url}
				</text>
			));
		}
		case "spawn_agent": {
			const info = parseSpawnAgentInput(rawInput);
			if (!info) break;
			const task =
				info.task.length > 80 ? `${info.task.slice(0, 80)}...` : info.task;
			return (
				<text fg="gray" selectable>
					{"  "}
					{task}
				</text>
			);
		}
		case "switch_to_act_mode":
			return (
				<text fg="gray" selectable>
					{"  "}Switch from plan mode to act mode
				</text>
			);
		case "ask_followup_question": {
			if (rawInput && typeof rawInput === "object" && "question" in rawInput) {
				const q = String((rawInput as { question: unknown }).question);
				const preview = q.length > 80 ? `${q.slice(0, 80)}...` : q;
				return (
					<text fg="gray" selectable>
						{"  "}
						{preview}
					</text>
				);
			}
			break;
		}
	}

	if (rawInput != null) {
		const json = JSON.stringify(rawInput, null, 2);
		const preview = json.length > 200 ? `${json.slice(0, 200)}...` : json;
		return (
			<text fg="gray" selectable>
				{"  "}
				{preview}
			</text>
		);
	}
	return null;
}

export function ToolApprovalContent(
	props: ChoiceContext<boolean> & { request: ToolApprovalRequest },
) {
	useDialogKeyboard((key) => {
		if (key.name === "y" || key.name === "return") {
			props.resolve(true);
		}
		if (key.name === "n" || key.name === "escape") {
			props.resolve(false);
		}
	}, props.dialogId);

	const params = formatApprovalParams(
		props.request.toolName,
		props.request.input,
	);

	return (
		<box flexDirection="column" paddingX={1}>
			<text fg="yellow">Approve tool call?</text>

			<text fg={palette.act} marginTop={1}>
				<strong>{props.request.toolName}</strong>
			</text>

			{params && (
				<box flexDirection="column" marginTop={1}>
					{params}
				</box>
			)}

			<text marginTop={1}>
				<span fg={palette.success}>[y]</span> approve{"  "}
				<span fg="red">[n]</span> deny
			</text>
		</box>
	);
}

import type { ScrollBoxRenderable } from "@opentui/core";
import { useKeyboard, useTerminalDimensions } from "@opentui/react";
import { useCallback, useEffect, useRef, useState } from "react";
import { palette } from "../palette";
import type { RuntimeToolInteraction } from "../types";
import { formatApprovalParams } from "./dialogs/tool-approval";

export interface InlineToolResponseProps {
	interaction: RuntimeToolInteraction;
	accent: string;
	inputBackground: string;
	inputForeground: string;
	inputPlaceholder: string;
	onResolveToolApproval: (id: number, approved: boolean) => void;
	onResolveAskQuestion: (id: number, answer: string | null) => void;
}

function isPrintableKey(name: string): boolean {
	return name.length === 1 || name === "space";
}

function keyToText(name: string): string {
	return name === "space" ? " " : name;
}

function getToolShellMaxHeight(terminalHeight: number): number {
	return Math.max(7, Math.min(14, Math.floor(terminalHeight * 0.38)));
}

function getAskQuestionShellMaxHeight(terminalHeight: number): number {
	const preferredHeight = Math.max(11, Math.floor(terminalHeight * 0.58));
	const availableHeight = Math.max(7, terminalHeight - 3);
	return Math.min(18, preferredHeight, availableHeight);
}

function getAskQuestionBodyHeight(shellMaxHeight: number): number {
	return Math.max(1, shellMaxHeight - 4);
}

function addWrappedWidth(input: {
	rows: number;
	lineWidth: number;
	width: number;
	maxWidth: number;
}): { rows: number; lineWidth: number } {
	if (input.width <= 0) {
		return { rows: input.rows, lineWidth: input.lineWidth };
	}

	let rows = input.rows;
	let remainingWidth = input.width;
	let lineWidth = input.lineWidth;

	if (lineWidth > 0) {
		const availableWidth = input.maxWidth - lineWidth;
		if (remainingWidth <= availableWidth) {
			return { rows, lineWidth: lineWidth + remainingWidth };
		}

		remainingWidth -= Math.max(0, availableWidth);
		rows += 1;
		lineWidth = 0;
	}

	rows += Math.max(0, Math.ceil(remainingWidth / input.maxWidth) - 1);
	lineWidth = remainingWidth % input.maxWidth || input.maxWidth;

	return { rows, lineWidth };
}

function countWrappedRows(text: string, width: number): number {
	const safeWidth = Math.max(1, width);
	const paragraphs = text.split("\n");
	let rows = 0;

	for (const paragraph of paragraphs) {
		rows += 1;
		let lineWidth = 0;
		const tokens = paragraph.match(/\s+|\S+/g) ?? [];

		for (const token of tokens) {
			const tokenWidth = Bun.stringWidth(token);
			const isWhitespace = /^\s+$/.test(token);

			if (
				!isWhitespace &&
				lineWidth > 0 &&
				lineWidth + tokenWidth > safeWidth
			) {
				rows += 1;
				lineWidth = 0;
			}

			const next = addWrappedWidth({
				rows,
				lineWidth,
				width: tokenWidth,
				maxWidth: safeWidth,
			});
			rows = next.rows;
			lineWidth = next.lineWidth;
		}
	}

	return rows;
}

function getAskQuestionContentHeight(input: {
	terminalWidth: number;
	question: string;
	options: string[];
	customText: string;
}): number {
	const questionWidth = Math.max(1, input.terminalWidth - 3);
	const optionTextWidth = Math.max(1, input.terminalWidth - 7);
	const questionRows = countWrappedRows(input.question, questionWidth);
	const optionRows = input.options.reduce(
		(rows, option) => rows + countWrappedRows(option, optionTextWidth),
		0,
	);
	const customRows = countWrappedRows(input.customText, optionTextWidth);
	return questionRows + 1 + optionRows + customRows;
}

function getAskQuestionChoiceId(interactionId: number, index: number): string {
	return `ask-question-${interactionId.toString()}-choice-${index.toString()}`;
}

function Shell(
	props: Pick<
		InlineToolResponseProps,
		"accent" | "inputBackground" | "inputForeground"
	> & {
		title: string;
		maxHeight?: number;
		overflow?: "hidden";
		children: React.ReactNode;
	},
) {
	const { height } = useTerminalDimensions();
	const maxHeight = props.maxHeight ?? getToolShellMaxHeight(height);

	return (
		<box
			flexDirection="column"
			width="100%"
			maxHeight={maxHeight}
			overflow={props.overflow}
			backgroundColor={props.inputBackground}
			paddingX={1}
			paddingY={1}
			gap={1}
		>
			<box flexDirection="row" gap={1}>
				<text fg={palette.act}>{props.title}</text>
			</box>
			{props.children}
		</box>
	);
}

function ChoiceButton(props: {
	label: string;
	selected: boolean;
	selectedFg?: string;
	onPress: () => void;
}) {
	return (
		// biome-ignore lint/a11y/noStaticElementInteractions: OpenTUI boxes handle terminal mouse input.
		<box
			paddingX={1}
			backgroundColor={props.selected ? palette.selection : undefined}
			onMouseDown={props.onPress}
		>
			<text
				fg={
					props.selected
						? (props.selectedFg ?? palette.textOnSelection)
						: undefined
				}
			>
				{props.label}
			</text>
		</box>
	);
}

function ToolApprovalResponse(
	props: InlineToolResponseProps & {
		interaction: Extract<RuntimeToolInteraction, { kind: "tool_approval" }>;
	},
) {
	const [selected, setSelected] = useState<"approve" | "deny">("approve");
	const selectedRef = useRef(selected);
	selectedRef.current = selected;
	const request = props.interaction.request;
	const interactionId = props.interaction.id;
	const onResolveToolApproval = props.onResolveToolApproval;
	const params = formatApprovalParams(request.toolName, request.input);

	const resolve = useCallback(
		(approved: boolean) => {
			onResolveToolApproval(interactionId, approved);
		},
		[interactionId, onResolveToolApproval],
	);

	useKeyboard((key) => {
		if (key.name === "y") {
			resolve(true);
			return;
		}
		if (key.name === "n" || key.name === "escape") {
			resolve(false);
			return;
		}
		if (key.name === "left" || key.name === "right" || key.name === "tab") {
			setSelected((current) => (current === "approve" ? "deny" : "approve"));
			return;
		}
		if (key.name === "return" || key.name === "enter") {
			resolve(selectedRef.current === "approve");
		}
	});

	return (
		<Shell
			title="Cline needs permission"
			accent={props.accent}
			inputBackground={props.inputBackground}
			inputForeground={props.inputForeground}
		>
			<box flexDirection="column" gap={1}>
				<text fg="yellow">Approve tool call?</text>
				<text fg={props.accent} selectable>
					{request.toolName}
				</text>
				{params && (
					<box flexDirection="column" overflow="hidden">
						{params}
					</box>
				)}
			</box>
			<box flexDirection="row" gap={1}>
				<ChoiceButton
					label="[y] Approve"
					selected={selected === "approve"}
					onPress={() => resolve(true)}
				/>
				<ChoiceButton
					label="[n] Deny"
					selected={selected === "deny"}
					onPress={() => resolve(false)}
				/>
			</box>
		</Shell>
	);
}

function AskQuestionResponse(
	props: InlineToolResponseProps & {
		interaction: Extract<RuntimeToolInteraction, { kind: "ask_question" }>;
	},
) {
	const { interaction } = props;
	const { height, width } = useTerminalDimensions();
	const [selected, setSelected] = useState(0);
	const [customValue, setCustomValue] = useState("");
	const [customEmptyAttempted, setCustomEmptyAttempted] = useState(false);
	const scrollRef = useRef<ScrollBoxRenderable | null>(null);
	const selectedRef = useRef(0);
	const customValueRef = useRef("");
	const interactionId = interaction.id;
	const onResolveAskQuestion = props.onResolveAskQuestion;
	const customIndex = interaction.options.length;
	const isTyping = selected === customIndex;
	const totalChoices = interaction.options.length + 1;
	const shellMaxHeight = getAskQuestionShellMaxHeight(height);
	const maxBodyHeight = getAskQuestionBodyHeight(shellMaxHeight);
	const customText = isTyping
		? customValue
			? `${customValue}|`
			: customEmptyAttempted
				? "Type a response first..."
				: "Type a response..."
		: "Type a response...";
	const bodyHeight = Math.min(
		maxBodyHeight,
		getAskQuestionContentHeight({
			terminalWidth: width,
			question: interaction.question,
			options: interaction.options,
			customText,
		}),
	);

	const selectIndex = useCallback(
		(index: number) => {
			selectedRef.current = index;
			setSelected(index);
			if (index !== customIndex) {
				setCustomEmptyAttempted(false);
			}
		},
		[customIndex],
	);

	const setCustomText = useCallback((value: string) => {
		customValueRef.current = value;
		setCustomValue(value);
		if (value.trim()) {
			setCustomEmptyAttempted(false);
		}
	}, []);

	const resolveAnswer = useCallback(
		(answer: string | null) => {
			onResolveAskQuestion(interactionId, answer);
		},
		[interactionId, onResolveAskQuestion],
	);

	useEffect(() => {
		const choiceId = getAskQuestionChoiceId(interactionId, selected);
		let canceled = false;
		const scrollSelectedChoiceIntoView = () => {
			if (canceled) {
				return;
			}

			scrollRef.current?.scrollChildIntoView(choiceId);
		};

		scrollSelectedChoiceIntoView();
		queueMicrotask(scrollSelectedChoiceIntoView);
		const timeout = setTimeout(scrollSelectedChoiceIntoView, 0);
		return () => {
			canceled = true;
			clearTimeout(timeout);
		};
	}, [interactionId, selected]);

	useKeyboard((key) => {
		const typing = selectedRef.current === customIndex;
		if (key.name === "escape") {
			if (typing && customValueRef.current) {
				setCustomText("");
				return;
			}
			resolveAnswer(null);
			return;
		}
		if (typing && key.name === "backspace") {
			setCustomText(customValueRef.current.slice(0, -1));
			return;
		}
		if (typing && key.name === "delete") {
			setCustomText("");
			return;
		}
		if (key.name === "return" || key.name === "enter") {
			if (typing) {
				const answer = customValueRef.current.trim();
				if (answer) {
					resolveAnswer(answer);
					return;
				}
				setCustomEmptyAttempted(true);
				return;
			}
			resolveAnswer(interaction.options[selectedRef.current] ?? "");
			return;
		}
		if (key.name === "up" || (key.ctrl && key.name === "p")) {
			const next =
				selectedRef.current <= 0 ? totalChoices - 1 : selectedRef.current - 1;
			selectIndex(next);
			return;
		}
		if (key.name === "down" || (key.ctrl && key.name === "n")) {
			const next =
				selectedRef.current >= totalChoices - 1 ? 0 : selectedRef.current + 1;
			selectIndex(next);
			return;
		}
		if (!typing && key.name >= "1" && key.name <= "9") {
			const index = Number.parseInt(key.name, 10) - 1;
			const option = interaction.options[index];
			if (option) {
				resolveAnswer(option);
				return;
			}
		}
		if (typing && !key.ctrl && !key.meta && isPrintableKey(key.name)) {
			const value = keyToText(key.name);
			setCustomText(`${customValueRef.current}${value}`);
			return;
		}
		if (!key.ctrl && !key.meta && isPrintableKey(key.name)) {
			const value = keyToText(key.name);
			setCustomText(value);
			selectIndex(customIndex);
		}
	});

	return (
		<Shell
			title="Cline is asking a question"
			accent={props.accent}
			inputBackground={props.inputBackground}
			inputForeground={props.inputForeground}
			maxHeight={shellMaxHeight}
			overflow="hidden"
		>
			<scrollbox
				ref={scrollRef}
				height={bodyHeight}
				width="100%"
				scrollY
				scrollX={false}
				viewportOptions={{ overflow: "hidden" }}
				contentOptions={{ flexDirection: "column" }}
			>
				<box flexDirection="column" gap={1} flexShrink={0} width="100%">
					<text fg={props.inputForeground} selectable flexShrink={0}>
						{interaction.question}
					</text>

					<box flexDirection="column" flexShrink={0} width="100%">
						{interaction.options.map((option, index) => {
							const optionSelected = !isTyping && selected === index;
							return (
								// biome-ignore lint/a11y/noStaticElementInteractions: OpenTUI boxes handle terminal mouse input.
								<box
									id={getAskQuestionChoiceId(interactionId, index)}
									key={`${index.toString()}:${option}`}
									paddingX={1}
									flexDirection="row"
									gap={1}
									flexShrink={0}
									width="100%"
									backgroundColor={
										optionSelected ? palette.selection : undefined
									}
									onMouseDown={() => resolveAnswer(option)}
								>
									<text
										fg={optionSelected ? palette.textOnSelection : "gray"}
										flexShrink={0}
									>
										{optionSelected ? ">" : " "}
									</text>
									<text
										fg={
											optionSelected
												? palette.textOnSelection
												: props.inputForeground
										}
										flexGrow={1}
										flexShrink={1}
									>
										{option}
									</text>
								</box>
							);
						})}
						{/* biome-ignore lint/a11y/noStaticElementInteractions: OpenTUI boxes handle terminal mouse input. */}
						<box
							id={getAskQuestionChoiceId(interactionId, customIndex)}
							paddingX={1}
							flexDirection="row"
							gap={1}
							flexShrink={0}
							width="100%"
							backgroundColor={isTyping ? palette.selection : undefined}
							onMouseDown={() => selectIndex(customIndex)}
						>
							<text
								fg={isTyping ? palette.textOnSelection : "gray"}
								flexShrink={0}
							>
								{isTyping ? ">" : " "}
							</text>
							{isTyping ? (
								<text fg={palette.textOnSelection} flexGrow={1} flexShrink={1}>
									{customText}
								</text>
							) : (
								<text fg={props.inputPlaceholder} flexGrow={1} flexShrink={1}>
									Type a response...
								</text>
							)}
						</box>
					</box>
				</box>
			</scrollbox>
		</Shell>
	);
}

export function InlineToolResponse(props: InlineToolResponseProps) {
	if (props.interaction.kind === "tool_approval") {
		return <ToolApprovalResponse {...props} interaction={props.interaction} />;
	}

	return <AskQuestionResponse {...props} interaction={props.interaction} />;
}

import {
	decodePasteBytes,
	type KeyEvent,
	type PasteEvent,
	stripAnsiSequences,
	type TextareaRenderable,
} from "@opentui/core";
import { useCallback, useRef } from "react";
import {
	readClipboardImageDataUrl,
	readImagePasteAttachment,
	readImmediateImagePasteAttachment,
} from "../utils/image-paste";
import { shouldCompactPastedText } from "../utils/pasted-snippets";

export type TextareaHandle = Pick<
	TextareaRenderable,
	| "plainText"
	| "onSubmit"
	| "focus"
	| "setText"
	| "insertText"
	| "cursorOffset"
	| "visualCursor"
	| "height"
	| "virtualLineCount"
	| "extmarks"
	| "getSelection"
>;

export interface InputBarProps {
	accent: string;
	ruleColor: string;
	inputForeground: string;
	inputPlaceholder: string;
	placeholder: string;
	initialValue: string;
	inputKey: number;
	onSubmit: () => void;
	onContentChange: (text: string) => void;
	onImagePaste?: (dataUrl: string) => string;
	onLargeTextPaste?: (text: string) => string;
	onVisualCursorChange?: (cursor: {
		visualCol: number;
		visualRow: number;
	}) => void;
	onFocusRequest?: () => void;
	textareaRef?: React.MutableRefObject<TextareaHandle | null>;
}

function readTextPaste(event: PasteEvent): string | null {
	if (
		event.metadata?.kind === "binary" ||
		event.metadata?.mimeType?.startsWith("image/")
	) {
		return null;
	}

	return stripAnsiSequences(decodePasteBytes(event.bytes));
}

export function InputBar(props: InputBarProps) {
	const {
		accent,
		ruleColor,
		inputForeground,
		inputPlaceholder,
		placeholder,
		initialValue,
		inputKey,
		onSubmit,
		onContentChange,
	} = props;
	const localRef = useRef<TextareaHandle | null>(null);
	const inputRef = props.textareaRef ?? localRef;

	const onSubmitRef = useRef(onSubmit);
	onSubmitRef.current = onSubmit;
	const onContentChangeRef = useRef(onContentChange);
	onContentChangeRef.current = onContentChange;
	const onImagePasteRef = useRef(props.onImagePaste);
	onImagePasteRef.current = props.onImagePaste;
	const onLargeTextPasteRef = useRef(props.onLargeTextPaste);
	onLargeTextPasteRef.current = props.onLargeTextPaste;
	const onVisualCursorChangeRef = useRef(props.onVisualCursorChange);
	onVisualCursorChangeRef.current = props.onVisualCursorChange;

	const emitVisualCursorChange = useCallback(() => {
		const cursor = inputRef.current?.visualCursor;
		if (!cursor) return;
		onVisualCursorChangeRef.current?.({
			visualCol: cursor.visualCol,
			visualRow: cursor.visualRow,
		});
	}, [inputRef]);

	const textareaRefCallback = useCallback(
		(node: unknown) => {
			const ta = node as TextareaHandle | null;
			inputRef.current = ta;
			if (ta) {
				ta.onSubmit = () => {
					onSubmitRef.current();
				};
				emitVisualCursorChange();
			}
		},
		[emitVisualCursorChange, inputRef],
	);

	const insertImageAttachment = useCallback(
		(dataUrl: string) => {
			const marker = onImagePasteRef.current?.(dataUrl);
			if (!marker) return;
			inputRef.current?.insertText(`${marker} `);
			queueMicrotask(() => {
				const text = inputRef.current?.plainText ?? "";
				onContentChangeRef.current(text);
			});
		},
		[inputRef],
	);

	const insertAtomicText = useCallback(
		(text: string) => {
			const ta = inputRef.current;
			if (!ta) return;

			const selection = ta.getSelection();
			const start = selection
				? Math.min(selection.start, selection.end)
				: ta.cursorOffset;
			ta.insertText(text);
			ta.extmarks.create({
				start,
				end: start + text.length,
				virtual: true,
			});
			queueMicrotask(() => {
				const plainText = inputRef.current?.plainText ?? "";
				onContentChangeRef.current(plainText);
			});
		},
		[inputRef],
	);

	const handlePaste = useCallback(
		(event: PasteEvent) => {
			if (onImagePasteRef.current) {
				const immediate = readImmediateImagePasteAttachment(event);
				if (immediate) {
					event.preventDefault();
					insertImageAttachment(immediate.dataUrl);
					return;
				}
			}

			const pastedText = readTextPaste(event);
			if (
				pastedText &&
				shouldCompactPastedText(pastedText) &&
				onLargeTextPasteRef.current
			) {
				const marker = onLargeTextPasteRef.current(pastedText);
				event.preventDefault();
				insertAtomicText(marker);
				return;
			}

			if (onImagePasteRef.current) {
				void readImagePasteAttachment(event).then((attachment) => {
					if (!attachment) return;
					event.preventDefault();
					insertImageAttachment(attachment.dataUrl);
				});
			}
		},
		[insertAtomicText, insertImageAttachment],
	);

	const handleKeyDown = useCallback(
		(event: KeyEvent) => {
			if (!event.ctrl || event.name !== "v" || !onImagePasteRef.current) {
				return;
			}

			void readClipboardImageDataUrl().then((dataUrl) => {
				if (!dataUrl) return;
				event.preventDefault();
				insertImageAttachment(dataUrl);
			});
		},
		[insertImageAttachment],
	);

	return (
		<box
			flexDirection="row"
			alignItems="flex-start"
			border={["top", "bottom"]}
			borderStyle="single"
			borderColor={ruleColor}
			onMouseDown={props.onFocusRequest}
		>
			<text fg={accent}>
				<strong>{"❯"}</strong>
			</text>
			<box flexGrow={1} paddingLeft={1}>
				<textarea
					key={inputKey}
					ref={textareaRefCallback as React.RefCallback<never>}
					initialValue={initialValue}
					onContentChange={() => {
						queueMicrotask(() => {
							const text = inputRef.current?.plainText ?? "";
							onContentChangeRef.current(text);
							emitVisualCursorChange();
						});
					}}
					onPaste={handlePaste}
					onKeyDown={(event: KeyEvent) => {
						handleKeyDown(event);
						queueMicrotask(() => {
							emitVisualCursorChange();
						});
					}}
					placeholder={placeholder}
					placeholderColor={inputPlaceholder}
					textColor={inputForeground}
					focusedTextColor={inputForeground}
					focused
					flexGrow={1}
					cursorColor={accent}
					minHeight={1}
					maxHeight={5}
					wrapMode="word"
					keyBindings={[
						{ name: "return", action: "submit" },
						{ name: "return", shift: true, action: "newline" },
						{ name: "return", ctrl: true, action: "newline" },
						{ name: "return", meta: true, action: "newline" },
					]}
				/>
			</box>
		</box>
	);
}

import type {
	ClineRecommendedModel,
	ClineRecommendedModelsData,
} from "@cline/core";

export type ClineModelPickerTier = "recommended" | "subscribed" | "free";

export interface ClineModelPickerItem {
	kind: "model";
	model: ClineRecommendedModel;
	tier: ClineModelPickerTier;
}

export interface ClineModelPickerBrowse {
	kind: "browse";
}

export type ClineModelPickerEntry =
	| ClineModelPickerItem
	| ClineModelPickerBrowse;

export const CLINE_MODEL_PICKER_TIER_LABELS: Record<
	ClineModelPickerTier,
	string
> = {
	recommended: "Recommended",
	subscribed: "Subscribed",
	free: "Free",
};

// Featured entries for the sectioned picker, keyed by provider: cline gets
// Recommended/Free with a browse-all escape into the full catalog; cline-pass
// gets Subscribed/Free (see buildClinePassModelEntries for why no browse-all).
export function buildFeaturedModelEntries(
	providerId: string,
	data: ClineRecommendedModelsData,
): ClineModelPickerEntry[] {
	return providerId === "cline-pass"
		? buildClinePassModelEntries(data)
		: buildClineModelEntries(data);
}

function buildClineModelEntries(
	data: ClineRecommendedModelsData,
): ClineModelPickerEntry[] {
	const entries: ClineModelPickerEntry[] = [];
	for (const m of data.recommended) {
		entries.push({ kind: "model", model: m, tier: "recommended" });
	}
	for (const m of data.free) {
		entries.push({ kind: "model", model: m, tier: "free" });
	}
	entries.push({ kind: "browse" });
	return entries;
}

// Shown under the Free section header when picking a model for ClinePass
export const CLINE_PASS_FREE_SECTION_DESCRIPTION =
	"Try with limited usage, separate from ClinePass quota.";

// ClinePass shows the subscription's models plus the Cline free models — both
// providers hit the same Cline API, so free models are selectable in place
// (they ride usage billing at $0 instead of the subscription quota).
// No "browse all" entry when the clinePass bucket is populated: unlike cline,
// the ClinePass catalog contains exactly these two buckets, so the sections
// already list every selectable model. An empty clinePass bucket means the
// fetch fell back to the bundled list (which has no pass models) — without an
// escape into the full catalog a subscriber could only pick free models, so
// browse-all comes back in that degraded mode.
function buildClinePassModelEntries(
	data: ClineRecommendedModelsData,
): ClineModelPickerEntry[] {
	const entries: ClineModelPickerEntry[] = [];
	for (const m of data.clinePass) {
		entries.push({ kind: "model", model: m, tier: "subscribed" });
	}
	for (const m of data.free) {
		entries.push({ kind: "model", model: m, tier: "free" });
	}
	if (data.clinePass.length === 0) {
		entries.push({ kind: "browse" });
	}
	return entries;
}

// The quota explainer only makes sense in the ClinePass picker, which is the
// only picker that has a "subscribed" section
export function freeTierDescriptionFor(
	entries: ClineModelPickerEntry[],
): string | undefined {
	const isClinePassPicker = entries.some(
		(entry) => entry.kind === "model" && entry.tier === "subscribed",
	);
	return isClinePassPicker ? CLINE_PASS_FREE_SECTION_DESCRIPTION : undefined;
}

// OpenRouter marks free variants with "(free)" in names and ":free" in ids to
// disambiguate them from their paid twins. Inside the sectioned pickers the
// Free header already says it, so the markers are redundant — but keep them in
// flat lists (e.g. browse-all), where both variants appear side by side.
export function stripFreeMarker(displayName: string): string {
	return displayName
		.replace(/\s*\(free\)\s*$/i, "")
		.replace(/:free$/i, "")
		.trim();
}

import { describe, expect, it } from "vitest";
import {
	buildFeaturedModelEntries,
	CLINE_PASS_FREE_SECTION_DESCRIPTION,
	freeTierDescriptionFor,
	stripFreeMarker,
} from "./cline-model-entries";

const model = (id: string) => ({ id, name: id, description: "", tags: [] });

describe("cline model picker entries", () => {
	it("builds Recommended/Free sections for the cline provider", () => {
		const entries = buildFeaturedModelEntries("cline", {
			recommended: [model("anthropic/claude-sonnet-5")],
			free: [model("deepseek/deepseek-v4-flash")],
			clinePass: [model("cline-pass/glm-5.1")],
		});

		expect(entries).toEqual([
			{
				kind: "model",
				model: model("anthropic/claude-sonnet-5"),
				tier: "recommended",
			},
			{
				kind: "model",
				model: model("deepseek/deepseek-v4-flash"),
				tier: "free",
			},
			{ kind: "browse" },
		]);
	});

	it("builds Subscribed/Free sections for the cline-pass provider", () => {
		const entries = buildFeaturedModelEntries("cline-pass", {
			recommended: [model("anthropic/claude-sonnet-5")],
			free: [model("deepseek/deepseek-v4-flash")],
			clinePass: [model("cline-pass/glm-5.1"), model("cline-pass/kimi-k2.6")],
		});

		expect(entries).toEqual([
			{ kind: "model", model: model("cline-pass/glm-5.1"), tier: "subscribed" },
			{
				kind: "model",
				model: model("cline-pass/kimi-k2.6"),
				tier: "subscribed",
			},
			{
				kind: "model",
				model: model("deepseek/deepseek-v4-flash"),
				tier: "free",
			},
		]);
	});

	it("adds the browse-all escape when the clinePass bucket is empty", () => {
		// The fetch fell back to the bundled list (no pass models); the sections
		// alone would leave a subscriber able to pick only free models.
		const entries = buildFeaturedModelEntries("cline-pass", {
			recommended: [],
			free: [model("deepseek/deepseek-v4-flash")],
			clinePass: [],
		});

		expect(entries).toEqual([
			{
				kind: "model",
				model: model("deepseek/deepseek-v4-flash"),
				tier: "free",
			},
			{ kind: "browse" },
		]);
	});

	it("attaches the quota explainer only to the ClinePass picker's free section", () => {
		const data = {
			recommended: [model("anthropic/claude-sonnet-5")],
			free: [model("deepseek/deepseek-v4-flash")],
			clinePass: [model("cline-pass/glm-5.1")],
		};

		expect(
			freeTierDescriptionFor(buildFeaturedModelEntries("cline-pass", data)),
		).toBe(CLINE_PASS_FREE_SECTION_DESCRIPTION);
		expect(
			freeTierDescriptionFor(buildFeaturedModelEntries("cline", data)),
		).toBe(undefined);
	});

	it("strips redundant free markers from display names", () => {
		expect(stripFreeMarker("Laguna M.1 (free)")).toBe("Laguna M.1");
		expect(stripFreeMarker("Trinity Large Preview (FREE)")).toBe(
			"Trinity Large Preview",
		);
		expect(stripFreeMarker("laguna-m.1:free")).toBe("laguna-m.1");
		expect(stripFreeMarker("DeepSeek V4 Flash")).toBe("DeepSeek V4 Flash");
	});
});

// @jsxImportSource @opentui/react

import {
	type ClineRecommendedModelsData,
	fetchClineRecommendedModels,
} from "@cline/core";
import type { ReactNode } from "react";
import { useEffect, useState } from "react";
import "opentui-spinner/react";
import { palette } from "../../palette";
import {
	CLINE_MODEL_PICKER_TIER_LABELS,
	type ClineModelPickerEntry,
	freeTierDescriptionFor,
	stripFreeMarker,
} from "./cline-model-entries";

export {
	buildFeaturedModelEntries,
	CLINE_MODEL_PICKER_TIER_LABELS,
	type ClineModelPickerBrowse,
	type ClineModelPickerEntry,
	type ClineModelPickerItem,
	type ClineModelPickerTier,
	freeTierDescriptionFor,
	stripFreeMarker,
} from "./cline-model-entries";

function tagColor(tag: string): string {
	if (tag === "FREE") return palette.success;
	if (tag === "BEST") return "magenta";
	return palette.act;
}

function resolveDisplayName(
	modelId: string,
	knownModels?: Record<string, unknown>,
): string {
	if (knownModels) {
		const candidates = [modelId, modelId.split("/").pop()];
		for (const key of candidates) {
			if (!key) continue;
			const hit = knownModels[key] as { name?: string } | undefined;
			if (hit?.name) return stripFreeMarker(hit.name);
		}
	}
	const fallback = modelId.includes("/")
		? (modelId.split("/").pop() ?? modelId)
		: modelId;
	return stripFreeMarker(fallback);
}

export function useClineRecommendedModels() {
	const [data, setData] = useState<ClineRecommendedModelsData | null>(null);
	const [loading, setLoading] = useState(true);

	useEffect(() => {
		let cancelled = false;
		fetchClineRecommendedModels()
			.then((result) => {
				if (!cancelled) setData(result);
			})
			.finally(() => {
				if (!cancelled) setLoading(false);
			});
		return () => {
			cancelled = true;
		};
	}, []);

	return { data, loading };
}

export function ClineModelPicker(props: {
	entries: ClineModelPickerEntry[];
	selected: number;
	loading?: boolean;
	knownModels?: Record<string, unknown>;
	currentModelId?: string;
}) {
	const { entries, selected, loading, knownModels, currentModelId } = props;

	if (loading) {
		return (
			<box flexDirection="row" gap={1} paddingX={1}>
				<spinner name="dots" color="gray" />
				<text fg="gray">Loading models...</text>
			</box>
		);
	}

	let lastTier: string | null = null;
	let isFirstHeader = true;
	const rows: ReactNode[] = [];
	const freeTierDescription = freeTierDescriptionFor(entries);

	for (let i = 0; i < entries.length; i++) {
		const entry = entries[i];
		if (!entry) continue;
		const isSel = i === selected;

		if (entry.kind === "model") {
			if (entry.tier !== lastTier) {
				lastTier = entry.tier;
				const label = CLINE_MODEL_PICKER_TIER_LABELS[entry.tier];
				rows.push(
					<box
						key={`tier-${entry.tier}`}
						paddingX={1}
						marginTop={isFirstHeader ? 0 : 1}
						flexDirection="column"
					>
						<text fg="gray">{label}</text>
						{entry.tier === "free" && freeTierDescription && (
							<text fg="gray">
								<em>{freeTierDescription}</em>
							</text>
						)}
					</box>,
				);
				isFirstHeader = false;
			}

			const tags = entry.model.tags;
			const name = resolveDisplayName(entry.model.id, knownModels);
			const isCurrent = currentModelId === entry.model.id;
			rows.push(
				<box
					key={entry.model.id}
					paddingX={1}
					flexDirection="row"
					gap={1}
					backgroundColor={isSel ? palette.selection : undefined}
				>
					<text fg={isSel ? palette.textOnSelection : "gray"} flexShrink={0}>
						{isSel ? "\u276f" : " "}
					</text>
