					paddingX={1}
				>
					<input
						value={modelId}
						onInput={(value: string) => {
							setModelId(value);
							setError("");
						}}
						placeholder="provider/model"
						flexGrow={1}
						focused={!onProvider}
					/>
				</box>
				{error && <text fg="red">{error}</text>}
			</box>

			<text fg="gray">Enter to save, Tab to change provider, Esc to close</text>
		</box>
	);
}

export function ModelSelectorContent(
	props: ChoiceContext<string> & {
		currentModel: string;
		currentProviderName: string;
		models: ModelOption[];
		showCustomModelId?: boolean;
	},
) {
	const {
		resolve,
		dismiss,
		dialogId,
		currentModel,
		currentProviderName,
		models,
		showCustomModelId = true,
	} = props;
	const [search, setSearch] = useState("");
	const [selected, setSelected] = useState(() => {
		const idx = models.findIndex((m) => m.key === currentModel);
		return idx >= 0 ? idx : 0;
	});
	const [onProvider, setOnProvider] = useState(false);
	const [isCreatingCustomModel, setIsCreatingCustomModel] = useState(false);
	const [customModelId, setCustomModelId] = useState("");
	const [customModelError, setCustomModelError] = useState("");

	const filtered = useMemo(() => {
		if (!search) return models;
		const q = search.toLowerCase();
		const scored = models
			.map((m) => ({ model: m, score: fuzzyScore(m, q) }))
			.filter((r) => r.score > 0);
		scored.sort((a, b) => b.score - a.score);
		return scored.map((r) => r.model);
	}, [models, search]);

	const optionCount = filtered.length + (showCustomModelId ? 1 : 0);
	const safeSelected = Math.min(selected, Math.max(0, optionCount - 1));

	useDialogKeyboard((key) => {
		if (key.name === "escape") {
			if (isCreatingCustomModel) {
				setIsCreatingCustomModel(false);
				setCustomModelError("");
				return;
			}
			dismiss();
			return;
		}
		if (isCreatingCustomModel) return;
		if (key.name === "return" || key.name === "enter") {
			if (onProvider) {
				resolve(CHANGE_PROVIDER_ACTION);
				return;
			}
			const model = filtered[safeSelected];
			if (model) {
				resolve(model.key);
				return;
			}
			if (showCustomModelId && safeSelected === filtered.length) {
				setIsCreatingCustomModel(true);
				setCustomModelId("");
				setCustomModelError("");
			}
			return;
		}
		if (key.name === "tab") {
			if (onProvider) {
				setOnProvider(false);
			} else {
				setOnProvider(true);
			}
			return;
		}
		if (key.name === "up" || (key.ctrl && key.name === "p")) {
			if (!onProvider) {
				setSelected((s) =>
					optionCount === 0 ? 0 : s <= 0 ? optionCount - 1 : s - 1,
				);
			}
			return;
		}
		if (key.name === "down" || (key.ctrl && key.name === "n")) {
			if (!onProvider) {
				setSelected((s) =>
					optionCount === 0 ? 0 : s >= optionCount - 1 ? 0 : s + 1,
				);
			}
			return;
		}
	}, dialogId);

	if (isCreatingCustomModel) {
		return (
			<box flexDirection="column" gap={1}>
				<text>Create custom model ID</text>

				<ProviderRow providerName={currentProviderName} focused={false} />

				<box flexDirection="column" gap={0}>
					<text fg="gray">Model ID</text>
					<box
						border
						borderStyle="rounded"
						borderColor={customModelError ? "red" : "gray"}
						paddingX={1}
					>
						<input
							value={customModelId}
							onInput={(v: string) => {
								setCustomModelId(v);
								setCustomModelError("");
							}}
							onSubmit={() => {
								const modelId = customModelId.trim();
								if (!modelId) {
									setCustomModelError("Enter a model ID");
									return;
								}
								resolve(modelId);
							}}
							placeholder=""
							flexGrow={1}
							focused
						/>
					</box>
					{customModelError && <text fg="red">{customModelError}</text>}
				</box>

				<text fg="gray">
					Enter to create, Esc to go back to model selection
				</text>
			</box>
		);
	}

	return (
		<box flexDirection="column" gap={1}>
			<text>Select Model</text>

			<ProviderRow providerName={currentProviderName} focused={onProvider} />

			<box border borderStyle="rounded" borderColor="gray" paddingX={1}>
				<input
					onInput={(v: string) => {
						setSearch(v);
						setSelected(0);
						setOnProvider(false);
					}}
					placeholder="Search models..."
					flexGrow={1}
					focused
				/>
			</box>

			<ModelList
				items={filtered}
				selected={safeSelected}
				dimmed={onProvider}
				currentModel={currentModel}
				onSelect={resolve}
				showCustomModelId={showCustomModelId}
				onCreateCustomModel={() => {
					setIsCreatingCustomModel(true);
					setCustomModelId("");
					setCustomModelError("");
				}}
			/>

			<text fg="gray">
				Type to search, ↑/↓ navigate, Enter to select, Tab to change provider,
				Esc to close
			</text>
		</box>
	);
}

