import "opentui-spinner/react";
import { useEffect, useState } from "react";
import { useSession } from "../contexts/session-context";
import { palette } from "../palette";
import type { QueuedPromptItem } from "../types";

function truncatePrompt(prompt: string): string {
	return prompt.length > 64 ? `${prompt.slice(0, 64)}...` : prompt;
}

function attachmentLabel(count: number): string {
	if (count <= 0) return "";
	return count === 1 ? " 1 attachment" : ` ${count} attachments`;
}

export function QueuedPrompts(props: {
	items: QueuedPromptItem[];
	selectedId: string | null;
	editingId: string | null;
	onEditConfirm: (id: string, prompt: string) => void;
}) {
	const session = useSession();
	if (props.items.length === 0) return null;

	const selected = props.selectedId
		? props.items.find((item) => item.id === props.selectedId)
		: undefined;
	const selectedIsEditing = selected?.id === props.editingId;
	const escapeHint = session.isRunning ? "Esc cancels turn" : "Esc back";
	const hint = selected
		? selectedIsEditing
			? "Enter confirm, Esc cancel"
			: selected.steer
				? session.isRunning
					? "Waiting. ↑/↓ navigate, Tab edit, Esc cancels turn"
					: `Steered next. ↑/↓ navigate, Tab edit, ${escapeHint}`
				: `↑/↓ navigate, Enter steer, Tab edit, ${escapeHint}`
		: "↑ steer or edit messages";

	return (
		<box
			flexDirection="column"
			border
			borderStyle="rounded"
			borderColor={selected ? palette.selection : "gray"}
			paddingX={1}
		>
			<text fg="gray">
				<em>Queued messages:</em>
			</text>
			{props.items.map((item) => {
				const isSelected = item.id === props.selectedId;
				const isEditing = item.id === props.editingId;
				return (
					<QueuedPromptRow
						key={item.id}
						item={item}
						selected={isSelected}
						editing={isEditing}
						onEditConfirm={(prompt) => props.onEditConfirm(item.id, prompt)}
					/>
				);
			})}
			<text fg="gray">
				<em>{hint}</em>
			</text>
		</box>
	);
}

function QueuedPromptRow(props: {
	item: QueuedPromptItem;
	selected: boolean;
	editing: boolean;
	onEditConfirm: (prompt: string) => void;
}) {
	const { item, selected, editing } = props;
	const [editValue, setEditValue] = useState(item.prompt);

	useEffect(() => {
		if (editing) {
			setEditValue(item.prompt);
		}
	}, [editing, item.prompt]);

	return (
		<box
			paddingX={1}
			flexDirection="row"
			gap={1}
			backgroundColor={selected ? palette.selection : undefined}
		>
			{item.steer && !editing ? (
				<spinner
					name="dots"
					color={selected ? palette.textOnSelection : "gray"}
				/>
			) : (
				<text fg={selected ? palette.textOnSelection : "gray"} flexShrink={0}>
					{selected ? "❯" : " "}
				</text>
			)}
			{editing ? (
				<input
					value={editValue}
					onInput={setEditValue}
					onSubmit={() => props.onEditConfirm(editValue)}
					placeholder="Edit message..."
					backgroundColor={palette.selection}
					focusedBackgroundColor={palette.selection}
					textColor={palette.textOnSelection}
					cursorColor={palette.textOnSelection}
					placeholderColor={palette.textOnSelection}
					focused
					flexGrow={1}
				/>
			) : (
				<text fg={selected ? palette.textOnSelection : undefined} flexGrow={1}>
					{truncatePrompt(item.prompt)}
				</text>
			)}
			{!editing && item.attachmentCount > 0 && (
				<text fg={selected ? palette.textOnSelection : "gray"} flexShrink={0}>
					{attachmentLabel(item.attachmentCount)}
				</text>
			)}
		</box>
	);
}

import { useTerminalDimensions } from "@opentui/react";
import { useEffect, useState } from "react";
import { type CroppedFrame, FRAMES } from "./robot-frames";

const FRAME_STRAIGHT = 0;
const FRAME_BOTTOM_LEFT = 64;
const FRAME_BOTTOM_CENTER = 96;
const FRAME_BOTTOM_RIGHT = 128;

const ROBOT_HEIGHT = 12;

function buildTheme(defaultColor: string): Record<string, string> {
	return {
		black: defaultColor,
		whiteBright: defaultColor,
		gray: defaultColor,
	};
}

function getColor(key: string, theme: Record<string, string>): string {
	return theme[key] || key;
}

interface ColorSegment {
	text: string;
	fg: string;
}

function buildRowSegments(
	row: string,
	rowIdx: number,
	colors: Record<string, string>,
	defaultColor: string,
	theme: Record<string, string>,
): ColorSegment[] {
	const segments: ColorSegment[] = [];
	let currentFg = defaultColor;
	let currentText = "";

	for (let col = 0; col < row.length; col++) {
		const key = `${col},${rowIdx}`;
		const fg = colors[key] ? getColor(colors[key], theme) : defaultColor;
		if (fg !== currentFg) {
			if (currentText) segments.push({ text: currentText, fg: currentFg });
			currentFg = fg;
			currentText = row[col];
		} else {
			currentText += row[col];
		}
	}
	if (currentText) segments.push({ text: currentText, fg: currentFg });
	return segments;
}

function RobotFrame(props: { frame: CroppedFrame; defaultColor: string }) {
	const { frame, defaultColor } = props;
	const theme = buildTheme(defaultColor);
	return (
		<box flexDirection="column">
			{frame.rows.map((row, rowIdx) => {
				const segments = buildRowSegments(
					row,
					rowIdx,
					frame.colors,
					defaultColor,
					theme,
				);
				return (
					// biome-ignore lint/suspicious/noArrayIndexKey: static animation frame with fixed row order
					<text key={`row-${rowIdx}`}>
						{segments.map((seg, j) => (
							// biome-ignore lint/suspicious/noArrayIndexKey: static animation frame with fixed row order
							<span key={`seg-${rowIdx}-${j}`} fg={seg.fg}>
								{seg.text}
							</span>
						))}
					</text>
				);
			})}
		</box>
	);
}

export function RobotAnimation(props: {
	cursorX: number;
	cursorY: number;
	defaultColor?: string;
}) {
	const [frameIndex, setFrameIndex] = useState(FRAME_STRAIGHT);
	const [targetFrame, setTargetFrame] = useState(FRAME_STRAIGHT);
	const { width, height } = useTerminalDimensions();

	const faceX = Math.floor(width / 2);
	const trackStartY = Math.floor(height / 2) - Math.floor(ROBOT_HEIGHT / 2);

	useEffect(() => {
		const dx = props.cursorX - faceX;
		const dy = props.cursorY - trackStartY;

		if (dy < 0) {
			setTargetFrame(FRAME_STRAIGHT);
			return;
		}

		const maxTrackY = height - trackStartY;
		if (dy > maxTrackY) {
			setTargetFrame(FRAME_STRAIGHT);
			return;
		}

		const maxOffset = 40;
		const clampedDx = Math.max(-maxOffset, Math.min(maxOffset, dx));
		const normalized = clampedDx / maxOffset;

		let target: number;
		if (normalized <= 0) {
			target = Math.round(
				FRAME_BOTTOM_LEFT +
					(1 + normalized) * (FRAME_BOTTOM_CENTER - FRAME_BOTTOM_LEFT),
			);
		} else {
			target = Math.round(
				FRAME_BOTTOM_CENTER +
					normalized * (FRAME_BOTTOM_RIGHT - FRAME_BOTTOM_CENTER),
			);
		}

		setTargetFrame(target);
	}, [props.cursorX, props.cursorY, faceX, trackStartY, height]);

	useEffect(() => {
		const interval = setInterval(() => {
			setFrameIndex((current) => {
				if (current === targetFrame) return current;
				const diff = targetFrame - current;
				const step =
					Math.sign(diff) * Math.max(Math.abs(Math.round(diff * 0.5)), 1);
				const next = current + step;
				if (
					(diff > 0 && next > targetFrame) ||
					(diff < 0 && next < targetFrame)
				) {
					return targetFrame;
				}
				return next;
			});
		}, 12);

		return () => clearInterval(interval);
	}, [targetFrame]);

	const safeIndex = Math.max(0, Math.min(frameIndex, FRAMES.length - 1));
	const frame = FRAMES[safeIndex];
	if (!frame) return null;

	return (
		<box flexDirection="column" alignItems="center" width="100%">
			<RobotFrame frame={frame} defaultColor={props.defaultColor ?? "white"} />
		</box>
	);
}

import encodedFrames from "./robot-frames.generated.json";

export interface CroppedFrame {
	rows: string[];
	colors: Record<string, string>;
}

interface EncodedRobotFrames {
	schema: 1;
	width: number;
	height: number;
	palette: string[];
	frames: [rows: string[], colorRuns: number[]][];
}

function decodeRunLengthColors(
	colorRuns: number[],
	palette: string[],
	width: number,
	height: number,
): Record<string, string> {
	const colors: Record<string, string> = {};
	let cellIndex = 0;

	for (let offset = 0; offset < colorRuns.length; offset += 2) {
		const count = colorRuns[offset];
		const paletteIndex = colorRuns[offset + 1];
		if (count === undefined || paletteIndex === undefined) {
			throw new Error(`Invalid robot frame color run at offset ${offset}`);
		}

		const color = palette[paletteIndex];
		if (!color) {
			throw new Error(`Unknown robot frame palette index ${paletteIndex}`);
		}

		for (let i = 0; i < count; i++) {
			const x = cellIndex % width;
			const y = Math.floor(cellIndex / width);
			colors[`${x},${y}`] = color;
			cellIndex++;
		}
	}

	const expectedCells = width * height;
	if (cellIndex !== expectedCells) {
		throw new Error(
			`Robot frame decoded to ${cellIndex} cells, expected ${expectedCells}`,
		);
	}

	return colors;
}

function decodeRobotFrames(encoded: EncodedRobotFrames): CroppedFrame[] {
	if (encoded.schema !== 1) {
		throw new Error(`Unsupported robot frame schema ${encoded.schema}`);
	}

	return encoded.frames.map(([rows, colorRuns]) => ({
		rows,
		colors: decodeRunLengthColors(
			colorRuns,
			encoded.palette,
			encoded.width,
			encoded.height,
		),
	}));
}

export const FRAMES: CroppedFrame[] = decodeRobotFrames(
	encodedFrames as EncodedRobotFrames,
);

