import type { AgentMode } from "@cline/core";
import { useTerminalDimensions } from "@opentui/react";
import {
	shouldShowCliUsageCost,
	shouldShowCliUsageCoveredBySubscription,
} from "../../utils/usage-cost-display";
import {
	useTerminalBackground,
	useTerminalTheme,
} from "../hooks/use-terminal-background";
import {
	getDefaultForeground,
	getModeAccent,
	getSuccessColor,
} from "../palette";
import { HOME_VIEW_MAX_WIDTH } from "../types";

export function createContextBar(
	used: number,
	total?: number,
	width = 6,
): { filled: string; empty: string } {
	const normalizedWidth = Math.max(0, Math.floor(width));
	const ratio = total && total > 0 ? Math.min(used / total, 1) : 0;
	const filledCount =
		total && total > 0 && used > 0
			? used >= total
				? normalizedWidth
				: Math.min(
						Math.max(1, Math.ceil(ratio * normalizedWidth)),
						Math.max(0, normalizedWidth - 1),
					)
			: 0;
	const emptyCount = Math.max(0, normalizedWidth - filledCount);
	return {
		filled: "\u2588".repeat(filledCount),
		empty: "\u2588".repeat(emptyCount),
	};
}

export function resolveContextBarFilledForeground(
	defaultForeground: string | undefined,
): string {
	return defaultForeground ?? "#ffffff";
}

function formatCost(cost: number): string {
	return `$${cost.toFixed(2)}`;
}

function formatCostText(providerId: string, totalCost: number): string {
	// Subscription providers (ClinePass) have no per-use cost worth surfacing.
	if (shouldShowCliUsageCoveredBySubscription(providerId)) {
		return "";
	}

	if (!shouldShowCliUsageCost(providerId)) {
		return "";
	}

	return formatCost(totalCost);
}

export function formatStatusBarUsageText(input: {
	totalTokens: number;
	totalCost: number;
	providerId: string;
}): string {
	const tokens = `(${input.totalTokens.toLocaleString()})`;
	const costText = formatCostText(input.providerId, input.totalCost);

	if (!costText) {
		return tokens;
	}

	return `${tokens} ${costText}`;
}

// knownModels keys are bare IDs ("claude-sonnet-4-6") but config.modelId
// may include a provider prefix ("anthropic/claude-sonnet-4-6"), so we
// try the full ID first, then strip the prefix and retry.
function lookupModelInfo(
	modelId: string,
	knownModels?: Record<string, unknown>,
): { name?: string } | undefined {
	if (!knownModels) return undefined;
	const candidates = [modelId, modelId.split("/").pop()];
	for (const key of candidates) {
		if (!key) continue;
		const hit = knownModels[key] as { name?: string } | undefined;
		if (hit) return hit;
	}
	return undefined;
}

export function resolveModelDisplayName(config: {
	providerId?: string;
	modelId: string;
	knownModels?: Record<string, unknown>;
	thinking?: boolean;
	reasoningEffort?: string;
}): string {
	const info = lookupModelInfo(config.modelId, config.knownModels);
	const modelIdTail = config.modelId.split("/").pop() ?? config.modelId;
	let displayName = info?.name ?? modelIdTail;
	if (config.thinking && config.reasoningEffort) {
		displayName = `${displayName} (${config.reasoningEffort})`;
	}
	if (config.providerId === "cline-pass") {
		displayName = `ClinePass: ${displayName}`;
	}
	return displayName;
}

export function resolveModelMaxInputTokens(config: {
	modelId: string;
	knownModels?: Record<string, unknown>;
}): number | undefined {
	const info = (lookupModelInfo(config.modelId, config.knownModels) ?? {}) as {
		maxInputTokens?: number;
		contextWindow?: number;
	};
	if (typeof info.maxInputTokens === "number" && info.maxInputTokens > 0) {
		return info.maxInputTokens;
	}
	if (typeof info.contextWindow === "number" && info.contextWindow > 0) {
		return info.contextWindow;
	}
	return undefined;
}

export interface StatusBarProps {
	providerId: string;
	modelId: string;
	totalTokens: number;
	totalCost: number;
	maxInputTokens?: number;
	uiMode: AgentMode;
	autoApproveAll: boolean;
	workspaceName: string;
	gitBranch: string | null;
	gitDiffStats: {
		files: number;
		additions: number;
		deletions: number;
	} | null;
	onToggleMode?: () => void;
	variant?: "home" | "chat";
}

export function StatusBar(props: StatusBarProps) {
	const {
		modelId,
		totalTokens,
		totalCost,
		maxInputTokens,
		uiMode,
		autoApproveAll,
		workspaceName,
		gitBranch,
		gitDiffStats,
		onToggleMode,
	} = props;

	const { width } = useTerminalDimensions();
	const terminalBg = useTerminalBackground();
	const terminalTheme = useTerminalTheme();
	const defaultFg = getDefaultForeground(terminalBg);
	const contextBarFilledFg = resolveContextBarFilledForeground(defaultFg);
	const actAccent = getModeAccent("act", terminalTheme);
	const planAccent = getModeAccent("plan", terminalTheme);
	const successColor = getSuccessColor(terminalTheme);
	const hasMaxInputTokens =
		typeof maxInputTokens === "number" &&
		Number.isFinite(maxInputTokens) &&
		maxInputTokens > 0;
	const bar = hasMaxInputTokens
		? createContextBar(totalTokens, maxInputTokens)
		: undefined;

	// Available content width after accounting for padding.
	// Home view: parent box is capped at 60 wide, status bar adds paddingX=1 (-2).
	// Chat view: status bar adds paddingX=1 (-2).
	const avail =
		props.variant === "home"
			? Math.min(width, HOME_VIEW_MAX_WIDTH) - 2
			: width - 2;

	// Row 1 layout: [model + context info] .... [Plan/Act toggle]
	// When the full row doesn't fit, context info drops to its own row 2.
	// Model ID truncates with "..." before wrapping; toggle stays right-aligned.
	const toggleWidth = 20;
	const usageText = formatStatusBarUsageText({
		totalTokens,
		totalCost,
		providerId: props.providerId,
	});
	const contextText = bar
		? ` ${bar.filled}${bar.empty} ${usageText}`
		: ` ${usageText}`;
	const firstRowFits =
		modelId.length + contextText.length + toggleWidth + 1 <= avail;
	const renderContextText = (withLeadingSpace: boolean) => (
		<>
			{withLeadingSpace && " "}
			{bar && (
				<>
					<span fg={contextBarFilledFg}>{bar.filled}</span>
					<span fg="gray">{bar.empty}</span>{" "}
				</>
			)}
			{usageText}
		</>
	);

	const modelMaxLen = Math.max(
		10,
		avail - toggleWidth - (firstRowFits ? contextText.length : 0) - 1,
	);
	const truncatedModel =
		modelId.length > modelMaxLen
			? `${modelId.slice(0, modelMaxLen - 3)}...`
			: modelId;

	// Repo row: [workspace (branch) | N files +X -Y]
	// Git stats stay visible; path/branch truncates with "..." when narrow.
	const hasGitDiff = gitDiffStats && gitDiffStats.files > 0;
	const gitSuffix = hasGitDiff
		? ` | ${gitDiffStats.files} file${gitDiffStats.files !== 1 ? "s" : ""} +${gitDiffStats.additions} -${gitDiffStats.deletions}`
		: "";
	const pathPart = workspaceName + (gitBranch ? ` (${gitBranch})` : "");
	const pathMax = Math.max(5, avail - gitSuffix.length);
	const truncatedPath =
		pathPart.length > pathMax
			? `${pathPart.slice(0, pathMax - 3)}...`
			: pathPart;
	return (
		<box flexDirection="column" paddingX={1}>
			<box flexDirection="row" justifyContent="space-between">
				<text fg="gray">
					{truncatedModel}
					{firstRowFits && renderContextText(true)}
				</text>
				<box
					flexDirection="row"
					gap={1}
					flexShrink={0}
					onMouseDown={onToggleMode}
				>
					<text fg={uiMode === "plan" ? planAccent : "gray"}>
						{uiMode === "plan" ? "●" : "○"} Plan
					</text>
					<text fg={uiMode === "act" ? actAccent : "gray"}>
						{uiMode === "act" ? "●" : "○"} Act
					</text>
					<text fg="gray">(Tab)</text>
				</box>
			</box>

			{!firstRowFits && <text fg="gray">{renderContextText(false)}</text>}

			<text fg={defaultFg}>
				{truncatedPath}
				{hasGitDiff && (
					<span fg="gray">
						{" | "}
						{gitDiffStats.files} file
						{gitDiffStats.files !== 1 ? "s" : ""}{" "}
						<span fg={successColor}>+{gitDiffStats.additions}</span>{" "}
						<span fg="red">-{gitDiffStats.deletions}</span>
					</span>
				)}
			</text>

			{autoApproveAll ? (
				<text fg={defaultFg}>
					<span fg={successColor}>
						{"\u23f5\u23f5"} Auto-approve all enabled
					</span>
					<span fg="gray"> (Shift+Tab)</span>
				</text>
			) : (
				<text fg="gray">Auto-approve all disabled (Shift+Tab)</text>
			)}
		</box>
	);
}

import { useTerminalDimensions } from "@opentui/react";
import { palette } from "../palette";

export type ToastVariant = "info" | "success" | "error";

export type ToastState = {
	message: string;
	variant: ToastVariant;
};

const variantColor: Record<ToastVariant, string> = {
	info: palette.selection,
	success: palette.success,
	error: palette.error,
};

export function Toast(props: { toast: ToastState | null }) {
	const { width } = useTerminalDimensions();

	if (!props.toast) {
		return null;
	}

	const availableWidth = Math.max(1, width - 4);
	const maxWidth = Math.min(44, availableWidth);
	const right = width < 32 ? 0 : 2;
	const color = variantColor[props.toast.variant];

	return (
		<box
			position="absolute"
			zIndex={100}
			top={1}
			right={right}
			maxWidth={maxWidth}
			border
			borderStyle="rounded"
			borderColor={color}
			paddingX={1}
		>
			<text fg={color} wrapMode="word">
				{props.toast.message}
			</text>
		</box>
	);
}

import { useState } from "react";
import { useTerminalTheme } from "../hooks/use-terminal-background";
import { diffPalettes, palette, type TerminalTheme } from "../palette";
import { makeUnifiedDiff } from "../utils/diff";
import { getSyntaxStyle } from "../utils/syntax-style";
import { getToolErrorPresentation } from "../utils/tool-errors";
import {
	detectLanguage,
	extractFullOutputText,
	parseApplyPatchInput,
	parseEditorInput,
	parseReadFilesInput,
	shortenPath,
} from "../utils/tool-parsing";

const MAX_COLLAPSED_LINES = 5;
const RESULT = "\u23bf";

export interface ToolOutputProps {
	toolName: string;
	outputSummary: string;
	rawOutput?: unknown;
	rawInput?: unknown;
	error?: string;
}

function isAskTool(toolName: string): boolean {
	return toolName === "ask_question" || toolName === "ask_followup_question";
}

function isBashTool(toolName: string): boolean {
	return toolName === "run_commands" || toolName === "bash";
}

function isReadTool(toolName: string): boolean {
	return toolName === "read_files";
}

function isEditTool(toolName: string): boolean {
	return (
		toolName === "editor" ||
		toolName === "edit" ||
		toolName === "write" ||
		toolName === "apply_patch"
	);
}

function BashOutput(props: { fullText: string; theme: TerminalTheme }) {
	const [expanded, setExpanded] = useState(false);
	const { fullText } = props;
	const trimmed = fullText.trimEnd();
	const lines = trimmed.split("\n");
	const firstLine = lines[0] ?? "";
	const hasMore = lines.length > 1;

	if (!expanded) {
		return (
			<box
				flexDirection="column"
				paddingLeft={2}
				onMouseDown={() => hasMore && setExpanded(true)}
			>
				<text selectable>
					<span fg="gray">
						{RESULT} {firstLine}
					</span>
				</text>
				{hasMore && (
					<text fg="gray">
						{"   "}... {lines.length - 1} more lines
					</text>
				)}
			</box>
		);
	}

	return (
		<box
			flexDirection="column"
			paddingLeft={2}
			onMouseDown={() => setExpanded(false)}
		>
			<text fg="gray">{RESULT} output:</text>
			<box marginLeft={2} marginTop={1} marginBottom={1}>
				<code
					content={fullText}
					filetype="bash"
					syntaxStyle={getSyntaxStyle(props.theme)}
					selectable
				/>
			</box>
		</box>
	);
}

function ReadOutput(props: { fullText: string; rawInput?: unknown }) {
	const { fullText, rawInput } = props;
	const lines = fullText.split("\n");

	const readInfo = parseReadFilesInput(rawInput);
	const filePath = readInfo?.files[0]?.path;
	const language = filePath ? detectLanguage(filePath) : undefined;

	return (
		<box paddingLeft={2}>
			<text fg="gray">
				{RESULT} {lines.length} lines
				{language ? ` | ${language}` : ""}
			</text>
		</box>
	);
}

function DiffStats(props: {
	added: number;
	removed: number;
	language?: string;
}) {
	const { added, removed, language } = props;
	return (
		<text fg="gray">
			{RESULT}{" "}
			{removed > 0 ? (
				<>
					<span fg={palette.success}>+{added}</span>{" "}
					<span fg="red">-{removed}</span> lines
				</>
			) : (
				<span fg={palette.success}>+{added} lines (new)</span>
			)}
			{language ? ` | ${language}` : ""}
		</text>
	);
}

function EditOutput(props: {
	rawInput?: unknown;
	outputSummary: string;
	theme: TerminalTheme;
}) {
	const [expanded, setExpanded] = useState(true);
	const editorInfo = parseEditorInput(props.rawInput);

	if (!editorInfo?.oldText && !editorInfo?.newText) {
		return (
			<box paddingLeft={2}>
				<text fg="gray">
					{"  "} {props.outputSummary || "done"}
				</text>
			</box>
		);
	}

	const oldText = editorInfo.oldText ?? "";
	const newText = editorInfo.newText;
	const language = detectLanguage(editorInfo.path);
	const addedLines = newText.split("\n").length;
	const removedLines = oldText ? oldText.split("\n").length : 0;
	const diffPalette = diffPalettes[props.theme];

	return (
		<box
			flexDirection="column"
			paddingLeft={2}
			onMouseDown={() => setExpanded(!expanded)}
		>
			<DiffStats
				added={addedLines}
				removed={removedLines}
				language={language}
			/>
			{expanded && (
				<box marginLeft={2} marginTop={1} marginBottom={1}>
					<diff
						diff={makeUnifiedDiff(oldText, newText, editorInfo.path)}
						view="unified"
						filetype={language ?? "text"}
						syntaxStyle={getSyntaxStyle(props.theme)}
						showLineNumbers
						addedBg={diffPalette.addedBg}
						removedBg={diffPalette.removedBg}
						addedLineNumberBg={diffPalette.addedLineNumberBg}
						removedLineNumberBg={diffPalette.removedLineNumberBg}
						addedSignColor={diffPalette.addedSignColor}
						removedSignColor={diffPalette.removedSignColor}
						lineNumberFg={diffPalette.lineNumberFg}
					/>
				</box>
			)}
		</box>
	);
}

function ApplyPatchOutput(props: {
	rawInput?: unknown;
	outputSummary: string;
	theme: TerminalTheme;
}) {
	const [expanded, setExpanded] = useState(true);
	const info = parseApplyPatchInput(props.rawInput);

	if (!info) {
		return (
			<box paddingLeft={2}>
				<text fg="gray">
					{"  "} {props.outputSummary || "done"}
				</text>
			</box>
		);
	}

	const fileLabel = info.files.map((f) => shortenPath(f, 40)).join(", ");
	const language = detectLanguage(info.files[0] ?? "");
	const diffPalette = diffPalettes[props.theme];

	return (
		<box
			flexDirection="column"
			paddingLeft={2}
			onMouseDown={() => setExpanded(!expanded)}
		>
			<DiffStats
				added={info.additions}
				removed={info.deletions}
				language={fileLabel}
			/>
			{expanded && (
				<box marginLeft={2} marginTop={1} marginBottom={1}>
					<diff
						diff={info.diff}
						view="unified"
						filetype={language ?? "text"}
						syntaxStyle={getSyntaxStyle(props.theme)}
						showLineNumbers
						addedBg={diffPalette.addedBg}
						removedBg={diffPalette.removedBg}
						addedLineNumberBg={diffPalette.addedLineNumberBg}
						removedLineNumberBg={diffPalette.removedLineNumberBg}
						addedSignColor={diffPalette.addedSignColor}
						removedSignColor={diffPalette.removedSignColor}
						lineNumberFg={diffPalette.lineNumberFg}
					/>
				</box>
			)}
		</box>
	);
}

function GenericOutput(props: { outputSummary: string; fullText?: string }) {
	const [expanded, setExpanded] = useState(false);
	const displayText = props.fullText || props.outputSummary;
	const lines = displayText.split("\n");
	const isLong = lines.length > MAX_COLLAPSED_LINES;

	if (!displayText.trim()) return null;

	if (!expanded) {
		const collapsedText = isLong
			? `${lines.slice(0, MAX_COLLAPSED_LINES).join("\n")}\n... ${lines.length - MAX_COLLAPSED_LINES} more lines`
			: displayText;

		return (
			<box
				flexDirection="column"
				paddingLeft={2}
				onMouseDown={() => isLong && setExpanded(true)}
			>
				<text selectable>
					<span fg="gray">
						{isLong ? RESULT : " "} {collapsedText}
					</span>
				</text>
			</box>
		);
	}

	return (
		<box
			flexDirection="column"
			paddingLeft={2}
			onMouseDown={() => setExpanded(false)}
		>
			<text fg="gray">{RESULT}</text>
			<box marginLeft={2} marginBottom={1}>
				<text fg="gray" selectable>
					{displayText}
				</text>
			</box>
		</box>
	);
}

export function ToolOutput(props: ToolOutputProps) {
	const { toolName, outputSummary, rawOutput, rawInput, error } = props;
	const terminalTheme = useTerminalTheme();
	const [errorExpanded, setErrorExpanded] = useState(false);

	if (error) {
		const presentation = getToolErrorPresentation(error);
		const isWarning = presentation.severity === "warning";
		const showDetail =
			errorExpanded && presentation.detail !== presentation.summary.trim();
		return (
			<box
				flexDirection="column"
				paddingLeft={2}
				onMouseDown={() => setErrorExpanded(!errorExpanded)}
			>
				<text fg={isWarning ? "yellow" : "red"} selectable>
					{"  "} {isWarning ? "!" : "Error:"} {presentation.summary}
				</text>
				{showDetail && (
					<box paddingLeft={3}>
						<text fg="gray" selectable>
							{presentation.detail}
						</text>
					</box>
				)}
			</box>
		);
	}

	if (toolName === "switch_to_act_mode") return null;
	if (!outputSummary.trim() && !rawOutput) return null;

	const fullText = rawOutput ? extractFullOutputText(rawOutput) : undefined;

	if (isAskTool(toolName)) {
		const answer = (fullText || outputSummary).trim();
		if (!answer) return null;
		return (
			<box paddingLeft={2}>
				<text fg="gray" selectable>
					{RESULT} {answer}
				</text>
			</box>
		);
	}

	if (isBashTool(toolName)) {
		return (
			<BashOutput fullText={fullText || outputSummary} theme={terminalTheme} />
		);
	}

	if (isReadTool(toolName)) {
		return (
			<ReadOutput fullText={fullText || outputSummary} rawInput={rawInput} />
		);
	}

	if (toolName === "apply_patch") {
		return (
			<ApplyPatchOutput
				rawInput={rawInput}
				outputSummary={outputSummary}
				theme={terminalTheme}
			/>
		);
	}

	if (isEditTool(toolName)) {
		return (
			<EditOutput
				rawInput={rawInput}
				outputSummary={outputSummary}
				theme={terminalTheme}
			/>
		);
	}

	return <GenericOutput outputSummary={outputSummary} fullText={fullText} />;
}

import { useCallback, useRef, useState } from "react";
import { useTerminalBackground } from "../hooks/use-terminal-background";
import { getDefaultForeground } from "../palette";
import { RobotAnimation } from "./robot-animation";

export function useMouseTracker() {
	const [cursor, setCursor] = useState({ x: 0, y: 0 });
	const lastUpdateRef = useRef(0);

	const onMouseMove = useCallback((event: { x: number; y: number }) => {
		const now = Date.now();
		if (now - lastUpdateRef.current < 30) return;
		lastUpdateRef.current = now;
		setCursor({ x: event.x, y: event.y });
	}, []);

	return { cursor, onMouseMove };
}

export function TrackedRobot(props: { cursorX?: number; cursorY?: number }) {
	const terminalBg = useTerminalBackground();
	const defaultFg = getDefaultForeground(terminalBg);
	return (
		<box width="100%" flexShrink={1} overflow="hidden">
			<RobotAnimation
				cursorX={props.cursorX ?? 0}
				cursorY={props.cursorY ?? 0}
				defaultColor={defaultFg}
			/>
		</box>
	);
}

import type { AgentEvent, TeamEvent } from "@cline/core";
import type React from "react";
import { createContext, useEffect, useRef } from "react";
import type {
	PendingPromptSnapshot,
	PendingPromptSubmittedEvent,
} from "../../runtime/session-events";
import type { TuiProps } from "../types";

interface EventBridgeHandlers {
	onAgentEvent: (event: AgentEvent) => void;
	onTeamEvent: (event: TeamEvent) => void;
	onPendingPrompts: (event: PendingPromptSnapshot) => void;
	onPendingPromptSubmitted: (event: PendingPromptSubmittedEvent) => void;
}

const EventBridgeContext = createContext<null>(null);

export function EventBridgeProvider(props: {
	subscribeToEvents: TuiProps["subscribeToEvents"];
	handlers: EventBridgeHandlers;
	children: React.ReactNode;
}) {
	const handlersRef = useRef(props.handlers);
	handlersRef.current = props.handlers;

	const subscribeRef = useRef(props.subscribeToEvents);
	subscribeRef.current = props.subscribeToEvents;

	useEffect(() => {
		const unsubscribe = subscribeRef.current({
			onAgentEvent: (event) => handlersRef.current.onAgentEvent(event),
			onTeamEvent: (event) => handlersRef.current.onTeamEvent(event),
			onPendingPrompts: (event) => handlersRef.current.onPendingPrompts(event),
			onPendingPromptSubmitted: (event) =>
				handlersRef.current.onPendingPromptSubmitted(event),
		});
		return unsubscribe;
	}, []);

	return (
		<EventBridgeContext.Provider value={null}>
			{props.children}
		</EventBridgeContext.Provider>
	);
}

import { describe, expect, it } from "vitest";
import { nextUsageTokenDisplay } from "./session-context";

describe("nextUsageTokenDisplay", () => {
	it("uses streaming input tokens as an absolute context size", () => {
		let displayedTokens = 0;

		displayedTokens = nextUsageTokenDisplay(displayedTokens, {
			inputTokens: 633_000,
			outputTokens: 31_000,
		});
		displayedTokens = nextUsageTokenDisplay(displayedTokens, {
			inputTokens: 934_000,
			outputTokens: 266_000,
		});

		expect(displayedTokens).toBe(934_000);
	});

	it("ignores output-only usage events for the context size display", () => {
		expect(
			nextUsageTokenDisplay(633_000, {
				outputTokens: 31_000,
			}),
		).toBe(633_000);
	});
});

import type { AgentMode } from "@cline/core";
import type React from "react";
import {
	createContext,
	useCallback,
	useContext,
	useRef,
	useState,
} from "react";
import { getCliCompactionMode } from "../../utils/compaction-mode";
import type { CliCompactionMode } from "../../utils/types";
import type { ChatEntry, InlineStream, TuiProps } from "../types";
import { MAX_BUFFERED_LINES } from "../types";

interface SessionContextValue {
	entries: ChatEntry[];
	isRunning: boolean;
	isStreaming: boolean;
	abortRequested: boolean;
	hasSubmitted: boolean;
	uiMode: AgentMode;
	autoApproveAll: boolean;
	compactionMode: CliCompactionMode;
	lastTotalTokens: number;
	lastTotalCost: number;
	isExitRequested: boolean;

	appendEntry: (entry: ChatEntry) => void;
	updateLastEntry: (updater: (prev: ChatEntry) => ChatEntry) => void;
	updateEntry: (updater: (entry: ChatEntry) => ChatEntry) => void;
	closeInlineStream: () => void;
	activeInlineStreamRef: React.MutableRefObject<InlineStream>;

	setIsRunning: (v: boolean) => void;
	setIsStreaming: (v: boolean) => void;
	setAbortRequested: (v: boolean) => void;
	setHasSubmitted: (v: boolean) => void;
	setLastTotalTokens: (v: number) => void;
	setLastTotalCost: (v: number) => void;
	addUsageDelta: (usage: UsageDelta) => void;
	setUiMode: (mode: AgentMode) => void;
	toggleMode: () => void;
	toggleAutoApprove: () => void;
	setCompactionMode: (mode: CliCompactionMode) => void;
	requestExit: () => void;
	clearEntries: () => void;
	replaceEntries: (entries: ChatEntry[]) => void;
}

type UsageDelta = {
	inputTokens?: number;
	outputTokens?: number;
	cost?: number;
};

const SessionContext = createContext<SessionContextValue | null>(null);

export function useSession(): SessionContextValue {
	const ctx = useContext(SessionContext);
	if (!ctx) throw new Error("useSession must be within SessionProvider");
	return ctx;
}

export function nextUsageTokenDisplay(
	previousTotalTokens: number,
	usage: UsageDelta,
): number {
	const inputTokens = Math.max(0, usage.inputTokens ?? 0);
	return inputTokens > 0 ? inputTokens : previousTotalTokens;
}

export function SessionProvider(props: {
	config: TuiProps["config"];
	initialEntries?: ChatEntry[];
	initialUsage?: {
		totalTokens: number;
		totalCost: number;
	};
	onRunningChange: TuiProps["onRunningChange"];
	onAutoApproveChange: TuiProps["onAutoApproveChange"];
	onCompactionModeChange: TuiProps["onCompactionModeChange"];
	onExit: TuiProps["onExit"];
	children: React.ReactNode;
}) {
	const {
		config,
		initialEntries,
		initialUsage,
		onRunningChange,
		onAutoApproveChange,
		onCompactionModeChange,
		onExit,
	} = props;

	const [entries, setEntries] = useState<ChatEntry[]>(() =>
		initialEntries && initialEntries.length > MAX_BUFFERED_LINES
			? initialEntries.slice(initialEntries.length - MAX_BUFFERED_LINES)
			: (initialEntries ?? []),
	);
	const [isRunning, _setIsRunning] = useState(false);
	const [isStreaming, setIsStreaming] = useState(false);
	const [abortRequested, setAbortRequested] = useState(false);
	const [hasSubmitted, setHasSubmitted] = useState(
		(initialEntries?.length ?? 0) > 0,
	);
	const [uiMode, _setUiMode] = useState<AgentMode>(
		config.mode === "plan" ? "plan" : "act",
	);
	// Mirror for appendEntry: entries are appended from event-handler
	// callbacks that must see the mode at append time, not at closure time.
	const uiModeRef = useRef<AgentMode>(config.mode === "plan" ? "plan" : "act");
	const setUiMode = useCallback((mode: AgentMode) => {
		uiModeRef.current = mode;
		_setUiMode(mode);
	}, []);
	const initialAutoApproveAll = config.toolPolicies["*"]?.autoApprove !== false;
	const autoApproveAllRef = useRef(initialAutoApproveAll);
	const [autoApproveAll, _setAutoApproveAll] = useState(initialAutoApproveAll);
	const [compactionMode, _setCompactionMode] = useState<CliCompactionMode>(() =>
		getCliCompactionMode(config),
	);
	const [lastTotalTokens, setLastTotalTokens] = useState(
		() => initialUsage?.totalTokens ?? 0,
	);
	const [lastTotalCost, setLastTotalCost] = useState(
		() => initialUsage?.totalCost ?? 0,
	);
	const [isExitRequested, setIsExitRequested] = useState(false);

	const activeInlineStreamRef = useRef<InlineStream>(undefined);

	const setIsRunning = useCallback(
		(v: boolean) => {
			_setIsRunning(v);
			setAbortRequested(false);
			onRunningChange(v);
		},
		[onRunningChange],
	);

	const appendEntry = useCallback((entry: ChatEntry) => {
		const stamped = entry.mode ? entry : { ...entry, mode: uiModeRef.current };
		setEntries((prev) => {
			const next = [...prev, stamped];
			return next.length <= MAX_BUFFERED_LINES
				? next
				: next.slice(next.length - MAX_BUFFERED_LINES);
		});
	}, []);

	const updateLastEntry = useCallback(
		(updater: (prev: ChatEntry) => ChatEntry) => {
			setEntries((prev) => {
				if (prev.length === 0) return prev;
				const next = [...prev];
				next[next.length - 1] = updater(next[next.length - 1] as ChatEntry);
				return next;
			});
		},
		[],
	);

	const updateEntry = useCallback(
		(updater: (entry: ChatEntry) => ChatEntry) => {
			setEntries((prev) => {
				let changed = false;
				const next = prev.map((entry) => {
					const updated = updater(entry);
					if (updated !== entry) changed = true;
					return updated;
				});
				return changed ? next : prev;
			});
		},
		[],
	);

	const closeInlineStream = useCallback(() => {
		activeInlineStreamRef.current = undefined;
		setEntries((prev) => {
			if (prev.length === 0) return prev;
			const last = prev[prev.length - 1];
			if (
				last &&
				(last.kind === "assistant_text" ||
					last.kind === "reasoning" ||
					last.kind === "tool_call") &&
				last.streaming
			) {
				const next = [...prev];
				next[next.length - 1] = { ...last, streaming: false } as ChatEntry;
				return next;
			}
			return prev;
		});
	}, []);

	const toggleMode = useCallback(() => {
		setUiMode(uiModeRef.current === "act" ? "plan" : "act");
	}, [setUiMode]);

	const toggleAutoApprove = useCallback(() => {
		const next = !autoApproveAllRef.current;
		autoApproveAllRef.current = next;
		onAutoApproveChange(next);
		_setAutoApproveAll(next);
	}, [onAutoApproveChange]);

	const setCompactionMode = useCallback(
		(mode: CliCompactionMode) => {
			_setCompactionMode(mode);
			void onCompactionModeChange(mode);
		},
		[onCompactionModeChange],
	);

	const requestExit = useCallback(() => {
		setIsExitRequested(true);
		setTimeout(() => onExit(), 0);
	}, [onExit]);

	const clearEntries = useCallback(() => {
		setEntries([]);
		setLastTotalTokens(0);
		setLastTotalCost(0);
	}, []);

	const addUsageDelta = useCallback((usage: UsageDelta) => {
		const nextTotalTokens = nextUsageTokenDisplay(0, usage);
		if (nextTotalTokens > 0) {
			setLastTotalTokens((prev) => nextUsageTokenDisplay(prev, usage));
		}
		const costDelta = usage.cost;
		if (
			typeof costDelta === "number" &&
			Number.isFinite(costDelta) &&
			costDelta > 0
		) {
			setLastTotalCost((prev) => prev + costDelta);
		}
	}, []);

	const replaceEntries = useCallback((nextEntries: ChatEntry[]) => {
		setEntries(
			nextEntries.length > MAX_BUFFERED_LINES
				? nextEntries.slice(nextEntries.length - MAX_BUFFERED_LINES)
				: nextEntries,
		);
	}, []);

	const value: SessionContextValue = {
		entries,
		isRunning,
		isStreaming,
		abortRequested,
		hasSubmitted,
		uiMode,
		autoApproveAll,
		compactionMode,
		lastTotalTokens,
		lastTotalCost,
		isExitRequested,
		appendEntry,
		updateLastEntry,
		updateEntry,
		closeInlineStream,
		activeInlineStreamRef,
		setIsRunning,
		setIsStreaming,
		setAbortRequested,
		setHasSubmitted,
		setLastTotalTokens,
		setLastTotalCost,
		addUsageDelta,
		setUiMode,
		toggleMode,
		toggleAutoApprove,
		setCompactionMode,
		requestExit,
		clearEntries,
		replaceEntries,
	};

	return (
		<SessionContext.Provider value={value}>
			{props.children}
		</SessionContext.Provider>
	);
}

import type { SessionHistoryRecord } from "@cline/core";
import { createCliRenderer } from "@opentui/core";
import { createRoot } from "@opentui/react";
import React from "react";
import { deleteSession } from "../session/session";
import { HistoryStandaloneContent } from "./views/history-view";

export async function renderHistoryStandalone(input: {
	rows: SessionHistoryRecord[];
	onExport: (sessionId: string) => Promise<string | undefined>;
	refreshRows?: () => Promise<SessionHistoryRecord[]>;
}): Promise<number | string> {
	const renderer = await createCliRenderer({
		exitOnCtrlC: true,
		autoFocus: false,
		enableMouseMovement: true,
	});

	return new Promise((resolve) => {
		let result: number | string = 0;
		let resolved = false;
		let destroyStarted = false;
		let unmounted = false;
		const root = createRoot(renderer);

		const unmountRoot = () => {
			if (unmounted) {
				return;
			}
			unmounted = true;
			root.unmount();
		};

		// Resolve only once teardown has finished, so callers never run while
		// the renderer is still restoring the terminal.
		renderer.on("destroy", () => {
			unmountRoot();
			if (!resolved) {
				resolved = true;
				resolve(result);
			}
		});

		const settle = (value: number | string) => {
			if (destroyStarted) {
				return;
			}
			destroyStarted = true;
			result = value;
			unmountRoot();
			// Let OpenTUI finish parsing the current stdin batch before teardown.
			queueMicrotask(() => {
				renderer.destroy();
			});
		};

		root.render(
			React.createElement(HistoryStandaloneContent, {
				rows: input.rows,
				onResolve: (sessionId: string) => settle(sessionId),
				onExport: input.onExport,
				refreshRows: input.refreshRows,
				onDelete: async (sessionId: string) => {
					const result = await deleteSession(sessionId);
					return result.deleted;
				},
				onDismiss: () => settle(0),
			}),
		);
	});
}

import type { LocalSlashCommandInvocation } from "../utils/skill-command-input";
import type { OpenConfigOptions } from "./use-config-panel";

export interface LocalSlashCommandActionInput {
	name: string;
	isRunning: boolean;
	openAccount: () => void;
	openConfig: (options?: OpenConfigOptions) => void;
	openMcpManager: () => Promise<boolean>;
	openModelSelector: () => void;
	openSkills: (invocation?: LocalSlashCommandInvocation) => void;
	invocation?: LocalSlashCommandInvocation;
	runCompact: () => void;
	runFork: () => void;
	runUndo: () => Promise<void>;
	clearConversation: () => Promise<void>;
	openHelp: () => void;
	openHistory: () => void;
	exitCline: () => void;
}

export function runLocalSlashCommandAction(
	input: LocalSlashCommandActionInput,
): boolean | Promise<boolean> {
	const normalized = input.name;
	if (normalized === "config" || normalized === "settings") {
		input.openConfig();
		return true;
	}
	if (normalized === "plugins") {
		input.openConfig({ initialTab: "plugins" });
		return true;
	}
	if (normalized === "skills") {
		input.openSkills(input.invocation);
		return true;
	}
	if (normalized === "mcp") {
		return input.openMcpManager().then(() => true);
	}
	if (normalized === "account") {
		input.openAccount();
		return true;
	}
	if (normalized === "model") {
		input.openModelSelector();
		return true;
	}
	if (normalized === "compact") {
		// Autocomplete can invoke local commands while a turn is running. Keep
		// /compact handled, but do not let it take ownership of the active turn's
		// shared running state.
		if (!input.isRunning) {
			input.runCompact();
		}
		return true;
	}
	if (normalized === "fork") {
		input.runFork();
		return true;
	}
	if (normalized === "undo") {
		return input.runUndo().then(() => true);
	}
	if (normalized === "clear") {
		return input.clearConversation().then(() => true);
	}
	if (normalized === "help") {
		input.openHelp();
		return true;
	}
	if (normalized === "history") {
		input.openHistory();
		return true;
	}
	if (normalized === "quit") {
		setTimeout(input.exitCline, 0);
		return true;
	}
	return false;
}

export function shouldHandleInputHistory(input: {
	isRunning: boolean;
	hasQueuedPrompts: boolean;
}): boolean {
	return !input.isRunning || !input.hasQueuedPrompts;
}

import { describe, expect, it } from "vitest";
import { matchTranscriptKeybind } from "./transcript-keybinds";

function key(input: {
	name: string;
	ctrl?: boolean;
	meta?: boolean;
	shift?: boolean;
}) {
	return {
		name: input.name,
		ctrl: input.ctrl ?? false,
		meta: input.meta ?? false,
		shift: input.shift ?? false,
	};
}

describe("matchTranscriptKeybind", () => {
	it("matches OpenCode-style page scroll keybinds", () => {
		expect(matchTranscriptKeybind(key({ name: "pageup" }))).toBe(
			"messages_page_up",
		);
		expect(matchTranscriptKeybind(key({ name: "pagedown" }))).toBe(
			"messages_page_down",
		);
		expect(
			matchTranscriptKeybind(key({ name: "b", ctrl: true, meta: true })),
		).toBe("messages_page_up");
		expect(
			matchTranscriptKeybind(key({ name: "f", ctrl: true, meta: true })),
		).toBe("messages_page_down");
	});

	it("matches OpenCode-style half-page keybinds", () => {
		expect(
			matchTranscriptKeybind(key({ name: "u", ctrl: true, meta: true })),
		).toBe("messages_half_page_up");
		expect(
			matchTranscriptKeybind(key({ name: "d", ctrl: true, meta: true })),
		).toBe("messages_half_page_down");
	});

	it("matches transcript bound keybinds that do not conflict with input editing", () => {
		expect(matchTranscriptKeybind(key({ name: "g", ctrl: true }))).toBe(
			"messages_first",
		);
		expect(
			matchTranscriptKeybind(key({ name: "g", ctrl: true, meta: true })),
		).toBe("messages_last");
	});

	it("does not match modified variants outside the configured defaults", () => {
		expect(matchTranscriptKeybind(key({ name: "home" }))).toBe(null);
		expect(matchTranscriptKeybind(key({ name: "end" }))).toBe(null);
		expect(matchTranscriptKeybind(key({ name: "home", ctrl: true }))).toBe(
			null,
		);
		expect(matchTranscriptKeybind(key({ name: "pageup", shift: true }))).toBe(
			null,
		);
	});
});

export type TranscriptCommand =
	| "messages_page_up"
	| "messages_page_down"
	| "messages_half_page_up"
	| "messages_half_page_down"
	| "messages_first"
	| "messages_last";

type TranscriptKey = {
	name: string;
	ctrl: boolean;
	meta: boolean;
	shift: boolean;
};

type TranscriptKeybind = {
	name: string;
	ctrl?: boolean;
	meta?: boolean;
	shift?: boolean;
};

export const TRANSCRIPT_KEYBINDS: Record<
	TranscriptCommand,
	readonly TranscriptKeybind[]
> = {
	messages_page_up: [{ name: "pageup" }, { name: "b", ctrl: true, meta: true }],
	messages_page_down: [
		{ name: "pagedown" },
		{ name: "f", ctrl: true, meta: true },
	],
	messages_half_page_up: [{ name: "u", ctrl: true, meta: true }],
	messages_half_page_down: [{ name: "d", ctrl: true, meta: true }],
	messages_first: [{ name: "g", ctrl: true }],
	messages_last: [{ name: "g", ctrl: true, meta: true }],
};

function keybindMatches(
	keybind: TranscriptKeybind,
	key: TranscriptKey,
): boolean {
	return (
		key.name === keybind.name &&
		key.ctrl === !!keybind.ctrl &&
		key.meta === !!keybind.meta &&
		key.shift === !!keybind.shift
	);
}

export function matchTranscriptKeybind(
	key: TranscriptKey,
): TranscriptCommand | null {
	for (const [command, keybinds] of Object.entries(TRANSCRIPT_KEYBINDS)) {
		if (keybinds.some((keybind) => keybindMatches(keybind, key))) {
			return command as TranscriptCommand;
		}
	}
	return null;
}

import type { ChoiceContext } from "@opentui-ui/dialog";
import type { DialogActions } from "@opentui-ui/dialog/react";
import open from "open";
import { useCallback } from "react";
import type { ClineAccountSnapshot } from "../cline-account";
import {
	type AccountDialogAction,
	AccountDialogContent,
} from "../components/dialogs/account-dialog";
import {
	OAuthLoginContent,
	type OAuthLoginResult,
} from "../components/dialogs/provider-picker";
import type { OpenModelSelectorOptions } from "./use-model-selector";

export function useAccountDialog(opts: {
	dialog: DialogActions;
	termHeight: number;
	loadAccount: () => Promise<ClineAccountSnapshot>;
	switchAccount: (organizationId?: string | null) => Promise<void>;
	onAccountChange?: () => Promise<void>;
	openModelSelector: (options?: OpenModelSelectorOptions) => Promise<void>;
	refocusTextarea: () => void;
}) {
	const {
		dialog,
		termHeight,
		loadAccount,
		switchAccount,
		onAccountChange,
		openModelSelector,
		refocusTextarea,
	} = opts;

	const openAccountDialog = useCallback(async () => {
		const action = await dialog.choice<AccountDialogAction>({
			size: "large",
			style: { maxHeight: termHeight - 2 },
			closeOnEscape: false,
			content: (ctx: ChoiceContext<AccountDialogAction>) => (
				<AccountDialogContent
					{...ctx}
					loadAccount={loadAccount}
					switchAccount={switchAccount}
					onAccountChange={onAccountChange}
				/>
			),
		});
		if (action === "change-model") {
			await openModelSelector({ onCancel: openAccountDialog });
			return;
		}
		if (action === "change-provider") {
			await openModelSelector({
				onCancel: openAccountDialog,
				startWithProviderChange: true,
			});
			return;
		}
		if (action === "learn-more") {
			await open("https://cline.bot", { wait: false }).catch(() => {});
			refocusTextarea();
			return;
		}
		if (action === "login") {
			const saved = await dialog.choice<OAuthLoginResult>({
				style: { maxHeight: termHeight - 2 },
				closeOnEscape: false,
				content: (ctx: ChoiceContext<OAuthLoginResult>) => (
					<OAuthLoginContent {...ctx} providerId="cline" providerName="Cline" />
				),
			});
			if (saved === true) {
				await onAccountChange?.();
				await openAccountDialog();
				return;
			}
		}
		refocusTextarea();
	}, [
		dialog,
		loadAccount,
		onAccountChange,
		openModelSelector,
		refocusTextarea,
		switchAccount,
		termHeight,
	]);

	return openAccountDialog;
}

import type { AgentEvent, TeamEvent } from "@cline/core";
import { formatDisplayUserInput } from "@cline/shared";
import { useCallback, useRef } from "react";
import type {
	PendingPromptSnapshot,
	PendingPromptSubmittedEvent,
} from "../../runtime/session-events";
import { formatCliErrorMessage } from "../../utils/cline-pass-errors";
import { resolveNonCompactionStatusLabel } from "../../utils/events";
import {
	formatToolInput,
	formatToolOutput,
	truncate,
} from "../../utils/helpers";
import type { ChatEntry, InlineStream, TuiProps } from "../types";
import { parseCompactionNoticeMetadata } from "../utils/compaction-status";

interface AgentEventDeps {
	appendEntry: (entry: ChatEntry) => void;
	updateLastEntry: (updater: (prev: ChatEntry) => ChatEntry) => void;
	updateEntry: (updater: (entry: ChatEntry) => ChatEntry) => void;
	closeInlineStream: () => void;
	activeInlineStreamRef: React.MutableRefObject<InlineStream>;
	setIsRunning: (v: boolean) => void;
	setIsStreaming: (v: boolean) => void;
	addUsageDelta: (usage: {
		inputTokens?: number;
		outputTokens?: number;
		cost?: number;
	}) => void;
	onTurnErrorReported: TuiProps["onTurnErrorReported"];
	verbose: boolean;
}

export function useAgentEventHandlers(deps: AgentEventDeps) {
	const openCompactionEntryRef = useRef(false);
	const {
		appendEntry,
		updateLastEntry,
		updateEntry,
		closeInlineStream,
		activeInlineStreamRef,
		setIsRunning,
		setIsStreaming,
		addUsageDelta,
		onTurnErrorReported,
		verbose,
	} = deps;

	// Compaction dividers that arrived while an assistant message was still
	// streaming. Appending them immediately would split the message in two, so
	// they are held until the active content block closes (or the turn ends).
	const pendingCompactionEntriesRef = useRef<
		Extract<ChatEntry, { kind: "compaction" }>[]
	>([]);

	const flushPendingCompactionEntries = useCallback(() => {
		const pending = pendingCompactionEntriesRef.current;
		if (pending.length === 0) return;
		pendingCompactionEntriesRef.current = [];
		for (const entry of pending) {
			if (entry.status !== "started" && openCompactionEntryRef.current) {
				updateEntry((current) =>
					current.kind === "compaction" && current.status === "started"
						? { ...current, ...entry }
						: current,
				);
				openCompactionEntryRef.current = false;
			} else {
				appendEntry(entry);
				if (entry.status === "started") {
					openCompactionEntryRef.current = true;
				}
			}
		}
	}, [appendEntry, updateEntry]);

	const finalizeDanglingCompactionEntry = useCallback(
		(status: "failed" | "cancelled") => {
			if (!openCompactionEntryRef.current) return;
			openCompactionEntryRef.current = false;
			updateEntry((entry) =>
				entry.kind === "compaction" && entry.status === "started"
					? { ...entry, status }
					: entry,
			);
		},
		[updateEntry],
	);

	const closeToolEntry = useCallback(
		(event: AgentEvent & { type: "content_end" }) => {
			const error = event.error ?? undefined;
			const output = event.output;
			const result = {
				outputSummary: error ? "" : formatToolOutput(output),
				rawOutput: error ? undefined : output,
				error,
			};
			if (event.toolCallId) {
				updateEntry((entry) => {
					if (
						entry.kind !== "tool_call" ||
						entry.toolCallId !== event.toolCallId
					) {
						return entry;
					}
					return { ...entry, streaming: false, result };
				});
			} else {
				updateLastEntry((prev) => {
					if (prev.kind !== "tool_call") return prev;
					return { ...prev, streaming: false, result };
				});
			}
		},
		[updateEntry, updateLastEntry],
	);

	const turnErrorReportedRef = useRef(false);
	const knownPendingPromptIdsRef = useRef(new Set<string>());

	const handleAgentEvent = useCallback(
		(event: AgentEvent) => {
			switch (event.type) {
				case "iteration_start":
					setIsRunning(true);
					setIsStreaming(true);
					closeInlineStream();
					flushPendingCompactionEntries();
					break;
				case "iteration_end":
					closeInlineStream();
					flushPendingCompactionEntries();
					break;
				case "content_start": {
					setIsStreaming(false);
					switch (event.contentType) {
						case "text": {
							if (activeInlineStreamRef.current !== "text") {
								closeInlineStream();
								activeInlineStreamRef.current = "text";
								appendEntry({
									kind: "assistant_text",
									text: event.text ?? "",
									streaming: true,
								});
							} else {
								updateLastEntry((prev) =>
									prev.kind === "assistant_text"
										? { ...prev, text: prev.text + (event.text ?? "") }
										: prev,
								);
							}
							break;
						}
						case "reasoning": {
							const chunk =
								event.redacted && !event.reasoning
									? "[redacted]"
									: (event.reasoning ?? "");
							if (activeInlineStreamRef.current !== "reasoning") {
								closeInlineStream();
								activeInlineStreamRef.current = "reasoning";
								appendEntry({
									kind: "reasoning",
									text: chunk,
									streaming: true,
								});
							} else {
								updateLastEntry((prev) =>
									prev.kind === "reasoning"
										? { ...prev, text: prev.text + chunk }
										: prev,
								);
							}
							break;
						}
						case "tool": {
							closeInlineStream();
							const toolName = event.toolName ?? "unknown_tool";
							appendEntry({
								kind: "tool_call",
								toolCallId: event.toolCallId,
								toolName,
								inputSummary: formatToolInput(toolName, event.input),
								rawInput: event.input,
								streaming: true,
							});
							break;
						}
					}
					break;
				}
				case "content_end": {
					switch (event.contentType) {
						case "text":
						case "reasoning":
							closeInlineStream();
							break;
						case "tool": {
							closeInlineStream();
							closeToolEntry(event);
							break;
						}
					}
					break;
				}
				case "done":
					setIsRunning(false);
					setIsStreaming(false);
					closeInlineStream();
					flushPendingCompactionEntries();
					finalizeDanglingCompactionEntry("cancelled");
					break;
				case "error":
					setIsRunning(false);
					setIsStreaming(false);
					closeInlineStream();
					flushPendingCompactionEntries();
					finalizeDanglingCompactionEntry("failed");
					turnErrorReportedRef.current = true;
					onTurnErrorReported(true);
					if (!event.recoverable || verbose) {
						appendEntry({
							kind: "error",
							text: formatCliErrorMessage(event.error),
						});
					}
					break;
				case "notice":
					if (event.displayRole === "status") {
						const compaction = parseCompactionNoticeMetadata(event.metadata);
						if (!compaction) {
							closeInlineStream();
						}
						if (compaction) {
							if (activeInlineStreamRef.current) {
								// An assistant message is still streaming; appending now
								// would split it around the divider. Hold the divider (final
								// state until the content block closes, then reconcile it
								// with the same open divider atomically.
								pendingCompactionEntriesRef.current.push({
									kind: "compaction",
									...compaction,
								});
								break;
							}
							if (compaction.status === "started") {
								appendEntry({ kind: "compaction", ...compaction });
								openCompactionEntryRef.current = true;
							} else if (openCompactionEntryRef.current) {
								// Finalize the in-progress divider in place, wherever it
								// sits in the transcript.
								updateEntry((entry) =>
									entry.kind === "compaction" && entry.status === "started"
										? { ...entry, ...compaction }
										: entry,
								);
								openCompactionEntryRef.current = false;
							} else {
								appendEntry({ kind: "compaction", ...compaction });
							}
							break;
						}
						const label = resolveNonCompactionStatusLabel(event);
						if (label) {
							appendEntry({ kind: "status", text: label });
						}
					}
					break;
				case "usage":
					addUsageDelta({
						inputTokens: event.inputTokens,
						outputTokens: event.outputTokens,
						cost: event.cost,
					});
					break;
			}
		},
		[
			appendEntry,
			updateLastEntry,
			updateEntry,
			closeInlineStream,
			activeInlineStreamRef,
			setIsRunning,
			setIsStreaming,
			addUsageDelta,
			onTurnErrorReported,
			verbose,
			closeToolEntry,
			finalizeDanglingCompactionEntry,
			flushPendingCompactionEntries,
		],
	);

	const handleTeamEvent = useCallback(
		(event: TeamEvent) => {
			const team = (text: string) => {
				closeInlineStream();
				appendEntry({ kind: "team", text });
			};
			switch (event.type) {
				case "teammate_spawned":
					team(`[team] teammate spawned: ${event.agentId}`);
					break;
				case "teammate_shutdown":
					team(`[team] teammate shutdown: ${event.agentId}`);
					break;
				case "team_task_updated":
					team(`[team task] ${event.task.id} -> ${event.task.status}`);
					break;
				case "team_message":
					team(
						`[mailbox] ${event.message.fromAgentId} -> ${event.message.toAgentId}: ${event.message.subject}`,
					);
					break;
				case "team_mission_log":
					team(
						`[mission] ${event.entry.agentId}: ${truncate(event.entry.summary, 90)}`,
					);
					break;
				case "run_queued":
					team(`[team run] queued ${event.run.id} -> ${event.run.agentId} ...`);
					break;
				case "run_started":
					team(
						`[team run] started ${event.run.id} -> ${event.run.agentId} ...`,
					);
					break;
				case "run_progress":
					if (event.message === "heartbeat") break;
					team(`[team run] progress ${event.run.id}: ${event.message}`);
					break;
				case "run_completed":
					team(`[team run] completed ${event.run.id}`);
					break;
				case "run_failed":
					team(
						`[team run] failed ${event.run.id}: ${event.run.error ?? "unknown error"}`,
					);
					break;
				case "run_cancelled":
					team(`[team run] cancelled ${event.run.id}`);
					break;
				case "run_interrupted":
					team(`[team run] interrupted ${event.run.id}`);
					break;
				case "outcome_created":
					team(
						`[team outcome] created ${event.outcome.id}: ${event.outcome.title}`,
					);
					break;
				case "outcome_fragment_attached":
					team(
						`[team outcome] fragment ${event.fragment.id} attached to ${event.fragment.section}`,
					);
					break;
				case "outcome_fragment_reviewed":
					team(
						`[team outcome] fragment ${event.fragment.id} -> ${event.fragment.status}`,
					);
					break;
				case "outcome_finalized":
					team(`[team outcome] finalized ${event.outcome.id}`);
					break;
				case "task_start":
				case "task_end":
				case "agent_event":
					break;
			}
		},
		[appendEntry, closeInlineStream],
	);

	const handlePendingPrompts = useCallback((event: PendingPromptSnapshot) => {
		knownPendingPromptIdsRef.current = new Set(event.prompts.map((e) => e.id));
	}, []);

	const handlePendingPromptSubmitted = useCallback(
		(event: PendingPromptSubmittedEvent) => {
			knownPendingPromptIdsRef.current.delete(event.id);
			// Display boundary: formatDisplayUserInput strips runtime-generated
			// notice elements (e.g. mode_notice) that normalizeUserInput must
			// preserve, since the latter also sanitizes model-bound prompts.
			appendEntry({
				kind: "user_submitted",
				text: formatDisplayUserInput(event.prompt),
			});
		},
		[appendEntry],
	);

	return {
		handleAgentEvent,
		handleTeamEvent,
		handlePendingPrompts,
		handlePendingPromptSubmitted,
		turnErrorReportedRef,
	};
}

import { describe, expect, it } from "vitest";
import {
	extractSlashQuery,
	formatMentionAutocompleteValue,
	getFirstSelectableIndex,
	insertMention,
} from "./use-autocomplete";

describe("TUI autocomplete slash command replacement", () => {
	it("detects a slash query immediately before the cursor", () => {
		expect(extractSlashQuery("/review")).toEqual({
			inSlashMode: true,
			query: "review",
			slashIndex: 0,
		});
		expect(extractSlashQuery("please /review")).toEqual({
			inSlashMode: true,
			query: "review",
			slashIndex: 7,
		});
	});

	it("supports replacing only the slash token at the cursor", () => {
		const text = "please /review this file";
		const cursor = "please /review".length;
		const slash = extractSlashQuery(text.slice(0, cursor));
		const replacement = "/review ";

		expect(slash.inSlashMode).toBe(true);
		if (!slash.inSlashMode) return;
		expect(
			text.slice(0, slash.slashIndex) + replacement + text.slice(cursor),
		).toBe("please /review  this file");
	});

	it("selects the first command option instead of a section header", () => {
		expect(
			getFirstSelectableIndex([
				{ display: "Skills", value: "", isHeader: true },
				{ display: "/review", value: "/review " },
			]),
		).toBe(1);
	});

	it("formats workspace mention completions as relative file mentions", () => {
		expect(formatMentionAutocompleteValue("src/main.ts")).toBe(
			"@./src/main.ts ",
		);
		expect(insertMention("open @src", 5, "src/main.ts")).toBe(
			"open @./src/main.ts ",
		);
	});

	it("preserves parser-compatible mention prefixes", () => {
		expect(formatMentionAutocompleteValue("/tmp/file.txt")).toBe(
			"@/tmp/file.txt ",
		);
		expect(formatMentionAutocompleteValue("~/file.txt")).toBe("@~/file.txt ");
		expect(formatMentionAutocompleteValue("./file.txt")).toBe("@./file.txt ");
		expect(formatMentionAutocompleteValue("../file.txt")).toBe("@../file.txt ");
	});

	it("quotes parser-compatible mention paths containing spaces", () => {
		expect(formatMentionAutocompleteValue("docs/my file.md")).toBe(
			'@"./docs/my file.md" ',
		);
		expect(insertMention("open @docs", 5, "docs/my file.md")).toBe(
			'open @"./docs/my file.md" ',
		);
	});
});

import { useCallback, useRef, useState } from "react";
import { searchWorkspaceFilesForMention } from "../../tui/interactive-welcome";
import {
	formatSlashCommandAutocompleteValue,
	type SlashCommandRegistryEntry,
} from "../commands/slash-command-registry";
import { COMPLETION_DEBOUNCE_MS, MAX_COMPLETION_RESULTS } from "../types";

export type AutocompleteMode = false | "@" | "/";

interface MentionQueryInfo {
	inMentionMode: boolean;
	query: string;
	atIndex: number;
}

interface SlashQueryInfo {
	inSlashMode: boolean;
	query: string;
	slashIndex: number;
}

export function extractMentionQuery(text: string): MentionQueryInfo {
	const atIndex = text.lastIndexOf("@");
	if (atIndex === -1 || (atIndex > 0 && !/\s/.test(text[atIndex - 1] ?? ""))) {
		return { inMentionMode: false, query: "", atIndex: -1 };
	}
	const query = text.slice(atIndex + 1);
	if (query.includes(" ")) {
		return { inMentionMode: false, query: "", atIndex: -1 };
	}
	return { inMentionMode: true, query, atIndex };
}

export function extractSlashQuery(text: string): SlashQueryInfo {
	const slashIndex = text.lastIndexOf("/");
	if (slashIndex === -1) {
		return { inSlashMode: false, query: "", slashIndex: -1 };
	}
	if (slashIndex > 0 && !/\s/.test(text[slashIndex - 1] ?? "")) {
		return { inSlashMode: false, query: "", slashIndex: -1 };
	}
	const query = text.slice(slashIndex + 1);
	if (/\s/.test(query)) {
		return { inSlashMode: false, query: "", slashIndex: -1 };
	}
	const firstSlashCommandRegex = /(^|\s)\/[a-zA-Z0-9_.-]+\s/;
	const textBeforeCurrentSlash = text.slice(0, slashIndex);
	if (firstSlashCommandRegex.test(textBeforeCurrentSlash)) {
		return { inSlashMode: false, query: "", slashIndex: -1 };
	}
	return { inSlashMode: true, query, slashIndex };
}

export function insertMention(
	text: string,
	atIndex: number,
	filePath: string,
): string {
	const endIndex = text.indexOf(" ", atIndex);
	const end = endIndex === -1 ? text.length : endIndex;
	const normalizedPath =
		filePath.startsWith("/") ||
		filePath.startsWith("~/") ||
		filePath.startsWith("./") ||
		filePath.startsWith("../")
			? filePath
			: `./${filePath}`;
	const mention = normalizedPath.includes(" ")
		? `@"${normalizedPath}"`
		: `@${normalizedPath}`;
	return `${text.slice(0, atIndex)}${mention} ${text.slice(end).trimStart()}`;
}

export function formatMentionAutocompleteValue(filePath: string): string {
	const normalizedPath =
		filePath.startsWith("/") ||
		filePath.startsWith("~/") ||
		filePath.startsWith("./") ||
		filePath.startsWith("../")
			? filePath
			: `./${filePath}`;
	const mention = normalizedPath.includes(" ")
		? `@"${normalizedPath}"`
		: `@${normalizedPath}`;
	return `${mention} `;
}

export function insertSlashCommand(
	text: string,
	slashIndex: number,
	commandName: string,
): string {
	return `${text.slice(0, slashIndex)}/${commandName} `;
}

export interface AutocompleteOption {
	display: string;
	value: string;
	description?: string;
	onSelect?: () => void;
	isHeader?: boolean;
	commandName?: string;
	commandExecution?: SlashCommandRegistryEntry["execution"];
	commandSource?: SlashCommandRegistryEntry["source"];
	commandPreserveInput?: SlashCommandRegistryEntry["preserveInput"];
}

export interface AutocompleteState {
	mode: AutocompleteMode;
	filter: string;
	selected: number;
	filteredOptions: AutocompleteOption[];
	mentionResults: string[];
}

export function getFirstSelectableIndex(
	options: readonly AutocompleteOption[],
): number {
	const index = options.findIndex((option) => !option.isHeader);
	return index === -1 ? 0 : index;
}

export function useAutocomplete(opts: {
	workspaceRoot: string;
	systemCommands: SlashCommandRegistryEntry[];
	skillCommands: SlashCommandRegistryEntry[];
}) {
	const { workspaceRoot, systemCommands, skillCommands } = opts;

	const [mode, setMode] = useState<AutocompleteMode>(false);
	const [filter, setFilter] = useState("");
	const [selected, setSelected] = useState(0);
	const [mentionResults, setMentionResults] = useState<string[]>([]);

	const searchTimerRef = useRef<NodeJS.Timeout | null>(null);
	const searchCounterRef = useRef(0);

	const systemOptions: AutocompleteOption[] = systemCommands.map((cmd) => ({
		display: `/${cmd.name}`,
		value: formatSlashCommandAutocompleteValue(cmd),
		description: cmd.description,
		commandName: cmd.name,
		commandExecution: cmd.execution,
		commandSource: cmd.source,
		commandPreserveInput: cmd.preserveInput,
	}));

	const skillOptions: AutocompleteOption[] = skillCommands.map((cmd) => ({
		display: `/${cmd.name}`,
		value: formatSlashCommandAutocompleteValue(cmd),
		description: cmd.description,
		commandName: cmd.name,
		commandExecution: cmd.execution,
		commandSource: cmd.source,
		commandPreserveInput: cmd.preserveInput,
	}));

	const getFilteredSlashOptions = useCallback(
		(query: string): AutocompleteOption[] => {
			const q = query.toLowerCase();
			const filterFn = (o: AutocompleteOption) => {
				if (!q) return true;
				const name = o.display.toLowerCase().slice(1);
				const desc = o.description?.toLowerCase() ?? "";
				return name.includes(q) || desc.includes(q);
			};
			const sortFn = (a: AutocompleteOption, b: AutocompleteOption) => {
				if (!q) return 0;
				const aName = a.display.toLowerCase().slice(1);
				const bName = b.display.toLowerCase().slice(1);
				const aNameStarts = aName.startsWith(q);
				const bNameStarts = bName.startsWith(q);
				if (aNameStarts && !bNameStarts) return -1;
				if (!aNameStarts && bNameStarts) return 1;
				const aNameIncludes = aName.includes(q);
				const bNameIncludes = bName.includes(q);
				if (aNameIncludes && !bNameIncludes) return -1;
				if (!aNameIncludes && bNameIncludes) return 1;
				return 0;
			};

			const filteredSystem = systemOptions.filter(filterFn).sort(sortFn);
			const filteredSkills = skillOptions.filter(filterFn).sort(sortFn);

			if (filteredSkills.length === 0) return filteredSystem;

			const result: AutocompleteOption[] = [...filteredSystem];
			result.push({
				display: "Skills",
				value: "",
				isHeader: true,
			});
			result.push(...filteredSkills);
			return result.slice(0, MAX_COMPLETION_RESULTS);
		},
		[systemOptions, skillOptions],
	);

	const getFilteredMentionOptions = useCallback(
		(_query: string): AutocompleteOption[] => {
			return mentionResults.slice(0, MAX_COMPLETION_RESULTS).map((f) => ({
				display: f,
				value: formatMentionAutocompleteValue(f),
			}));
		},
		[mentionResults],
	);

	const updateAutocomplete = useCallback(
		(text: string) => {
			const slash = extractSlashQuery(text);
			if (slash.inSlashMode) {
				setMode("/");
				setFilter(slash.query);
				setSelected(
					getFirstSelectableIndex(getFilteredSlashOptions(slash.query)),
				);
				return;
			}

			const mention = extractMentionQuery(text);
			if (mention.inMentionMode) {
				setMode("@");
				setFilter(mention.query);
				setSelected(0);

				if (searchTimerRef.current) {
					clearTimeout(searchTimerRef.current);
				}
				setMentionResults([]);
				const counter = ++searchCounterRef.current;
				searchTimerRef.current = setTimeout(() => {
					searchWorkspaceFilesForMention({
						workspaceRoot,
						query: mention.query,
						limit: MAX_COMPLETION_RESULTS,
					})
						.then((results) => {
							if (counter === searchCounterRef.current) {
								setMentionResults(results);
							}
						})
						.catch(() => {});
				}, COMPLETION_DEBOUNCE_MS);
				return;
			}

			setMode(false);
			setFilter("");
		},
		[workspaceRoot, getFilteredSlashOptions],
	);

	const getFilteredOptions = useCallback((): AutocompleteOption[] => {
		if (mode === "/") return getFilteredSlashOptions(filter);
		if (mode === "@") return getFilteredMentionOptions(filter);
		return [];
	}, [mode, filter, getFilteredSlashOptions, getFilteredMentionOptions]);

	const close = useCallback(() => {
		setMode(false);
		setFilter("");
		setSelected(0);
	}, []);

	return {
		mode,
		filter,
		selected,
		setSelected,
		updateAutocomplete,
		getFilteredOptions,
		close,
		setMode,
	};
}

import { Llms } from "@cline/core";
import type { ChoiceContext } from "@opentui-ui/dialog";
import type { DialogActions } from "@opentui-ui/dialog/react";
import { useCallback, useMemo } from "react";
import type {
	InteractiveConfigData,
	InteractiveConfigItem,
	InteractiveConfigTab,
	LoadInteractiveConfigDataOptions,
} from "../../tui/interactive-config";
import type { CliCompactionMode, Config } from "../../utils/types";
import {
	ConfigErrorContent,
	DeleteConfigItemConfirmContent,
	ExtDetailContent,
} from "../components/dialogs/config-dialogs";
import { withLoadingDialog } from "../components/dialogs/loading-dialog";
import { ConfigPanelContent } from "../views/config-view";
import type { ConfigAction } from "../views/config-view-helpers";
import type { OpenModelSelectorOptions } from "./use-model-selector";

export interface OpenConfigOptions {
	initialTab?: InteractiveConfigTab;
}

export function useConfigPanel(opts: {
	dialog: DialogActions;
	config: Config;
	sessionUiMode: string;
	compactionMode: CliCompactionMode;
	toggleMode: () => void;
	toggleAutoApprove: () => void;
	setCompactionMode: (mode: CliCompactionMode) => void;
	termHeight: number;
	loadConfigData: (
		options?: LoadInteractiveConfigDataOptions,
	) => Promise<InteractiveConfigData>;
	onToggleConfigItem?: (
		item: InteractiveConfigItem,
		options?: LoadInteractiveConfigDataOptions,
	) => Promise<InteractiveConfigData | undefined>;
	onDeleteConfigItem?: (
		item: InteractiveConfigItem,
		options?: LoadInteractiveConfigDataOptions,
	) => Promise<InteractiveConfigData | undefined>;
	openModelSelector: (options?: OpenModelSelectorOptions) => Promise<void>;
	openMcpManager: (options?: { refocus?: boolean }) => Promise<boolean>;
	refocusTextarea: () => void;
}) {
	const emptyConfigData = useMemo(
		() => ({
			workflows: [] as InteractiveConfigItem[],
			rules: [] as InteractiveConfigItem[],
			skills: [] as InteractiveConfigItem[],
			hooks: [] as InteractiveConfigItem[],
			agents: [] as InteractiveConfigItem[],
			plugins: [] as InteractiveConfigItem[],
			mcp: [] as InteractiveConfigItem[],
			tools: [] as InteractiveConfigItem[],
			workflowSlashCommands: [],
		}),
		[],
	);

	const openConfig = useCallback(
		async (options: OpenConfigOptions = {}) => {
			let keepOpen = true;
			let activeTab = options.initialTab;
			while (keepOpen) {
				const [data, providerInfo] = await withLoadingDialog(
					opts.dialog,
					"Loading settings...",
					async () =>
						await Promise.all([
							opts
								.loadConfigData({ includePluginTools: false })
								.catch(() => emptyConfigData),
							Llms.getProvider(opts.config.providerId).catch(() => undefined),
						]),
				);
				const providerDisplayName =
					providerInfo?.name ?? opts.config.providerId;
				const action = await opts.dialog.choice<ConfigAction>({
					size: "large",
					style: { maxHeight: opts.termHeight - 2 },
					closeOnEscape: false,
					content: (ctx: ChoiceContext<ConfigAction>) => (
						<ConfigPanelContent
							{...ctx}
							config={opts.config}
							configData={data}
							loadConfigData={opts.loadConfigData}
							providerDisplayName={providerDisplayName}
							currentMode={opts.sessionUiMode}
							currentCompactionMode={opts.compactionMode}
							initialTab={activeTab}
							onActiveTabChange={(tab) => {
								activeTab = tab;
							}}
							onToggleConfigItem={opts.onToggleConfigItem}
							onDeleteConfigItem={opts.onDeleteConfigItem}
							onToggleMode={opts.toggleMode}
							onToggleAutoApprove={opts.toggleAutoApprove}
							onSetCompactionMode={opts.setCompactionMode}
						/>
					),
				});

				if (!action) {
					keepOpen = false;
					continue;
				}

				if (action.kind === "open-provider") {
					await opts.openModelSelector({
						startWithProviderChange: true,
						onCancel: () => {},
					});
				} else if (action.kind === "open-model") {
					await opts.openModelSelector({ onCancel: () => {} });
				} else if (action.kind === "toggle-item") {
					await opts.onToggleConfigItem?.(action.item);
				} else if (action.kind === "delete-item") {
					const confirmed = await opts.dialog.choice<boolean>({
						closeOnEscape: true,
						content: (ctx: ChoiceContext<boolean>) => (
							<DeleteConfigItemConfirmContent {...ctx} item={action.item} />
						),
					});
					if (confirmed && opts.onDeleteConfigItem) {
						try {
							await withLoadingDialog(
								opts.dialog,
								`Deleting ${action.item.name}...`,
								async () =>
									await opts.onDeleteConfigItem?.(action.item, {
										includePluginTools: false,
									}),
							);
						} catch (error) {
							await opts.dialog.choice<void>({
								closeOnEscape: true,
								content: (ctx: ChoiceContext<void>) => (
									<ConfigErrorContent
										{...ctx}
										title="Plugin delete failed"
										message={
											error instanceof Error ? error.message : String(error)
										}
									/>
								),
							});
						}
					}
				} else if (action.kind === "ext-detail") {
					await opts.dialog.choice<void>({
						style: { maxHeight: opts.termHeight - 2 },
						closeOnEscape: false,
						content: (ctx: ChoiceContext<void>) => (
							<ExtDetailContent
								{...ctx}
								item={action.item}
								onToggleConfigItem={opts.onToggleConfigItem}
							/>
						),
					});
				} else if (action.kind === "open-mcp") {
					const changed = await opts.openMcpManager({ refocus: false });
					if (changed) {
						keepOpen = false;
					}
				}
			}
			opts.refocusTextarea();
		},
		[opts, emptyConfigData],
	);

	return openConfig;
}

import { describe, expect, it } from "vitest";
import { getHistoryNavigationAction } from "./use-input-history";

const basePosition = {
	cursorOffset: 4,
	textLength: 10,
	visualRow: 1,
	height: 3,
	virtualLineCount: 3,
};

describe("history navigation boundaries", () => {
	it("navigates previous history when the cursor is at the start", () => {
		expect(
			getHistoryNavigationAction({
				...basePosition,
				direction: "up",
				cursorOffset: 0,
				visualRow: 0,
			}),
		).toBe("navigate");
	});

	it("moves to the start before previous history on the first visual row", () => {
		expect(
			getHistoryNavigationAction({
				...basePosition,
				direction: "up",
				cursorOffset: 5,
				visualRow: 0,
			}),
		).toBe("move-to-boundary");
	});

	it("lets up move through text when the cursor is below the first visual row", () => {
		expect(
			getHistoryNavigationAction({
				...basePosition,
				direction: "up",
				cursorOffset: 5,
				visualRow: 1,
			}),
		).toBe("ignore");
	});

	it("navigates next history when the cursor is at the end", () => {
		expect(
			getHistoryNavigationAction({
				...basePosition,
				direction: "down",
				cursorOffset: 10,
				visualRow: 2,
			}),
		).toBe("navigate");
	});

	it("moves to the end before next history on the last visual row", () => {
		expect(
			getHistoryNavigationAction({
				...basePosition,
				direction: "down",
				cursorOffset: 5,
				visualRow: 2,
			}),
		).toBe("move-to-boundary");
	});

	it("uses content height for the bottom row when the textarea is taller", () => {
		expect(
			getHistoryNavigationAction({
				...basePosition,
				direction: "down",
				cursorOffset: 5,
				visualRow: 0,
				height: 5,
				virtualLineCount: 1,
			}),
		).toBe("move-to-boundary");
	});

	it("lets down move through text when the cursor is above the last visual row", () => {
		expect(
			getHistoryNavigationAction({
				...basePosition,
				direction: "down",
				cursorOffset: 5,
				visualRow: 1,
			}),
		).toBe("ignore");
	});
});

import { useCallback, useRef, useState } from "react";
import {
	appendInputHistory,
	loadInputHistory,
	prependInputHistoryEntry,
} from "../../utils/input-history";
import type { TextareaHandle } from "../components/input-bar";

type HistoryDirection = "up" | "down";
type HistoryNavigationAction = "navigate" | "move-to-boundary" | "ignore";

export interface HistoryNavigationPosition {
	direction: HistoryDirection;
	cursorOffset: number;
	textLength: number;
	visualRow: number;
	height: number;
	virtualLineCount: number;
}

export function getHistoryNavigationAction(
	position: HistoryNavigationPosition,
): HistoryNavigationAction {
	if (position.direction === "up") {
		if (position.cursorOffset <= 0) return "navigate";
		return position.visualRow === 0 ? "move-to-boundary" : "ignore";
	}

	if (position.cursorOffset >= position.textLength) return "navigate";

	const visibleLineCount = Math.max(
		1,
		Math.min(position.height, Math.max(1, position.virtualLineCount)),
	);
	const bottomVisualRow = visibleLineCount - 1;
	return position.visualRow >= bottomVisualRow ? "move-to-boundary" : "ignore";
}

export function useInputHistory(
	textareaRef: React.MutableRefObject<TextareaHandle | null>,
) {
	const [history, setHistory] = useState<string[]>(() => loadInputHistory());
	const historyRef = useRef(history);
	const indexRef = useRef(-1);
	const savedInputRef = useRef("");
	const pendingHistoryTextRef = useRef<string | null>(null);
	historyRef.current = history;

	const navigateHistory = useCallback(
		(direction: HistoryDirection, currentInput: string) => {
			const ta = textareaRef.current;
			const entries = historyRef.current;
			if (!ta) return false;

			const action = getHistoryNavigationAction({
				direction,
				cursorOffset: ta.cursorOffset,
				textLength: ta.plainText.length,
				visualRow: ta.visualCursor.visualRow,
				height: ta.height,
				virtualLineCount: ta.virtualLineCount,
			});

			if (action === "ignore") return false;

			if (action === "move-to-boundary") {
				ta.cursorOffset = direction === "up" ? 0 : ta.plainText.length;
				return true;
			}

			if (entries.length === 0) return false;

			if (indexRef.current === -1) {
				if (direction === "down") return false;
				savedInputRef.current = currentInput;
			}

			if (direction === "up") {
				if (indexRef.current < entries.length - 1) {
					indexRef.current++;
				} else {
					return false;
				}
			} else {
				if (indexRef.current > -1) {
					indexRef.current--;
				} else {
					return false;
				}
			}

			const text =
				indexRef.current === -1
					? savedInputRef.current
					: (entries[indexRef.current] ?? "");

			pendingHistoryTextRef.current = text;
			ta.setText(text);
			ta.cursorOffset = direction === "up" ? 0 : text.length;
			return true;
		},
		[textareaRef],
	);

	const resetHistoryIndex = useCallback(() => {
		indexRef.current = -1;
	}, []);

	const recordHistoryEntry = useCallback(
		(prompt: string) => {
			appendInputHistory(prompt);
			setHistory((current) => prependInputHistoryEntry(current, prompt));
			resetHistoryIndex();
		},
		[resetHistoryIndex],
	);

	const shouldResetHistoryIndex = useCallback((text: string) => {
		if (pendingHistoryTextRef.current === text) {
			pendingHistoryTextRef.current = null;
			return false;
		}
		return true;
	}, []);

	return {
		navigateHistory,
		recordHistoryEntry,
		resetHistoryIndex,
		shouldResetHistoryIndex,
	};
}

import { describe, expect, it, vi } from "vitest";
import { formatCompactionStatus } from "../utils/compaction-status";
import {
	type LocalSlashCommandActionInput,
	runLocalSlashCommandAction,
} from "./local-command-actions";

function makeActions(
	overrides: Partial<Omit<LocalSlashCommandActionInput, "name">> = {},
): Omit<LocalSlashCommandActionInput, "name"> {
	return {
		isRunning: false,
		openAccount: vi.fn(),
		openConfig: vi.fn(),
		openMcpManager: vi.fn(async () => false),
		openModelSelector: vi.fn(),
		openSkills: vi.fn(),
		runCompact: vi.fn(),
		runFork: vi.fn(),
		runUndo: vi.fn(async () => {}),
		clearConversation: vi.fn(async () => {}),
		openHelp: vi.fn(),
		openHistory: vi.fn(),
		exitCline: vi.fn(),
		...overrides,
	};
}

describe("runLocalSlashCommandAction", () => {
	it("opens the skills picker with skills", () => {
		const openSkills = vi.fn();
		const actions = makeActions({ openSkills });
		const invocation = {
			text: "please /skills",
			cursorOffset: "please /skills".length,
			replaceRange: { start: "please ".length, end: "please /skills".length },
		};

		const handled = runLocalSlashCommandAction({
			name: "skills",
			invocation,
			...actions,
		});

		expect(handled).toBe(true);
		expect(openSkills).toHaveBeenCalledWith(invocation);
	});

	it("opens settings to the plugins tab with plugins", () => {
		const openConfig = vi.fn();
		const actions = makeActions({ openConfig });

		const handled = runLocalSlashCommandAction({
			name: "plugins",
			...actions,
		});

		expect(handled).toBe(true);
		expect(openConfig).toHaveBeenCalledWith({ initialTab: "plugins" });
	});

	it("does not start compaction while a turn is running", () => {
		const runCompact = vi.fn();
		const actions = makeActions({ isRunning: true, runCompact });

		const handled = runLocalSlashCommandAction({
			name: "compact",
			...actions,
		});

		expect(handled).toBe(true);
		expect(runCompact).not.toHaveBeenCalled();
	});

	it("starts compaction while the session is idle", () => {
		const runCompact = vi.fn();
		const actions = makeActions({ runCompact });

		const handled = runLocalSlashCommandAction({
			name: "compact",
			...actions,
		});

		expect(handled).toBe(true);
		expect(runCompact).toHaveBeenCalledOnce();
	});

	it("waits for clear to reset the runtime session", async () => {
		let resolveClear: (() => void) | undefined;
		const clearConversation = vi.fn(
			() =>
				new Promise<void>((resolve) => {
					resolveClear = resolve;
				}),
		);
		const actions = makeActions({ clearConversation });

		const handled = runLocalSlashCommandAction({
			name: "clear",
			...actions,
		});
		const handledPromise = Promise.resolve(handled);
		let settled = false;
		void handledPromise.then(() => {
			settled = true;
		});

		await Promise.resolve();

		expect(clearConversation).toHaveBeenCalledOnce();
		expect(settled).toBe(false);

		resolveClear?.();

		expect(await handledPromise).toBe(true);
		expect(settled).toBe(true);
	});

	it("waits for undo to finish restoring", async () => {
		let resolveUndo: (() => void) | undefined;
		const runUndo = vi.fn(
			() =>
				new Promise<void>((resolve) => {
					resolveUndo = resolve;
				}),
		);
		const actions = makeActions({ runUndo });

		const handled = runLocalSlashCommandAction({
			name: "undo",
			...actions,
		});
		const handledPromise = Promise.resolve(handled);
		let settled = false;
		void handledPromise.then(() => {
			settled = true;
		});

		await Promise.resolve();

		expect(runUndo).toHaveBeenCalledOnce();
		expect(settled).toBe(false);

		resolveUndo?.();

		expect(await handledPromise).toBe(true);
		expect(settled).toBe(true);
	});

	it("exits Cline with quit", () => {
		vi.useFakeTimers();
		const exitCline = vi.fn();
		const actions = makeActions({ exitCline });

		try {
			const handled = runLocalSlashCommandAction({
				name: "quit",
				...actions,
			});

			expect(handled).toBe(true);
			expect(exitCline).not.toHaveBeenCalled();

			vi.runAllTimers();

			expect(exitCline).toHaveBeenCalledOnce();
		} finally {
			vi.useRealTimers();
		}
	});
});

describe("formatCompactionStatus", () => {
	it("reports when core did not return a compaction result", () => {
		expect(
			formatCompactionStatus({
				messagesBefore: 300,
				messagesAfter: 300,
				compacted: false,
			}),
		).toBe("No compaction needed.");
	});

	it("reports same-count compaction without implying no-op", () => {
		expect(
			formatCompactionStatus({
				messagesBefore: 300,
				messagesAfter: 300,
				compacted: true,
			}),
		).toBe("Compacted context; message count stayed at 300 messages.");
	});

	it("reports empty sessions separately", () => {
		expect(
			formatCompactionStatus({
				messagesBefore: 0,
				messagesAfter: 0,
				compacted: false,
			}),
		).toBe("No messages to compact.");
	});
});

import { useTerminalDimensions } from "@opentui/react";
import type { ChoiceContext } from "@opentui-ui/dialog";
import { useDialog } from "@opentui-ui/dialog/react";
import { useCallback } from "react";
import type { SlashCommandRegistry } from "../commands/slash-command-registry";
import { resolveSlashCommand } from "../commands/slash-command-registry";
import { ForkConfirmContent } from "../components/dialogs/fork-confirm";
import { HelpDialogContent } from "../components/dialogs/help-dialog";
import { withLoadingDialog } from "../components/dialogs/loading-dialog";
import { useSession } from "../contexts/session-context";
import type { AppView, TuiProps } from "../types";
import { hydrateSessionMessages } from "../utils/hydrate-messages";
import type { LocalSlashCommandInvocation } from "../utils/skill-command-input";
import { HistoryDialogContent } from "../views/history-view";
import { runLocalSlashCommandAction } from "./local-command-actions";
import type { OpenConfigOptions } from "./use-config-panel";

export function useLocalCommandActions(input: {
	slashCommandRegistry: SlashCommandRegistry;
	canForkSession: boolean;
	openAccount: () => void;
	openConfig: (options?: OpenConfigOptions) => void;
	openMcpManager: () => Promise<boolean>;
	openModelSelector: () => void;
	openSkills: (invocation?: LocalSlashCommandInvocation) => void;
	refocusTextarea: () => void;
	setAppView: (view: AppView) => void;
	onClearConversation: () => Promise<void>;
	onResumeSession: TuiProps["onResumeSession"];
	onCompact: TuiProps["onCompact"];
	onFork: TuiProps["onFork"];
	onUndo: () => Promise<void>;
	onExit: TuiProps["onExit"];
}) {
	const dialog = useDialog();
	const session = useSession();
	const { height: termHeight } = useTerminalDimensions();
	const {
		slashCommandRegistry,
		canForkSession,
		openAccount,
		openConfig,
		openMcpManager,
		openModelSelector,
		openSkills,
		refocusTextarea,
		setAppView,
		onClearConversation,
		onResumeSession,
		onCompact,
		onFork,
		onUndo,
		onExit,
	} = input;

	const openHistory = useCallback(async () => {
		const sessionId = await dialog.choice<string>({
			size: "large",
			style: { maxHeight: termHeight - 2 },
			content: (ctx: ChoiceContext<string>) => (
				<HistoryDialogContent {...ctx} />
			),
		});
		if (sessionId) {
			try {
				await withLoadingDialog(dialog, "Loading session...", async () => {
					const result = await onResumeSession(sessionId);
					const { messages } = result;
					const entries = hydrateSessionMessages(messages);
					if (entries.length === 0) {
						session.appendEntry({
							kind: "error",
							text: `Session ${sessionId} has no messages to resume.`,
						});
					} else {
						session.clearEntries();
						// replaceEntries rather than appendEntry: appendEntry
						// stamps unstamped entries with the CURRENT mode, which
						// would lock hydrated history to the resume-time accent.
						session.replaceEntries(entries);
						if (typeof result.currentContextSize === "number") {
							session.setLastTotalTokens(result.currentContextSize);
						}
						if (typeof result.totalCost === "number") {
							session.setLastTotalCost(result.totalCost);
						}
						session.setHasSubmitted(true);
						setAppView("chat");
					}
				});
			} catch (error) {
				session.appendEntry({
					kind: "error",
					text: `Failed to resume session: ${error instanceof Error ? error.message : String(error)}`,
				});
			}
		}
		refocusTextarea();
	}, [
		dialog,
		onResumeSession,
		refocusTextarea,
		session,
		setAppView,
		termHeight,
	]);

	const openHelp = useCallback(async () => {
		await dialog.choice<void>({
			size: "large",
			style: { maxHeight: termHeight - 2 },
			content: (ctx: ChoiceContext<void>) => <HelpDialogContent {...ctx} />,
		});
		refocusTextarea();
	}, [dialog, refocusTextarea, termHeight]);

	const runCompact = useCallback(async () => {
		session.setIsRunning(true);
		session.appendEntry({
			kind: "compaction",
			compactionMode: "manual",
			status: "started",
		});
		try {
			const result = await onCompact();
			session.updateLastEntry((entry) =>
				entry.kind === "compaction" && entry.status === "started"
					? {
							...entry,
							status: result.compacted ? "completed" : "skipped",
							messagesBefore: result.messagesBefore,
							messagesAfter:
								result.workingContextMessagesAfter ?? result.messagesAfter,
						}
					: entry,
			);
		} catch (error) {
			const cancelled =
				error instanceof Error &&
				(error.name === "AbortError" || /abort/i.test(error.message));
			session.updateLastEntry((entry) =>
				entry.kind === "compaction" && entry.status === "started"
					? { ...entry, status: cancelled ? "cancelled" : "failed" }
					: entry,
			);
			if (!cancelled) {
				session.appendEntry({
					kind: "error",
					text: `Compaction failed: ${error instanceof Error ? error.message : String(error)}`,
				});
			}
		} finally {
			session.setIsRunning(false);
		}
	}, [onCompact, session]);

	const runFork = useCallback(async () => {
		if (!canForkSession) {
			session.appendEntry({
				kind: "status",
				text: "Fork is available after this session has messages.",
			});
			return;
		}
		const confirmed = await dialog.choice<boolean>({
			closeOnEscape: true,
			content: (ctx: ChoiceContext<boolean>) => <ForkConfirmContent {...ctx} />,
		});
		refocusTextarea();
		if (!confirmed) return;
		session.appendEntry({
			kind: "status",
			text: "Creating forked session...",
		});
		try {
			const result = await onFork();
			if (result) {
				session.updateLastEntry(() => ({
					kind: "status",
					text: `Forked into new session ${result.newSessionId}. This is now the active session. Use /history to switch sessions.`,
				}));
				if (result.carriedWorkingContext) {
					session.appendEntry({
						kind: "compaction",
						compactionMode: "inherited",
						status: "completed",
						messagesBefore: result.carriedWorkingContext.canonicalMessages,
						messagesAfter: result.carriedWorkingContext.workingContextMessages,
					});
				}
			} else {
				session.updateLastEntry(() => ({
					kind: "error",
					text: "Fork failed: could not read messages from the current session.",
				}));
			}
		} catch (error) {
			session.updateLastEntry(() => ({
				kind: "error",
				text: `Fork failed: ${error instanceof Error ? error.message : String(error)}`,
			}));
		}
	}, [canForkSession, dialog, onFork, refocusTextarea, session]);

	const handleSlashCommand = useCallback(
		(command: string, invocation?: LocalSlashCommandInvocation) => {
			const resolved = resolveSlashCommand(slashCommandRegistry, command);
			if (!resolved || resolved.execution !== "local") {
				return false;
			}
			return runLocalSlashCommandAction({
				name: resolved.name,
				isRunning: session.isRunning,
				invocation,
				openAccount,
				openConfig,
				openMcpManager,
				openModelSelector,
				openSkills,
				runCompact,
				runFork,
				runUndo: onUndo,
				clearConversation: onClearConversation,
				openHelp,
				openHistory,
				exitCline: onExit,
			});
		},
		[
			onClearConversation,
			onExit,
			onUndo,
			openAccount,
			openConfig,
			openMcpManager,
			openHelp,
			openHistory,
			openModelSelector,
			openSkills,
			runCompact,
			runFork,
			session.isRunning,
			slashCommandRegistry,
		],
	);

	return { handleSlashCommand };
}

import type { ChoiceContext } from "@opentui-ui/dialog";
import type { DialogActions } from "@opentui-ui/dialog/react";
import { useCallback } from "react";
import type {
	InteractiveConfigData,
	InteractiveConfigItem,
} from "../../tui/interactive-config";
import {
	type McpEntry,
	McpManagerContent,
} from "../components/dialogs/mcp-manager-dialog";

function toMcpEntries(items: InteractiveConfigItem[]): McpEntry[] {
	return items.map((item) => ({
		name: item.name,
		path: item.path,
		enabled: item.enabled,
		description: item.description,
		lastError: item.loadError,
		pluginName: item.pluginName,
	}));
}

export function useMcpManager(opts: {
	dialog: DialogActions;
	termHeight: number;
	loadConfigData: () => Promise<InteractiveConfigData>;
	onSessionRestart: () => Promise<void>;
	refocusTextarea: () => void;
}) {
	return useCallback(
		async (options?: { refocus?: boolean }) => {
			const data = await opts.loadConfigData().catch(() => undefined);
			const servers = toMcpEntries(data?.mcp ?? []);
			const changed = await opts.dialog.choice<boolean>({
				style: { maxHeight: opts.termHeight - 2 },
				closeOnEscape: false,
				content: (ctx: ChoiceContext<boolean>) => (
					<McpManagerContent {...ctx} servers={servers} />
				),
			});
			if (changed) {
				await opts.onSessionRestart();
			}
			if (options?.refocus !== false) {
				opts.refocusTextarea();
			}
			return changed === true;
		},
		[opts],
	);
}

