export interface OpenModelSelectorOptions {
	onCancel?: () => Promise<void> | void;
	startWithProviderChange?: boolean;
}

async function getProviderDisplayName(providerId: string): Promise<string> {
	const info = await Llms.getProvider(providerId);
	return info?.name ?? providerId;
}

async function refreshCurrentProviderModels(config: Config): Promise<void> {
	const manager = new ProviderSettingsManager();
	await refreshProviderModelsFromSource(manager, config.providerId).catch(
		() => {},
	);
	const resolved = await resolveProviderConfig(
		config.providerId,
		{
			loadLatestOnInit: true,
			loadPrivateOnAuth: true,
			failOnError: false,
		},
		manager.getProviderConfig(config.providerId, { includeKnownModels: false }),
	);
	if (resolved?.knownModels) {
		config.knownModels = resolved.knownModels;
	}
}

function clearReasoningConfig(config: Config): void {
	config.thinking = false;
	config.reasoningEffort = undefined;
}

function usesModelIdInput(providerId: string): boolean {
	return providerId === "openai-compatible";
}

/**
 * Ask an OpenAI-compatible endpoint for its model list (`GET <baseUrl>/models`)
 * using the provider's stored API key and headers, mirroring the extension's
 * refreshOpenAiModels handler. Returns [] on any failure so callers fall back
 * to manual model-id entry.
 */
async function fetchOpenAiCompatibleModelIds(
	providerId: string,
): Promise<string[]> {
	try {
		const manager = new ProviderSettingsManager();
		const config = manager.getProviderConfig(providerId, {
			includeKnownModels: false,
		});
		const baseUrl = config?.baseUrl?.trim().replace(/\/+$/, "");
		if (!baseUrl || !URL.canParse(baseUrl)) return [];

		const headers: Record<string, string> = { ...(config?.headers ?? {}) };
		const apiKey = config?.apiKey?.trim();
		if (
			apiKey &&
			!Object.keys(headers).some((h) => h.toLowerCase() === "authorization")
		) {
			headers.Authorization = `Bearer ${apiKey}`;
		}

		const response = await fetch(`${baseUrl}/models`, {
			headers,
			signal: AbortSignal.timeout(5_000),
		});
		if (!response.ok) return [];
		const payload = (await response.json()) as { data?: unknown };
		const list = Array.isArray(payload?.data) ? payload.data : [];
		const ids = list
			.map((model) => {
				const id = (model as { id?: unknown } | null)?.id;
				return typeof id === "string" ? id.trim() : "";
			})
			.filter(Boolean);
		return [...new Set(ids)];
	} catch {
		return [];
	}
}

function providerToExistingProviderOptions(input: {
	providerId: string;
	providerName: string;
	dialog: DialogActions;
	termHeight: number;
}): ExistingProviderOption[] {
	if (input.providerId !== "cline-pass") {
		return [];
	}

	return [
		{
			value: "open_subscription_page",
			label: "Manage subscription & see usage",
			onSelect: async () => {
				await input.dialog.choice<boolean>({
					style: { maxHeight: input.termHeight - 2 },
					closeOnEscape: false,
					content: (ctx: ChoiceContext<boolean>) => (
						<ClinePassSubscriptionContent
							{...ctx}
							providerName={input.providerName}
						/>
					),
				});
			},
		},
	];
}

async function runProviderChange(
	dialog: DialogActions,
	config: Config,
	termHeight: number,
	onModelChange: () => Promise<void>,
): Promise<boolean> {
	const newProviderId = await dialog.choice<string>({
		style: { maxHeight: termHeight - 2 },
		content: (ctx: ChoiceContext<string>) => (
			<ProviderPickerContent {...ctx} currentProviderId={config.providerId} />
		),
	});
	if (!newProviderId) return false;

	const manager = new ProviderSettingsManager();
	const displayName = await withLoadingDialog(
		dialog,
		"Loading provider...",
		async () => await getProviderDisplayName(newProviderId),
	);
	const existingSettings = manager.getProviderSettings(newProviderId);

	// Manual API key entry is the escape hatch for when OAuth login isn't
	// working; only the Cline providers accept a dashboard API key.
	const supportsManualApiKey = isClineProvider(newProviderId);
	const openManualApiKeyDialog = async (): Promise<boolean | undefined> =>
		await dialog.choice<boolean>({
			style: { maxHeight: termHeight - 2 },
			closeOnEscape: false,
			content: (ctx: ChoiceContext<boolean>) => (
				<OAuthApiKeyInputContent
					{...ctx}
					providerId={newProviderId}
					providerName={displayName}
					providerSettingsManager={manager}
				/>
			),
		});

	let needsAuth = true;
	if (isProviderConfigured(newProviderId, existingSettings)) {
		let option: ExistingProviderOption | undefined;
		const extraOptions = providerToExistingProviderOptions({
			providerId: newProviderId,
			providerName: displayName,
			dialog,
			termHeight,
		});
		while (true) {
			option = await dialog.choice<ExistingProviderOption>({
				style: { maxHeight: termHeight - 2 },
				content: (ctx: ChoiceContext<ExistingProviderOption>) => (
					<UseExistingOrReconfigureContent
						{...ctx}
						providerName={displayName}
						extraOptions={extraOptions}
					/>
				),
			});
			if (!option) return false;
			if (option.onSelect) {
				await option.onSelect();
				option = undefined;
				continue;
			}
			break;
		}
		needsAuth = option.value === "reconfigure";
	}

	if (needsAuth) {
		let saved: boolean | undefined;
		if (isOAuthProvider(newProviderId)) {
			const loginResult = await dialog.choice<OAuthLoginResult>({
				style: { maxHeight: termHeight - 2 },
				closeOnEscape: false,
				content: (ctx: ChoiceContext<OAuthLoginResult>) => (
					<OAuthLoginContent
						{...ctx}
						providerId={newProviderId}
						providerName={displayName}
						allowApiKeyFallback={supportsManualApiKey}
					/>
				),
			});
			saved =
				loginResult === "use_api_key"
					? await openManualApiKeyDialog()
					: loginResult;
		} else if (isOpenAICodexCliProvider(newProviderId)) {
			saved = await dialog.choice<boolean>({
				style: { maxHeight: termHeight - 2 },
				closeOnEscape: false,
				content: (ctx: ChoiceContext<boolean>) => (
					<CodexCliStatusContent {...ctx} providerName={displayName} />
				),
			});
			if (saved) {
				manager.saveProviderSettings({
					...(existingSettings ?? {}),
					provider: newProviderId,
				});
			}
		} else {
			const { fields } = getProviderConfigFields(newProviderId);
			saved = await dialog.choice<boolean>({
				style: { maxHeight: termHeight - 2 },
				closeOnEscape: false,
				content: (ctx: ChoiceContext<boolean>) => (
					<ProviderConfigInputContent
						{...ctx}
						providerId={newProviderId}
						providerName={displayName}
						fields={fields}
						providerSettingsManager={manager}
					/>
				),
			});
		}
		if (!saved) return false;
	}
	await withLoadingDialog(
		dialog,
		`Loading ${displayName} models...`,
		async () => {
			await refreshProviderModelsFromSource(manager, newProviderId).catch(
				() => {},
			);
			const newSettings = manager.getProviderSettings(newProviderId);
			const newApiKey =
				getPersistedProviderApiKey(newProviderId, newSettings) ?? "";

			manager.saveProviderSettings(
				{
					...(newSettings ?? {}),
					provider: newProviderId,
				},
				{ setLastUsed: true },
			);

			config.providerId = newProviderId;
			config.apiKey = newApiKey;
			const resolved = await resolveProviderConfig(
				newProviderId,
				{
					loadLatestOnInit: true,
					loadPrivateOnAuth: true,
					failOnError: false,
				},
				manager.getProviderConfig(newProviderId, { includeKnownModels: false }),
			);
			config.knownModels = resolved?.knownModels;
			const modelIds = Object.keys(resolved?.knownModels ?? {});
			if (newSettings?.model) {
				config.modelId = newSettings.model;
			} else if (modelIds[0]) {
				config.modelId = modelIds[0];
			}

			await onModelChange();
		},
	);
	return true;
}

export function useModelSelector(opts: {
	dialog: DialogActions;
	config: Config;
	termHeight: number;
	onModelChange: () => Promise<void>;
	refocusTextarea: () => void;
}) {
	const { dialog, config, termHeight, onModelChange, refocusTextarea } = opts;

	const openModelSelector = useCallback(
		async (options?: OpenModelSelectorOptions) => {
			const handleCancel = async () => {
				if (options?.onCancel) {
					await options.onCancel();
					return;
				}
				refocusTextarea();
			};

			let modelOptions = buildModelOptions(
				config.knownModels as Record<string, Llms.ModelInfo>,
			);
			let providerDisplayName = config.providerId;
			let endpointModelOptions: ModelOption[] = [];

			const refreshProviderContext = async () => {
				modelOptions = buildModelOptions(
					config.knownModels as Record<string, Llms.ModelInfo>,
				);
				providerDisplayName = await getProviderDisplayName(config.providerId);
				// Free-text providers (openai-compatible) can still suggest model
				// ids when their endpoint answers /models; otherwise they keep the
				// manual input.
				endpointModelOptions = usesModelIdInput(config.providerId)
					? buildModelOptions(
							Object.fromEntries(
								(await fetchOpenAiCompatibleModelIds(config.providerId)).map(
									(id) => [id, { id, name: id }],
								),
							),
						)
					: [];
				if (endpointModelOptions.length > 0) {
					modelOptions = endpointModelOptions;
				}
			};

			if (!options?.startWithProviderChange) {
				await withLoadingDialog(dialog, "Loading models...", async () => {
					await refreshCurrentProviderModels(config);
					await refreshProviderContext();
				});
			}

			const changeProvider = async (): Promise<boolean> => {
				const changed = await runProviderChange(
					dialog,
					config,
					termHeight,
					onModelChange,
				);
				if (changed) {
					await withLoadingDialog(dialog, "Loading models...", async () => {
						await refreshProviderContext();
					});
				}
				return changed;
			};

			if (options?.startWithProviderChange) {
				const changed = await changeProvider();
				if (!changed) {
					await handleCancel();
					return;
				}
			}

			let pickingModel = true;

			while (pickingModel) {
				if (
					usesModelIdInput(config.providerId) &&
					endpointModelOptions.length === 0
				) {
					const modelId = await dialog.choice<string>({
						style: { maxHeight: termHeight - 2 },
						content: (ctx: ChoiceContext<string>) => (
							<ModelIdInputContent
								{...ctx}
								currentModel={config.modelId}
								currentProviderName={providerDisplayName}
							/>
						),
					});
					if (!modelId) {
						await handleCancel();
						return;
					}
					if (modelId === CHANGE_PROVIDER_ACTION) {
						await changeProvider();
						continue;
					}
					config.modelId = modelId;
					clearReasoningConfig(config);
					pickingModel = false;
					continue;
				}

				if (
					config.providerId === "cline" ||
					config.providerId === "cline-pass"
				) {
					// ClinePass gets the same sectioned picker with Subscribed/Free
					// sections — free models are selectable while staying on ClinePass
					const featuredProviderId = config.providerId;
					const clineResult = await dialog.choice<string>({
						style: { maxHeight: termHeight - 2 },
						content: (ctx: ChoiceContext<string>) => (
							<ClineModelSelectorDialogContent
								{...ctx}
								currentModel={config.modelId}
								currentProviderName={providerDisplayName}
								knownModels={config.knownModels as Record<string, unknown>}
								loadEntries={async () =>
									buildFeaturedModelEntries(
										featuredProviderId,
										await fetchClineRecommendedModels(),
									)
								}
							/>
						),
					});
					if (!clineResult) {
						await handleCancel();
						return;
					}
					if (clineResult === CHANGE_PROVIDER_ACTION) {
						await changeProvider();
						continue;
					}
					if (clineResult === BROWSE_ALL_ACTION) {
						const browseResult = await dialog.choice<string>({
							style: { maxHeight: termHeight - 2 },
							content: (ctx: ChoiceContext<string>) => (
								<ModelSelectorContent
									{...ctx}
									currentModel={config.modelId}
									currentProviderName={providerDisplayName}
									models={modelOptions}
									showCustomModelId={config.providerId !== "cline-pass"}
								/>
							),
						});
						if (!browseResult) continue;
						if (browseResult === CHANGE_PROVIDER_ACTION) {
							await changeProvider();
							continue;
						}
						config.modelId = browseResult;
						const browseModel = modelOptions.find(
							(m: ModelOption) => m.key === browseResult,
						);
						if (browseModel?.supportsReasoning) {
							const lvl: ThinkingLevel = config.reasoningEffort
								? (config.reasoningEffort as ThinkingLevel)
								: config.thinking
									? "medium"
									: "none";
							const pick = await dialog.choice<ThinkingLevel>({
								style: { maxHeight: termHeight - 2 },
								content: (ctx: ChoiceContext<ThinkingLevel>) => (
									<ThinkingLevelContent
										{...ctx}
										modelName={browseModel.name}
										currentLevel={lvl}
									/>
								),
							});
							if (pick !== undefined) {
								if (pick === "none") {
									config.thinking = false;
									config.reasoningEffort = undefined;
								} else {
									config.thinking = true;
									config.reasoningEffort = pick;
								}
							}
						}
						if (!browseModel?.supportsReasoning) {
							clearReasoningConfig(config);
						}
						pickingModel = false;
						continue;
					}

					config.modelId = clineResult;
					const selectedModel = modelOptions.find(
						(m: ModelOption) => m.key === clineResult,
					);
					if (selectedModel?.supportsReasoning) {
						const currentLevel: ThinkingLevel = config.reasoningEffort
							? (config.reasoningEffort as ThinkingLevel)
							: config.thinking
								? "medium"
								: "none";
						const thinkingLevel = await dialog.choice<ThinkingLevel>({
							style: { maxHeight: termHeight - 2 },
							content: (ctx: ChoiceContext<ThinkingLevel>) => (
								<ThinkingLevelContent
									{...ctx}
									modelName={selectedModel.name}
									currentLevel={currentLevel}
								/>
							),
						});
						if (thinkingLevel !== undefined) {
							if (thinkingLevel === "none") {
								config.thinking = false;
								config.reasoningEffort = undefined;
							} else {
								config.thinking = true;
								config.reasoningEffort = thinkingLevel;
							}
						}
					}
					if (!selectedModel?.supportsReasoning) {
						clearReasoningConfig(config);
					}
					pickingModel = false;
					continue;
				}

				const selectedKey = await dialog.choice<string>({
					style: { maxHeight: termHeight - 2 },
					content: (ctx: ChoiceContext<string>) => (
						<ModelSelectorContent
							{...ctx}
							currentModel={config.modelId}
							currentProviderName={providerDisplayName}
							models={modelOptions}
							showCustomModelId={config.providerId !== "cline-pass"}
						/>
					),
				});
				if (!selectedKey) {
					await handleCancel();
					return;
				}

				if (selectedKey === CHANGE_PROVIDER_ACTION) {
					await changeProvider();
					continue;
				}

				config.modelId = selectedKey;

				const selectedModel = modelOptions.find(
					(m: ModelOption) => m.key === selectedKey,
				);
				if (!selectedModel?.supportsReasoning) {
					clearReasoningConfig(config);
					pickingModel = false;
					break;
				}

				const currentLevel: ThinkingLevel = config.reasoningEffort
					? (config.reasoningEffort as ThinkingLevel)
					: config.thinking
						? "medium"
						: "none";

				const thinkingLevel = await dialog.choice<ThinkingLevel>({
					style: { maxHeight: termHeight - 2 },
					content: (ctx: ChoiceContext<ThinkingLevel>) => (
						<ThinkingLevelContent
							{...ctx}
							modelName={selectedModel.name}
							currentLevel={currentLevel}
						/>
					),
				});

				if (thinkingLevel === undefined) {
					continue;
				}

				if (thinkingLevel === "none") {
					config.thinking = false;
					config.reasoningEffort = undefined;
				} else {
					config.thinking = true;
					config.reasoningEffort = thinkingLevel;
				}
				pickingModel = false;
			}

			await withLoadingDialog(dialog, "Applying model...", async () => {
				await onModelChange();
			});
			refocusTextarea();
		},
		[dialog, config, termHeight, onModelChange, refocusTextarea],
	);

	return openModelSelector;
}

import { useCallback, useLayoutEffect, useRef, useState } from "react";
import { formatCliErrorMessage } from "../../utils/cline-pass-errors";
import { shouldShowCliUsageCost } from "../../utils/usage-cost-display";
import type { SlashCommandRegistry } from "../commands/slash-command-registry";
import {
	expandUserCommandPrompt,
	resolveSlashCommand,
} from "../commands/slash-command-registry";
import type { TextareaHandle } from "../components/input-bar";
import { useSession } from "../contexts/session-context";
import type { AppView, TuiProps } from "../types";
import {
	createUniquePastedTextSnippetMarker,
	expandPastedTextSnippets,
	type PastedTextSnippet,
} from "../utils/pasted-snippets";
import {
	insertSelectedSkillCommand,
	type LocalSlashCommandInvocation,
	removeLocalSlashCommandInvocation,
} from "../utils/skill-command-input";
import type { AutocompleteOption, useAutocomplete } from "./use-autocomplete";
import { extractSlashQuery } from "./use-autocomplete";
import { useInputHistory } from "./use-input-history";

interface PastedImage {
	marker: string;
	dataUrl: string;
}

export function usePromptInputController(input: {
	autocomplete: ReturnType<typeof useAutocomplete>;
	slashCommandRegistry: SlashCommandRegistry;
	handleSlashCommand: (
		command: string,
		invocation?: LocalSlashCommandInvocation,
	) => boolean | Promise<boolean>;
	onSubmit: TuiProps["onSubmit"];
	initialPrompt?: string;
	providerId: string;
	configVerbose: boolean;
	refreshRepoStatus: () => void;
	setAppView: (view: AppView) => void;
	turnErrorReportedRef: { current: boolean };
}) {
	const {
		autocomplete,
		slashCommandRegistry,
		handleSlashCommand,
		onSubmit,
		initialPrompt,
		providerId,
		configVerbose,
		refreshRepoStatus,
		setAppView,
		turnErrorReportedRef,
	} = input;
	const session = useSession();
	const [inputKey, setInputKey] = useState(0);
	const [inputValue, setInputValue] = useState(initialPrompt ?? "");
	const [pendingCursorOffset, setPendingCursorOffset] = useState<number | null>(
		null,
	);
	const textareaRef = useRef<TextareaHandle | null>(null);
	const inputValueRef = useRef("");
	const pastedImagesRef = useRef<PastedImage[]>([]);
	const pastedTextSnippetsRef = useRef<PastedTextSnippet[]>([]);
	const localCommandInFlightRef = useRef(false);
	inputValueRef.current = inputValue;

	const inputHistory = useInputHistory(textareaRef);

	const focusTextarea = useCallback(() => {
		textareaRef.current?.focus();
	}, []);

	const refocusTextarea = useCallback(() => {
		setInputKey((k) => k + 1);
	}, []);

	useLayoutEffect(() => {
		if (pendingCursorOffset === null) return;
		const textarea = textareaRef.current;
		if (!textarea) return;
		textarea.cursorOffset = pendingCursorOffset;
		textarea.focus();
		setPendingCursorOffset(null);
	}, [pendingCursorOffset]);

	const populateInput = useCallback((value: string) => {
		inputValueRef.current = value;
		setInputValue(value);
		setInputKey((k) => k + 1);
		setPendingCursorOffset(value.length);
	}, []);

	const applyInputText = useCallback((value: string, cursorOffset: number) => {
		inputValueRef.current = value;
		setInputValue(value);
		setInputKey((k) => k + 1);
		setPendingCursorOffset(cursorOffset);
	}, []);

	const insertSkillCommand = useCallback(
		(commandName: string, invocation?: LocalSlashCommandInvocation) => {
			const text =
				invocation?.text ??
				textareaRef.current?.plainText ??
				inputValueRef.current;
			const cursorOffset =
				invocation?.cursorOffset ??
				textareaRef.current?.cursorOffset ??
				text.length;
			const next = insertSelectedSkillCommand({
				text,
				cursorOffset,
				commandName,
				replaceRange: invocation?.replaceRange,
			});
			applyInputText(next.text, next.cursorOffset);
		},
		[applyInputText],
	);

	const removeLocalCommandInvocation = useCallback(
		(invocation: LocalSlashCommandInvocation) => {
			const next = removeLocalSlashCommandInvocation(invocation);
			applyInputText(next.text, next.cursorOffset);
		},
		[applyInputText],
	);

	const clearPastedImages = useCallback(() => {
		pastedImagesRef.current = [];
	}, []);

	const clearPastedTextSnippets = useCallback(() => {
		pastedTextSnippetsRef.current = [];
	}, []);

	const clearPasteAttachments = useCallback(() => {
		clearPastedImages();
		clearPastedTextSnippets();
	}, [clearPastedImages, clearPastedTextSnippets]);

	const handleImagePaste = useCallback((dataUrl: string) => {
		const marker = `[Image ${pastedImagesRef.current.length + 1}]`;
		pastedImagesRef.current = [...pastedImagesRef.current, { marker, dataUrl }];
		return marker;
	}, []);

	const handleLargeTextPaste = useCallback((text: string) => {
		const marker = createUniquePastedTextSnippetMarker(
			text,
			pastedTextSnippetsRef.current.map((snippet) => snippet.marker),
		);
		pastedTextSnippetsRef.current = [
			...pastedTextSnippetsRef.current,
			{ marker, text },
		];
		return marker;
	}, []);

	const prunePastedTextSnippets = useCallback((text: string) => {
		pastedTextSnippetsRef.current = pastedTextSnippetsRef.current.filter(
			(snippet) => text.includes(snippet.marker),
		);
	}, []);

	const runSlashCommand = useCallback(
		async (
			cmd: string,
			invocation?: LocalSlashCommandInvocation,
		): Promise<boolean> => {
			if (localCommandInFlightRef.current) return false;
			localCommandInFlightRef.current = true;
			try {
				return await Promise.resolve(handleSlashCommand(cmd, invocation));
			} finally {
				localCommandInFlightRef.current = false;
			}
		},
		[handleSlashCommand],
	);

	const selectAutocompleteOption = useCallback(
		async (option: AutocompleteOption) => {
			const ta = textareaRef.current;
			if (!ta) return;

			if (option.onSelect) {
				ta.setText("");
				ta.cursorOffset = 0;
				autocomplete.close();
				setInputValue("");
				clearPasteAttachments();
				option.onSelect();
				return;
			}

			if (autocomplete.mode === "/") {
				const cmd = option.commandName ?? option.display.slice(1);
				const text = inputValueRef.current;
				const offset = ta.cursorOffset;
				const before = text.slice(0, offset);
				const slash = extractSlashQuery(before);
				if (option.commandExecution === "local") {
					const invocation: LocalSlashCommandInvocation = {
						text,
						cursorOffset: offset,
						replaceRange: slash.inSlashMode
							? { start: slash.slashIndex, end: offset }
							: undefined,
					};
					if (!option.commandPreserveInput) {
						ta.setText("");
						ta.cursorOffset = 0;
						setInputValue("");
						clearPasteAttachments();
					}
					if (await runSlashCommand(cmd, invocation)) {
						autocomplete.close();
						return;
					}
				}
				if (slash.inSlashMode) {
					const newText =
						text.slice(0, slash.slashIndex) + option.value + text.slice(offset);
					ta.setText(newText);
					if (option.commandExecution === "user-command") {
						ta.extmarks.create({
							start: slash.slashIndex,
							end: slash.slashIndex + option.value.trimEnd().length,
							virtual: true,
						});
					}
					ta.cursorOffset = slash.slashIndex + option.value.length;
				}
			} else if (autocomplete.mode === "@") {
				const text = inputValueRef.current;
				const offset = ta.cursorOffset;
				const before = text.slice(0, offset);
				const atIdx = before.lastIndexOf("@");
				if (atIdx >= 0) {
					const newText =
						text.slice(0, atIdx) + option.value + text.slice(offset);
					ta.setText(newText);
					ta.cursorOffset = atIdx + option.value.length;
				}
			}
			autocomplete.close();
			setInputValue(ta.plainText);
		},
		[autocomplete, clearPasteAttachments, runSlashCommand],
	);

	const selectRef = useRef(selectAutocompleteOption);
	selectRef.current = selectAutocompleteOption;

	const submitPrompt = useCallback(
		async (delivery?: "queue" | "steer") => {
			if (localCommandInFlightRef.current) return;

			const prompt = inputValueRef.current.trim();
			if (!prompt) return;

			if (!delivery && prompt.startsWith("/")) {
				const parts = prompt.split(/\s+/);
				const cmd = (parts[0] ?? "").slice(1);
				const command = resolveSlashCommand(slashCommandRegistry, cmd);
				let invocation: LocalSlashCommandInvocation | undefined;
				if (command?.execution === "local") {
					const text = inputValueRef.current;
					const commandToken = parts[0] ?? "";
					const tokenStart = text.length - text.trimStart().length;
					const tokenEnd = tokenStart + commandToken.length;
					invocation = {
						text,
						cursorOffset: textareaRef.current?.cursorOffset ?? tokenEnd,
						replaceRange:
							text.slice(tokenStart, tokenEnd) === commandToken
								? { start: tokenStart, end: tokenEnd }
								: undefined,
					};
					if (!command.preserveInput) {
						setInputKey((k) => k + 1);
						setInputValue("");
						clearPasteAttachments();
					}
				}
				if (await runSlashCommand(cmd, invocation)) {
					return;
				}
			}

			const activePastedTextSnippets = pastedTextSnippetsRef.current.filter(
				(snippet) => prompt.includes(snippet.marker),
			);
			const expandedPrompt = expandPastedTextSnippets(
				prompt,
				activePastedTextSnippets,
			);
			const activeUserImages = pastedImagesRef.current
				.filter((image) => prompt.includes(image.marker))
				.map((image) => image.dataUrl);
			const promptForSubmit = expandUserCommandPrompt(
				expandedPrompt,
				slashCommandRegistry,
			);

			session.setHasSubmitted(true);
			setAppView("chat");
			if (!delivery) {
				session.setIsRunning(true);
				session.setIsStreaming(true);
				session.setAbortRequested(false);
				turnErrorReportedRef.current = false;
				session.appendEntry({
					kind: "user_submitted",
					text: prompt,
				});
			}
			setInputKey((k) => k + 1);
			setInputValue("");
			clearPasteAttachments();
			if (!delivery) {
				inputHistory.recordHistoryEntry(prompt);
			}

			const startedAt = performance.now();
			let commandOutputAppended = false;
			const appendCommandOutput = (text: string) => {
				commandOutputAppended = true;
				session.appendEntry({
					kind: "status",
					text,
				});
			};
			try {
				const result = await onSubmit(
					promptForSubmit,
					session.uiMode,
					delivery,
					activeUserImages.length > 0
						? { userImages: activeUserImages }
						: undefined,
					appendCommandOutput,
				);
				if (result.commandOutput && !commandOutputAppended) {
					session.appendEntry({
						kind: "status",
						text: result.commandOutput,
					});
				}
				if (result.queued) return;
				if (typeof result.currentContextSize === "number") {
					session.setLastTotalTokens(result.currentContextSize);
				}
				if (typeof result.usage.totalCost === "number") {
					session.setLastTotalCost(result.usage.totalCost);
				}
				if (!result.commandOutput && configVerbose) {
					const elapsed = ((performance.now() - startedAt) / 1000).toFixed(2);
					const showUsageCost = shouldShowCliUsageCost(providerId);
					session.appendEntry({
						kind: "done",
						tokens: result.currentContextSize ?? session.lastTotalTokens,
						cost:
							showUsageCost && typeof result.usage.totalCost === "number"
								? result.usage.totalCost
								: 0,
						elapsed,
						iterations: result.iterations,
					});
				}
			} catch (error) {
				if (!turnErrorReportedRef.current) {
					session.appendEntry({
						kind: "error",
						text: formatCliErrorMessage(error),
					});
				}
			} finally {
				if (!delivery) {
					session.closeInlineStream();
					session.setIsRunning(false);
					session.setIsStreaming(false);
					refreshRepoStatus();
				}
			}
		},
		[
			clearPasteAttachments,
			configVerbose,
			inputHistory,
			onSubmit,
			providerId,
			refreshRepoStatus,
			runSlashCommand,
			session,
			setAppView,
			slashCommandRegistry,
			turnErrorReportedRef,
		],
	);

	const submitRef = useRef(submitPrompt);
	submitRef.current = submitPrompt;

	const submitInitialPrompt = useCallback(() => {
		const prompt = initialPrompt?.trim();
		if (!prompt) return;
		inputValueRef.current = prompt;
		setInputValue(prompt);
		submitRef.current();
	}, [initialPrompt]);

	const handleSubmit = useCallback(() => {
		if (autocomplete.mode) {
			const opts = autocomplete.getFilteredOptions();
			if (opts.length > 0) {
				selectRef.current(
					opts[Math.min(autocomplete.selected, opts.length - 1)] ?? opts[0],
				);
				return;
			}
		}
		submitRef.current(session.isRunning ? "queue" : undefined);
	}, [autocomplete, session.isRunning]);

	const handleContentChange = useCallback(
		(text: string) => {
			setInputValue(text);
			if (!text.trim()) {
				clearPasteAttachments();
			} else {
				prunePastedTextSnippets(text);
			}
			autocomplete.updateAutocomplete(text);
			if (inputHistory.shouldResetHistoryIndex(text)) {
				inputHistory.resetHistoryIndex();
			}
		},
		[
			autocomplete,
			clearPasteAttachments,
			inputHistory,
			prunePastedTextSnippets,
		],
	);

	const syncInputFromTextarea = useCallback(() => {
		queueMicrotask(() => {
			const text = textareaRef.current?.plainText ?? "";
			if (text === inputValueRef.current) return;
			setInputValue(text);
			if (!text.trim()) {
				clearPasteAttachments();
			} else {
				prunePastedTextSnippets(text);
			}
			autocomplete.updateAutocomplete(text);
			if (inputHistory.shouldResetHistoryIndex(text)) {
				inputHistory.resetHistoryIndex();
			}
		});
	}, [
		autocomplete,
		clearPasteAttachments,
		inputHistory,
		prunePastedTextSnippets,
	]);

	const getCurrentInputText = useCallback(() => {
		return textareaRef.current?.plainText ?? inputValueRef.current;
	}, []);

	return {
		inputKey,
		inputValue,
		inputValueRef,
		textareaRef,
		inputHistory,
		selectRef,
		submitRef,
		setInputKey,
		setInputValue,
		populateInput,
		insertSkillCommand,
		removeLocalCommandInvocation,
		focusTextarea,
		refocusTextarea,
		submitInitialPrompt,
		selectAutocompleteOption,
		handleImagePaste,
		handleLargeTextPaste,
		handleSubmit,
		handleContentChange,
		syncInputFromTextarea,
		getCurrentInputText,
	};
}

import { describe, expect, it } from "vitest";
import type { PendingPromptSnapshot } from "../../runtime/session-events";
import {
	resolveQueuedPromptSelection,
	toQueuedPromptItems,
} from "./use-queued-prompts";

describe("queued prompt helpers", () => {
	it("maps pending prompt snapshots to TUI queue items", () => {
		const event: PendingPromptSnapshot = {
			sessionId: "sess-1",
			prompts: [
				{
					id: "pending-1",
					prompt: "keep going",
					delivery: "queue",
					attachmentCount: 2,
				},
				{
					id: "pending-2",
					prompt: "change direction",
					delivery: "steer",
					attachmentCount: 0,
				},
			],
		};

		expect(toQueuedPromptItems(event)).toEqual([
			{
				id: "pending-1",
				prompt: "keep going",
				steer: false,
				attachmentCount: 2,
			},
			{
				id: "pending-2",
				prompt: "change direction",
				steer: true,
				attachmentCount: 0,
			},
		]);
	});

	it("moves up from the input into the closest queued prompt", () => {
		const items = [
			{ id: "first", prompt: "first", steer: false, attachmentCount: 0 },
			{ id: "second", prompt: "second", steer: false, attachmentCount: 0 },
		];

		expect(
			resolveQueuedPromptSelection({
				items,
				selectedId: null,
				direction: "up",
			}),
		).toBe("second");
	});

	it("moves down through the queue and then back to the input", () => {
		const items = [
			{ id: "first", prompt: "first", steer: false, attachmentCount: 0 },
			{ id: "second", prompt: "second", steer: false, attachmentCount: 0 },
		];

		expect(
			resolveQueuedPromptSelection({
				items,
				selectedId: "first",
				direction: "down",
			}),
		).toBe("second");
		expect(
			resolveQueuedPromptSelection({
				items,
				selectedId: "second",
				direction: "down",
			}),
		).toBeNull();
	});
});

import { useCallback, useState } from "react";
import type { PendingPromptSnapshot } from "../../runtime/session-events";
import type { QueuedPromptItem } from "../types";

export function toQueuedPromptItems(
	event: PendingPromptSnapshot,
): QueuedPromptItem[] {
	return event.prompts.map((entry, index) => ({
		id: entry.id || `${entry.delivery}:${index}:${entry.prompt}`,
		prompt: entry.prompt,
		steer: entry.delivery === "steer",
		attachmentCount: entry.attachmentCount,
	}));
}

export function resolveQueuedPromptSelection(input: {
	items: QueuedPromptItem[];
	selectedId: string | null;
	direction: "up" | "down";
}): string | null {
	if (input.items.length === 0) {
		return null;
	}

	const currentIndex = input.selectedId
		? input.items.findIndex((item) => item.id === input.selectedId)
		: -1;

	if (input.direction === "up") {
		if (currentIndex < 0) {
			return input.items[input.items.length - 1]?.id ?? null;
		}
		return input.items[Math.max(0, currentIndex - 1)]?.id ?? null;
	}

	if (currentIndex < 0) {
		return null;
	}
	const nextIndex = currentIndex + 1;
	return nextIndex >= input.items.length
		? null
		: (input.items[nextIndex]?.id ?? null);
}

export function useQueuedPrompts() {
	const [queuedPrompts, setQueuedPrompts] = useState<QueuedPromptItem[]>([]);

	const handlePendingPrompts = useCallback((event: PendingPromptSnapshot) => {
		setQueuedPrompts(toQueuedPromptItems(event));
	}, []);

	return { queuedPrompts, handlePendingPrompts };
}

import { describe, expect, it } from "vitest";
import { shouldHandleInputHistory } from "./root-keyboard-routing";

describe("root keyboard input history routing", () => {
	it("handles history while idle", () => {
		expect(
			shouldHandleInputHistory({
				isRunning: false,
				hasQueuedPrompts: false,
			}),
		).toBe(true);
	});

	it("handles history during a running turn when the prompt queue is empty", () => {
		expect(
			shouldHandleInputHistory({
				isRunning: true,
				hasQueuedPrompts: false,
			}),
		).toBe(true);
	});

	it("keeps running-turn arrow keys reserved for queued prompts when the queue is populated", () => {
		expect(
			shouldHandleInputHistory({
				isRunning: true,
				hasQueuedPrompts: true,
			}),
		).toBe(false);
	});
});

import type { KeyEvent } from "@opentui/core";
import { useKeyboard } from "@opentui/react";
import type { Dispatch, SetStateAction } from "react";
import { useRef } from "react";
import type { TranscriptScrollHandle } from "../components/chat-message-list";
import { useSession } from "../contexts/session-context";
import type { AppView, QueuedPromptItem } from "../types";
import { shouldHandleInputHistory } from "./root-keyboard-routing";
import { matchTranscriptKeybind } from "./transcript-keybinds";
import type { AutocompleteOption, useAutocomplete } from "./use-autocomplete";
import type { useInputHistory } from "./use-input-history";
import { resolveQueuedPromptSelection } from "./use-queued-prompts";

type TranscriptKey = {
	name: string;
	ctrl: boolean;
	meta: boolean;
	shift: boolean;
	preventDefault: () => void;
};

export function handleTranscriptKeybind(
	key: TranscriptKey,
	transcriptScroll: TranscriptScrollHandle | null | undefined,
): boolean {
	const command = matchTranscriptKeybind(key);
	if (!command || !transcriptScroll) return false;

	key.preventDefault();
	transcriptScroll.runTranscriptCommand(command);
	return true;
}

export function useRootKeyboard(input: {
	isDialogOpen: boolean;
	appView: AppView;
	autocomplete: ReturnType<typeof useAutocomplete>;
	inputHistory: ReturnType<typeof useInputHistory>;
	transcriptScrollRef: { current: TranscriptScrollHandle | null };
	inputValueRef: { current: string };
	selectRef: { current: (option: AutocompleteOption) => void };
	submitRef: { current: (delivery?: "queue" | "steer") => void };
	queuedPromptSelection: {
		items: QueuedPromptItem[];
		selectedId: string | null;
		editingId: string | null;
		select: (id: string | null) => void;
		beginEdit: (id: string) => void;
		cancelEdit: () => void;
		promote: (id: string) => void;
	};
	syncInputFromTextarea: () => void;
	getCurrentInputText: () => string;
	setInputKey: Dispatch<SetStateAction<number>>;
	setInputValue: Dispatch<SetStateAction<string>>;
	onAbort: () => boolean;
	onExit: () => void;
	onToggleMode: () => void;
	onClearConversation: () => Promise<void>;
	onRestoreCheckpoint: () => Promise<void>;
	onOpenCommandPalette: () => Promise<void>;
	onCommandPaletteShortcut: (key: KeyEvent) => boolean;
}) {
	const session = useSession();
	const lastEscapeRef = useRef(0);

	useKeyboard((key) => {
		if (session.isExitRequested) return;

		const hasInputText = input.getCurrentInputText().trim().length > 0;

		const mayEditTextarea =
			!key.ctrl &&
			!key.meta &&
			(key.name.length === 1 ||
				key.name === "backspace" ||
				key.name === "delete" ||
				key.name === "space");
		if (
			!input.isDialogOpen &&
			input.appView !== "onboarding" &&
			mayEditTextarea
		) {
			input.syncInputFromTextarea();
		}

		if (key.ctrl && key.name === "c") {
			if (!input.isDialogOpen && hasInputText) {
				input.setInputKey((k) => k + 1);
				input.setInputValue("");
			} else {
				input.onExit();
			}
			return;
		}

		if (input.isDialogOpen) return;
		if (input.appView === "onboarding") return;

		if (handleTranscriptKeybind(key, input.transcriptScrollRef.current)) {
			if (input.autocomplete.mode) {
				input.autocomplete.close();
			}
			return;
		}

		if (input.autocomplete.mode) {
			const opts = input.autocomplete.getFilteredOptions();
			if (key.name === "escape") {
				input.autocomplete.close();
				return;
			}
			if (key.name === "up" || (key.ctrl && key.name === "p")) {
				let next =
					input.autocomplete.selected <= 0
						? opts.length - 1
						: input.autocomplete.selected - 1;
				if (opts[next]?.isHeader) next = next <= 0 ? opts.length - 1 : next - 1;
				input.autocomplete.setSelected(next);
				return;
			}
			if (key.name === "down" || (key.ctrl && key.name === "n")) {
				let next =
					input.autocomplete.selected >= opts.length - 1
						? 0
						: input.autocomplete.selected + 1;
				if (opts[next]?.isHeader) next = next >= opts.length - 1 ? 0 : next + 1;
				input.autocomplete.setSelected(next);
				return;
			}
			if (key.name === "tab" && opts.length > 0) {
				const selectedOption =
					opts[Math.min(input.autocomplete.selected, opts.length - 1)] ??
					opts[0];
				if (!selectedOption?.isHeader) {
					input.selectRef.current(selectedOption);
				}
				return;
			}
			return;
		}

		if (!session.isRunning && input.onCommandPaletteShortcut(key)) {
			return;
		}

		if (key.ctrl && key.name === "p" && !session.isRunning) {
			void input.onOpenCommandPalette();
			return;
		}

		const queuedSelection = input.queuedPromptSelection;
		const hasQueuedPrompts = queuedSelection.items.length > 0;
		const selectedQueuedPromptId = queuedSelection.selectedId;
		const canHandleInputHistory = shouldHandleInputHistory({
			isRunning: session.isRunning,
			hasQueuedPrompts,
		});

		if (queuedSelection.editingId && key.name !== "escape") {
			return;
		}

		if (hasQueuedPrompts && key.name === "up") {
			key.preventDefault();
			if (input.autocomplete.mode) {
				input.autocomplete.close();
			}
			queuedSelection.select(
				resolveQueuedPromptSelection({
					items: queuedSelection.items,
					selectedId: selectedQueuedPromptId,
					direction: "up",
				}),
			);
			return;
		}

		if (hasQueuedPrompts && selectedQueuedPromptId && key.name === "down") {
			key.preventDefault();
			queuedSelection.select(
				resolveQueuedPromptSelection({
					items: queuedSelection.items,
					selectedId: selectedQueuedPromptId,
					direction: "down",
				}),
			);
			return;
		}

		if (
			selectedQueuedPromptId &&
			!queuedSelection.editingId &&
			key.name === "tab" &&
			!key.shift
		) {
			key.preventDefault();
			queuedSelection.beginEdit(selectedQueuedPromptId);
			return;
		}

		if (
			selectedQueuedPromptId &&
			!queuedSelection.editingId &&
			(key.name === "enter" || key.name === "return")
		) {
			key.preventDefault();
			queuedSelection.promote(selectedQueuedPromptId);
			return;
		}

		if (key.name === "up" && canHandleInputHistory) {
			if (
				input.inputHistory.navigateHistory("up", input.inputValueRef.current)
			) {
				key.preventDefault();
			}
			return;
		}
		if (key.name === "down" && canHandleInputHistory) {
			if (
				input.inputHistory.navigateHistory("down", input.inputValueRef.current)
			) {
				key.preventDefault();
			}
			return;
		}

		if (key.name === "escape") {
			if (queuedSelection.editingId) {
				key.preventDefault();
				queuedSelection.cancelEdit();
			} else if (session.isRunning) {
				const abortStarted = input.onAbort();
				if (abortStarted) {
					session.setAbortRequested(true);
					session.setIsStreaming(false);
					session.closeInlineStream();
				}
			} else if (selectedQueuedPromptId) {
				queuedSelection.select(null);
				input.setInputKey((k) => k + 1);
			} else {
				const now = Date.now();
				if (now - lastEscapeRef.current < 300) {
					lastEscapeRef.current = 0;
					void input.onRestoreCheckpoint();
				} else {
					lastEscapeRef.current = now;
				}
			}
			return;
		}

		if (key.ctrl && key.name === "d") {
			if (!session.isRunning && !hasInputText) {
				input.onExit();
			}
			return;
		}

		if (key.name === "tab" && !key.shift) {
			input.onToggleMode();
			return;
		}

		if (key.shift && key.name === "tab") {
			session.toggleAutoApprove();
			return;
		}

		if (key.ctrl && key.name === "l") {
			if (session.isRunning) {
				session.clearEntries();
				return;
			}
			void input.onClearConversation();
			return;
		}

		if (key.ctrl && key.name === "s") {
			if (session.isRunning && input.inputValueRef.current.trim()) {
				input.submitRef.current("steer");
			}
			return;
		}
	});
}

import type { AgentMode } from "@cline/core";
import type { ToolApprovalRequest, ToolApprovalResult } from "@cline/shared";
import { useCallback, useEffect, useRef, useState } from "react";
import type { RuntimeToolInteraction, TuiProps } from "../types";

type PendingRuntimeToolInteraction =
	| {
			id: number;
			kind: "tool_approval";
			request: ToolApprovalRequest;
			resolve: (result: ToolApprovalResult) => void;
	  }
	| {
			id: number;
			kind: "ask_question";
			question: string;
			options: string[];
			resolve: (answer: string) => void;
	  };

function toRuntimeToolInteraction(
	pending: PendingRuntimeToolInteraction,
): RuntimeToolInteraction {
	if (pending.kind === "tool_approval") {
		return {
			id: pending.id,
			kind: pending.kind,
			request: pending.request,
		};
	}
	return {
		id: pending.id,
		kind: pending.kind,
		question: pending.question,
		options: pending.options,
	};
}

function deniedToolResult(request: ToolApprovalRequest): ToolApprovalResult {
	return {
		approved: false,
		reason: `Tool "${request.toolName}" was denied by user`,
	};
}

function dismissPendingInteraction(pending: PendingRuntimeToolInteraction) {
	if (pending.kind === "tool_approval") {
		pending.resolve(deniedToolResult(pending.request));
		return;
	}
	pending.resolve("[User dismissed the question]");
}

export function useRuntimeDialogBridge(input: {
	setToolApprover: TuiProps["setToolApprover"];
	setAskQuestion: TuiProps["setAskQuestion"];
	setModeChangeNotifier: TuiProps["setModeChangeNotifier"];
	setUiMode: (mode: AgentMode) => void;
	refocusTextarea: () => void;
}) {
	const {
		setToolApprover,
		setAskQuestion,
		setModeChangeNotifier,
		setUiMode,
		refocusTextarea,
	} = input;
	const [interaction, setInteraction] = useState<RuntimeToolInteraction | null>(
		null,
	);
	const activeRef = useRef<PendingRuntimeToolInteraction | null>(null);
	const queueRef = useRef<PendingRuntimeToolInteraction[]>([]);
	const nextIdRef = useRef(1);

	const activate = useCallback((pending: PendingRuntimeToolInteraction) => {
		activeRef.current = pending;
		setInteraction(toRuntimeToolInteraction(pending));
	}, []);

	const enqueue = useCallback(
		(pending: PendingRuntimeToolInteraction) => {
			if (activeRef.current) {
				queueRef.current.push(pending);
				return;
			}
			activate(pending);
		},
		[activate],
	);

	const finishActive = useCallback(
		(id: number) => {
			if (activeRef.current?.id !== id) {
				return false;
			}
			const next = queueRef.current.shift() ?? null;
			if (next) {
				activate(next);
				return true;
			}
			activeRef.current = null;
			setInteraction(null);
			return false;
		},
		[activate],
	);

	const resolveToolApproval = useCallback(
		(id: number, approved: boolean) => {
			const pending = activeRef.current;
			if (!pending || pending.id !== id || pending.kind !== "tool_approval") {
				return;
			}
			pending.resolve(
				approved ? { approved: true } : deniedToolResult(pending.request),
			);
			const hasNext = finishActive(id);
			if (!hasNext) {
				refocusTextarea();
			}
		},
		[finishActive, refocusTextarea],
	);

	const resolveAskQuestion = useCallback(
		(id: number, answer: string | null) => {
			const pending = activeRef.current;
			if (!pending || pending.id !== id || pending.kind !== "ask_question") {
				return;
			}
			pending.resolve(
				answer === null ? "[User dismissed the question]" : answer,
			);
			const hasNext = finishActive(id);
			if (!hasNext) {
				refocusTextarea();
			}
		},
		[finishActive, refocusTextarea],
	);

	const dismissAll = useCallback(() => {
		if (activeRef.current) {
			dismissPendingInteraction(activeRef.current);
			activeRef.current = null;
		}
		for (const pending of queueRef.current) {
			dismissPendingInteraction(pending);
		}
		queueRef.current = [];
		setInteraction(null);
	}, []);

	useEffect(() => {
		setToolApprover(
			(request) =>
				new Promise<ToolApprovalResult>((resolve) => {
					enqueue({
						id: nextIdRef.current,
						kind: "tool_approval",
						request,
						resolve,
					});
					nextIdRef.current += 1;
				}),
		);
		setAskQuestion(
			(question, options) =>
				new Promise<string>((resolve) => {
					enqueue({
						id: nextIdRef.current,
						kind: "ask_question",
						question,
						options,
						resolve,
					});
					nextIdRef.current += 1;
				}),
		);
		setModeChangeNotifier((mode) => {
			setUiMode(mode);
		});
		return () => {
			setToolApprover(null);
			setAskQuestion(null);
			setModeChangeNotifier(null);
			dismissAll();
		};
	}, [
		dismissAll,
		enqueue,
		setAskQuestion,
		setModeChangeNotifier,
		setToolApprover,
		setUiMode,
	]);

	return {
		interaction,
		resolveToolApproval,
		resolveAskQuestion,
	};
}

import { useEffect, useMemo, useState } from "react";
import {
	buildSlashCommandRegistry,
	getInvokableUserSlashCommands,
	getVisibleSystemSlashCommands,
	getVisibleUserSlashCommands,
} from "../commands/slash-command-registry";
import type { TuiProps } from "../types";

export function useSlashCommands(input: {
	workflowSlashCommands: TuiProps["workflowSlashCommands"];
	loadAdditionalSlashCommands: TuiProps["loadAdditionalSlashCommands"];
	canFork: boolean;
}) {
	const { workflowSlashCommands, loadAdditionalSlashCommands, canFork } = input;
	const [additionalSlashCommands, setAdditionalSlashCommands] = useState<
		TuiProps["workflowSlashCommands"] | undefined
	>(loadAdditionalSlashCommands ? [] : undefined);

	useEffect(() => {
		if (!loadAdditionalSlashCommands) {
			setAdditionalSlashCommands(undefined);
			return;
		}
		let cancelled = false;
		void loadAdditionalSlashCommands()
			.then((commands) => {
				if (!cancelled) {
					setAdditionalSlashCommands(commands);
				}
			})
			.catch(() => {
				if (!cancelled) {
					setAdditionalSlashCommands([]);
				}
			});
		return () => {
			cancelled = true;
		};
	}, [loadAdditionalSlashCommands]);

	const registry = useMemo(() => {
		return buildSlashCommandRegistry({
			workflowSlashCommands,
			additionalSlashCommands,
			canFork,
		});
	}, [workflowSlashCommands, additionalSlashCommands, canFork]);

	const systemCommands = useMemo(
		() => getVisibleSystemSlashCommands(registry),
		[registry],
	);
	const skillCommands = useMemo(
		() => getVisibleUserSlashCommands(registry),
		[registry],
	);
	const invokableSkillCommands = useMemo(
		() => getInvokableUserSlashCommands(registry),
		[registry],
	);

	return { registry, systemCommands, skillCommands, invokableSkillCommands };
}

import { createContext, useContext } from "react";
