import { spawn } from "node:child_process";
import { release } from "node:os";

const CLIPBOARD_COMMAND_TIMEOUT_MS = 1500;

// Skipping the fallback inside SSH sessions is the safe default: OSC52 is the
// mechanism that targets the user's local terminal clipboard, while the
// fallback would write to the remote host instead. Setting
// CLINE_CLIPBOARD_FALLBACK_REMOTE=1 opts back in for users who explicitly
// want the remote machine's clipboard.
const CLIPBOARD_FALLBACK_REMOTE_ENV = "CLINE_CLIPBOARD_FALLBACK_REMOTE";

// Setting CLINE_DEBUG_CLIPBOARD=1 logs why the fallback skipped or which
// command failed; off by default so the TUI canvas stays clean.
const CLIPBOARD_DEBUG_ENV = "CLINE_DEBUG_CLIPBOARD";

function debugLog(env: NodeJS.ProcessEnv, message: string): void {
	if (env[CLIPBOARD_DEBUG_ENV]?.trim() === "1") {
		console.debug(`[clipboard] ${message}`);
	}
}

interface ClipboardCommand {
	command: string;
	args: string[];
	env?: NodeJS.ProcessEnv;
	stdinEncoding?: BufferEncoding;
}

interface CopyTextOptions {
	platform?: NodeJS.Platform;
	osRelease?: string;
	timeoutMs?: number;
	env?: NodeJS.ProcessEnv;
	signal?: AbortSignal;
}

function isWslRelease(osRelease: string): boolean {
	return /microsoft/i.test(osRelease);
}

function isRemoteSession(env: NodeJS.ProcessEnv): boolean {
	const remote =
		env.SSH_CONNECTION?.trim() || env.SSH_CLIENT?.trim() || env.SSH_TTY?.trim();
	if (!remote) {
		return false;
	}
	return env[CLIPBOARD_FALLBACK_REMOTE_ENV]?.trim() !== "1";
}

function macosClipboardEnv(env: NodeJS.ProcessEnv): NodeJS.ProcessEnv {
	const next: NodeJS.ProcessEnv = {
		...env,
		LANG: "en_US.UTF-8",
		LC_CTYPE: "en_US.UTF-8",
	};
	delete next.LC_ALL;
	return next;
}

const POWERSHELL_SET_CLIPBOARD_SCRIPT = [
	"$ErrorActionPreference = 'Stop';",
	"[Console]::InputEncoding = New-Object System.Text.UTF8Encoding $false;",
	"$text = [Console]::In.ReadToEnd();",
	"Set-Clipboard -Value $text;",
].join(" ");

function powershellClipboardCommand(executable: string): ClipboardCommand {
	return {
		command: executable,
		args: [
			"-NoProfile",
			"-NonInteractive",
			"-ExecutionPolicy",
			"Bypass",
			"-Command",
			POWERSHELL_SET_CLIPBOARD_SCRIPT,
		],
		stdinEncoding: "utf8",
	};
}

function powershellClipboardCommands(): ClipboardCommand[] {
	return [
		powershellClipboardCommand("powershell.exe"),
		powershellClipboardCommand("pwsh.exe"),
	];
}

function getClipboardCommands(
	options: CopyTextOptions = {},
): ClipboardCommand[] {
	const platform = options.platform ?? process.platform;
	const osRelease = options.osRelease ?? release();
	const env = options.env ?? process.env;

	if (platform === "darwin") {
		return [
			{
				command: "pbcopy",
				args: [],
				env: macosClipboardEnv(env),
				stdinEncoding: "utf8",
			},
		];
	}

	if (platform === "win32") {
		return powershellClipboardCommands();
	}

	if (platform === "linux" && isWslRelease(osRelease)) {
		return powershellClipboardCommands();
	}

	if (platform === "linux") {
		return [
			{ command: "wl-copy", args: [], stdinEncoding: "utf8" },
			{
				command: "xclip",
				args: ["-selection", "clipboard"],
				stdinEncoding: "utf8",
			},
		];
	}

	return [];
}

function runClipboardCommand(
	command: ClipboardCommand,
	text: string,
	timeoutMs: number,
	signal: AbortSignal | undefined,
): Promise<boolean> {
	return new Promise((resolve) => {
		if (signal?.aborted) {
			resolve(false);
			return;
		}

		const child = spawn(command.command, command.args, {
			stdio: ["pipe", "ignore", "ignore"],
			...(command.env ? { env: command.env } : {}),
			// Prevent a console window from flashing on Windows.
			windowsHide: true,
		});
		let settled = false;

		const onAbort = () => {
			child.kill();
			finish(false);
		};

		const finish = (success: boolean) => {
			if (settled) return;
			settled = true;
			clearTimeout(timer);
			signal?.removeEventListener("abort", onAbort);
			resolve(success);
		};

		const timer = setTimeout(() => {
			child.kill();
			finish(false);
		}, timeoutMs);

		signal?.addEventListener("abort", onAbort, { once: true });

		child.on("error", () => finish(false));
		child.on("close", (code) => finish(code === 0));

		const stdin = child.stdin;
		if (!stdin) {
			finish(false);
			return;
		}
		stdin.on("error", () => finish(false));
		stdin.end(text, command.stdinEncoding ?? "utf8");
	});
}

export async function copyTextToSystemClipboard(
	text: string,
	options: CopyTextOptions = {},
): Promise<boolean> {
	if (!text) {
		return false;
	}

	const env = options.env ?? process.env;
	if (isRemoteSession(env)) {
		debugLog(
			env,
			`skipped fallback inside SSH session; set ${CLIPBOARD_FALLBACK_REMOTE_ENV}=1 to opt in`,
		);
		return false;
	}

	const timeoutMs = options.timeoutMs ?? CLIPBOARD_COMMAND_TIMEOUT_MS;
	for (const command of getClipboardCommands(options)) {
		if (options.signal?.aborted) {
			return false;
		}
		if (await runClipboardCommand(command, text, timeoutMs, options.signal)) {
			return true;
		}
		debugLog(env, `command "${command.command}" did not succeed; trying next`);
	}

	return false;
}

import { describe, expect, it } from "vitest";
import {
	formatCompactionDividerLabel,
	formatTokenCount,
	parseCompactionNoticeMetadata,
} from "./compaction-status";

describe("parseCompactionNoticeMetadata", () => {
	it("extracts a divider entry from a completed auto-compaction notice", () => {
		expect(
			parseCompactionNoticeMetadata({
				kind: "auto_compaction",
				reason: "auto_compaction",
				phase: "completed",
				tokensBefore: 25_101,
				tokensAfter: 6_300,
				messagesBefore: 142,
				messagesAfter: 9,
			}),
		).toEqual({
			compactionMode: "auto",
			status: "completed",
			tokensBefore: 25_101,
			tokensAfter: 6_300,
			messagesBefore: 142,
			messagesAfter: 9,
		});
	});

	it("extracts a streaming divider entry from a started notice", () => {
		expect(
			parseCompactionNoticeMetadata({
				kind: "auto_compaction",
				phase: "started",
			}),
		).toEqual({ compactionMode: "auto", status: "started" });
	});

	it("maps manual compaction notices to manual mode", () => {
		expect(
			parseCompactionNoticeMetadata({
				kind: "manual_compaction",
				phase: "completed",
			})?.compactionMode,
		).toBe("manual");
	});

	it("maps a benign no-result terminal notice to skipped", () => {
		expect(
			parseCompactionNoticeMetadata({
				kind: "auto_compaction",
				phase: "skipped",
			}),
		).toEqual({ compactionMode: "auto", status: "skipped" });
	});

	it("ignores non-compaction metadata", () => {
		expect(
			parseCompactionNoticeMetadata({ kind: "recovery", phase: "completed" }),
		).toBeUndefined();
		expect(
			parseCompactionNoticeMetadata({ kind: "auto_compaction" }),
		).toBeUndefined();
		expect(parseCompactionNoticeMetadata(undefined)).toBeUndefined();
	});

	it("drops non-numeric counters instead of rendering garbage", () => {
		const parsed = parseCompactionNoticeMetadata({
			kind: "auto_compaction",
			phase: "completed",
			tokensBefore: "25000",
			tokensAfter: Number.NaN,
		});
		expect(parsed?.tokensBefore).toBeUndefined();
		expect(parsed?.tokensAfter).toBeUndefined();
	});
});

describe("formatTokenCount", () => {
	it("formats counts into compact units", () => {
		expect(formatTokenCount(999)).toBe("999");
		expect(formatTokenCount(6_300)).toBe("6.3k");
		expect(formatTokenCount(25_000)).toBe("25k");
		expect(formatTokenCount(1_200_000)).toBe("1.2M");
	});
});

describe("formatCompactionDividerLabel", () => {
	it("includes token and message deltas when present", () => {
		expect(
			formatCompactionDividerLabel({
				kind: "compaction",
				compactionMode: "auto",
				status: "completed",
				tokensBefore: 25_101,
				tokensAfter: 6_300,
				messagesBefore: 142,
				messagesAfter: 9,
			}),
		).toBe("Context compacted · 25.1k → 6.3k tokens · 142 → 9 messages");
	});

	it("labels in-progress compaction", () => {
		expect(
			formatCompactionDividerLabel({
				kind: "compaction",
				compactionMode: "auto",
				status: "started",
			}),
		).toBe("Auto compacting messages");
		expect(
			formatCompactionDividerLabel({
				kind: "compaction",
				compactionMode: "manual",
				status: "started",
			}),
		).toBe("Compacting messages");
	});

	it("labels failed and cancelled compaction", () => {
		expect(
			formatCompactionDividerLabel({
				kind: "compaction",
				compactionMode: "auto",
				status: "failed",
			}),
		).toBe("Compaction failed");
		expect(
			formatCompactionDividerLabel({
				kind: "compaction",
				compactionMode: "auto",
				status: "cancelled",
			}),
		).toBe("Compaction cancelled");
	});

	it("labels skipped compaction without calling it cancelled", () => {
		expect(
			formatCompactionDividerLabel({
				kind: "compaction",
				compactionMode: "auto",
				status: "skipped",
			}),
		).toBe("Compaction skipped");
	});

	it("labels inherited working context from forks and restarts", () => {
		expect(
			formatCompactionDividerLabel({
				kind: "compaction",
				compactionMode: "inherited",
				status: "completed",
				messagesBefore: 60,
				messagesAfter: 15,
			}),
		).toBe("Compacted working context carried over · 60 → 15 messages");
	});

	it("labels manual compaction and omits missing counters", () => {
		expect(
			formatCompactionDividerLabel({
				kind: "compaction",
				compactionMode: "manual",
				status: "completed",
			}),
		).toBe("Context compacted (manual)");
	});
});

import type { ChatEntry, InteractiveCompactionResult } from "../types";

export type CompactionDividerEntry = Extract<ChatEntry, { kind: "compaction" }>;

function formatMessageCount(count: number): string {
	return `${count} ${count === 1 ? "message" : "messages"}`;
}

function asFiniteNumber(value: unknown): number | undefined {
	return typeof value === "number" && Number.isFinite(value)
		? value
		: undefined;
}

/**
 * Extracts a compaction divider entry from a status notice's metadata.
 * "started" notices produce a streaming (in-progress) divider; "completed"
 * notices produce the final divider with counters. Returns undefined for
 * non-compaction notices.
 */
export function parseCompactionNoticeMetadata(
	metadata: Record<string, unknown> | undefined,
): Omit<CompactionDividerEntry, "kind"> | undefined {
	if (
		!metadata ||
		(metadata.phase !== "started" &&
			metadata.phase !== "completed" &&
			metadata.phase !== "skipped")
	) {
		return undefined;
	}
	const kind = metadata.kind ?? metadata.reason;
	if (kind !== "auto_compaction" && kind !== "manual_compaction") {
		return undefined;
	}
	const compactionMode = kind === "manual_compaction" ? "manual" : "auto";
	if (metadata.phase === "started") {
		return { compactionMode, status: "started" };
	}
	if (metadata.phase === "skipped") {
		return { compactionMode, status: "skipped" };
	}
	return {
		compactionMode,
		status: "completed",
		tokensBefore: asFiniteNumber(metadata.tokensBefore),
		tokensAfter: asFiniteNumber(metadata.tokensAfter),
		messagesBefore: asFiniteNumber(metadata.messagesBefore),
		messagesAfter: asFiniteNumber(metadata.messagesAfter),
	};
}

export function formatTokenCount(count: number): string {
	if (count < 1_000) {
		return `${count}`;
	}
	if (count < 1_000_000) {
		return `${(count / 1_000).toFixed(1).replace(/\.0$/, "")}k`;
	}
	return `${(count / 1_000_000).toFixed(1).replace(/\.0$/, "")}M`;
}

export function formatCompactionDividerLabel(
	entry: CompactionDividerEntry,
): string {
	if (entry.status === "started") {
		return entry.compactionMode === "manual"
			? "Compacting messages"
			: "Auto compacting messages";
	}
	if (entry.status === "failed") {
		return "Compaction failed";
	}
	if (entry.status === "cancelled") {
		return "Compaction cancelled";
	}
	if (entry.status === "skipped") {
		return "Compaction skipped";
	}
	const parts: string[] = [
		entry.compactionMode === "manual"
			? "Context compacted (manual)"
			: entry.compactionMode === "inherited"
				? "Compacted working context carried over"
				: "Context compacted",
	];
	if (
		typeof entry.tokensBefore === "number" &&
		typeof entry.tokensAfter === "number"
	) {
		parts.push(
			`${formatTokenCount(entry.tokensBefore)} → ${formatTokenCount(entry.tokensAfter)} tokens`,
		);
	}
	if (
		typeof entry.messagesBefore === "number" &&
		typeof entry.messagesAfter === "number"
	) {
		parts.push(`${entry.messagesBefore} → ${entry.messagesAfter} messages`);
	}
	return parts.join(" · ");
}

export function formatCompactionStatus(
	result: InteractiveCompactionResult,
): string {
	if (result.messagesBefore === 0) {
		return "No messages to compact.";
	}
	if (!result.compacted) {
		return "No compaction needed.";
	}
	if (typeof result.workingContextMessagesAfter === "number") {
		return `Compacted working context to ${formatMessageCount(result.workingContextMessagesAfter)}; saved history remains ${formatMessageCount(result.messagesAfter)}.`;
	}
	if (result.messagesBefore === result.messagesAfter) {
		return `Compacted context; message count stayed at ${formatMessageCount(result.messagesAfter)}.`;
	}
	return `Compacted ${formatMessageCount(result.messagesBefore)} to ${formatMessageCount(result.messagesAfter)}.`;
}

function computeLcs(a: string[], b: string[]): number[][] {
	const m = a.length;
	const n = b.length;
	const dp: number[][] = Array.from({ length: m + 1 }, () =>
		new Array(n + 1).fill(0),
	);
	for (let i = 1; i <= m; i++) {
		for (let j = 1; j <= n; j++) {
			dp[i][j] =
				a[i - 1] === b[j - 1]
					? dp[i - 1][j - 1] + 1
					: Math.max(dp[i - 1][j], dp[i][j - 1]);
		}
	}
	return dp;
}

function diffLines(
	oldLines: string[],
	newLines: string[],
): { type: "+" | "-" | " "; line: string }[] {
	const dp = computeLcs(oldLines, newLines);
	const result: { type: "+" | "-" | " "; line: string }[] = [];
	let i = oldLines.length;
	let j = newLines.length;
	while (i > 0 || j > 0) {
		if (i > 0 && j > 0 && oldLines[i - 1] === newLines[j - 1]) {
			result.unshift({ type: " ", line: oldLines[i - 1] });
			i--;
			j--;
		} else if (j > 0 && (i === 0 || dp[i][j - 1] >= dp[i - 1][j])) {
			result.unshift({ type: "+", line: newLines[j - 1] });
			j--;
		} else {
			result.unshift({ type: "-", line: oldLines[i - 1] });
			i--;
		}
	}
	return result;
}

export function makeUnifiedDiff(
	oldText: string,
	newText: string,
	filePath: string,
	ctx = 3,
): string {
	const oldArr = oldText ? oldText.split("\n") : [];
	const newArr = newText.split("\n");
	const ops = diffLines(oldArr, newArr);

	const output: string[] = [];
	output.push(`--- a/${filePath}`);
	output.push(`+++ b/${filePath}`);

	let i = 0;
	while (i < ops.length) {
		if (ops[i].type === " ") {
			i++;
			continue;
		}

		const hunkStart = Math.max(0, i - ctx);
		let end = i;
		while (end < ops.length) {
			if (ops[end].type !== " ") {
				end++;
				continue;
			}
			let next = end;
			while (next < ops.length && ops[next].type === " ") next++;
			if (next < ops.length && next - end <= ctx * 2) {
				end = next + 1;
			} else {
				break;
			}
		}
		const hunkEnd = Math.min(ops.length, end + ctx);

		let oldCount = 0;
		let newCount = 0;
		for (let k = hunkStart; k < hunkEnd; k++) {
			if (ops[k].type !== "+") oldCount++;
			if (ops[k].type !== "-") newCount++;
		}

		let oldStart = 1;
		let newStart = 1;
		for (let k = 0; k < hunkStart; k++) {
			if (ops[k].type !== "+") oldStart++;
			if (ops[k].type !== "-") newStart++;
		}

		output.push(`@@ -${oldStart},${oldCount} +${newStart},${newCount} @@`);
		for (let k = hunkStart; k < hunkEnd; k++) {
			const prefix = ops[k].type === " " ? " " : ops[k].type;
			output.push(`${prefix}${ops[k].line}`);
		}

		i = hunkEnd;
	}

	return output.join("\n");
}

export function hunkHeader(lines: string[]): string {
	let oldCount = 0;
	let newCount = 0;
	for (const l of lines) {
		if (!l.startsWith("+")) oldCount++;
		if (!l.startsWith("-")) newCount++;
	}
	return `@@ -1,${oldCount} +1,${newCount} @@`;
}

import type { Message } from "@cline/shared";
import { describe, expect, it } from "vitest";
import { ACT_MODE_CONTINUATION_PROMPT } from "../../runtime/interactive/mode";
import { hydrateSessionMessages } from "./hydrate-messages";

describe("hydrateSessionMessages", () => {
	it("renders regular user messages", () => {
		const messages = [
			{
				role: "user",
				content: '<user_input mode="plan">lets do it</user_input>',
			},
		] as Message[];

		expect(hydrateSessionMessages(messages)).toEqual([
			{ kind: "user_submitted", text: "lets do it", mode: "plan" },
		]);
	});

	it("hides the synthetic act-mode continuation prompt", () => {
		const messages = [
			{
				role: "user",
				content: `<user_input mode="act">${ACT_MODE_CONTINUATION_PROMPT}</user_input>`,
			},
			{
				role: "user",
				content: [
					{
						type: "text",
						text: `<user_input mode="act">${ACT_MODE_CONTINUATION_PROMPT}</user_input>`,
					},
				],
			},
			{
				role: "assistant",
				content: "On it.",
			},
		] as Message[];

		expect(hydrateSessionMessages(messages)).toEqual([
			{ kind: "assistant_text", text: "On it.", streaming: false, mode: "act" },
		]);
	});

	it("stamps entries with the mode of the user message that produced them", () => {
		const messages = [
			{
				role: "user",
				content: '<user_input mode="plan">plan this out</user_input>',
			},
			{ role: "assistant", content: "Here is the plan." },
			{
				role: "user",
				content: '<user_input mode="act">do it</user_input>',
			},
			{ role: "assistant", content: "Doing it." },
		] as Message[];

		expect(hydrateSessionMessages(messages)).toEqual([
			{ kind: "user_submitted", text: "plan this out", mode: "plan" },
			{
				kind: "assistant_text",
				text: "Here is the plan.",
				streaming: false,
				mode: "plan",
			},
			{ kind: "user_submitted", text: "do it", mode: "act" },
			{
				kind: "assistant_text",
				text: "Doing it.",
				streaming: false,
				mode: "act",
			},
		]);
	});

	it("switches to act mode after a switch_to_act_mode tool call", () => {
		const messages = [
			{
				role: "user",
				content: '<user_input mode="plan">plan then build</user_input>',
			},
			{
				role: "assistant",
				content: [
					{ type: "text", text: "Plan looks good, switching." },
					{
						type: "tool_use",
						id: "tool-1",
						name: "switch_to_act_mode",
						input: {},
					},
					{ type: "text", text: "Building now." },
				],
			},
		] as Message[];

		expect(hydrateSessionMessages(messages)).toEqual([
			{ kind: "user_submitted", text: "plan then build", mode: "plan" },
			{
				kind: "assistant_text",
				text: "Plan looks good, switching.",
				streaming: false,
				mode: "plan",
			},
			{
				kind: "tool_call",
				toolName: "switch_to_act_mode",
				inputSummary: expect.any(String),
				rawInput: {},
				streaming: false,
				mode: "plan",
			},
			{
				kind: "assistant_text",
				text: "Building now.",
				streaming: false,
				mode: "act",
			},
		]);
	});

	it("strips mode switch notices from displayed user text", () => {
		const messages = [
			{
				role: "user",
				content:
					'<user_input mode="plan"><mode_notice>The user switched from act mode to plan mode before sending this message.</mode_notice>\nare you okay?</user_input>',
			},
		] as Message[];

		expect(hydrateSessionMessages(messages)).toEqual([
			{ kind: "user_submitted", text: "are you okay?", mode: "plan" },
		]);
	});

	it("leaves mode undefined for transcripts without user_input wrappers", () => {
		const messages = [
			{ role: "user", content: "plain old message" },
			{ role: "assistant", content: "reply" },
		] as Message[];

		expect(hydrateSessionMessages(messages)).toEqual([
			{ kind: "user_submitted", text: "plain old message", mode: undefined },
			{
				kind: "assistant_text",
				text: "reply",
				streaming: false,
				mode: undefined,
			},
		]);
	});
});

import type { AgentMode } from "@cline/core";
import {
	formatDisplayUserInput,
	type Message,
	parseUserInputMode,
} from "@cline/shared";
import { ACT_MODE_CONTINUATION_PROMPT } from "../../runtime/interactive/mode";
import { formatToolInput } from "../../utils/helpers";
import type { ChatEntry } from "../types";

type PersistedMessage = Message & {
	metadata?: Record<string, unknown>;
};

function getDisplayRole(msg: PersistedMessage): string | undefined {
	const role = msg.metadata?.displayRole;
	return typeof role === "string" ? role.trim().toLowerCase() : undefined;
}

// The act-mode continuation prompt is runtime-generated, not typed by the
// user, so it should not surface as a user bubble in the transcript.
function isSyntheticUserText(text: string): boolean {
	return text === ACT_MODE_CONTINUATION_PROMPT;
}

function stringifyToolResult(
	content: string | Array<{ type: string; text?: string; path?: string }>,
): string {
	if (typeof content === "string") return content;
	return content
		.map((block) => {
			if (block.type === "text" && typeof block.text === "string")
				return block.text;
			if (block.type === "file" && typeof block.path === "string")
				return `Attached file: ${block.path}`;
			return "";
		})
		.filter(Boolean)
		.join("\n");
}

export function hydrateSessionMessages(messages: Message[]): ChatEntry[] {
	const entries: ChatEntry[] = [];
	const toolUseMap = new Map<string, number>();
	// Mode each entry was produced in, recovered from <user_input mode="...">
	// wrappers and switch_to_act_mode tool calls as we walk the transcript.
	// Stays undefined for transcripts with no mode markers (pre-wrapper
	// builds, or transcripts laundered by older builds that stripped the
	// wrappers on session restarts).
	let mode: AgentMode | undefined;

	for (const msg of messages as PersistedMessage[]) {
		const displayRole = getDisplayRole(msg);
		if (displayRole === "system" || displayRole === "status") {
			continue;
		}

		if (typeof msg.content === "string") {
			if (msg.role === "user") {
				mode = parseUserInputMode(msg.content) ?? mode;
				const text = formatDisplayUserInput(msg.content);
				if (text && !isSyntheticUserText(text)) {
					entries.push({ kind: "user_submitted", text, mode });
				}
			} else {
				entries.push({
					kind: "assistant_text",
					text: msg.content,
					streaming: false,
					mode,
				});
			}
			continue;
		}

		const userTextParts: string[] = [];

		for (const block of msg.content) {
			if (block.type === "text") {
				if (msg.role === "user") {
					userTextParts.push(block.text);
				} else {
					entries.push({
						kind: "assistant_text",
						text: block.text,
						streaming: false,
						mode,
					});
				}
				continue;
			}

			if (block.type === "thinking") {
				entries.push({
					kind: "reasoning",
					text: block.thinking,
					streaming: false,
					mode,
				});
				continue;
			}

			if (block.type === "redacted_thinking") {
				continue;
			}

			if (block.type === "tool_use") {
				entries.push({
					kind: "tool_call",
					toolName: block.name,
					inputSummary: formatToolInput(block.name, block.input),
					rawInput: block.input,
					streaming: false,
					mode,
				});
				toolUseMap.set(block.id, entries.length - 1);
				// The switch tool flips the session to act mid-run; everything
				// after it was produced in act mode.
				if (block.name === "switch_to_act_mode") {
					mode = "act";
				}
				continue;
			}

			if (block.type === "tool_result") {
				const idx = toolUseMap.get(block.tool_use_id);
				if (idx != null) {
					const entry = entries[idx];
					if (entry && entry.kind === "tool_call") {
						const resultText = stringifyToolResult(
							block.content as
								| string
								| Array<{ type: string; text?: string; path?: string }>,
						);
						entry.result = {
							outputSummary: resultText.slice(0, 500),
							rawOutput: block.content,
							error: block.is_error ? resultText : undefined,
						};
					}
				}
			}
		}

		if (msg.role === "user" && userTextParts.length > 0) {
			const combined = userTextParts.join("\n");
			mode = parseUserInputMode(combined) ?? mode;
			const text = formatDisplayUserInput(combined);
			if (text && !isSyntheticUserText(text)) {
				entries.push({ kind: "user_submitted", text, mode });
			}
		}
	}

	return entries;
}

import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import { describe, expect, it } from "vitest";
import {
	readImageDataUrlFromPastedText,
	readImmediateImagePasteAttachment,
	resolvePastedImagePath,
} from "./image-paste";

describe("image paste helpers", () => {
	it("loads pasted image file paths as data urls", () => {
		const dir = mkdtempSync(join(tmpdir(), "cli image paste "));
		const imagePath = join(dir, "hero.png");
		writeFileSync(imagePath, Buffer.from("hello"));

		const result = readImageDataUrlFromPastedText(`"${imagePath}"`);

		expect(result).toEqual({
			dataUrl: "data:image/png;base64,aGVsbG8=",
			source: "path",
		});
	});

	it("resolves file url paste paths", () => {
		const dir = mkdtempSync(join(tmpdir(), "cli-image-paste-"));
		const imagePath = join(dir, "hero.png");

		expect(resolvePastedImagePath(pathToFileURL(imagePath).href)).toBe(
			imagePath,
		);
	});

	it("decodes direct image paste bytes when metadata is available", () => {
		const event = {
			bytes: Buffer.from("hello"),
			metadata: { mimeType: "image/png" },
		};

		expect(readImmediateImagePasteAttachment(event)).toEqual({
			dataUrl: "data:image/png;base64,aGVsbG8=",
			source: "paste",
		});
	});

	it("loads macOS screenshot paths when narrow no-break space is normalized to a regular space", () => {
		// macOS Sonoma+ embeds U+202F (NARROW NO-BREAK SPACE) before AM/PM
		// in screenshot filenames. When the path travels through clipboards,
		// terminals, or anything that normalizes whitespace, U+202F can be
		// collapsed to a regular space (U+0020) -- but the on-disk filename
		// still contains U+202F, so a literal readFileSync fails with ENOENT.
		const dir = mkdtempSync(join(tmpdir(), "cli-image-paste-nnbsp-"));
		const onDiskName = "Screenshot 2026-05-12 at 4.42.48\u202FPM.png";
		const pastedName = "Screenshot 2026-05-12 at 4.42.48 PM.png";
		const onDiskPath = join(dir, onDiskName);
		writeFileSync(onDiskPath, Buffer.from("hello"));

		const result = readImageDataUrlFromPastedText(join(dir, pastedName));

		expect(result).toEqual({
			dataUrl: "data:image/png;base64,aGVsbG8=",
			source: "path",
		});
	});

	it("loads paths when an arbitrary Unicode space differs from the on-disk filename", () => {
		// Generalized variant: any exotic space (here U+00A0 NBSP) in the
		// actual filename should still resolve when the pasted text uses a
		// regular space.
		const dir = mkdtempSync(join(tmpdir(), "cli-image-paste-nbsp-"));
		const onDiskName = "weird\u00a0name.png";
		const pastedName = "weird name.png";
		writeFileSync(join(dir, onDiskName), Buffer.from("hello"));

		const result = readImageDataUrlFromPastedText(join(dir, pastedName));

		expect(result).toEqual({
			dataUrl: "data:image/png;base64,aGVsbG8=",
			source: "path",
		});
	});
});

import { spawn } from "node:child_process";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { release, tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import {
	bufferToImageDataUrl,
	isImagePath,
	loadImageAsDataUrl,
	resolveExistingImagePath,
} from "../../utils/image-attachments";

const COMMAND_TIMEOUT_MS = 1500;
const MAX_CLIPBOARD_BYTES = 20 * 1024 * 1024;
const PASTE_DECODER = new TextDecoder();
const ESC = String.fromCharCode(27);
const BEL = String.fromCharCode(7);
const ANSI_SEQUENCE_PATTERN = new RegExp(
	`${ESC}(?:[@-Z\\\\-_]|\\[[0-?]*[ -/]*[@-~]|\\][^${BEL}]*(?:${BEL}|${ESC}\\\\))`,
	"g",
);

interface PasteLikeEvent {
	bytes: Uint8Array;
	metadata?: {
		mimeType?: string;
	};
}

export interface ImagePasteAttachment {
	dataUrl: string;
	source: "clipboard" | "path" | "paste";
}

function normalizePasteText(text: string): string {
	return text.replace(/\r\n/g, "\n").replace(/\r/g, "\n");
}

function decodePasteBytes(bytes: Uint8Array): string {
	return PASTE_DECODER.decode(bytes);
}

function stripAnsiSequences(text: string): string {
	return text.replace(ANSI_SEQUENCE_PATTERN, "");
}

function stripWrappingQuotes(text: string): string {
	return text.replace(/^['"]+|['"]+$/g, "");
}

function unescapeTerminalPath(text: string): string {
	if (process.platform === "win32") {
		return text;
	}
	return text.replace(/\\(.)/g, "$1");
}

export function resolvePastedImagePath(text: string): string | undefined {
	const normalized = normalizePasteText(text).trim();
	if (!normalized) {
		return undefined;
	}

	const lines = normalized.split("\n").filter((line) => line.trim().length > 0);
	if (lines.length !== 1) {
		return undefined;
	}

	const raw = stripWrappingQuotes(lines[0]?.trim() ?? "");
	if (!raw || /^(https?):\/\//i.test(raw)) {
		return undefined;
	}

	if (raw.startsWith("file://")) {
		try {
			return fileURLToPath(raw);
		} catch {
			return undefined;
		}
	}

	return unescapeTerminalPath(raw);
}

export function readImageDataUrlFromPastedText(
	text: string,
): ImagePasteAttachment | undefined {
	const filePath = resolvePastedImagePath(text);
	if (!filePath || !isImagePath(filePath)) {
		return undefined;
	}

	// Resolve macOS-style filename variants (narrow no-break space before
	// AM/PM, NFD normalization, curly apostrophe, etc.) before reading.
	// See resolveExistingImagePath for the full ladder.
	const resolvedPath = resolveExistingImagePath(filePath);
	if (!resolvedPath) {
		return undefined;
	}

	try {
		return {
			dataUrl: loadImageAsDataUrl(resolvedPath),
			source: "path",
		};
	} catch {
		return undefined;
	}
}

async function runCommand(
	command: string,
	args: string[],
): Promise<Buffer | undefined> {
	return await new Promise((resolve) => {
		const child = spawn(command, args, {
			stdio: ["ignore", "pipe", "ignore"],
			// Prevent a console window from flashing on Windows.
			windowsHide: true,
		});
		const chunks: Buffer[] = [];
		let total = 0;
		let settled = false;

		const finish = (buffer: Buffer | undefined) => {
			if (settled) return;
			settled = true;
			clearTimeout(timer);
			resolve(buffer);
		};

		const timer = setTimeout(() => {
			child.kill();
			finish(undefined);
		}, COMMAND_TIMEOUT_MS);

		child.on("error", () => finish(undefined));
		child.stdout.on("data", (chunk: Buffer) => {
			total += chunk.length;
			if (total > MAX_CLIPBOARD_BYTES) {
				child.kill();
				finish(undefined);
				return;
			}
			chunks.push(chunk);
		});
		child.on("close", (code) => {
			if (code !== 0 || chunks.length === 0) {
				finish(undefined);
				return;
			}
			finish(Buffer.concat(chunks));
		});
	});
}

async function readMacClipboardImage(): Promise<string | undefined> {
	const dir = await mkdtemp(join(tmpdir(), "cline-clipboard-"));
	const filePath = join(dir, "clipboard.png");
	try {
		const escapedPath = filePath.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
		await runCommand("osascript", [
			"-e",
			'set imageData to the clipboard as "PNGf"',
			"-e",
			`set fileRef to open for access POSIX file "${escapedPath}" with write permission`,
			"-e",
			"set eof fileRef to 0",
			"-e",
			"write imageData to fileRef",
			"-e",
			"close access fileRef",
		]);
		const buffer = await readFile(filePath).catch(() => undefined);
		if (!buffer || buffer.length === 0) {
			return undefined;
		}
		return bufferToImageDataUrl(buffer, "image/png");
	} finally {
		await rm(dir, { recursive: true, force: true }).catch(() => {});
	}
}

async function readWindowsClipboardImage(): Promise<string | undefined> {
	const script =
		"Add-Type -AssemblyName System.Windows.Forms; $img = [System.Windows.Forms.Clipboard]::GetImage(); if ($img) { $ms = New-Object System.IO.MemoryStream; $img.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png); [System.Convert]::ToBase64String($ms.ToArray()) }";
	const output = await runCommand("powershell.exe", [
		"-NonInteractive",
		"-NoProfile",
		"-Command",
		script,
	]);
	const base64 = output?.toString("utf8").trim();
	if (!base64) {
		return undefined;
	}
	const buffer = Buffer.from(base64, "base64");
	if (buffer.length === 0) {
		return undefined;
	}
	return bufferToImageDataUrl(buffer, "image/png");
}

async function readLinuxClipboardImage(): Promise<string | undefined> {
	const wayland = await runCommand("wl-paste", ["-t", "image/png"]);
	if (wayland && wayland.length > 0) {
		return bufferToImageDataUrl(wayland, "image/png");
	}

	const x11 = await runCommand("xclip", [
		"-selection",
		"clipboard",
		"-t",
		"image/png",
		"-o",
	]);
	if (x11 && x11.length > 0) {
		return bufferToImageDataUrl(x11, "image/png");
	}

	return undefined;
}

export async function readClipboardImageDataUrl(): Promise<string | undefined> {
	if (process.platform === "darwin") {
		return await readMacClipboardImage();
	}

	if (process.platform === "win32" || release().includes("WSL")) {
		const windowsImage = await readWindowsClipboardImage();
		if (windowsImage) {
			return windowsImage;
		}
	}

	if (process.platform === "linux") {
		return await readLinuxClipboardImage();
	}

	return undefined;
}

export function readImmediateImagePasteAttachment(
	event: PasteLikeEvent,
): ImagePasteAttachment | undefined {
	const mimeType = event.metadata?.mimeType;
	if (mimeType?.startsWith("image/") && event.bytes.length > 0) {
		return {
			dataUrl: bufferToImageDataUrl(Buffer.from(event.bytes), mimeType),
			source: "paste",
		};
	}

	const text = normalizePasteText(
		stripAnsiSequences(decodePasteBytes(event.bytes)),
	);
	return readImageDataUrlFromPastedText(text);
}

export async function readImagePasteAttachment(
	event: PasteLikeEvent,
): Promise<ImagePasteAttachment | undefined> {
	const immediate = readImmediateImagePasteAttachment(event);
	if (immediate) {
		return immediate;
	}

	const text = normalizePasteText(
		stripAnsiSequences(decodePasteBytes(event.bytes)),
	);

	if (text.trim()) {
		return undefined;
	}

	const dataUrl = await readClipboardImageDataUrl();
	if (!dataUrl) {
		return undefined;
	}

	return {
		dataUrl,
		source: "clipboard",
	};
}

import { describe, expect, it } from "vitest";
import {
	countPastedTextLines,
	createUniquePastedTextSnippetMarker,
	expandPastedTextSnippets,
	formatPastedTextSnippetMarker,
	shouldCompactPastedText,
} from "./pasted-snippets";

describe("pasted text snippet helpers", () => {
	it("counts pasted lines across newline formats", () => {
		expect(countPastedTextLines("one\ntwo\r\nthree\rfour")).toBe(4);
		expect(countPastedTextLines("one\ntwo\nthree\nfour\n")).toBe(4);
	});

	it("compacts pastes at the large paste line threshold", () => {
		expect(shouldCompactPastedText("one\ntwo\nthree\nfour")).toBe(false);
		expect(shouldCompactPastedText("one\ntwo\nthree\nfour\n")).toBe(false);
		expect(shouldCompactPastedText("one\ntwo\nthree\nfour\nfive")).toBe(true);
	});

	it("formats a compact single-line marker with preview text", () => {
		expect(formatPastedTextSnippetMarker("alpha\nbeta\ngamma")).toBe(
			"[alpha beta gamma... Pasted +3 lines]",
		);
	});

	it("keeps markers unique when previews collide", () => {
		const marker = formatPastedTextSnippetMarker("alpha\nbeta\ngamma");

		expect(
			createUniquePastedTextSnippetMarker("alpha\nbeta\ngamma", [marker]),
		).toBe("[alpha beta gamma... Pasted +3 lines #2]");
	});

	it("expands pasted snippet markers before submission", () => {
		expect(
			expandPastedTextSnippets("before [snippet] after", [
				{ marker: "[snippet]", text: "line 1\nline 2" },
			]),
		).toBe("before line 1\nline 2 after");
	});
});

export interface PastedTextSnippet {
	marker: string;
	text: string;
}

export const LARGE_PASTE_LINE_THRESHOLD = 5;

const PREVIEW_MAX_CHARS = 48;

export function countPastedTextLines(text: string): number {
	if (text.length === 0) return 0;
	const lines = text.split(/\r\n|\r|\n/);
	return lines.at(-1) === "" ? lines.length - 1 : lines.length;
}

export function shouldCompactPastedText(text: string): boolean {
	return countPastedTextLines(text) >= LARGE_PASTE_LINE_THRESHOLD;
}

function previewText(text: string): string {
	const normalized = text.trim().replace(/\s+/g, " ");
	if (!normalized) return "";
	return normalized.length > PREVIEW_MAX_CHARS
		? normalized.slice(0, PREVIEW_MAX_CHARS).trimEnd()
		: normalized;
}

export function formatPastedTextSnippetMarker(text: string): string {
	const lineCount = countPastedTextLines(text);
	const preview = previewText(text);
	const lineLabel = lineCount === 1 ? "line" : "lines";
	const prefix = preview ? `${preview}... ` : "";
	return `[${prefix}Pasted +${lineCount} ${lineLabel}]`;
}

export function createUniquePastedTextSnippetMarker(
	text: string,
	existingMarkers: Iterable<string>,
): string {
	const base = formatPastedTextSnippetMarker(text);
	const existing = new Set(existingMarkers);
	if (!existing.has(base)) return base;

	for (let suffix = 2; ; suffix += 1) {
		const candidate = base.replace(/\]$/, ` #${suffix}]`);
		if (!existing.has(candidate)) return candidate;
	}
}

export function expandPastedTextSnippets(
	text: string,
	snippets: readonly PastedTextSnippet[],
): string {
	let expanded = text;
	for (const snippet of snippets) {
		if (!expanded.includes(snippet.marker)) continue;
		expanded = expanded.split(snippet.marker).join(snippet.text);
	}
	return expanded;
}

