import { formatDisplayUserInput } from "@cline/shared";
import type { AppView, ChatEntry } from "../types";

const APP_TITLE = "Cline";
const CHAT_TITLE_PREFIX = "> ";
const MAX_TERMINAL_TITLE_LENGTH = 80;
// biome-ignore lint/suspicious/noControlCharactersInRegex: stripping control characters from terminal titles is the purpose of this pattern
const CONTROL_CHARACTER_PATTERN = /[\u0000-\u001f\u007f-\u009f]/g;

function truncateTitle(title: string): string {
	if (title.length <= MAX_TERMINAL_TITLE_LENGTH) {
		return title;
	}
	return `${title.slice(0, MAX_TERMINAL_TITLE_LENGTH - 3).trimEnd()}...`;
}

function sanitizeTerminalTitleText(text: string): string {
	return text
		.replace(CONTROL_CHARACTER_PATTERN, " ")
		.replace(/\s+/g, " ")
		.trim();
}

function normalizeChatTitleText(text: string): string {
	const formatted = formatDisplayUserInput(text);
	const firstLine = formatted.split("\n")[0] ?? formatted;
	return sanitizeTerminalTitleText(firstLine);
}

export function deriveTerminalTitle(input: {
	appView: AppView;
	entries: ChatEntry[];
	initialPrompt?: string;
}): string {
	if (input.appView !== "chat") {
		return APP_TITLE;
	}

	for (let index = input.entries.length - 1; index >= 0; index -= 1) {
		const entry = input.entries[index];
		if (entry?.kind !== "user_submitted" && entry?.kind !== "user") {
			continue;
		}
		const text = normalizeChatTitleText(entry.text);
		if (text) {
			return truncateTitle(`${CHAT_TITLE_PREFIX}${text}`);
		}
	}

	const initialPrompt = normalizeChatTitleText(input.initialPrompt ?? "");
	return initialPrompt
		? truncateTitle(`${CHAT_TITLE_PREFIX}${initialPrompt}`)
		: APP_TITLE;
}

import { describe, expect, it } from "vitest";
import {
	getToolErrorPresentation,
	isWarningToolError,
	unwrapToolError,
} from "./tool-errors";

describe("tool error presentation", () => {
	it("unwraps JSON-encoded tool errors", () => {
		const raw = JSON.stringify({
			error: "Tool call run_commands was rejected before execution: nope",
		});

		expect(unwrapToolError(raw)).toBe(
			"Tool call run_commands was rejected before execution: nope",
		);
	});

	it("summarizes invalid tool input as a warning", () => {
		const raw = JSON.stringify({
			error:
				'Tool call run_commands was rejected before execution: Invalid input for tool run_commands: Type validation failed: Value: {"commands":[{"command":"cat file"}]}.\nError message: []',
		});

		expect(getToolErrorPresentation(raw)).toMatchObject({
			severity: "warning",
			summary: "Invalid run_commands input; tool call skipped.",
		});
		expect(isWarningToolError(raw)).toBe(true);
	});

	it("summarizes generic pre-execution rejections as warnings", () => {
		expect(
			getToolErrorPresentation(
				"Tool call editor was rejected before execution: approval request failed",
			),
		).toMatchObject({
			severity: "warning",
			summary: "editor call was skipped before execution.",
		});
	});

	it("keeps non-rejection failures as errors", () => {
		const presentation = getToolErrorPresentation("command failed with exit 1");

		expect(presentation).toEqual({
			severity: "error",
			summary: "command failed with exit 1",
			detail: "command failed with exit 1",
		});
	});

	it("summarizes JSON-wrapped hard errors without dumping stacks", () => {
		const raw = JSON.stringify({
			error:
				"Error: command failed with exit 1\n    at runTool (/tmp/tool.ts:10:1)\n    at async main (/tmp/main.ts:5:1)",
		});

		expect(getToolErrorPresentation(raw)).toEqual({
			severity: "error",
			summary: "command failed with exit 1",
