export function ChatView(props: {
	config: TuiProps["config"];
	inputValue: string;
	inputKey: number;
	onSubmit: () => void;
	onContentChange: (text: string) => void;
	onImagePaste: (dataUrl: string) => string;
	onLargeTextPaste: (text: string) => string;
	onInputFocusRequest?: () => void;
	repoStatus: {
		branch: string | null;
		diffStats: {
			files: number;
			additions: number;
			deletions: number;
		} | null;
	};
	textareaRef?: React.MutableRefObject<TextareaHandle | null>;
	transcriptScrollRef?: React.Ref<TranscriptScrollHandle>;
	loadIndividualSubscriptionPlans?: TuiProps["loadIndividualSubscriptionPlans"];
	autocomplete?: AutocompleteDropdownProps;
	queuedPrompts?: QueuedPromptItem[];
	selectedQueuedPromptId?: string | null;
	editingQueuedPrompt?: QueuedPromptItem;
	onQueuedPromptEditConfirm: (id: string, prompt: string) => void;
	onToggleMode: () => void;
	runtimeInteraction?: RuntimeToolInteraction | null;
	onResolveToolApproval: (id: number, approved: boolean) => void;
	onResolveAskQuestion: (id: number, answer: string | null) => void;
}) {
	const {
		config,
		inputValue,
		inputKey,
		onSubmit,
		onContentChange,
		onImagePaste,
		onLargeTextPaste,
		repoStatus,
	} = props;
	const session = useSession();
	const terminalBg = useTerminalBackground();
	const terminalTheme = useTerminalTheme();
	const accent = getModeAccent(session.uiMode, terminalTheme);
	const inputBackground = getModeInputBackground(session.uiMode, terminalBg);
	const inputRuleColor = getInputRuleColor(terminalBg);
	const inputForeground = getModeInputForeground(session.uiMode, terminalBg);
	const inputPlaceholder = getModeInputPlaceholder(session.uiMode, terminalBg);
	const placeholder =
		session.uiMode === "plan" ? "Plan something..." : "Ask anything...";
	const modelDisplayName = resolveModelDisplayName(config);
	const maxInputTokens = resolveModelMaxInputTokens(config);
	const runtimeInteraction = props.runtimeInteraction ?? null;

	return (
		<box flexDirection="column" width="100%" height="100%">
			<ChatMessageList
				ref={props.transcriptScrollRef}
				entries={session.entries}
				isStreaming={session.isStreaming}
				loadIndividualSubscriptionPlans={props.loadIndividualSubscriptionPlans}
				uiMode={session.uiMode}
			/>

			<box flexDirection="column" flexShrink={0}>
				{runtimeInteraction ? (
					<box marginBottom={1}>
						<InlineToolResponse
							key={runtimeInteraction.id}
							interaction={runtimeInteraction}
							accent={accent}
							inputBackground={inputBackground}
							inputForeground={inputForeground}
							inputPlaceholder={inputPlaceholder}
							onResolveToolApproval={props.onResolveToolApproval}
							onResolveAskQuestion={props.onResolveAskQuestion}
						/>
					</box>
				) : (
					<>
						{props.autocomplete && (
							<AutocompleteDropdown {...props.autocomplete} accent={accent} />
						)}

						{props.queuedPrompts && props.queuedPrompts.length > 0 && (
							<QueuedPrompts
								items={props.queuedPrompts}
								selectedId={props.selectedQueuedPromptId ?? null}
								editingId={props.editingQueuedPrompt?.id ?? null}
								onEditConfirm={props.onQueuedPromptEditConfirm}
							/>
						)}

						<box>
							<InputBar
								accent={accent}
								ruleColor={inputRuleColor}
								inputForeground={inputForeground}
								inputPlaceholder={inputPlaceholder}
								placeholder={placeholder}
								initialValue={inputValue}
								inputKey={inputKey}
								onSubmit={onSubmit}
								onContentChange={onContentChange}
								onImagePaste={onImagePaste}
								onLargeTextPaste={onLargeTextPaste}
								onFocusRequest={props.onInputFocusRequest}
								textareaRef={props.textareaRef}
							/>
						</box>
					</>
				)}

				<StatusBar
					providerId={config.providerId}
					modelId={modelDisplayName}
					totalTokens={session.lastTotalTokens}
					totalCost={session.lastTotalCost}
					maxInputTokens={maxInputTokens}
					uiMode={session.uiMode}
					autoApproveAll={session.autoApproveAll}
					workspaceName={
						config.workspaceRoot
							? (config.workspaceRoot.split("/").pop() ?? "")
							: ""
					}
					gitBranch={repoStatus.branch}
					gitDiffStats={repoStatus.diffStats}
					onToggleMode={props.onToggleMode}
					variant="chat"
				/>
			</box>
		</box>
	);
}

import type {
	InteractiveConfigData,
	InteractiveConfigItem,
	InteractiveConfigTab,
} from "../../tui/interactive-config";
import { isToggleableInteractiveConfigItem } from "../../tui/interactive-config";

export type ConfigAction =
	| { kind: "open-provider" }
	| { kind: "open-model" }
	| { kind: "toggle-item"; item: InteractiveConfigItem }
	| { kind: "delete-item"; item: InteractiveConfigItem }
	| {
			kind: "ext-detail";
			item: InteractiveConfigItem;
	  }
	| { kind: "open-mcp" };

const CONFIG_TABS: InteractiveConfigTab[] = [
	"general",
	"mcp",
	"skills",
	"rules",
	"tools",
	"plugins",
	"agents",
	"hooks",
];

export function getConfigTabs(): InteractiveConfigTab[] {
	return CONFIG_TABS;
}

export function resolveInitialConfigTab(
	tab: InteractiveConfigTab | undefined,
): InteractiveConfigTab {
	return tab && CONFIG_TABS.includes(tab) ? tab : "general";
}

export function getAdjacentConfigTab(
	currentTab: InteractiveConfigTab,
	direction: "left" | "right",
): InteractiveConfigTab {
	const currentIndex = CONFIG_TABS.indexOf(currentTab);
	const safeIndex = currentIndex >= 0 ? currentIndex : 0;
	const delta = direction === "left" ? -1 : 1;
	const nextIndex =
		(safeIndex + delta + CONFIG_TABS.length) % CONFIG_TABS.length;
	return CONFIG_TABS[nextIndex] ?? "general";
}

export function toTabLabel(tab: InteractiveConfigTab): string {
	switch (tab) {
		case "general":
			return "General";
		case "tools":
			return "Tools";
		case "plugins":
			return "Plugins";
		case "agents":
			return "Agents";
		case "hooks":
			return "Hooks";
		case "skills":
			return "Skills";
		case "rules":
			return "Rules";
		case "mcp":
			return "MCP";
		case "workflows":
			return "Workflows";
	}
}

function sourceRank(source: InteractiveConfigItem["source"]): number {
	switch (source) {
		case "builtin":
			return 0;
		case "workspace":
			return 1;
		case "workspace-plugin":
			return 2;
		case "global":
			return 3;
		case "global-plugin":
			return 4;
	}
}

function sortBySourceThenName(
	items: InteractiveConfigItem[],
): InteractiveConfigItem[] {
	return [...items].sort((a, b) => {
		if (a.source !== b.source) {
			return sourceRank(a.source) - sourceRank(b.source);
		}
		return a.name.localeCompare(b.name);
	});
}

export function resolveActiveConfigItems(
	configData: InteractiveConfigData,
	configTab: InteractiveConfigTab,
): InteractiveConfigItem[] {
	switch (configTab) {
		case "general":
			return [];
		case "tools":
			return sortBySourceThenName(configData.tools);
		case "plugins":
			return sortBySourceThenName(configData.plugins);
		case "agents":
			return sortBySourceThenName(configData.agents);
		case "hooks":
			return sortBySourceThenName(configData.hooks);
		case "skills":
			return sortBySourceThenName([
				...configData.workflows,
				...configData.skills,
			]);
		case "rules":
			return sortBySourceThenName(configData.rules);
		case "mcp":
			return sortBySourceThenName(configData.mcp);
		case "workflows":
			return sortBySourceThenName(configData.workflows);
	}
}

export function isToggleableConfigItem(item: InteractiveConfigItem): boolean {
	return isToggleableInteractiveConfigItem(item);
}

export function isDeletableConfigItem(item: InteractiveConfigItem): boolean {
	return item.kind === "plugin";
}

export function resolveConfigItemSelectAction(
	item: InteractiveConfigItem,
): ConfigAction {
	if (
		typeof item.enabled === "boolean" &&
		item.kind !== "skill" &&
		isToggleableConfigItem(item)
	) {
		return { kind: "toggle-item", item };
	}

	return {
		kind: "ext-detail",
		item,
	};
}

export function resolveConfigItemToggleAction(
	item: InteractiveConfigItem,
): ConfigAction | undefined {
	if (typeof item.enabled !== "boolean" || !isToggleableConfigItem(item)) {
		return undefined;
	}
	return { kind: "toggle-item", item };
}

export function resolveConfigItemDeleteAction(
	item: InteractiveConfigItem,
): ConfigAction | undefined {
	if (!isDeletableConfigItem(item)) {
		return undefined;
	}
	return { kind: "delete-item", item };
}

export function isInlineConfigAction(
	action: ConfigAction | undefined,
): boolean {
	return action?.kind === "toggle-item";
}

export function canToggleConfigFooterRow(
	row:
		| { kind: "toggle" }
		| { kind: "ext"; enabled?: boolean; item: InteractiveConfigItem }
		| { kind: string }
		| undefined,
): boolean {
	if (!row) {
		return false;
	}
	if (row.kind === "toggle") {
		return true;
	}
	return (
		row.kind === "ext" &&
		"item" in row &&
		typeof row.enabled === "boolean" &&
		isToggleableConfigItem(row.item)
	);
}

export function canDeleteConfigFooterRow(
	row:
		| { kind: "ext"; item: InteractiveConfigItem }
		| { kind: string }
		| undefined,
): boolean {
	return (
		row?.kind === "ext" && "item" in row && isDeletableConfigItem(row.item)
	);
}

export function getConfigFooterText({
	canToggle = false,
	canDelete = false,
}: {
	canToggle?: boolean;
	canDelete?: boolean;
} = {}): string {
	const actions = ["←/→ switch tabs", "↑/↓ navigate", "Tab/Enter select"];
	if (canToggle) {
		actions.push("Space toggle");
	}
	if (canDelete) {
		actions.push("D delete");
	}
	actions.push("Esc close");
	return actions.join(", ");
}

export function getConfigItemDisplayName(name: string): string {
	return name;
}

export function getPluginDiagnosticsLoadingText(
	tab: InteractiveConfigTab,
): string | undefined {
	if (tab === "tools") {
		return "Loading plugin tools...";
	}
	if (tab === "plugins") {
		return "Loading plugin diagnostics...";
	}
	return undefined;
}

