function groupToolItems(
	items: InteractiveConfigItem[],
): Array<[string, InteractiveConfigItem[]]> {
	const groups = new Map<string, InteractiveConfigItem[]>();
	for (const item of items) {
		const groupKey = `${item.source}:${item.pluginPath ?? item.path}:${item.pluginName}`;
		const group = groups.get(groupKey) ?? [];
		group.push(item);
		groups.set(groupKey, group);
	}

	return [...groups.entries()].sort((left, right) => {
		const leftItem = left[1][0];
		const rightItem = right[1][0];
		const leftSource = leftItem?.source ?? "global-plugin";
		const rightSource = rightItem?.source ?? "global-plugin";
		if (leftSource !== rightSource) {
			return sourceRank(leftSource) - sourceRank(rightSource);
		}
		return (leftItem?.pluginName ?? "").localeCompare(
			rightItem?.pluginName ?? "",
		);
	});
}

function getSharedToolNames(items: InteractiveConfigItem[]): Set<string> {
	const counts = new Map<string, number>();
	for (const item of items) {
		counts.set(item.name, (counts.get(item.name) ?? 0) + 1);
	}
	return new Set(
		[...counts.entries()]
			.filter(([, count]) => count > 1)
			.map(([name]) => name),
	);
}

function appendToolGroupRows(
	rows: ConfigRow[],
	groups: Array<[string, InteractiveConfigItem[]]>,
	sharedToolNames: ReadonlySet<string>,
): void {
	for (const [, groupItems] of groups) {
		const first = groupItems[0];
		const enabledCount = groupItems.filter(
			(item) => item.enabled !== false,
		).length;
		rows.push({
			kind: "tool-group",
			label: first?.pluginName ?? "plugin",
			rightLabel: `${enabledCount}/${groupItems.length} tools enabled`,
			indent: 2,
		});

		for (const item of sortBySourceThenName(groupItems)) {
			rows.push({
				kind: "ext",
				name: item.name,
				path: item.path,
				source: item.source,
				enabled: item.enabled,
				description: item.description,
				item,
				indent: 4,
				rightLabel: sharedToolNames.has(item.name) ? "shared tool name" : "",
			});
		}
	}
}

function appendExtRows(
	rows: ConfigRow[],
	items: InteractiveConfigItem[],
	indent?: number,
): void {
	for (const item of sortBySourceThenName(items)) {
		rows.push({
			kind: "ext",
			name: item.name,
			path: item.path,
			source: item.source,
			enabled: item.enabled,
			description: item.description,
			item,
			indent,
		});
	}
}

function appendToolRows(
	rows: ConfigRow[],
	items: InteractiveConfigItem[],
): void {
	const builtinTools = sortBySourceThenName(
		items.filter((item) => !item.pluginName),
	);
	if (builtinTools.length > 0) {
		rows.push({ kind: "head", label: "Built-in" });
		appendExtRows(rows, builtinTools);
	}

	const pluginToolItems = items.filter((item) => item.pluginName);
	const pluginGroups = groupToolItems(pluginToolItems);
	if (pluginGroups.length > 0) {
		rows.push({ kind: "head", label: "Plugins" });
		appendToolGroupRows(
			rows,
			pluginGroups,
			getSharedToolNames(pluginToolItems),
		);
	}
}

function hasPluginDiagnostics(data: InteractiveConfigData): boolean {
	return (
		data.pluginDiagnosticsLoaded || data.tools.some((item) => item.pluginName)
	);
}

function appendSkillRows(
	rows: ConfigRow[],
	items: InteractiveConfigItem[],
): void {
	const detectedItems = items.filter((item) => !item.pluginName);
	if (detectedItems.length > 0) {
		rows.push({ kind: "head", label: "Detected" });
		appendExtRows(rows, detectedItems);
	}

	const pluginItems = items.filter((item) => item.pluginName);
	const pluginGroups = groupToolItems(pluginItems);
	if (pluginGroups.length > 0) {
		rows.push({ kind: "head", label: "Plugins" });
		for (const [, groupItems] of pluginGroups) {
			const first = groupItems[0];
			const enabledCount = groupItems.filter(
				(item) => item.enabled !== false,
			).length;
			rows.push({
				kind: "tool-group",
				label: first?.pluginName ?? "plugin",
				rightLabel: `${enabledCount}/${groupItems.length} skills enabled`,
				indent: 2,
			});
			appendExtRows(rows, groupItems, 4);
		}
	}
}

function withOptimisticToggle(
	data: InteractiveConfigData,
	item: InteractiveConfigItem,
): InteractiveConfigData {
	if (typeof item.enabled !== "boolean") {
		return data;
	}
	const nextEnabled = !item.enabled;
	const matchesItem = (candidate: InteractiveConfigItem) =>
		candidate.id === item.id &&
		candidate.path === item.path &&
		candidate.kind === item.kind;
	const toolNames = new Set(
		(item.toolNames && item.toolNames.length > 0
			? item.toolNames
			: [item.name]
		).filter(Boolean),
	);
	const updateItems = (items: InteractiveConfigItem[]) =>
		items.map((candidate) => {
			if (matchesItem(candidate)) {
				return { ...candidate, enabled: nextEnabled };
			}
			if (
				item.kind === "plugin" &&
				(candidate.path === item.path || candidate.pluginPath === item.path)
			) {
				return { ...candidate, enabled: nextEnabled };
			}
			return candidate;
		});
	const updateTools = (items: InteractiveConfigItem[]) =>
		items.map((candidate) => {
			if (matchesItem(candidate)) {
				return { ...candidate, enabled: nextEnabled };
			}
			if (
				item.kind === "tool" &&
				toolNames.has(candidate.name) &&
				(candidate.source === "builtin" ||
					candidate.source === "workspace-plugin" ||
					candidate.source === "global-plugin")
			) {
				return { ...candidate, enabled: nextEnabled };
			}
			if (item.kind === "plugin" && candidate.path === item.path) {
				return { ...candidate, enabled: nextEnabled };
			}
			return candidate;
		});

	return {
		...data,
		workflows: updateItems(data.workflows),
		rules: updateItems(data.rules),
		skills: updateItems(data.skills),
		hooks: updateItems(data.hooks),
		agents: updateItems(data.agents),
		plugins: updateItems(data.plugins),
		mcp: updateItems(data.mcp),
		tools: updateTools(data.tools),
	};
}

function getPluginLoadErrorLabel(
	item: InteractiveConfigItem,
): string | undefined {
	if (!item.loadError) {
		return undefined;
	}
	const lines = item.loadError.split("\n");
	const first = lines[0] ?? item.loadError;
	return lines.length > 1 ? `${first} (+${lines.length - 1} more)` : first;
}

export function ConfigPanelContent(props: ConfigPanelProps) {
	const {
		resolve,
		dismiss,
		dialogId,
		config,
		loadConfigData,
		onActiveTabChange,
	} = props;
	const { height } = useTerminalDimensions();

	const [mode, setMode] = useState(props.currentMode);
	const [autoApprove, setAutoApprove] = useState(
		config.toolPolicies["*"]?.autoApprove !== false,
	);
	const [autoUpdateEnabled, setAutoUpdateEnabled] = useState(
		() => readGlobalSettings().autoUpdateEnabled,
	);
	const [verbose, setVerbose] = useState(config.verbose);
	const [compactionMode, setCompactionMode] = useState(
		props.currentCompactionMode,
	);
	const [activeTab, setActiveTab] = useState<InteractiveConfigTab>(() =>
		resolveInitialConfigTab(props.initialTab),
	);
	const [configData, setConfigData] = useState(props.configData);
	const [pluginToolsLoaded, setPluginToolsLoaded] = useState(
		hasPluginDiagnostics(props.configData),
	);
	const [pluginToolsLoading, setPluginToolsLoading] = useState(false);
	const [pluginToolsError, setPluginToolsError] = useState<
		string | undefined
	>();
	const [togglingItemId, setTogglingItemId] = useState<string | null>(null);
	const [toggleError, setToggleError] = useState<string | undefined>();
	const [navPos, setNavPos] = useState(0);

	const displayName = resolveModelDisplayName(config);

	useEffect(() => {
		onActiveTabChange?.(activeTab);
	}, [activeTab, onActiveTabChange]);

	useEffect(() => {
		if (
			(activeTab !== "tools" && activeTab !== "plugins") ||
			pluginToolsLoaded ||
			pluginToolsError ||
			!loadConfigData
		) {
			return;
		}

		let cancelled = false;
		setPluginToolsLoading(true);
		setPluginToolsError(undefined);
		loadConfigData({ includePluginTools: true })
			.then((nextData) => {
				if (cancelled) {
					return;
				}
				setConfigData(nextData);
				setPluginToolsLoaded(true);
			})
			.catch((error) => {
				if (cancelled) {
					return;
				}
				const message = error instanceof Error ? error.message : String(error);
				setPluginToolsError(`Failed to load plugin diagnostics: ${message}`);
			})
			.finally(() => {
				if (!cancelled) {
					setPluginToolsLoading(false);
				}
			});

		return () => {
			cancelled = true;
		};
	}, [activeTab, pluginToolsError, pluginToolsLoaded, loadConfigData]);

	const rows = useMemo(() => {
		const r: ConfigRow[] = [];

		if (activeTab === "general") {
			r.push({ kind: "provider" });
			r.push({ kind: "model" });
			r.push({ kind: "toggle", id: "mode", label: "Mode" });
			r.push({ kind: "toggle", id: "compaction", label: "Compaction" });
			r.push({
				kind: "toggle",
				id: "auto-approve",
				label: "Auto-approve all",
			});
			r.push({ kind: "toggle", id: "auto-update", label: "Auto update" });
			r.push({ kind: "toggle", id: "verbose", label: "Verbose" });
		} else {
			const activeItems = resolveActiveConfigItems(configData, activeTab);
			r.push({
				kind: "head",
				label: `${toTabLabel(activeTab)} (${activeItems.length})`,
			});

			if (activeItems.length === 0 && !pluginToolsLoading) {
				r.push({
					kind: "detail",
					text: `No ${toTabLabel(activeTab).toLowerCase()} found.`,
				});
			} else if (activeTab === "tools") {
				appendToolRows(r, activeItems);
				const loadingText = getPluginDiagnosticsLoadingText(activeTab);
				if (pluginToolsLoading && loadingText) {
					r.push({
						kind: "detail",
						text: loadingText,
					});
				}
				if (pluginToolsError) {
					r.push({
						kind: "detail",
						text: pluginToolsError,
					});
				}
			} else if (activeTab === "skills") {
				appendSkillRows(r, activeItems);
			} else {
				for (const item of activeItems) {
					r.push({
						kind: "ext",
						name: item.name,
						path: item.path,
						source: item.source,
						enabled: item.enabled,
						description: item.description,
						item,
						rightLabel:
							activeTab === "mcp"
								? getMcpManagerEntryStatus({
										description: item.description,
										lastError: item.loadError,
									})
								: getPluginLoadErrorLabel(item),
					});
				}
				if (activeTab === "plugins" && pluginToolsLoading) {
					const loadingText = getPluginDiagnosticsLoadingText(activeTab);
					r.push({
						kind: "detail",
						text: loadingText ?? "Loading plugin diagnostics...",
					});
				}
				if (activeTab === "plugins" && pluginToolsError) {
					r.push({
						kind: "detail",
						text: pluginToolsError,
					});
				}
			}

			if (activeTab === "mcp") {
				r.push({ kind: "mcp-manager" });
			}
		}

		return r;
	}, [activeTab, configData, pluginToolsError, pluginToolsLoading]);

	const navIndices = useMemo(
		() => rows.map((r, i) => (isNavigable(r) ? i : -1)).filter((i) => i >= 0),
		[rows],
	);

	const clampedNavPos = Math.min(navPos, Math.max(0, navIndices.length - 1));
	const selectedRowIdx = navIndices[clampedNavPos] ?? 0;
	const selectedRow = rows[selectedRowIdx];
	const canToggleSelectedRow = canToggleConfigFooterRow(selectedRow);
	const canDeleteSelectedRow = Boolean(
		props.onDeleteConfigItem && canDeleteConfigFooterRow(selectedRow),
	);

	const setNavPosition = (nextNavPos: number) => {
		setNavPos(nextNavPos);
	};

	const handleInlineToggle = async (item: InteractiveConfigItem) => {
		if (!props.onToggleConfigItem || togglingItemId) return;
		const previousData = configData;
		setTogglingItemId(item.id);
		setToggleError(undefined);
		setConfigData((current) => withOptimisticToggle(current, item));
		try {
			const nextData = await props.onToggleConfigItem(item, {
				includePluginTools: pluginToolsLoaded,
			});
			if (nextData) {
				setConfigData(nextData);
				setPluginToolsLoaded(hasPluginDiagnostics(nextData));
			} else if (item.kind === "plugin" && loadConfigData) {
				const refreshedData = await loadConfigData({
					includePluginTools: true,
				});
				setConfigData(refreshedData);
				setPluginToolsLoaded(hasPluginDiagnostics(refreshedData));
				setPluginToolsError(undefined);
			}
		} catch (error) {
			setConfigData(previousData);
			const message = error instanceof Error ? error.message : String(error);
			setToggleError(`Failed to update ${item.name}: ${message}`);
		} finally {
			setTogglingItemId(null);
		}
	};

	const handleSelect = () => {
		const row = rows[selectedRowIdx];
		if (!row) return;
		switch (row.kind) {
			case "provider":
				resolve({ kind: "open-provider" });
				break;
			case "model":
				resolve({ kind: "open-model" });
				break;
			case "toggle":
				switch (row.id) {
					case "mode":
						setMode(mode === "plan" ? "act" : "plan");
						props.onToggleMode();
						break;
					case "auto-approve":
						setAutoApprove(!autoApprove);
						props.onToggleAutoApprove();
						break;
					case "auto-update":
						setAutoUpdateEnabled((previous) => {
							const next = !previous;
							setAutoUpdateEnabledGlobally(next);
							return next;
						});
						break;
					case "compaction": {
						const nextMode = getNextCliCompactionMode(compactionMode);
						setCompactionMode(nextMode);
						props.onSetCompactionMode(nextMode);
						break;
					}
					case "verbose":
						config.verbose = !verbose;
						setVerbose(!verbose);
						break;
				}
				break;
			case "ext": {
				const action = resolveConfigItemSelectAction(row.item);
				if (isInlineConfigAction(action)) {
					void handleInlineToggle(row.item);
				} else {
					resolve(action);
				}
				break;
			}
			case "mcp-manager":
				resolve({ kind: "open-mcp" });
				break;
			case "tool-group":
				break;
		}
	};

	const handleToggleSelected = () => {
		const row = rows[selectedRowIdx];
		if (!row) return;
		if (row.kind === "toggle") {
			handleSelect();
			return;
		}
		if (!isToggleableRow(row)) return;
		const action = resolveConfigItemToggleAction(row.item);
		if (isInlineConfigAction(action)) {
			void handleInlineToggle(row.item);
		}
	};

	const handleDeleteSelected = () => {
		if (!props.onDeleteConfigItem) {
			return;
		}
		const row = rows[selectedRowIdx];
		if (!row || row.kind !== "ext") {
			return;
		}
		const action = resolveConfigItemDeleteAction(row.item);
		if (action) {
			resolve(action);
		}
	};

	useDialogKeyboard((key) => {
		if (key.name === "escape") {
			dismiss();
			return;
		}
		if (key.name === "left" || key.name === "right") {
			const direction = key.name === "left" ? "left" : "right";
			setActiveTab((tab) => {
				const nextTab = getAdjacentConfigTab(tab, direction);
				return nextTab;
			});
			setNavPosition(0);
			return;
		}
		if (key.name === "up") {
			const nextNavPos =
				clampedNavPos > 0 ? clampedNavPos - 1 : navIndices.length - 1;
			setNavPosition(nextNavPos);
			return;
		}
		if (key.name === "down") {
			const nextNavPos =
				clampedNavPos < navIndices.length - 1 ? clampedNavPos + 1 : 0;
			setNavPosition(nextNavPos);
			return;
		}
		if (key.name === "space") {
			handleToggleSelected();
			return;
		}
		if (
			key.name === "d" &&
			!key.ctrl &&
			!key.meta &&
			!key.option &&
			!key.shift
		) {
			handleDeleteSelected();
			return;
		}
		if (key.name === "return" || key.name === "tab") {
			handleSelect();
		}
	}, dialogId);

	const maxVisible = Math.max(5, height - 12);
	const win = getVisibleWindow(rows, selectedRowIdx, maxVisible);
	const aboveCount = win.startIndex;
	const belowCount = rows.length - win.startIndex - win.items.length;

	return (
		<box flexDirection="column" paddingX={1}>
			<text fg={palette.act}>
				<strong>Settings</strong>
			</text>

			<box flexDirection="row" flexWrap="wrap" paddingBottom={1}>
				{getConfigTabs().map((tab) => {
					const isActive = tab === activeTab;
					return (
						<box
							key={tab}
							height={1}
							backgroundColor={isActive ? palette.selection : undefined}
						>
							<text fg={isActive ? palette.textOnSelection : "gray"}>
								{` ${toTabLabel(tab)} `}
							</text>
						</box>
					);
				})}
			</box>

			{aboveCount > 0 && (
				<text fg="gray">
					{"▲ "}
					{aboveCount} more
				</text>
			)}

			{win.items.map((row, i) => {
				const absIdx = win.startIndex + i;
				const isSel = absIdx === selectedRowIdx;
				const pfx = isSel ? "▸ " : "  ";

				switch (row.kind) {
					case "spacer":
						return <text key={absIdx}> </text>;
					case "head":
						return (
							<text key={absIdx} fg="white">
								{" ".repeat(row.indent ?? 0)}
								{row.label}
							</text>
						);
					case "detail":
						return (
							<text key={absIdx} fg="gray">
								{"  "}
								{row.text}
							</text>
						);
					case "tool-group":
						return (
							<box
								key={absIdx}
								flexDirection="row"
								justifyContent="space-between"
							>
								<text fg="white">
									{"  "}
									{" ".repeat(row.indent ?? 0)}
									{row.label}
								</text>
								<text fg="gray">{row.rightLabel}</text>
							</box>
						);
					case "provider":
						return (
							<box
								key={absIdx}
								flexDirection="row"
								justifyContent="space-between"
							>
								<text fg={isSel ? palette.act : undefined}>{pfx}Provider</text>
								<text fg="white">{props.providerDisplayName}</text>
							</box>
						);
					case "model":
						return (
							<box
								key={absIdx}
								flexDirection="row"
								justifyContent="space-between"
							>
								<text fg={isSel ? palette.act : undefined}>{pfx}Model</text>
								<text fg="white">{displayName}</text>
							</box>
						);
					case "toggle": {
						let value: string;
						let valueColor: string;
						if (row.id === "mode") {
							value = mode === "plan" ? "Plan" : "Act";
							valueColor = getModeAccent(mode);
						} else if (row.id === "auto-approve") {
							value = autoApprove ? "● on" : "○ off";
							valueColor = autoApprove ? palette.success : "gray";
						} else if (row.id === "auto-update") {
							value = autoUpdateEnabled ? "● on" : "○ off";
							valueColor = autoUpdateEnabled ? palette.success : "gray";
						} else if (row.id === "compaction") {
							value = formatCliCompactionMode(compactionMode);
							valueColor = COMPACTION_MODE_COLORS[compactionMode];
						} else {
							value = verbose ? "● on" : "○ off";
							valueColor = verbose ? palette.success : "gray";
						}
						return (
							<box
								key={absIdx}
								flexDirection="row"
								justifyContent="space-between"
							>
								<text fg={isSel ? palette.act : undefined}>
									{pfx}
									{row.label}
								</text>
								<text fg={valueColor}>{value}</text>
							</box>
						);
					}
					case "ext": {
						const enabledState =
							row.item.enabledState ??
							(row.enabled === false ? "disabled" : "enabled");
						const isPending = togglingItemId === row.item.id;
						const enabledIcon =
							typeof row.enabled === "boolean"
								? isPending
									? "~ "
									: enabledState === "partial"
										? "◐ "
										: row.enabled
											? "● "
											: "○ "
								: "";
						const rightLabel = row.rightLabel ?? "";
						const toggleable = isToggleableConfigItem(row.item);
						const prefix = " ".repeat(row.indent ?? 0);
						const rowColor = row.item.loadError
							? "red"
							: toggleable && enabledState === "enabled"
								? palette.success
								: enabledState === "partial"
									? "yellow"
									: isSel
										? palette.act
										: "gray";
						return (
							<box
								key={absIdx}
								flexDirection="row"
								justifyContent="space-between"
							>
								<text fg={rowColor}>
									{pfx}
									{prefix}
									{enabledIcon}
									{getConfigItemDisplayName(row.name)}
								</text>
								<text fg="gray">{rightLabel}</text>
							</box>
						);
					}
					case "mcp-manager":
						return (
							<text key={absIdx} fg={isSel ? palette.act : "gray"}>
								{pfx}Manage MCP Servers...
							</text>
						);
					default:
						return null;
				}
			})}

			{belowCount > 0 && (
				<text fg="gray">
					{"▼ "}
					{belowCount} more
				</text>
			)}

			<text> </text>
			{toggleError && <text fg="red">{toggleError}</text>}
			<text fg="gray">
				<em>
					{togglingItemId
						? "Applying settings"
						: getConfigFooterText({
								canToggle: canToggleSelectedRow,
								canDelete: canDeleteSelectedRow,
							})}
				</em>
			</text>
		</box>
	);
}

