describe("resolveStatusNoticeLabel", () => {
	it("maps compaction status reasons to stable labels", () => {
		expect(
			resolveStatusNoticeLabel({
				type: "notice",
				noticeType: "status",
				displayRole: "status",
				message: "auto-compacting",
				reason: "auto_compaction",
			} as AgentEvent),
		).toBe("auto-compacting");
		expect(
			resolveStatusNoticeLabel({
				type: "notice",
				noticeType: "status",
				displayRole: "status",
				message: "manual",
