	});
});

describe("handleEvent text formatting", () => {
	let output = "";
	let errorOutput = "";

	beforeEach(() => {
		output = "";
		errorOutput = "";
		setCurrentOutputMode("text");
		vi.spyOn(process.stdout, "write").mockImplementation((chunk: unknown) => {
			output += String(chunk);
			return true;
		});
		vi.spyOn(process.stderr, "write").mockImplementation((chunk: unknown) => {
			errorOutput += String(chunk);
			return true;
		});
		vi.spyOn(console, "error").mockImplementation((...args: unknown[]) => {
			errorOutput += `${args.map(String).join(" ")}\n`;
		});
	});

	it("adds a ⎿ before text that follows a tool block", () => {
		handleEvent(
			{
				type: "content_start",
				contentType: "tool",
				toolName: "read_files",
				input: { path: "/tmp/demo.txt" },
			} as unknown as AgentEvent,
			{} as Config,
		);
		handleEvent(
			{
				type: "content_end",
				contentType: "tool",
				toolName: "read_files",
				output: "ok",
			} as unknown as AgentEvent,
			{} as Config,
		);
		handleEvent(
			{
				type: "content_start",
				contentType: "text",
				text: "Now let me check this file.",
			} as unknown as AgentEvent,
			{} as Config,
		);

		expect(output).toContain(
			`\x1b[36m[read_files]\x1b[0m {"path":"/tmp/demo.txt"}`,
		);
		expect(output).toMatch(/⎿.*ok/s);
	});

	it("prints adjacent tool starts on separate lines", () => {
		handleEvent(
			{
				type: "content_start",
				contentType: "tool",
				toolName: "run_commands",
				input: { commands: ["echo one"] },
			} as unknown as AgentEvent,
			{} as Config,
		);
		handleEvent(
			{
				type: "content_start",
				contentType: "tool",
				toolName: "read_files",
				input: { file_paths: ["/tmp/demo.txt"] },
			} as unknown as AgentEvent,
			{} as Config,
		);

		expect(output).toMatch(/\[run_commands\].*\n.*\[read_files\]/s);
	});

	it("does not echo ask_question through the generic tool renderer", () => {
		handleEvent(
			{
				type: "content_start",
				contentType: "tool",
				toolName: "ask_question",
				input: {
					question: "How can I best assist you today?",
					options: [
						"Help me understand or analyze code in a repository",
						"Help me create or edit files",
					],
				},
			} as unknown as AgentEvent,
			{} as Config,
		);
		handleEvent(
			{
				type: "content_end",
				contentType: "tool",
				toolName: "ask_question",
				output: "Help me create or edit files",
			} as unknown as AgentEvent,
			{} as Config,
		);

		expect(output).toBe("");
	});

	it("prints tool errors inline", () => {
		handleEvent(
			{
				type: "content_start",
				contentType: "tool",
				toolName: "team_task",
				input: { action: "create", title: "Draft haiku" },
			} as unknown as AgentEvent,
			{} as Config,
		);
		handleEvent(
			{
				type: "content_end",
				contentType: "tool",
				toolName: "team_task",
				error:
					'✖ Field "status" is not allowed when action=create\n  → at status',
			} as unknown as AgentEvent,
			{} as Config,
		);

		expect(output).toContain(`\x1b[36m[team_task]\x1b[0m create`);
		expect(output).toContain("error:");
		expect(output).toContain(
			'Field "status" is not allowed when action=create',
		);
		expect(output).toContain("→ at status");
	});

	it("prints completed done events as finished in verbose mode", () => {
		handleEvent(
			{
				type: "done",
				reason: "completed",
				iterations: 5,
				text: "ok",
			} as unknown as AgentEvent,
			{ verbose: true } as Config,
		);

		expect(output).toContain("── finished (5 iterations) ──");
		expect(output).not.toContain("── aborted (5 iterations) ──");
	});

	it("prints aborted done events as aborted in verbose mode", () => {
		handleEvent(
			{
				type: "done",
				reason: "aborted",
				iterations: 2,
				text: "aborted",
			} as unknown as AgentEvent,
			{ verbose: true } as Config,
		);

		expect(output).toContain("── aborted (2 iterations) ──");
	});

	it("formats ClinePass limit agent errors before writing to stderr", () => {
		handleEvent(
			{
				type: "error",
				error: new Error(
					"Error: You have reached your 5-hour Clinepass limit. The limit resets in 5h, please try again later.",
				),
				recoverable: false,
			} as unknown as AgentEvent,
			{} as Config,
		);

		expect(errorOutput).toContain("ClinePass limit reached");
		expect(errorOutput).toContain("Switch to Cline usage-based billing");
		expect(errorOutput).toContain("--provider cline");
	});

	it("suppresses heartbeat-only team progress messages", () => {
		handleTeamEvent({
			type: "run_progress",
			run: {
				id: "run_00001",
				agentId: "worker-1",
			},
			message: "heartbeat",
		} as unknown as TeamEvent);

		expect(output).toBe("");
	});

	it("marks queued and started team runs as active", () => {
		handleTeamEvent({
			type: "run_queued",
			run: {
				id: "run_00001",
				agentId: "worker-1",
			},
		} as unknown as TeamEvent);
		handleTeamEvent({
			type: "run_started",
			run: {
				id: "run_00001",
				agentId: "worker-1",
			},
		} as unknown as TeamEvent);

		expect(output).toContain("queued");
		expect(output).toContain("started");
		expect(output).toContain("...");
		// Consecutive team events should not have blank lines between them
		expect(output).not.toMatch(/\n\n/);
	});

	it("closes inline reasoning before team events and terminates the line", () => {
		handleEvent(
			{
				type: "content_start",
				contentType: "reasoning",
				reasoning: "Investigating",
			} as unknown as AgentEvent,
			{} as Config,
		);
		handleTeamEvent({
			type: "run_started",
			run: {
				id: "run_00001",
				agentId: "worker-1",
			},
		} as unknown as TeamEvent);

		expect(output).toMatch(/Investigating.*\n.*\[team run\].*started.*\n$/s);
	});
});

import type { AgentEvent, TeamEvent } from "@cline/core";
import {
	formatCompactionDividerLabel,
	parseCompactionNoticeMetadata,
} from "../tui/utils/compaction-status";
import { formatCliErrorMessage } from "./cline-pass-errors";
import { formatToolInput, formatToolOutput, truncate } from "./helpers";
import {
	c,
	emitJsonLine,
	getCurrentOutputMode,
	write,
	writeErr,
} from "./output";
import type { Config } from "./types";

// =============================================================================
// Inline stream state
// =============================================================================

let activeInlineStream: "text" | "reasoning" | undefined;
let inlineStreamHasOutput = false;
let shouldPrefixNextTextWithBlankLine = false;

// Prefix for result rows
const HOOK = "⎿ ";
const TEAM_RUN_ACTIVE_SUFFIX = `${c.dim} ...${c.reset}`;

export function resolveStatusNoticeLabel(
	event: AgentEvent,
): string | undefined {
	if (event.type !== "notice" || event.displayRole !== "status") {
		return undefined;
	}
	const compaction = parseCompactionNoticeMetadata(event.metadata);
	if (compaction) {
		return formatCompactionDividerLabel({ kind: "compaction", ...compaction });
	}
	return resolveNonCompactionStatusLabel(event);
}

/**
 * Label for a status notice already known not to be a compaction notice.
 * Callers that have parsed the compaction metadata themselves use this to
 * avoid re-parsing.
 */
export function resolveNonCompactionStatusLabel(
	event: AgentEvent,
): string | undefined {
	if (event.type !== "notice" || event.displayRole !== "status") {
		return undefined;
	}
	switch (event.reason) {
		case "auto_compaction":
			return "auto-compacting";
		case "manual_compaction":
			return "compacting";
		case "compaction_budget_emergency":
			return "context budget adjusted";
	}
	return event.message.trim() || undefined;
}

export function closeInlineStreamIfNeeded(): void {
	if (!inlineStreamHasOutput) {
		return;
	}
	write("\n");
	activeInlineStream = undefined;
	inlineStreamHasOutput = false;
}

// Used by team events that arrive while the lead agent is mid-stream. Ends the
// current visual line so the team event prints cleanly, but keeps
// activeInlineStream set so the next text chunk continues on a new line without
// re-emitting any prefix.
function breakLineIfStreaming(): void {
	if (activeInlineStream === "text" && inlineStreamHasOutput) {
		write("\n");
		inlineStreamHasOutput = false;
	}
}

// =============================================================================
// Agent event handler
// =============================================================================

function formatResultLines(text: string, maxLines = 5): string[] {
	const lines = text.split("\n");
	if (lines.length <= maxLines) return lines;
	return [
		...lines.slice(0, maxLines),
		`... ${lines.length - maxLines} more lines`,
	];
}

export function handleEvent(event: AgentEvent, config: Config): void {
	if (getCurrentOutputMode() === "json") {
		emitJsonLine("stdout", { type: "agent_event", event });
		return;
	}

	switch (event.type) {
		case "iteration_start":
			closeInlineStreamIfNeeded();
			break;

		case "iteration_end":
			closeInlineStreamIfNeeded();
			break;

		case "content_start":
			switch (event.contentType) {
				case "text":
					if (activeInlineStream !== "text") {
						closeInlineStreamIfNeeded();
						if (shouldPrefixNextTextWithBlankLine) {
							write("\n");
							shouldPrefixNextTextWithBlankLine = false;
						}
						activeInlineStream = "text";
					}
					write(event.text ?? "");
					inlineStreamHasOutput = true;
					break;
				case "reasoning":
					if (activeInlineStream !== "reasoning") {
						closeInlineStreamIfNeeded();
						write(`${c.dim}[thinking] ${c.reset}`);
						activeInlineStream = "reasoning";
						inlineStreamHasOutput = true;
					}
					if (event.redacted && !event.reasoning) {
						write(`${c.dim}[redacted]${c.reset}`);
						inlineStreamHasOutput = true;
						break;
					}
					write(`${c.dim}${event.reasoning ?? ""}${c.reset}`);
					inlineStreamHasOutput = true;
					break;
				case "tool": {
					closeInlineStreamIfNeeded();
					const toolName = event.toolName ?? "unknown_tool";
					const inputStr = formatToolInput(toolName, event.input);
					if (toolName === "ask_question") {
						break;
					}
					write(
						`${c.cyan}[${toolName}]${c.reset}${inputStr ? ` ${inputStr}` : ""}\n`,
					);
					break;
				}
			}
			break;

		case "content_end":
			switch (event.contentType) {
				case "text":
				case "reasoning":
					closeInlineStreamIfNeeded();
					break;
				case "tool":
					closeInlineStreamIfNeeded();
					if (event.toolName === "ask_question") {
						break;
					}
					if (event.error) {
						write(
							`   ${c.gray}${HOOK}${c.reset}${c.red}error: ${event.error}${c.reset}\n`,
						);
					} else {
						const outputStr = formatToolOutput(event.output);
						if (outputStr) {
							const lines = formatResultLines(outputStr);
							for (let i = 0; i < lines.length; i++) {
								const prefix = i === 0 ? HOOK : "  ";
								write(
									`   ${c.gray}${prefix}${c.reset}${c.dim}${lines[i]}${c.reset}\n`,
								);
							}
						} else {
							write(`   ${c.gray}${HOOK}${c.reset}${c.green}ok${c.reset}\n`);
						}
					}
					shouldPrefixNextTextWithBlankLine = false;
					break;
			}
			break;

		case "done": {
			closeInlineStreamIfNeeded();
			if (config.verbose) {
				const iterations = event.iterations;
				const label = event.reason === "aborted" ? "aborted" : "finished";
				write(
					`\n${c.dim}── ${label} (${iterations} iterations) ──${c.reset}\n`,
				);
			}
			activeInlineStream = undefined;
			inlineStreamHasOutput = false;
			shouldPrefixNextTextWithBlankLine = false;
			break;
		}
		case "error":
			closeInlineStreamIfNeeded();
			if (!event.recoverable || config.verbose) {
				writeErr(formatCliErrorMessage(event.error));
			}
			break;
		case "notice":
			if (event.displayRole === "status") {
				closeInlineStreamIfNeeded();
				const label = resolveStatusNoticeLabel(event);
				if (label) {
					write(`\n${c.dim}[status]${c.reset} ${label}\n`);
				}
			}
			break;
	}
}

// =============================================================================
// Team event handler
// =============================================================================

export function handleTeamEvent(event: TeamEvent): void {
	if (getCurrentOutputMode() === "json") {
		emitJsonLine("stdout", { type: "team_event", event });
		return;
	}
	// Skip heartbeat events to avoid cluttering the CLI with too many messages,
	// since they can be emitted frequently during long-running tasks.
	if (event.type === "run_progress" && event.message === "heartbeat") {
		return;
	}

	breakLineIfStreaming();
	if (activeInlineStream !== "text") {
		closeInlineStreamIfNeeded();
	}

	switch (event.type) {
		case "teammate_spawned":
			write(
				`${c.dim}[team] teammate spawned:${c.reset} ${c.cyan}${event.agentId}${c.reset}\n`,
			);
			break;
		case "teammate_shutdown":
			write(
				`${c.dim}[team] teammate shutdown:${c.reset} ${c.cyan}${event.agentId}${c.reset}\n`,
			);
			break;
		case "team_task_updated":
			write(
				`${c.dim}[team task]${c.reset} ${c.cyan}${event.task.id}${c.reset} -> ${event.task.status}\n`,
			);
			break;
		case "team_message":
			write(
				`${c.dim}[mailbox]${c.reset} ${event.message.fromAgentId} -> ${event.message.toAgentId}: ${event.message.subject}\n`,
			);
			break;
		case "team_mission_log":
			write(
				`${c.dim}[mission]${c.reset} ${event.entry.agentId}: ${truncate(event.entry.summary, 90)}\n`,
			);
			break;
		case "run_queued":
			write(
				`${c.dim}[team run]${c.reset} queued ${c.cyan}${event.run.id}${c.reset} -> ${event.run.agentId}${TEAM_RUN_ACTIVE_SUFFIX}\n`,
			);
			break;
		case "run_started":
			write(
				`${c.dim}[team run]${c.reset} started ${c.cyan}${event.run.id}${c.reset} -> ${event.run.agentId}${TEAM_RUN_ACTIVE_SUFFIX}\n`,
			);
			break;
		case "run_progress":
			write(
				`${c.dim}[team run]${c.reset} progress ${c.cyan}${event.run.id}${c.reset}: ${event.message}\n`,
			);
			break;
		case "run_completed":
			write(
				`${c.dim}[team run]${c.reset} completed ${c.cyan}${event.run.id}${c.reset}\n`,
			);
			break;
		case "run_failed":
			write(
				`${c.dim}[team run]${c.reset} failed ${c.cyan}${event.run.id}${c.reset}: ${event.run.error ?? "unknown error"}\n`,
			);
			break;
		case "run_cancelled":
			write(
				`${c.dim}[team run]${c.reset} cancelled ${c.cyan}${event.run.id}${c.reset}\n`,
			);
			break;
		case "run_interrupted":
			write(
				`${c.dim}[team run]${c.reset} interrupted ${c.cyan}${event.run.id}${c.reset}\n`,
			);
			break;
		case "outcome_created":
			write(
				`${c.dim}[team outcome]${c.reset} created ${c.cyan}${event.outcome.id}${c.reset}: ${event.outcome.title}\n`,
			);
			break;
		case "outcome_fragment_attached":
			write(
				`${c.dim}[team outcome]${c.reset} fragment ${c.cyan}${event.fragment.id}${c.reset} attached to ${event.fragment.section}\n`,
			);
			break;
		case "outcome_fragment_reviewed":
			write(
				`${c.dim}[team outcome]${c.reset} fragment ${c.cyan}${event.fragment.id}${c.reset} -> ${event.fragment.status}\n`,
			);
			break;
		case "outcome_finalized":
			write(
				`${c.dim}[team outcome]${c.reset} finalized ${c.cyan}${event.outcome.id}${c.reset}\n`,
			);
			break;
		case "task_start":
			break;
		case "task_end":
			break;
		case "agent_event":
			break;
	}
}

