function isBooleanLikeAutoApproveValue(value: string | undefined): boolean {
	if (!value) {
		return false;
	}
	const normalized = value.trim().toLowerCase();
	return normalized === "true" || normalized === "false";
}

export function normalizeCliArgs(args: string[]): string[] {
	const normalized: string[] = [];
	for (let index = 0; index < args.length; index += 1) {
		const token = args[index];
		if (token === "--autoapprove" || token === "--auto-approve") {
			const nextToken = args[index + 1];
			if (isBooleanLikeAutoApproveValue(nextToken)) {
				normalized.push("--auto-approve", nextToken);
				index += 1;
				continue;
			}
			normalized.push("--auto-approve", "true");
			continue;
		}
		if (token.startsWith("--autoapprove=")) {
			normalized.push(token.replace(/^--autoapprove=/, "--auto-approve="));
			continue;
		}
		if (token === "--thinking") {
			const nextToken = args[index + 1];
			if (nextToken !== undefined && !nextToken.startsWith("-")) {
				normalized.push("--thinking", nextToken);
				index += 1;
				continue;
			}
			normalized.push("--thinking", "medium");
			continue;
		}
		if (token === "--reasoning-effort") {
			const nextToken = args[index + 1];
			// Legacy spelling is normalized to --thinking and intentionally relies
			// on commanderToParsedArgs for level validation, so invalid values behave
			// the same as `--thinking <value>` and `--thinking=<value>`.
			if (nextToken !== undefined && !nextToken.startsWith("-")) {
				normalized.push("--thinking", nextToken);
				index += 1;
				continue;
			}
			normalized.push("--thinking", "medium");
			continue;
		}
		if (token.startsWith("--reasoning-effort=")) {
			normalized.push(token.replace(/^--reasoning-effort=/, "--thinking="));
			continue;
		}
		normalized.push(token);
	}
	return normalized;
}

export const normalizeAutoApproveArgs = normalizeCliArgs;

export function parseArgs(args: string[]): ParsedArgs {
	const program = createProgram();
	try {
		program.parse(normalizeCliArgs(args), { from: "user" });
	} catch (_: unknown) {
		// exitOverride throws CommanderError on --help / --version; commander
		// handles output directly, and we treat the thrown error as a signal
		// to exit gracefully in the caller.
	}
	return commanderToParsedArgs(program);
}

export function resolveSandboxDataDir(
	cwd: string,
	explicitDir?: string,
): string {
	const envDir = process.env.CLINE_SANDBOX_DATA_DIR?.trim();
	const baseDir =
		explicitDir?.trim() || envDir || join(tmpdir(), "cline-sandbox");
	return resolve(cwd, baseDir);
}

export function configureSandboxEnvironment(options: {
	enabled: boolean;
	cwd: string;
	explicitDir?: string;
}): string | undefined {
	if (!options.enabled) {
		return undefined;
	}
	const dataDir = resolveSandboxDataDir(options.cwd, options.explicitDir);
	process.env.CLINE_SANDBOX = "1";
	process.env.CLINE_SANDBOX_DATA_DIR = dataDir;
	process.env.CLINE_DATA_DIR = dataDir;
	process.env.CLINE_DB_DATA_DIR = join(dataDir, "db");
	process.env.CLINE_SESSION_DATA_DIR = join(dataDir, "sessions");
	process.env.CLINE_TEAM_DATA_DIR = join(dataDir, "teams");
	process.env.CLINE_PROVIDER_SETTINGS_PATH = join(
		dataDir,
		"settings",
		"providers.json",
	);
	process.env.CLINE_HOOKS_LOG_PATH = join(dataDir, "logs", "hooks.jsonl");
	return dataDir;
}

import type { SessionHistoryRecord } from "@cline/core";
import { formatDisplayUserInput, truncateStr } from "@cline/shared";
import { formatUsd } from "./output";
import { shouldShowCliUsageCost } from "./usage-cost-display";

export function formatSessionStatusLabel(
	status: SessionHistoryRecord["status"] | undefined,
): string {
	return status?.trim() || "unknown";
}

export function mergeHistoryStatusRows(
	currentRows: SessionHistoryRecord[],
	refreshedRows: SessionHistoryRecord[],
): SessionHistoryRecord[] {
	const currentById = new Map(
		currentRows.map((row) => [row.sessionId, row] as const),
	);

	return refreshedRows.map((row) => {
		const current = currentById.get(row.sessionId);
		if (!current) {
			return row;
		}
		return {
			...current,
			status: row.status,
			endedAt: row.endedAt,
			exitCode: row.exitCode,
			updatedAt: row.updatedAt,
		};
	});
}

function formatHistoryTitle(
	title: string | undefined,
	prompt: string | undefined,
): string | undefined {
	const rawTitle = title?.trim() || prompt?.trim() || undefined;
	if (!rawTitle) return;
	const normalized = formatDisplayUserInput(rawTitle);
	return truncateStr(normalized.replace(/\s+/g, " "), 40);
}

export function formatCheckpointBadge(
	row: SessionHistoryRecord,
): string | undefined {
	const checkpoint = row.metadata?.checkpoint;
	const count = checkpoint?.history?.length ?? 0;
	const latestRun = checkpoint?.latest?.runCount;
	if (count <= 0) {
		return undefined;
	}
	if (typeof latestRun === "number" && Number.isFinite(latestRun)) {
		return `CP ${count} R${latestRun}`;
	}
	return `CP ${count}`;
}

export function formatCheckpointDetail(
	row: SessionHistoryRecord,
): string | undefined {
	const checkpoint = row.metadata?.checkpoint;
	const count = checkpoint?.history?.length ?? 0;
	const latest = checkpoint?.latest;
	if (count <= 0 || !latest?.ref) {
		return undefined;
	}
	const shortRef = truncateStr(latest.ref, 12);
	const created =
		typeof latest.createdAt === "number" && Number.isFinite(latest.createdAt)
			? formatUtcDate(new Date(latest.createdAt))
			: "unknown";
	const latestRun =
		typeof latest.runCount === "number" && Number.isFinite(latest.runCount)
			? ` run ${latest.runCount}`
			: "";
	return `Checkpoint ${shortRef}${latestRun} created ${created}. ${count} total. Restore with: cline checkpoint restore latest --session-id ${row.sessionId}`;
}

function formatUtcDate(date: Date): string {
	const month = String(date.getUTCMonth() + 1).padStart(2, "0");
	const day = String(date.getUTCDate()).padStart(2, "0");
	const year = date.getUTCFullYear();
	const hour = String(date.getUTCHours()).padStart(2, "0");
	const minute = String(date.getUTCMinutes()).padStart(2, "0");
	return `${month}/${day}/${year} ${hour}:${minute}`;
}

export function formatHistoryListLine(row: SessionHistoryRecord): string {
	const title = formatHistoryTitle(row.metadata?.title, row.prompt);
	if (!title) return "";
	const cost = shouldShowCliUsageCost(row.provider)
		? formatUsd(row.metadata?.totalCost ?? 0, 2)
		: undefined;
	const provider = truncateStr(row.provider?.trim() || "unknown", 20);
	const model = truncateStr(row.model?.trim() || "", 28);

	const checkpointCreatedAt = row.metadata?.checkpoint?.latest?.createdAt;
	const timestamp =
		typeof checkpointCreatedAt === "number" &&
		Number.isFinite(checkpointCreatedAt)
			? checkpointCreatedAt
			: new Date(row.startedAt).getTime();
	const date = formatUtcDate(new Date(timestamp));
	const costSegment = cost ? ` | ${cost}` : "";
	return `${date} ${provider}:${model} [${formatSessionStatusLabel(row.status)}]${costSegment} | ${title}`;
}

import { describe, expect, it } from "vitest";
import { buildHistoryResumeArgs } from "./history-resume";

describe("buildHistoryResumeArgs", () => {
	it("replaces the history subcommand with --id", () => {
		expect(
			buildHistoryResumeArgs({
				sessionId: "sess_1",
				normalizedArgs: ["history"],
				remainingArgs: ["history"],
			}),
		).toEqual(["--id", "sess_1"]);
	});

	it("preserves global flags that precede the subcommand", () => {
		expect(
			buildHistoryResumeArgs({
				sessionId: "sess_1",
				normalizedArgs: [
					"--data-dir",
					"/tmp/data",
					"-m",
					"claude-sonnet-4-6",
					"history",
					"--limit",
					"5",
				],
				remainingArgs: ["history", "--limit", "5"],
			}),
		).toEqual([
			"--data-dir",
			"/tmp/data",
			"-m",
			"claude-sonnet-4-6",
			"--id",
			"sess_1",
		]);
	});

	it("keeps a global flag value that matches the subcommand alias", () => {
		expect(
			buildHistoryResumeArgs({
				sessionId: "sess_1",
				normalizedArgs: ["-m", "h", "h"],
				remainingArgs: ["h"],
			}),
		).toEqual(["-m", "h", "--id", "sess_1"]);
	});

	it("forwards a config dir passed as a subcommand option", () => {
		expect(
			buildHistoryResumeArgs({
				sessionId: "sess_1",
				normalizedArgs: ["history", "--config", "/tmp/conf"],
				remainingArgs: ["history", "--config", "/tmp/conf"],
				configDir: "/tmp/conf",
			}),
		).toEqual(["--config", "/tmp/conf", "--id", "sess_1"]);
	});

	it("does not duplicate a config dir already in the global flags", () => {
		expect(
			buildHistoryResumeArgs({
				sessionId: "sess_1",
				normalizedArgs: ["--config", "/tmp/conf", "history"],
				remainingArgs: ["history"],
				configDir: "/tmp/conf",
			}),
		).toEqual(["--config", "/tmp/conf", "--id", "sess_1"]);
	});

	it("recognizes the --config=<dir> spelling in global flags", () => {
		expect(
			buildHistoryResumeArgs({
				sessionId: "sess_1",
				normalizedArgs: ["--config=/tmp/conf", "history"],
				remainingArgs: ["history"],
				configDir: "/tmp/conf",
			}),
		).toEqual(["--config=/tmp/conf", "--id", "sess_1"]);
	});

	it("returns undefined when remaining args are not a suffix of argv", () => {
		expect(
			buildHistoryResumeArgs({
				sessionId: "sess_1",
				normalizedArgs: ["history", "--limit", "5"],
				remainingArgs: ["history", "--limit", "9"],
			}),
		).toBeUndefined();
		expect(
			buildHistoryResumeArgs({
				sessionId: "sess_1",
				normalizedArgs: ["history"],
				remainingArgs: ["extra", "history"],
			}),
		).toBeUndefined();
	});
});

import { resolveCliLaunchSpec } from "./internal-launch";

export interface HistoryResumeCommand {
	launcher: string;
	childArgs: string[];
}

export interface BuildHistoryResumeArgsInput {
	sessionId: string;
	/** Full normalized CLI args (process.argv.slice(2) after normalization). */
	normalizedArgs: string[];
	/**
	 * Commander's `program.args` after parsing: the `history` subcommand token
	 * and everything following it. Must be a suffix of `normalizedArgs`.
	 */
	remainingArgs: string[];
	/**
	 * Config dir resolved from the full argv. Forwarded explicitly because
	 * `--config` may have been passed as a `history` subcommand option, which
	 * would otherwise be dropped with the rest of the subcommand args.
	 */
	configDir?: string;
}

/**
 * Builds argv for relaunching the CLI as `cline <globalFlags> --id <sessionId>`
 * after a session is picked in `cline history`. Returns undefined when the
 * global-flag prefix cannot be derived safely (caller falls back to resuming
 * in-process).
 */
export function buildHistoryResumeArgs(
	input: BuildHistoryResumeArgsInput,
): string[] | undefined {
	const { sessionId, normalizedArgs, remainingArgs, configDir } = input;
	const splitIndex = normalizedArgs.length - remainingArgs.length;
	if (splitIndex < 0) {
		return undefined;
	}
	for (let i = 0; i < remainingArgs.length; i++) {
		if (normalizedArgs[splitIndex + i] !== remainingArgs[i]) {
			return undefined;
		}
	}
	const globalArgs = normalizedArgs.slice(0, splitIndex);
	const args = [...globalArgs];
	const hasConfigFlag = globalArgs.some(
		(arg) => arg === "--config" || arg.startsWith("--config="),
	);
	if (configDir && !hasConfigFlag) {
		args.push("--config", configDir);
	}
	args.push("--id", sessionId);
	return args;
}

export function buildHistoryResumeCommand(
	input: BuildHistoryResumeArgsInput,
): HistoryResumeCommand | undefined {
	const childArgs = buildHistoryResumeArgs(input);
	if (!childArgs) {
		return undefined;
	}
	const spec = resolveCliLaunchSpec();
	if (!spec) {
		return undefined;
	}
	return {
		launcher: spec.launcher,
		childArgs: [...spec.childArgsPrefix, ...childArgs],
	};
}

/**
 * Resumes a history-picked session in a fresh `cline --id <sessionId>` child
 * process with inherited stdio, and returns its exit code. Creating a second
 * OpenTUI renderer in the picker's process can crash natively during teardown
 * (Bun "panic(main thread): Segmentation fault" on Ctrl+C), so the resumed
 * interactive TUI must get a process of its own.
 *
 * Returns undefined when the child cannot be launched; the caller should fall
 * back to resuming in-process.
 */
export async function spawnHistoryResume(
	input: BuildHistoryResumeArgsInput,
): Promise<number | undefined> {
	const command = buildHistoryResumeCommand(input);
	if (!command) {
		return undefined;
	}
	const { spawn } = await import("node:child_process");
	return await new Promise<number | undefined>((resolve) => {
		let child: ReturnType<typeof spawn>;
		try {
			child = spawn(command.launcher, command.childArgs, {
				stdio: "inherit",
			});
		} catch {
			resolve(undefined);
			return;
		}
		// The child shares this foreground process group, so terminal-generated
		// Ctrl+C already reaches it. Keep the parent alive to reap the child
		// without re-forwarding a second signal into the TUI teardown path.
		const suppressParentSignal = () => {};
		process.on("SIGINT", suppressParentSignal);
		process.on("SIGTERM", suppressParentSignal);
		const finish = (value: number | undefined) => {
			process.off("SIGINT", suppressParentSignal);
			process.off("SIGTERM", suppressParentSignal);
			resolve(value);
		};
		child.once("error", () => finish(undefined));
		child.once("exit", (code, signal) => finish(signal ? 1 : (code ?? 0)));
	});
}

