import {
	type AgentExtensionCommand,
	type AgentExtensionCommandResult,
	type BasicLogger,
	createContributionRegistry,
	resolveAndLoadAgentPlugins,
} from "@cline/core";
import type { AgentTool, Message } from "@cline/shared";
import {
	type ChatCommandDefinition,
	type ChatCommandHost,
	chatCommandHost,
} from "./chat-commands";

export interface PluginSlashCommand {
	name: string;
	description?: string;
}

export interface WorkspaceChatCommandHostResult {
	host: ChatCommandHost;
	// Plugin-registered commands surfaced as slash commands for TUI autocomplete.
	pluginSlashCommands: PluginSlashCommand[];
	shutdown?: () => Promise<void>;
}

function normalizeCommandName(name: string): string {
	const trimmed = name.trim();
	if (!trimmed) {
		return trimmed;
	}
	return trimmed.startsWith("/") ? trimmed : `/${trimmed}`;
}

function createPluginCommandDefinition(
	command: AgentExtensionCommand,
): ChatCommandDefinition | undefined {
	if (typeof command.handler !== "function") {
		return undefined;
	}
	const normalizedName = normalizeCommandName(command.name);
	if (!normalizedName) {
		return undefined;
	}
	return {
		names: [normalizedName.toLowerCase()],
		run: async ({ args }, context) => {
			const result = await command.handler?.(args.join(" "));
			const { reply, submitPrompt } = normalizeCommandResult(result);
			if (reply) {
				await context.reply(reply);
			}
			if (submitPrompt) {
				await context.submitPrompt?.(submitPrompt);
			}
		},
	};
}

function normalizeCommandResult(
	result: AgentExtensionCommandResult | undefined,
): { reply?: string; submitPrompt?: string } {
	if (typeof result === "string") {
		const reply = result.trim();
		return reply ? { reply } : {};
	}
	if (!result || typeof result !== "object") {
		return {};
	}
	const reply =
		typeof result.reply === "string" && result.reply.trim()
			? result.reply.trim()
			: undefined;
	const submitPrompt =
		typeof result.submitPrompt === "string" && result.submitPrompt.trim()
			? result.submitPrompt.trim()
			: undefined;
	return {
		...(reply ? { reply } : {}),
		...(submitPrompt ? { submitPrompt } : {}),
	};
}

export async function createWorkspaceChatCommandHost(input: {
	cwd: string;
	workspaceRoot?: string;
	logger?: BasicLogger;
}): Promise<WorkspaceChatCommandHostResult> {
	const workspaceRoot = input.workspaceRoot?.trim() || input.cwd;
	let loaded: Awaited<ReturnType<typeof resolveAndLoadAgentPlugins>>;
	try {
		loaded = await resolveAndLoadAgentPlugins({
			cwd: input.cwd,
			workspacePath: workspaceRoot,
		});
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		input.logger?.log(
			`plugin command loading failed; continuing without plugin commands (${message})`,
		);
		return { host: chatCommandHost, pluginSlashCommands: [] };
	}
	if (!loaded.extensions.length) {
		await loaded.shutdown?.().catch(() => {
			// Best effort cleanup when no command-capable plugins were loaded.
		});
		return { host: chatCommandHost, pluginSlashCommands: [] };
	}

	const registry = createContributionRegistry<
		(typeof loaded.extensions)[number],
		AgentTool,
		Message[]
	>({
		extensions: loaded.extensions,
	});
	try {
		await registry.initialize();
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		input.logger?.log(
			`plugin command registry initialization failed; continuing without plugin commands (${message})`,
		);
		await loaded.shutdown?.().catch(() => {
			// Best effort cleanup after failed command discovery.
		});
		return { host: chatCommandHost, pluginSlashCommands: [] };
	}

	const host = chatCommandHost.clone();
	const pluginSlashCommands: PluginSlashCommand[] = [];
	for (const command of registry.getRegistrySnapshot().commands) {
		const definition = createPluginCommandDefinition(command);
		if (definition) {
			host.register("command", definition);
			// Use the same normalized+lowercased name so TUI autocomplete matches the handler key.
			const normalizedName = definition.names[0]; // already lowercased, slash-prefixed
			pluginSlashCommands.push({
				name: normalizedName.startsWith("/")
					? normalizedName.slice(1)
					: normalizedName,
				description: command.description,
			});
		}
	}
	return { host, pluginSlashCommands, shutdown: loaded.shutdown };
}

import type { ProviderSettings } from "@cline/core";
import { describe, expect, it } from "vitest";
import { isProviderConfigured } from "./provider-auth";

describe("isProviderConfigured", () => {
	it("returns false when settings is undefined", () => {
		expect(isProviderConfigured("anthropic", undefined)).toBe(false);
	});

	it("returns false when api-key settings have no useful fields", () => {
		expect(
			isProviderConfigured("anthropic", {
				provider: "anthropic",
			} satisfies ProviderSettings),
		).toBe(false);
	});

	it("treats any persisted api key as configured", () => {
		expect(
			isProviderConfigured("anthropic", {
				provider: "anthropic",
				apiKey: "sk-test",
			} satisfies ProviderSettings),
		).toBe(true);
	});

	it("treats a persisted base URL as configured", () => {
		expect(
			isProviderConfigured("ollama", {
				provider: "ollama",
				baseUrl: "http://localhost:11434/v1",
			} satisfies ProviderSettings),
		).toBe(true);
	});

	it("treats a persisted model id as configured", () => {
		expect(
			isProviderConfigured("ollama", {
				provider: "ollama",
				model: "llama3.1",
			} satisfies ProviderSettings),
		).toBe(true);
	});

	it("treats lmstudio with model + base url as configured", () => {
		expect(
			isProviderConfigured("lmstudio", {
				provider: "lmstudio",
				model: "qwen2",
				baseUrl: "http://localhost:1234/v1",
			} satisfies ProviderSettings),
		).toBe(true);
	});

	it("requires an OAuth access token for cline", () => {
		expect(
			isProviderConfigured("cline", {
				provider: "cline",
			} satisfies ProviderSettings),
		).toBe(false);

		expect(
			isProviderConfigured("cline", {
				provider: "cline",
				auth: { accessToken: "workos:abc" },
			} satisfies ProviderSettings),
		).toBe(true);
	});
});

import {
	formatProviderOAuthApiKey,
	getPersistedProviderApiKey as getCorePersistedProviderApiKey,
	isOAuthProvider,
	Llms,
	type ProviderOAuthCredentials,
	type ProviderSettings,
} from "@cline/core";

export type OAuthCredentials = ProviderOAuthCredentials;

export function normalizeProviderId(providerId: string): string {
	return Llms.normalizeProviderId(providerId.trim());
}

export function normalizeAuthProviderId(providerId: string): string {
	const normalized = providerId.trim().toLowerCase();
	if (normalized === "codex" || normalized === "openai-codex") {
		return "openai-codex";
	}
	return normalizeProviderId(normalized);
}

export { isOAuthProvider };

export function toProviderApiKey(
	providerId: string,
	credentials: Pick<OAuthCredentials, "access">,
): string {
	return formatProviderOAuthApiKey(providerId, credentials);
}

export function getPersistedProviderApiKey(
	providerId: string,
	settings?: ProviderSettings,
): string | undefined {
	return getCorePersistedProviderApiKey(providerId, settings);
}

/**
 * Returns true when the user has previously saved any meaningful credentials
 * or endpoint config for the provider. Used by the picker to decide whether
 * to offer "Use existing configuration?" before opening the configure dialog.
 *
 * Treats OAuth providers as configured when an access token or a manually
 * saved API key is present (the /settings escape hatch for when OAuth isn't
 * working); for everything else, any persisted API key, base URL, or model id
 * counts. We don't enforce required fields here — the runtime no longer
 * pre-flights credentials, so a missing key only matters when the API call
 * actually runs and the provider's own auth error is surfaced.
 */
export function isProviderConfigured(
	providerId: string,
	settings: ProviderSettings | undefined,
): boolean {
	if (!settings) return false;
	if (isOAuthProvider(providerId)) {
		// getPersistedProviderApiKey covers both auth.accessToken and apiKey.
		return Boolean(getPersistedProviderApiKey(providerId, settings));
	}
	if (getPersistedProviderApiKey(providerId, settings)) return true;
	if (settings.baseUrl?.trim()) return true;
	if (settings.model?.trim()) return true;
	return false;
}

export async function ensureOAuthProviderApiKey(
	input: Parameters<
		typeof import("../commands/auth").ensureOAuthProviderApiKey
	>[0],
): Promise<
	Awaited<
		ReturnType<typeof import("../commands/auth").ensureOAuthProviderApiKey>
	>
> {
	const { ensureOAuthProviderApiKey: ensureFromCommand } = await import(
		"../commands/auth"
	);
	return await ensureFromCommand(input);
}

