		await writeFile(path.join(repoPath, "file.txt"), "hello");
		git(repoPath, ["add", "."]);
		git(repoPath, [
			"-c",
			"user.email=test@example.com",
			"-c",
			"user.name=Test",
			"commit",
			"-q",
			"-m",
			"init",
		]);
	});

	afterEach(async () => {
		if (originalClineDir === undefined) {
			delete process.env.CLINE_DIR;
		} else {
			process.env.CLINE_DIR = originalClineDir;
		}
		setClineDir(originalClineDir ?? path.join("~", ".cline"));
		await rm(sandboxRoot, { recursive: true, force: true });
	});

	it("places worktrees under ~/.cline/worktrees", () => {
		expect(getTaskWorktreesHomePath()).toBe(path.join(clineDir, "worktrees"));
	});

	it("creates a detached worktree at ~/.cline/worktrees/<taskId>/<repoName>", async () => {
		const result = await createTaskWorktree({
			cwd: repoPath,
			taskId: "my-task",
		});

		expect(result.success).toBe(true);
		expect(result.taskId).toBe("my-task");
		expect(result.repoRoot).toBeDefined();
		expect(result.path).toBeDefined();
		if (!result.repoRoot || !result.path) {
			throw new Error("Expected worktree result to include repoRoot and path.");
		}
		const worktreePath = result.path;

		expect(await realpath(result.repoRoot)).toBe(await realpath(repoPath));
		expect(result.path).toBe(
			path.join(clineDir, "worktrees", "my-task", "myrepo"),
		);
		expect(git(worktreePath, ["rev-parse", "--is-inside-work-tree"])).toBe(
			"true",
		);
		expect(git(worktreePath, ["rev-parse", "HEAD"])).toBe(
			git(repoPath, ["rev-parse", "HEAD"]),
		);
		expect(git(worktreePath, ["rev-parse", "--abbrev-ref", "HEAD"])).toBe(
			"HEAD",
		);
	});

	it("generates a Kanban-style short taskId when none is provided", async () => {
		const result = await createTaskWorktree({ cwd: repoPath });

		expect(result.success).toBe(true);
		expect(result.taskId).toMatch(/^[0-9a-f]{5}$/i);
		expect(result.taskId).toBeDefined();
		if (!result.taskId) {
			throw new Error("Expected generated taskId.");
		}
		expect(result.path).toBe(
			path.join(clineDir, "worktrees", result.taskId, "myrepo"),
		);
	});

	it("rejects when cwd is not a git repository", async () => {
		const result = await createTaskWorktree({ cwd: nonRepoPath });

		expect(result.success).toBe(false);
		expect(result.message).toMatch(/Not a git repository/);
	});

	it("cleans up the task directory when git worktree add fails", async () => {
		const emptyRepoPath = path.join(sandboxRoot, "empty-repo");
		await mkdir(emptyRepoPath, { recursive: true });
		git(emptyRepoPath, ["init", "-q", "-b", "main"]);

		const result = await createTaskWorktree({
			cwd: emptyRepoPath,
			taskId: "empty",
		});

		expect(result.success).toBe(false);
		expect(result.message).toMatch(/Failed to create worktree/);
		expect(await pathExists(path.join(clineDir, "worktrees", "empty"))).toBe(
			false,
		);
	});

	it("rejects unsafe taskIds", async () => {
		const traversal = await createTaskWorktree({
			cwd: repoPath,
			taskId: "../escape",
		});
		const nullByte = await createTaskWorktree({
			cwd: repoPath,
			taskId: "safe\0../escape",
		});

		expect(traversal.success).toBe(false);
		expect(traversal.message).toMatch(/Invalid worktree id/);
		expect(nullByte.success).toBe(false);
		expect(nullByte.message).toMatch(/Invalid worktree id/);
	});
});

import { execFile } from "node:child_process";
import { randomUUID } from "node:crypto";
import { access, mkdir, rm } from "node:fs/promises";
import * as path from "node:path";
import { promisify } from "node:util";
import { resolveClineDir } from "@cline/shared/storage";

const execFileAsync = promisify(execFile);
const TASK_ID_LENGTH = 5;

export interface CreateTaskWorktreeResult {
	success: boolean;
	message: string;
	path?: string;
	taskId?: string;
	repoRoot?: string;
}

export function getTaskWorktreesHomePath(): string {
	return path.join(resolveClineDir(), "worktrees");
}

function getWorkspaceFolderLabelForWorktreePath(repoPath: string): string {
	const folder = path.basename(repoPath.replace(/[\\/]+$/g, "")) || "workspace";
	const cleaned = [...folder]
		.filter((char) => {
			const code = char.charCodeAt(0);
			return code >= 32 && code !== 127;
		})
		.join("")
		.trim();
	return cleaned || "workspace";
}

function createShortTaskId(): string {
	return randomUUID().replaceAll("-", "").slice(0, TASK_ID_LENGTH);
}

async function pathExists(targetPath: string): Promise<boolean> {
	try {
		await access(targetPath);
		return true;
	} catch {
		return false;
	}
}

async function checkGitInstalled(): Promise<boolean> {
	try {
		await execFileAsync("git", ["--version"], { windowsHide: true });
		return true;
	} catch {
		return false;
	}
}

async function getGitRootPath(cwd: string): Promise<string | null> {
	try {
		const { stdout } = await execFileAsync(
			"git",
			["-C", cwd, "rev-parse", "--show-toplevel"],
			{ windowsHide: true },
		);
		const root = stdout.trim();
		return root || null;
	} catch {
		return null;
	}
}

export async function createTaskWorktree(options: {
	cwd: string;
	taskId?: string;
}): Promise<CreateTaskWorktreeResult> {
	if (!(await checkGitInstalled())) {
		return {
			success: false,
			message: "Git is not installed. --worktree requires git on PATH.",
		};
	}

	const repoRoot = await getGitRootPath(options.cwd);
	if (!repoRoot) {
		return {
			success: false,
			message: `Not a git repository: ${options.cwd}. --worktree requires a git repo.`,
		};
	}

	let taskId = options.taskId?.trim() || createShortTaskId();
	if (
		taskId.includes("/") ||
		taskId.includes("\\") ||
		taskId.includes("..") ||
		taskId.includes("\0")
	) {
		return { success: false, message: `Invalid worktree id: ${taskId}` };
	}

	const workspaceLabel = getWorkspaceFolderLabelForWorktreePath(repoRoot);
	let worktreePath = path.join(
		getTaskWorktreesHomePath(),
		taskId,
		workspaceLabel,
	);
	if (!options.taskId) {
		for (
			let attempt = 0;
			attempt < 16 && (await pathExists(worktreePath));
			attempt += 1
		) {
			taskId = createShortTaskId();
			worktreePath = path.join(
				getTaskWorktreesHomePath(),
				taskId,
				workspaceLabel,
			);
		}
	}

	const parentDir = path.dirname(worktreePath);
	const parentDirExisted = await pathExists(parentDir);

	try {
		await mkdir(parentDir, { recursive: true });
		await execFileAsync(
			"git",
			["-C", repoRoot, "worktree", "add", "--detach", worktreePath, "HEAD"],
			{ windowsHide: true },
		);
		return {
			success: true,
			message: `Worktree created at ${worktreePath}`,
			path: worktreePath,
			taskId,
			repoRoot,
		};
	} catch (error) {
		if (!parentDirExisted) {
			await rm(parentDir, { recursive: true, force: true }).catch(() => {});
		}
		return {
			success: false,
			message: `Failed to create worktree: ${error instanceof Error ? error.message : String(error)}`,
		};
	}
}

import * as p from "@clack/prompts";
import { runConnectAdapter } from "../../commands/connect";
import {
	PLATFORMS,
	type PlatformDef,
	type SecurityDef,
	shouldIncludeField,
} from "./platforms";

function isCancel(value: unknown): value is symbol {
	return p.isCancel(value);
}

const SENSITIVE_FLAGS = new Set([
	"-k",
	"--access-token",
	"--api-key",
	"--app-token",
	"--app-secret",
	"--bot-token",
	"--credentials-json",
	"--signing-secret",
	"--verify-token",
	"--webhook-secret",
]);

function redactCommandArgs(args: string[]): string {
	const redacted: string[] = [];
	for (let i = 0; i < args.length; i++) {
		const arg = args[i] ?? "";
		redacted.push(arg);
		if (SENSITIVE_FLAGS.has(arg) && i + 1 < args.length) {
			redacted.push("[redacted]");
			i++;
		}
	}
	return redacted.join(" ");
}

async function collectFields(platform: PlatformDef): Promise<string[] | null> {
	const args: string[] = [];
	const values: Record<string, string> = {};

	for (const field of platform.fields) {
		if (!shouldIncludeField(field, values)) {
			continue;
		}
		if (field.help) {
			for (const line of field.help) {
				p.log.info(line);
			}
		}

		const value = field.options
			? await p.select({
					message: field.label,
					options: field.options,
					initialValue: field.initialValue,
				})
			: await p.text({
					message: field.label,
					placeholder: field.placeholder,
					defaultValue: field.initialValue,
					validate: field.required
						? (v) => {
								if (!v?.trim()) return `${field.label} is required`;
								return undefined;
							}
						: undefined,
				});

		if (isCancel(value)) return null;

		const trimmed = (value as string).trim();
		values[field.flag] = trimmed;
		if (trimmed) {
			args.push(field.flag, trimmed);
		}
	}

	return args;
}

async function collectSecurity(
	security: SecurityDef,
): Promise<string[] | null> {
	const restrict = await p.confirm({
		message: security.prompt,
		initialValue: true,
	});

	if (isCancel(restrict)) return null;
	if (!restrict) {
		p.log.warn(
			"Anyone who finds this bot will be able to run tasks on your machine.",
		);
		return [];
	}

	const values: Record<string, string> = {};

	for (const field of security.fields) {
		if (field.help) {
			for (const line of field.help) {
				p.log.info(line);
			}
		}

		const value = await p.text({
			message: field.label,
			placeholder: field.placeholder,
			validate: (v) => {
				const trimmed = v?.trim();
				if (!trimmed) return field.requiredMessage;
				return field.validate?.(trimmed);
			},
		});

		if (isCancel(value)) return null;

		values[field.key] = (value as string).trim();
	}

	const args = security.buildArgs(values);
	p.log.success("Access restriction enabled");
	return args;
}

export async function runConnectWizard(): Promise<number> {
	p.intro("Connect a messaging platform");

	const platformId = await p.select({
		message: "Select a platform",
		options: PLATFORMS.map((pl) => ({
			value: pl.id,
			label: pl.name,
			hint: pl.hint,
		})),
	});

	if (isCancel(platformId)) {
		p.outro("Cancelled");
		return 0;
	}

	const platform = PLATFORMS.find((pl) => pl.id === (platformId as string));
	if (!platform) {
		p.log.error("Unknown platform");
		return 1;
	}

	p.log.step(`Setting up ${platform.name}`);

	if (platform.type === "webhook") {
		p.log.warn(
			"This connector requires a publicly accessible URL for webhooks.",
		);
	}

	const args = await collectFields(platform);
	if (!args) {
		p.outro("Cancelled");
		return 0;
	}

	if (platform.security) {
		const securityArgs = await collectSecurity(platform.security);
		if (!securityArgs) {
			p.outro("Cancelled");
			return 0;
		}
		args.push(...securityArgs);
	}

	const advanced = await p.group({
		provider: () =>
			p.text({
				message: "Provider override",
				placeholder: "leave empty for default",
			}),
		model: () =>
			p.text({
				message: "Model override",
				placeholder: "leave empty for default",
			}),
		systemPrompt: () =>
			p.text({
				message: "System prompt override",
				placeholder: "leave empty for default",
			}),
		mode: () =>
			p.select({
				message: "Agent mode",
				options: [
					{ value: "act", label: "Act", hint: "execute tasks" },
					{ value: "plan", label: "Plan", hint: "plan only" },
				],
				initialValue: "act",
			}),
	});

	if (isCancel(advanced)) {
		p.outro("Cancelled");
		return 0;
	}

	if (advanced.provider?.trim()) {
		args.push("--provider", advanced.provider.trim());
	}
	if (advanced.model?.trim()) {
		args.push("--model", advanced.model.trim());
	}
	if (advanced.systemPrompt?.trim()) {
		args.push("--system", advanced.systemPrompt.trim());
	}
	if (advanced.mode === "plan") {
		args.push("--mode", "plan");
	}

	args.push("-i");

	p.log.success(
		`Running: cline connect ${platform.id} ${redactCommandArgs(args)}`,
	);
	p.outro("Starting connector (Ctrl+C to stop)");

	return runConnectAdapter(platform.id, args, {
		writeln: (text) => {
			if (text) console.log(text);
		},
		writeErr: (text) => console.error(text),
	});
}

